local function isTableOrUserdata(candidate)
    local candidateType = type(candidate)
    return candidateType == "table" or candidateType == "userdata"
end

local function yieldScriptMs(requestedMs, fallbackMs)
    local waitMs = tonumber(requestedMs)
    if waitMs == nil or waitMs ~= waitMs then
        waitMs = tonumber(fallbackMs) or 0
    end
    local clampedWaitMs = math.max(0, math.min(waitMs, 2147483647))
    return Script.Yield(math.tointeger(math.ceil(clampedWaitMs)))
end

