                    crashFeature:SetBoolValue(false)
                end
                return false, "settings_load_suppressed"
            end
            if KS_BlockSessionCrashForBlacklistedCountry(crashFeatureId, crashFeature, featureOptions) then
                return false, "blacklisted_country_in_session"
            end
            return KSDispatchRuntimeFeature(crashFeatureId, crashFeature, featureOptions)
        end

        local emptyIterableFallback = {}
        local originalPairs = pairs
        local originalIpairs = ipairs

        function pairs(pairsTarget)
            if type(pairsTarget) ~= "table" then
                pairsTarget = emptyIterableFallback
            end
            return originalPairs(pairsTarget)
        end

        function ipairs(ipairsTarget)
            local ipairsTargetType = type(ipairsTarget)
            if ipairsTargetType ~= "table" and ipairsTargetType ~= "userdata" then
                ipairsTarget = emptyIterableFallback
            end
            return originalIpairs(ipairsTarget)
        end

        if type(tableContainsValue) ~= "function" then
            function tableContainsValue(searchTable, wantedValue)
                if type(searchTable) ~= "table" then
                    return false
                end
                for _, entryValue in pairs(searchTable) do
                    if entryValue == wantedValue then
                        return true
                    end
                end
                return false
            end
        end

        local function getRequiredContextField(fieldName, expectedType)
            local fieldValue = featurePlaneContext[fieldName]
            if expectedType and type(fieldValue) ~= expectedType then
                assert(false, ("missing feature plane context: %s"):format(tostring(fieldName)))
            end
            return fieldValue
        end

