        }
        local currentEmoteDuration = -1
        local currentEmoteAnimOrScenarioName = ""
        local currentEmoteDictOrType = ""
        isEmotePlaying = false
        local currentEmoteLabel = ""
        local currentEmoteAnimFlags = 0
        local hasEmotePropsAttached = false
        local emotePropHandles = {}
        local emoteHasSecondProp = false
        local unusedEmoteCancelFlagPrimary = false
        local unusedEmoteCancelFlagSecondary = false

        function SendNotif(notificationMessage)
            notify(notificationMessage)
        end

        function DestroyAllProps()
            for propIndex = 1, #emotePropHandles do
                local propHandle = emotePropHandles[propIndex]
                if ENTITY.IS_AN_ENTITY(propHandle) then
                    DeleteEnt(propHandle)
                end
            end
            emotePropHandles = {}
            hasEmotePropsAttached = false
        end

        function EmoteCancel()
            local localPed = PLAYER.GET_PLAYER_PED(-1)
            if currentEmoteDictOrType == "MaleScenario" then
                if isEmotePlaying then
                    TASK.CLEAR_PED_TASKS_IMMEDIATELY(localPed)
                    isEmotePlaying = false
                end
            elseif currentEmoteDictOrType == "Scenario" then
                if isEmotePlaying then
                    TASK.CLEAR_PED_TASKS_IMMEDIATELY(localPed)
                    isEmotePlaying = false
                end
            end
            unusedEmoteCancelFlagPrimary = false
            unusedEmoteCancelFlagSecondary = false
            if isEmotePlaying then
                TASK.CLEAR_PED_TASKS_IMMEDIATELY(localPed)
                DestroyAllProps()
                isEmotePlaying = false
            end
        end

        function CheckGender()
            local localPedInstance = GTA.GetLocalPed()
            if localPedInstance == nil then
                return
            end
            local pedModelInfo = localPedInstance.ModelInfo
            if pedModelInfo == nil then
                return
            end
            local pedModelHash = pedModelInfo.Model
            local maleFreemodeHash = MISC.GET_HASH_KEY("MP_M_freemode_01")
            local femaleFreemodeHash = MISC.GET_HASH_KEY("MP_F_freemode_01")
            if pedModelHash == maleFreemodeHash then
                return "male"
            else
                return "female"
            end
        end

        function OnEmotePlay(emoteEntry)
            function LoadAnim(animDictName)
                if not STREAMING.HAS_ANIM_DICT_LOADED(animDictName) then
                    STREAMING.REQUEST_ANIM_DICT(animDictName)
                    while not STREAMING.HAS_ANIM_DICT_LOADED(animDictName) do
                        Script.Yield(50)
                    end
                end
                return
            end

            function AddPropToPlayer(propModel, boneId, offsetX, offsetY, offsetZ, rotationX, rotationY, rotationZ)
                local propOwnerPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())
                local propSpawnX, propSpawnY, propSpawnZ = ENTITY.GET_ENTITY_COORDS(propOwnerPed)
                local numericModelHash = tonumber(propModel)
                propModel = numericModelHash or propModel
                if not numericModelHash then
                    propModel = MISC.GET_HASH_KEY(propModel)
                end
                if not STREAMING.HAS_MODEL_LOADED(propModel) then
                    STREAMING.REQUEST_MODEL(propModel)
                    while not STREAMING.HAS_MODEL_LOADED(propModel) do
                        Script.Yield(50)
                    end
                end
                local spawnedProp = GTA.CreateObject(propModel, propSpawnX, propSpawnY, propSpawnZ + 0.2, true, true)
                local boneIndex = PED.GET_PED_BONE_INDEX(propOwnerPed, tonumber(boneId) or 0)
                if not ENTITY.IS_AN_ENTITY(spawnedProp) or type(boneIndex) ~= "number" or boneIndex < 0 then
                    if ENTITY.IS_AN_ENTITY(spawnedProp) then
                        DeleteEnt(spawnedProp)
                    end
                    STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(propModel)
                    return false
                end
                ENTITY.ATTACH_ENTITY_TO_ENTITY(spawnedProp, propOwnerPed, boneIndex, tonumber(offsetX) or 0.0, tonumber(offsetY) or 0.0, tonumber(offsetZ) or 0.0, tonumber(rotationX) or 0.0, tonumber(rotationY) or 0.0, tonumber(rotationZ) or 0.0, true, true, false, true, 1, true)
                table.insert(emotePropHandles, spawnedProp)
                hasEmotePropsAttached = true
                STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(propModel)
                return true
            end

            local isInVehicle = PED.IS_PED_IN_ANY_VEHICLE(PLAYER.GET_PLAYER_PED(-1), true)
            if isInVehicle then
                notify("Please leave your Vehicle to use Emotes!")
                return
            end
            if not ENTITY.IS_AN_ENTITY(PLAYER.GET_PLAYER_PED(-1)) then
                return false
            end
            currentEmoteDictOrType, currentEmoteAnimOrScenarioName, currentEmoteLabel = table.unpack(emoteEntry)
            currentEmoteDuration = -1
            if hasEmotePropsAttached then
                DestroyAllProps()
            end
            local pedGender = CheckGender()
            local emotePed = PLAYER.GET_PLAYER_PED(-1)
            if currentEmoteDictOrType == "MaleScenario" then
                if isInVehicle then
                    return
                end
                if pedGender == "male" then
                    TASK.CLEAR_PED_TASKS_IMMEDIATELY(emotePed)
                    TASK.TASK_START_SCENARIO_IN_PLACE(emotePed, currentEmoteAnimOrScenarioName, 0, true)
                    isEmotePlaying = true
                else
                    notify("This emote is for male only!")
                end
                return
            elseif currentEmoteDictOrType == "ScenarioObject" then
                if isInVehicle then
                    return
                end
                TASK.CLEAR_PED_TASKS_IMMEDIATELY(emotePed)
                local pedX, pedY, pedZ = ENTITY.GET_ENTITY_COORDS(emotePed)
                TASK.TASK_START_SCENARIO_AT_POSITION(emotePed, currentEmoteAnimOrScenarioName, pedX, pedY, pedZ - 0.5, ENTITY.GET_ENTITY_HEADING(emotePed), 0, true, false)
                isEmotePlaying = true
                return
            elseif currentEmoteDictOrType == "Scenario" then
                if isInVehicle then
                    return
                end
                TASK.CLEAR_PED_TASKS_IMMEDIATELY(emotePed)
                TASK.TASK_START_SCENARIO_IN_PLACE(emotePed, currentEmoteAnimOrScenarioName, 0, true)
                isEmotePlaying = true
                return
            end
            LoadAnim(currentEmoteDictOrType)
            if emoteEntry.AnimationOptions then
                if emoteEntry.AnimationOptions.EmoteLoop then
                    currentEmoteAnimFlags = 1
                    if emoteEntry.AnimationOptions.EmoteMoving then
                        currentEmoteAnimFlags = 51
                    end
                elseif emoteEntry.AnimationOptions.EmoteMoving then
                    currentEmoteAnimFlags = 51
                elseif emoteEntry.AnimationOptions.EmoteMoving == false then
                    currentEmoteAnimFlags = 0
                elseif emoteEntry.AnimationOptions.EmoteStuck then
                    currentEmoteAnimFlags = 50
                end
            else
                currentEmoteAnimFlags = 0
            end
            if isInVehicle == 1 then
                currentEmoteAnimFlags = 51
            end
            local propAttachDelayMs = 0
            if emoteEntry.AnimationOptions then
                if emoteEntry.AnimationOptions.EmoteDuration == nil then
                    emoteEntry.AnimationOptions.EmoteDuration = -1
                    propAttachDelayMs = 0
                else
                    currentEmoteDuration = emoteEntry.AnimationOptions.EmoteDuration
                    propAttachDelayMs = emoteEntry.AnimationOptions.EmoteDuration
                end
            end
            TASK.TASK_PLAY_ANIM(PLAYER.GET_PLAYER_PED(-1), currentEmoteDictOrType, currentEmoteAnimOrScenarioName, 2.0, 2.0, currentEmoteDuration, currentEmoteAnimFlags, 0, false, false, false)
            STREAMING.REMOVE_ANIM_DICT(currentEmoteDictOrType)
            isEmotePlaying = true
            if emoteEntry.AnimationOptions and emoteEntry.AnimationOptions.Prop then
                PropName = emoteEntry.AnimationOptions.Prop
                PropBone = emoteEntry.AnimationOptions.PropBone
                PropPl1, PropPl2, PropPl3, PropPl4, PropPl5, PropPl6 = table.unpack(emoteEntry.AnimationOptions.PropPlacement)
                if emoteEntry.AnimationOptions.SecondProp then
                    SecondPropName = emoteEntry.AnimationOptions.SecondProp
                    SecondPropBone = emoteEntry.AnimationOptions.SecondPropBone
                    SecondPropPl1, SecondPropPl2, SecondPropPl3, SecondPropPl4, SecondPropPl5, SecondPropPl6 = table.unpack(emoteEntry.AnimationOptions.SecondPropPlacement)
                    emoteHasSecondProp = true
                else
                    emoteHasSecondProp = false
                end
                yieldScriptMs(propAttachDelayMs)
                AddPropToPlayer(PropName, PropBone, PropPl1, PropPl2, PropPl3, PropPl4, PropPl5, PropPl6)
                if emoteHasSecondProp then
                    AddPropToPlayer(SecondPropName, SecondPropBone, SecondPropPl1, SecondPropPl2, SecondPropPl3, SecondPropPl4, SecondPropPl5, SecondPropPl6)
                end
            end
            return true
        end
    end
    local originalNatTypeIndex, originalMatchmakingRegionIndex, currentMatchmakingRegionName, currentNatTypeName, currentHostQueueFactorName, globalPlayerBDBaseCached, latestModderDetectionByPlayer, isKScriptUserRoleReason, isIntroSplashRequested, startIntroSplashIfRequested, unregisterTosPromptRenderHandler, saveCurrentSettingsJob
    do
        originalNatTypeIndex = Memory.ReadInt(natTypeAddr)
        originalMatchmakingRegionIndex = Memory.ReadInt(geoLocRegionAddr)
        local startupMatchmakingRegionIndex = Memory.ReadInt(geoLocRegionAddr)
