        local startupNatTypeIndex = Memory.ReadInt(natTypeAddr)
        currentNatTypeName = NAT_TYPE_NAMES[startupNatTypeIndex] or "Unknown"
        local startupHostQueueFactorIndex = Memory.ReadInt(Memory.ReadLong(networkSessionPtrAddr) + 190680)
        currentHostQueueFactorName = HOST_SELECTION_MODE_NAMES[startupHostQueueFactorIndex] or "Unknown"
        local globalPlayerBDBase = ksGlobal("GlobalplayerBD")
        local unusedGlobalPlayerBDFMBase = ksGlobal("GlobalplayerBD_FM")
        local globalPlayerBDFM3Base = ksGlobal("GlobalplayerBD_FM_3")
        KS_REMOTE_PLAYER_WALLET_BASE = ksGlobal("RemotePlayerWalletBase")
        KS_REMOTE_PLAYER_WALLET_STRIDE = ksGlobal("RemotePlayerWalletStride")
        KS_REMOTE_PLAYER_TOTAL_BASE = ksGlobal("RemotePlayerTotalBase")
        globalPlayerBDBaseCached = globalPlayerBDBase

        function isNetPlayerOk(netPlayerId, shouldRequirePlaying, shouldRequireFreemodeState)
            if not shouldRequirePlaying then
                shouldRequirePlaying = false
            end
            shouldRequireFreemodeState = shouldRequireFreemodeState == nil or shouldRequireFreemodeState
            if not NETWORK.NETWORK_IS_PLAYER_ACTIVE(netPlayerId) then
                return false
            end
            if shouldRequirePlaying and not PLAYER.IS_PLAYER_PLAYING(netPlayerId) then
                return false
            end
            if shouldRequireFreemodeState and ScriptGlobal.GetInt(globalPlayerBDBase + 1 + netPlayerId * 468) ~= 4 then
                return false
            end
            return true
        end

        latestModderDetectionByPlayer = {}

        function checkDetections(suspectRockstarId)
            local detectionEntries = ModderDB.GetModderDetections(suspectRockstarId)
            if not detectionEntries then
                return nil
            end
            local latestDetection = nil
            for entryOffset = 1, #detectionEntries, 3 do
                local detectionTime = detectionEntries[entryOffset]
                local detectionCount = detectionEntries[entryOffset + 1]
                local detectionName = detectionEntries[entryOffset + 2]
                if type(detectionName) == "string" and type(detectionTime) == "number" and (not latestDetection or detectionTime > latestDetection.lastTime) then
                    latestDetection = { name = detectionName, count = detectionCount, lastTime = detectionTime }
                end
            end
            if latestDetection then
                latestModderDetectionByPlayer[suspectRockstarId] = latestDetection
                return latestDetection.name
            end
            return nil
        end

        function getTransitionState()
            return ScriptGlobal.GetInt(ksGlobal("SeamlessTransitionState")) or 0
        end

        function getTransitionStateName(transitionStateId)
            for stateName, stateCode in pairs(TransitionState) do
                if stateCode == transitionStateId then
                    return stateName
                end
            end
            return "UNKNOWN"
        end

        function isTableEmpty(candidateTable)
            return type(candidateTable) ~= "table"
        end

        if type(detectedPlayerNames) ~= "table" then
            detectedPlayerNames = {}
        end
        if type(detectedPlayerReasons) ~= "table" then
            detectedPlayerReasons = {}
