        KS_LOCAL_MODDER_WEBHOOK_REPORTED = type(KS_LOCAL_MODDER_WEBHOOK_REPORTED) == "table" and KS_LOCAL_MODDER_WEBHOOK_REPORTED or {}

        function KS_SanitizeModderWebhookText(rawText, fallbackText, maxLength)
            local sanitizedText = tostring(rawText or ""):gsub("@everyone", "(everyone)"):gsub("@here", "(here)"):gsub("<@&%d+>", "(role)"):gsub("[%c%[%]]+", " "):gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
            if sanitizedText == "" then
                sanitizedText = fallbackText
            end
            return sanitizedText:sub(1, maxLength)
        end

        function KS_ReportDetectedModder(modderPlayerId, modderName, detectionReason, rawRockstarId)
            modderPlayerId = tonumber(modderPlayerId)
            if modderPlayerId == nil or modderPlayerId < 0 or modderPlayerId >= 32 or modderPlayerId == GTA.GetLocalPlayerId() then
                return false
            end
            local safePlayerName = KS_SanitizeModderWebhookText(modderName, "Unknown", 80)
            local safeDetectionReason = KS_SanitizeModderWebhookText(detectionReason, "Unknown detection", 160)
            local canonicalRockstarId = toCanonicalPlayerIdentifier(rawRockstarId)
            local rockstarIdText = tostring(canonicalRockstarId or "")
            if not rockstarIdText:match("^%d+$") then
                rockstarIdText = "unavailable"
            end
            local truncatedRockstarId = rockstarIdText:sub(1, 20)
            local modderLabel = ("%s (Rockstar ID: %s)"):format(safePlayerName, truncatedRockstarId)
            local localNickname = "Unknown"
            if type(SOCIALCLUB) == "table" and type(SOCIALCLUB.SC_ACCOUNT_INFO_GET_NICKNAME) == "function" then
                localNickname = KS_SanitizeModderWebhookText(SOCIALCLUB.SC_ACCOUNT_INFO_GET_NICKNAME(), "Unknown", 80)
            end
            local reportedKeysForPlayer = KS_LOCAL_MODDER_WEBHOOK_REPORTED[modderPlayerId]
            if type(reportedKeysForPlayer) ~= "table" then
                reportedKeysForPlayer = {}
                KS_LOCAL_MODDER_WEBHOOK_REPORTED[modderPlayerId] = reportedKeysForPlayer
            end
            local reportKey = safePlayerName .. "\x00" .. truncatedRockstarId .. "\x00" .. safeDetectionReason
            if reportedKeysForPlayer[reportKey] == true then
                return false
            end
            local isReportLogged = logLegacyFeatureAction("modders", ("%s encountered Modder %s [%s]"):format(localNickname, modderLabel, safeDetectionReason))
            if isReportLogged then
                reportedKeysForPlayer[reportKey] = true
            end
            return isReportLogged == true
        end

        local KSCRIPT_USER_ROLE_REASONS = {
            ["K-Script User"] = true,
            ["K-Script Donator"] = true,
            ["K-Script Moderator"] = true,
            ["K-Script Admin"] = true,
            ["K-Script Developer"] = true,
        }

        function isKScriptUserRoleReason(reasonLabel)
            return KSCRIPT_USER_ROLE_REASONS[reasonLabel] == true
        end

        KS_FREE_SHOPPING_BALANCES = { [15000000] = "Free Shopping (likely Lexis User)", [20000000] = "Free Shopping" }
        KS_FREE_SHOPPING_PROBES = {}
        KS_FREE_SHOPPING_REPORTED = {}

        function KS_CheckFreeShoppingBalance(targetPlayerId, rockstarId, playerName)
            local walletBaseGlobal = tonumber(KS_REMOTE_PLAYER_WALLET_BASE) or 0
            local totalBaseGlobal = tonumber(KS_REMOTE_PLAYER_TOTAL_BASE) or 0
            local walletStride = tonumber(KS_REMOTE_PLAYER_WALLET_STRIDE) or 0
            if walletBaseGlobal <= 0 or totalBaseGlobal <= 0 or walletStride <= 0 or rockstarId == nil then
                KS_FREE_SHOPPING_PROBES[targetPlayerId] = nil
                return false
            end
            local walletReadOk, walletAmount = pcall(ScriptGlobal.GetInt, walletBaseGlobal + targetPlayerId * walletStride)
            local playerTotalOffset
            local totalReadOk, totalAmount = pcall(ScriptGlobal.GetInt, totalBaseGlobal + playerTotalOffset)
            local walletBalance = walletReadOk and tonumber(walletAmount) or nil
            local totalBalance = totalReadOk and tonumber(totalAmount) or nil
            local bankBalance = nil
            if walletBalance ~= nil and totalBalance ~= nil and walletBalance >= 0 and walletBalance <= totalBalance then
                bankBalance = totalBalance - walletBalance
            end
            local detectionReason = bankBalance ~= nil and KS_FREE_SHOPPING_BALANCES[bankBalance] or nil
            if detectionReason == nil then
                KS_FREE_SHOPPING_PROBES[targetPlayerId] = nil
                return false
            end
            local identityKey = "rid:" .. tostring(rockstarId)
            local existingProbe = KS_FREE_SHOPPING_PROBES[targetPlayerId]
            if type(existingProbe) ~= "table" or existingProbe.identity ~= identityKey or existingProbe.balance ~= bankBalance then
                KS_FREE_SHOPPING_PROBES[targetPlayerId] = { identity = identityKey, balance = bankBalance, confirmations = 1 }
                return false
            end
            existingProbe.confirmations = (tonumber(existingProbe.confirmations) or 0) + 1
            if existingProbe.confirmations < 2 then
                return false
            end
            local reportKey = identityKey .. ":" .. detectionReason
            if KS_FREE_SHOPPING_REPORTED[targetPlayerId] ~= reportKey then
                KS_FREE_SHOPPING_REPORTED[targetPlayerId] = reportKey
                ModderDB.AddModderByPlayerId(targetPlayerId, detectionReason)
                notify(("Detected %s for %s"):format(playerName, detectionReason))
                KS_ReportDetectedModder(targetPlayerId, playerName, detectionReason, rockstarId)
            end
            local playerListIndex = targetPlayerId + 1
            if detectedPlayerReasons[playerListIndex] == nil or detectedPlayerReasons[playerListIndex] == "Free Shopping" or detectedPlayerReasons[playerListIndex] == "Free Shopping (likely Lexis User)" then
                detectedPlayerNames[playerListIndex] = playerName
                detectedPlayerReasons[playerListIndex] = detectionReason
            end
            return true
        end

        function KS_ReassertAuthoritativeKScriptIdentity(targetPlayerId, rockstarId, playerName)
            targetPlayerId = tonumber(targetPlayerId)
            if targetPlayerId == nil or targetPlayerId < 0 or targetPlayerId >= 32 then
                return false
            end
            local canonicalPlayerId = toCanonicalPlayerIdentifier(rockstarId)
            local remoteStatusState = featurePlaneContext.KS_REMOTE_PLAYER_STATUS_STATE
            local playerStatus = type(remoteStatusState) == "table" and type(remoteStatusState.byPlayer) == "table" and remoteStatusState.byPlayer[targetPlayerId] or nil
            local serverReason = type(remoteStatusState) == "table" and type(remoteStatusState.serverReasonByPlayer) == "table" and remoteStatusState.serverReasonByPlayer[targetPlayerId] or nil
            if canonicalPlayerId == nil or type(playerStatus) ~= "table" or playerStatus.canonical_player_id ~= canonicalPlayerId or playerStatus.is_kscript_user ~= true or not isKScriptUserRoleReason(serverReason) then
                return false
            end
            local playerListIndex = targetPlayerId + 1
            detectedPlayerNames[playerListIndex] = playerName or Players.GetName(targetPlayerId)
            detectedPlayerReasons[playerListIndex] = serverReason
            return true
        end

        function KS_IsProtectedKScriptTarget(rawPlayerId, rockstarId, playerName)
            local targetPlayerId = tonumber(rawPlayerId)
            if targetPlayerId == nil or targetPlayerId < 0 or targetPlayerId >= 32 then
                return false
            end
            return KS_ReassertAuthoritativeKScriptIdentity(targetPlayerId, rockstarId, playerName) or isKScriptUserRoleReason(detectedPlayerReasons[targetPlayerId + 1])
        end

        function int2float(integerToConvert)
