            while not NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(entityHandle) and not ShouldUnload() and controlTimeoutMs > MISC.GET_GAME_TIMER() - requestStartMs do
                NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(entityHandle)
                Script.Yield(10)
            end
        end

