            local chosenColourId = vehicleColourIds[math.random(#vehicleColourIds)]
            return VEHICLE.SET_VEHICLE_COLOURS(vehicleHandle, chosenColourId, chosenColourId)
        end

        function getPlayerPosition(targetPlayerId)
            return targetPlayerId == GTA.GetLocalPlayerId() and ENTITY.GET_ENTITY_COORDS(getPlayerPed()) or V3.New(NETWORK.NETWORK_GET_LAST_PLAYER_POS_RECEIVED_OVER_NETWORK(targetPlayerId))
