        function getScriptTier(cheraxUid)
            local loaderTier = type(featurePlaneContext) == "table" and featurePlaneContext.KS_LOADER_SCRIPT_TIER or nil
            if loaderTier == "Admin" then
                return "Administrator"
            end
            if loaderTier == "Developer" or loaderTier == "Administrator" or loaderTier == "Moderator" or loaderTier == "Donator" or loaderTier == "Free" then
                return loaderTier
