        function KS_RuntimeNetworkSafe()
            if isUnloadRequested() then
                return false, "unload"
            end
            local nowMs = getRuntimeNowMs()
            if isIntroSplashRunning == true then
                return false, "intro-active"
            end
            if isIntroSplashRequested == true or isIntroPlaybackQueued == true then
                return false, "intro-pending"
            end
            if isRuntimeLoopDrainComplete ~= true then
                return false, "runtime-drainer-not-done"
            end
            if isRuntimeRenderReady ~= true then
                return false, "runtime-render-not-ready"
            end
            if networkQuietUntilMs and nowMs < networkQuietUntilMs then
                return false, "post-render-network-quiet"
            end
            return true, "ready"
        end

        if type(_G) == "table" then
            _G.KS_RuntimeNetworkSafe = KS_RuntimeNetworkSafe
        end

        function KS_PlayAngelAiSpeech(speechName, requestedContext, cooldownMs)
            local speechContext = tostring(requestedContext or "weapon")

            local function recordSkipReason(skipReason)
                featurePlaneContext.__ksAngelAi.lastReason = speechContext .. ":" .. tostring(skipReason or "unknown")
                return false
            end

            if isUnloadRequested() or featurePlaneContext.__ksAngelAi.unloading then
                return recordSkipReason("unload")
            end
            if not isFeaturePlaneInstallCurrent() or not isRuntimeGenerationCurrent() then
                return recordSkipReason("stale-generation")
            end
            if maintransitionActive then
                return recordSkipReason("transition")
            end
            if featurePlaneContext.__ksAngelAi.audioEnabled ~= true then
                return recordSkipReason("disabled")
            end
            if type(speechName) ~= "string" or speechName == "" then
                return recordSkipReason("speech-unavailable")
            end
            if featurePlaneContext.__ksAngelAi.playbackActive then
                return recordSkipReason("playback-busy")
            end
            if not isTableOrUserdata(AUDIO) or type(AUDIO.HAS_LOADED_MP_DATA_SET) ~= "function" or not isTableOrUserdata(Natives) or type(Natives.InvokeVoid) ~= "function" or not isTableOrUserdata(V3) or type(V3.New) ~= "function" or not isTableOrUserdata(ENTITY) or type(ENTITY.GET_ENTITY_COORDS) ~= "function" then
                return recordSkipReason("audio-api-unavailable")
            end
            local lastPlayedKey = speechContext .. "LastMs"
            local nowMs = getRuntimeNowMs()
            local lastPlayedMs = tonumber(featurePlaneContext.__ksAngelAi[lastPlayedKey] or 0) or 0
            if lastPlayedMs > 0 and nowMs - lastPlayedMs < (tonumber(cooldownMs or 1500) or 1500) then
                return recordSkipReason("cooldown")
            end
            local localPed = PLAYER.PLAYER_PED_ID()
            if localPed == nil or localPed == 0 or ENTITY.DOES_ENTITY_EXIST(localPed) ~= true then
                return recordSkipReason("ped-unavailable")
            end
            if AUDIO.HAS_LOADED_MP_DATA_SET() ~= true then
                return recordSkipReason("mp-data-set-unavailable")
            end
            local pedCoords = V3.New(ENTITY.GET_ENTITY_COORDS(localPed, false))
            if pedCoords == nil then
                return recordSkipReason("ped-coordinates-unavailable")
            end
            featurePlaneContext.__ksAngelAi.playbackActive = true
            Natives.InvokeVoid(-1340946686285742523, speechName, "XM25_AISECRETARY", pedCoords.x, pedCoords.y, pedCoords.z, "SPEECH_PARAMS_FORCE")
            featurePlaneContext.__ksAngelAi.playbackActive = false
            featurePlaneContext.__ksAngelAi[lastPlayedKey] = nowMs
            local speechCountByContext = featurePlaneContext.__ksAngelAi.speechCount
            local previousSpeechCount = tonumber(featurePlaneContext.__ksAngelAi.speechCount[speechContext]) or 0
            speechCountByContext[speechContext] = previousSpeechCount + 1
            featurePlaneContext.__ksAngelAi.lastReason = speechContext .. ":played"
            return true
        end

        local function requestIntroSplash(requestReason)
            if hasIntroSplashCompleted or isIntroSplashRunning then
                return false
            end
            isIntroSplashRequested = true
            if isRuntimeLoopDrainComplete and type(startIntroSplashIfRequested) == "function" then
                startIntroSplashIfRequested("request-after-drainer")
            end
            return true
        end

        local function markIntroSplashFinished(finishReason)
            isIntroSplashRequested = false
            isIntroSplashRunning = false
            hasIntroSplashCompleted = true
            isIntroPlaybackQueued = false
        end

        function startIntroSplashIfRequested(startReason)
            if not isFeaturePlaneInstallCurrent() then
                return false
            end
            if hasIntroSplashCompleted or isIntroSplashRunning or isIntroPlaybackQueued or not isIntroSplashRequested then
                return false
            end
            isIntroSplashRunning = true
            isIntroSplashRequested = false
            isIntroPlaybackQueued = true
            if Script.QueueJob(function()
                if not isFeaturePlaneInstallCurrent() then
                    markIntroSplashFinished("stale-generation")
                    return
                end
                local introRenderHandlerId = nil

                local function finishIntroSplash(finishReason)
                    if introRenderHandlerId ~= nil then
                        if featurePlaneInstall.handlers.intro_splash == introRenderHandlerId then
                            EventMgr.RemoveHandler(introRenderHandlerId)
                            featurePlaneInstall.handlers.intro_splash = nil
                        end
                        introRenderHandlerId = nil
                    end
                    markIntroSplashFinished(finishReason)
                end

                if ShouldUnload() then
                    finishIntroSplash("unload-before-start")
                    return
                end
                while DLC.GET_IS_LOADING_SCREEN_ACTIVE() or DLC.GET_IS_INITIAL_LOADING_SCREEN_ACTIVE() or maintransitionActive do
                    if ShouldUnload() then
                        finishIntroSplash("unload-during-loading-wait")
                        return
                    end
                    Script.Yield(250)
                end
                local playerNickname = SOCIALCLUB.SC_ACCOUNT_INFO_GET_NICKNAME()
                if type(playerNickname) ~= "string" or playerNickname == "" then
                    playerNickname = "UNKNOWN"
                end
                local scriptTierName = getScriptTier(Cherax.GetUID())
                local gameVersionLabel = getGameVersion(isGameVersionEnhanced)
                local welcomeLine = "Welcome, " .. tostring(playerNickname)
                local tierVersionLine = tostring(scriptTierName) .. "  |  " .. tostring(gameVersionLabel)
                local getBrandTexture = type(featurePlaneContext.KS_GetBrandTexture) == "function" and featurePlaneContext.KS_GetBrandTexture or nil
                local localPlayerPed = PLAYER.PLAYER_PED_ID()
                local playerCoords = V3.New(ENTITY.GET_ENTITY_COORDS(localPlayerPed, false))
                local introGreetingSpeechName = ENTITY.GET_ENTITY_MODEL(localPlayerPed) == Utils.Joaat("MP_M_Freemode_01") and "XM25_GENERIC_HI_MALE" or "XM25_GENERIC_HI_FEMALE"
                local introStartMs = Time.GetEpocheMs()
                local introDurationMs = 11500
                local fadeInDurationMs = 700
                local fadeOutDurationMs = 900

                local function clampNumber(inputNumber, lowerBound, upperBound)
                    return math.max(lowerBound, math.min(upperBound, inputNumber))
                end

                local function smoothStep(rawProgress)
                    local clampedProgress = clampNumber(rawProgress, 0.0, 1.0)
                    return clampedProgress * clampedProgress * (3.0 - 2.0 * clampedProgress)
                end

                local function scaleAlpha(baseAlpha, fadeFactor)
                    return math.floor(clampNumber(baseAlpha * fadeFactor, 0.0, 255.0))
                end

                local function measureTextWidth(measuredText)
                    local textWidth = ImGui.CalcTextSize(tostring(measuredText or ""))
                    return tonumber(textWidth) or 0
                end

                local function drawShadowedCenteredText(textCenterX, textY, textInput, textRed, textGreen, textBlue, textAlpha, fontScaleInput)
                    local labelText = tostring(textInput or "")
                    local fontScale = tonumber(fontScaleInput) or 1.0
                    ImGui.SetWindowFontScale(fontScale)
                    local textLeftX = textCenterX - measureTextWidth(labelText) * 0.5
                    local shadowAlpha = math.floor((tonumber(textAlpha) or 0) * 0.62)
                    ImGui.AddText(textLeftX - 1, textY, labelText, 12, 7, 9, shadowAlpha)
                    ImGui.AddText(textLeftX + 1, textY, labelText, 12, 7, 9, shadowAlpha)
                    ImGui.AddText(textLeftX, textY - 1, labelText, 12, 7, 9, shadowAlpha)
                    ImGui.AddText(textLeftX, textY + 1, labelText, 12, 7, 9, shadowAlpha)
                    ImGui.AddText(textLeftX, textY, labelText, textRed, textGreen, textBlue, textAlpha)
                    ImGui.SetWindowFontScale(1.0)
                end

                local function drawWaveCenteredText(waveCenterX, waveTextY, waveTextInput, waveAlpha, waveFontScaleInput, wavePhaseInput)
                    local waveText = tostring(waveTextInput or "")
                    local waveFontScale = tonumber(waveFontScaleInput) or 1.0
                    local wavePhase = tonumber(wavePhaseInput) or 0.0
                    ImGui.SetWindowFontScale(waveFontScale)
                    local waveLeftX = waveCenterX - measureTextWidth(waveText) * 0.5
                    local waveShadowAlpha = math.floor((tonumber(waveAlpha) or 0) * 0.68)
                    ImGui.AddText(waveLeftX - 1, waveTextY, waveText, 13, 6, 8, waveShadowAlpha)
                    ImGui.AddText(waveLeftX + 1, waveTextY, waveText, 13, 6, 8, waveShadowAlpha)
                    ImGui.AddText(waveLeftX, waveTextY - 1, waveText, 13, 6, 8, waveShadowAlpha)
                    ImGui.AddText(waveLeftX, waveTextY + 1, waveText, 13, 6, 8, waveShadowAlpha)
                    local charSpanCount = math.max(#waveText - 1, 1)
                    local glyphCursorX = waveLeftX
                    for charIndex = 1, #waveText do
                        local glyph = waveText:sub(charIndex, charIndex)
                        local waveBlend = (math.sin(((charIndex - 1) / charSpanCount + wavePhase) * math.pi * 2.0) + 1.0) * 0.5
                        local glyphGreen = math.floor(70 + waveBlend * 112)
                        local glyphBlue = math.floor(48 + (1.0 - waveBlend) * 45)
                        ImGui.AddText(glyphCursorX, waveTextY, glyph, 255, glyphGreen, glyphBlue, waveAlpha)
                        glyphCursorX = glyphCursorX + measureTextWidth(glyph)
                    end
                    ImGui.SetWindowFontScale(1.0)
                end

                local function renderIntroSplash()
                    if not isFeaturePlaneInstallCurrent() or ShouldUnload() then
                        return
                    end
                    local nowMs = Time.GetEpocheMs()
                    local elapsedMs = clampNumber(nowMs - introStartMs, 0, introDurationMs)
                    local remainingMs = introDurationMs - elapsedMs
                    local introProgress = smoothStep(elapsedMs / introDurationMs)
                    local overlayOpacity = 1.0
                    if elapsedMs < fadeInDurationMs then
                        overlayOpacity = smoothStep(elapsedMs / fadeInDurationMs)
                    elseif remainingMs < fadeOutDurationMs then
                        overlayOpacity = smoothStep(remainingMs / fadeOutDurationMs)
                    end
                    local screenWidth, screenHeight = ImGui.GetDisplaySize()
                    if type(screenWidth) ~= "number" or type(screenHeight) ~= "number" or screenWidth <= 0 or screenHeight <= 0 then
                        return
                    end
                    local uiScale = clampNumber(math.min(screenWidth / 1920, screenHeight / 1080), 0.7, 1.4)
                    local contentReveal = smoothStep(elapsedMs / 900)
                    local pulseWave = (math.sin(elapsedMs / 1000 * 2.4) + 1.0) * 0.5
                    local logoPulseScale = 0.94 + pulseWave * 0.16
                    local screenCenterX = screenWidth * 0.5
                    local glowSway = math.sin(elapsedMs / 1000 * 0.42)
                    local welcomeColorWave = (math.sin(elapsedMs / 1000 * 1.15) + 1.0) * 0.5
                    local titleWavePhase = elapsedMs / 5200 % 1.0
                    ImGui.AddRectFilled(0, 0, screenWidth, screenHeight, 4, 6, 10, scaleAlpha(210, overlayOpacity), 0)
                    ImGui.AddRectFilled(0, 0, screenWidth, screenHeight * 0.32, 23, 8, 12, scaleAlpha(40, overlayOpacity), 0)
                    ImGui.AddCircleFilled(screenCenterX + glowSway * 150 * uiScale, screenHeight * 0.31, 260 * uiScale, 255, 47, 58, scaleAlpha(5 + pulseWave * 3, overlayOpacity), 96)
                    ImGui.AddCircleFilled(screenCenterX - glowSway * 120 * uiScale, screenHeight * 0.72, 320 * uiScale, 255, 102, 56, scaleAlpha(3 + pulseWave * 2, overlayOpacity), 96)
                    local brandTexture = getBrandTexture and getBrandTexture() or nil
                    local overlayWindowFlags = ImGuiWindowFlags.NoDecoration | ImGuiWindowFlags.NoBackground | ImGuiWindowFlags.NoInputs | ImGuiWindowFlags.NoSavedSettings | ImGuiWindowFlags.NoFocusOnAppearing | ImGuiWindowFlags.NoBringToFrontOnFocus | ImGuiWindowFlags.NoNav
                    ImGui.SetNextWindowPos(0, 0, ImGuiCond.Always)
                    ImGui.SetNextWindowSize(screenWidth, screenHeight, ImGuiCond.Always)
                    ImGui.Begin("##KScriptIntroTypography", true, overlayWindowFlags)
                    local logoCenterY = screenHeight * 0.4 + (1.0 - contentReveal) * 22 * uiScale
                    ImGui.AddCircleFilled(screenCenterX, logoCenterY, 102 * uiScale, 255, 61, 67, scaleAlpha(8 + pulseWave * 8, overlayOpacity * contentReveal), 72)
                    ImGui.AddCircle(screenCenterX, logoCenterY, 88 * uiScale, 255, 78, 73, scaleAlpha(54 + pulseWave * 38, overlayOpacity * contentReveal), 72, 1.2)
                    local orbitAngle = elapsedMs / 1000 * 0.65
                    ImGui.AddCircleFilled(screenCenterX + math.cos(orbitAngle) * 88 * uiScale, logoCenterY + math.sin(orbitAngle) * 88 * uiScale, 2.8 * uiScale, 255, 126, 76, scaleAlpha(210, overlayOpacity * contentReveal), 18)
                    if brandTexture ~= nil then
                        ImGui.AddImageRotated(brandTexture, screenCenterX, logoCenterY, 156 * uiScale * logoPulseScale, 132 * uiScale * logoPulseScale, 0.0, scaleAlpha(255, overlayOpacity * contentReveal))
                    else
                        drawShadowedCenteredText(screenCenterX, logoCenterY - 7, "K // S", 255, 112, 70, scaleAlpha(235, overlayOpacity * contentReveal))
                    end
                    local textBlockTopY = logoCenterY + 118 * uiScale
                    local titleReveal = smoothStep((elapsedMs - 550) / 900)
                    local welcomeReveal = smoothStep((elapsedMs - 1250) / 950)
                    local tierVersionReveal = smoothStep((elapsedMs - 1950) / 950)
                    local taglineReveal = smoothStep((elapsedMs - 2700) / 1100)
                    local welcomeGreen = math.floor(176 + welcomeColorWave * 55)
                    local welcomeBlue = math.floor(168 + welcomeColorWave * 65)
                    drawWaveCenteredText(screenCenterX, textBlockTopY + (1.0 - titleReveal) * 10 * uiScale, "K - S C R I P T", scaleAlpha(250, overlayOpacity * contentReveal * titleReveal), 1.76, titleWavePhase)
                    drawShadowedCenteredText(screenCenterX, textBlockTopY + 47 * uiScale + (1.0 - welcomeReveal) * 8 * uiScale, welcomeLine, 255, welcomeGreen, welcomeBlue, scaleAlpha(240, overlayOpacity * contentReveal * welcomeReveal), 1.52)
                    drawShadowedCenteredText(screenCenterX, textBlockTopY + 86 * uiScale + (1.0 - tierVersionReveal) * 7 * uiScale, tierVersionLine, 190, 199, 211, scaleAlpha(215, overlayOpacity * contentReveal * tierVersionReveal), 1.3)
                    drawWaveCenteredText(screenCenterX, textBlockTopY + 126 * uiScale + (1.0 - taglineReveal) * 6 * uiScale, "The #1 Crashing Script", scaleAlpha(235, overlayOpacity * contentReveal * taglineReveal), 1.42, (titleWavePhase + 0.23) % 1.0)
                    local progressBarWidth = math.min(screenWidth - 96 * uiScale, 430 * uiScale)
                    local progressBarLeftX = screenCenterX - progressBarWidth * 0.5
                    local progressBarTopY = textBlockTopY + 179 * uiScale
                    ImGui.AddRectFilled(progressBarLeftX, progressBarTopY, progressBarLeftX + progressBarWidth, progressBarTopY + 3 * uiScale, 35, 41, 50, scaleAlpha(180, overlayOpacity * contentReveal), 2 * uiScale)
                    local progressFillWidth = progressBarWidth * introProgress
                    if progressFillWidth > 0 then
                        ImGui.AddRectFilled(progressBarLeftX, progressBarTopY, progressBarLeftX + progressFillWidth, progressBarTopY + 3 * uiScale, 249, 66, 76, scaleAlpha(220, overlayOpacity * contentReveal), 2 * uiScale)
                        ImGui.AddCircleFilled(progressBarLeftX + progressFillWidth, progressBarTopY + 1.5 * uiScale, 2.5 * uiScale, 255, 140, 91, scaleAlpha(225, overlayOpacity * contentReveal), 18)
                    end
                    ImGui.End()
                end

                if AUDIO.HAS_LOADED_MP_DATA_SET() then
                    Natives.InvokeVoid(-1340946686285742523, introGreetingSpeechName, "XM25_AISECRETARY", playerCoords.x, playerCoords.y, playerCoords.z, "SPEECH_PARAMS_FORCE")
                    featurePlaneContext.__ksAngelAi.introSpeechGeneration = runtimeLoadGeneration
                end
                introRenderHandlerId = EventMgr.RegisterHandler(eLuaEvent.ON_PRESENT, renderIntroSplash)
                if introRenderHandlerId == false or introRenderHandlerId == nil then
                    introRenderHandlerId = nil
                    finishIntroSplash("render-handler-rejected")
                    return
                end
                featurePlaneInstall.handlers.intro_splash = introRenderHandlerId
                while isFeaturePlaneInstallCurrent() and not ShouldUnload() do
                    local waitNowMs = Time.GetEpocheMs()
                    if not (introDurationMs > waitNowMs - introStartMs) then
                        break
                    end
                    Script.Yield(16)
                end
                finishIntroSplash(ShouldUnload() and "unload" or "complete")
            end) == false then
                markIntroSplashFinished("queue-rejected")
                return false
            end
            return true
        end

        function initiateIntro()
            if KS_INTRO_CONTROLLER_STARTED then
                return
            end
            KS_INTRO_CONTROLLER_STARTED = true

            function requestRuntimeStart(startReason)
                if not isFeaturePlaneInstallCurrent() then
                    return false
                end
                if isRuntimeActivated then
                    return true
                end
                if not HasAcceptedTermsOfService() then
                    deferredRuntimeStartReason = tostring(startReason or "tos-pending")
                    return true
                end
                if isRuntimeStartDeferred then
                    deferredRuntimeStartReason = tostring(startReason or "deferred")
                    return true
                end
                isRuntimeActivated = true
                isRuntimeRenderReady = false
                if startRuntimeLoopDrainer(startReason or "runtime-ready") == false then
                    isRuntimeActivated = false
                    return false
                end
                return true
            end

            local function tryFinalizeTosAcceptance(acceptanceReason)
                if hasTosAcceptanceBeenHandled then
                    return true
                end
                if not isFeaturePlaneInstallCurrent() or not HasAcceptedTermsOfService() then
                    return false
                end
                hasTosAcceptanceBeenHandled = true
                unregisterTosPromptRenderHandler()
                requestIntroSplash(acceptanceReason or "tos-accepted")
                requestRuntimeStart(acceptanceReason or "tos-accepted")
                return true
            end

            if HasAcceptedTermsOfService() then
                tryFinalizeTosAcceptance("tos-already-accepted")
                return
            end
            kScriptTosGateActive = true
            kScriptTosPromptStartedAt = nil
            kScriptTosClosing = false
            kScriptTosCloseStartedAt = nil
            kScriptTosCloseAction = nil
            registerTosPromptRenderHandler()
            if isTosAcceptanceWatcherRegistered then
                return
            end
            isTosAcceptanceWatcherRegistered = true
            if Script.RegisterLooped(function()
                if hasTosAcceptanceBeenHandled then
                    Script.Yield(60000)
                    return
                end
                if ShouldUnload() then
                    hasTosAcceptanceBeenHandled = true
                    unregisterTosPromptRenderHandler()
                    Script.Yield(60000)
                    return
                end
                if tryFinalizeTosAcceptance("tos-accepted") then
                    Script.Yield(60000)
                    return
                end
                if tosPromptRenderHandlerId == nil then
                    registerTosPromptRenderHandler()
                end
                Script.Yield(50)
            end) == false then
                isTosAcceptanceWatcherRegistered = false
                unregisterTosPromptRenderHandler()
                SetShouldUnload("ui_registration_failed")
            end
        end

