        function deleteEntityLocal(entityHandle)
            local entityHandleBuffer = Memory.AllocInt()
            local entityPointer = GTA.HandleToPointer(entityHandle)
            if entityPointer == nil then
                return
            end
            NetworkObjectMgr.UnregisterNetworkObject(entityPointer.NetObject, 15, true, true)
            Memory.WriteInt(entityHandleBuffer, entityHandle)
            ENTITY.DELETE_ENTITY(entityHandleBuffer)
            Memory.Free(entityHandleBuffer)
        end

