        function playerZeroCrash()
            local targetPlayerId = Utils.GetSelectedPlayer()
            local targetPlayer = Players.GetById(targetPlayerId)
            if not targetPlayer then
                return
            end
            local targetGamerInfo = targetPlayer:GetGamerInfo()
            if not targetGamerInfo then
                return
            end
            if Utils.GetSelectedPlayer() ~= GTA.GetLocalPlayerId() and Utils.GetSelectedPlayer() ~= nil then
                if blacklistRIDList[targetGamerInfo.RockstarId] then
                    if not isDev then
                        blacklistSound()
                        logLegacyFeatureAction("nogger", ("%s(%i) tried to Crash a Blacklisted Player (%s)!"):format(Players.GetName(GTA.GetLocalPlayerId()), Cherax.GetUID(), Players.GetName(Utils.GetSelectedPlayer())))
                        return
                    end
                elseif KS_IsProtectedKScriptTarget(targetPlayerId, targetGamerInfo.RockstarId, Players.GetName(targetPlayerId)) then
                    if not isDev then
                        blacklistSound("forbidden_protected_runtime_target")
                        logLegacyFeatureAction("nogger", ("%s(%i) tried to Crash another K-Script User (%s)!"):format(Players.GetName(GTA.GetLocalPlayerId()), Cherax.GetUID(), Players.GetName(Utils.GetSelectedPlayer())))
                        return
                    end
                end
            else
                return
            end
            if onCrashCooldown and not isDev then
                notify("Another Crash is running, please wait for it to Finish!")
                return
            end

            function log()
                local targetTags = Players.GetTags(targetPlayerId)
                local isTargetFriend = false
                if string.find(targetTags, "[F]", 1, true) then
                    isTargetFriend = true
                end
                logLegacyFeatureAction("lol", ("%s used Overfuck Crash against %s with UID %i, isSupporter %s, is Target Friend?: %s"):format(PLAYER.GET_PLAYER_NAME(GTA.GetLocalPlayerId()), Players.GetName(Utils.GetSelectedPlayer()), Cherax.GetUID(), tostring(isSupporter), tostring(isTargetFriend)))
            end

            Script.QueueJob(log)
            onCrashCooldown = true
            local targetPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(Utils.GetSelectedPlayer())
            local targetPosX, targetPosY, targetPosZ = ENTITY.GET_ENTITY_COORDS(targetPed, true)
            for _ = 0, 300 do
                local franklinAltPed = GTA.CreatePed(2937109846, 28, targetPosX, targetPosY, targetPosZ, ENTITY.GET_ENTITY_HEADING(targetPed))
                local michaelPed = GTA.CreatePed(Utils.Joaat("PLAYER_ZERO"), 28, targetPosX, targetPosY, targetPosZ, ENTITY.GET_ENTITY_HEADING(targetPed))
                local trevorPed = GTA.CreatePed(Utils.Joaat("PLAYER_TWO"), 28, targetPosX, targetPosY, targetPosZ, ENTITY.GET_ENTITY_HEADING(targetPed))
                local michaelAltPed = GTA.CreatePed(Utils.Joaat("P_Michael_02"), 28, targetPosX, targetPosY, targetPosZ, ENTITY.GET_ENTITY_HEADING(targetPed))
                Script.Yield(50)
                deleteEntityLocal(franklinAltPed)
                deleteEntityLocal(michaelPed)
                deleteEntityLocal(trevorPed)
