        function normalizeCountry(countryName, countryCode)
            if not countryName then
                return nil
            end
            countryName = tostring(countryName):gsub("^%s+", ""):gsub("%s+$", "")
            if countryCode and countryCodeMap[countryCode] then
                return countryCodeMap[countryCode]
            end
            return countryName
        end

        function isCountryEnabled(rawCountry)
            local normalizedCountry = normalizeCountry(rawCountry)
            if not normalizedCountry then
                return false
            end
            return table.contains(EnabledCountries, normalizedCountry)
        end

        function rebuildEnabledCountries()
            EnabledCountries = {}
            for _, countryName in ipairs(countriesToKick) do
                local countryFeatureHash = countryHashes[countryName]
                local countryFeature = countryFeatureHash and FeatureMgr.GetFeature(countryFeatureHash)
                if countryFeature and countryFeature:IsToggled() then
                    table.insert(EnabledCountries, countryName)
                end
            end
        end

        IPLookupState = IPLookupState or {}
        IPLookupInFlight = IPLookupInFlight or {}

        function CheckIPLocation(ipAddress, onLookupComplete)
            ipAddress = tostring(ipAddress or "")
            if ipAddress == "" then
                if onLookupComplete then
                    onLookupComplete(nil)
                end
                return false
            end
            if IPLookupInFlight[ipAddress] then
                if onLookupComplete then
                    table.insert(IPLookupInFlight[ipAddress], onLookupComplete)
                end
                return true
            end
            IPLookupInFlight[ipAddress] = onLookupComplete and { onLookupComplete } or {}

            local function finishLookup(lookupResult)
                local waitingCallbacks = IPLookupInFlight[ipAddress]
                IPLookupInFlight[ipAddress] = nil
                if type(waitingCallbacks) == "table" then
                    for _, waitingCallback in ipairs(waitingCallbacks) do
                        waitingCallback(lookupResult)
                    end
                end
            end

            Script.QueueJob(function(queuedIpAddress)
                local ksBridge = __ks_bridge_v3
                if type(ksBridge) ~= "table" or ksBridge.version ~= 3 or type(ksBridge.request) ~= "function" then
                    finishLookup(nil)
                    return
                end
                local requestStatus, lookupResponse = ksBridge.request("lookup.ip", { ip = queuedIpAddress }, 10000)
                if requestStatus ~= "ok" or type(lookupResponse) ~= "table" then
                    finishLookup(nil)
                    return
                end
                finishLookup({
                    ok = true,
                    ip = queuedIpAddress,
                    city = lookupResponse.city,
                    region = lookupResponse.region,
                    country = lookupResponse.country,
                    countryCode = lookupResponse.country_code,
                    isHosting = lookupResponse.hosting == true,
                    isProxy = lookupResponse.proxy == true,
                })
            end, ipAddress)
            return true
        end

        function punishPlayer(targetPlayerId)
            local localPlayerId = GTA.GetLocalPlayerId()
            if targetPlayerId == localPlayerId then
                return
            end
            local ipInfo = Players.GetIPInfo(targetPlayerId)
            if not ipInfo then
                return
            end
            local playerCountry = normalizeCountry(ipInfo.country, ipInfo.countryCode)

            local function punishIfCountryEnabled(resolvedCountry)
                if not resolvedCountry then
                    return
                end
                if not table.contains(EnabledCountries, resolvedCountry) then
                    return
                end
                local playerName = Players.GetName(targetPlayerId)
                if FeatureMgr.IsFeatureEnabled(Utils.Joaat("SessionPurifierAutoCrash")) then
                    local crashPlayerFeature = FeatureMgr.GetFeatureByName("Crash Player", targetPlayerId)
                    local auxCannonCrashFeature = FeatureMgr.GetFeatureByName("Auxiliary Cannon Crash", targetPlayerId)
                    local scriptEventCrashFeature = FeatureMgr.GetFeatureByName("Script Event Crash", targetPlayerId)
                    if crashPlayerFeature then
                        crashPlayerFeature:TriggerCallback()
                    end
                    if auxCannonCrashFeature then
                        auxCannonCrashFeature:TriggerCallback()
                    end
                    if scriptEventCrashFeature then
                        scriptEventCrashFeature:TriggerCallback()
                    end
                    notify(("Crashed %s"):format(playerName .. " (" .. resolvedCountry .. ")"))
                else
                    NETWORK.NETWORK_SESSION_KICK_PLAYER(targetPlayerId)
                    notify(("Kicked %s"):format(playerName .. " (" .. resolvedCountry .. ")"))
                end
            end

            if playerCountry == "NA" or playerCountry == "Unknown" or playerCountry == "Hidden" then
                local playerIp = Players.GetIP(targetPlayerId):ToString(false)
                if type(playerIp) ~= "string" or playerIp == "" then
                    return
                end
                local lookupStateKey = tostring(targetPlayerId) .. ":" .. playerIp
                if IPLookupState[lookupStateKey] then
                    return
                end
                IPLookupState[lookupStateKey] = true
                CheckIPLocation(playerIp, function(ipLocation)
                    IPLookupState[lookupStateKey] = nil
                    if not ipLocation or not ipLocation.country then
                        return
                    end
                    local lookedUpCountry = normalizeCountry(ipLocation.country, ipLocation.countryCode)
                    punishIfCountryEnabled(lookedUpCountry)
                end)
                return
            end
            punishIfCountryEnabled(playerCountry)
        end

        function onPurificationPlayerJoin(joiningPlayerId)
            if not purificationEnabled then
                return
            end
            rebuildEnabledCountries()
            if #EnabledCountries == 0 then
                return
            end
            punishPlayer(joiningPlayerId)
        end

        for kickCountryIndex, kickCountryName in ipairs(countriesToKick) do
            local kickCountryFeatureHash = Utils.Joaat(kickCountryName)
            countryHashes[kickCountryName] = kickCountryFeatureHash
            FeatAdd(kickCountryFeatureHash, kickCountryName, eFeatureType.Toggle, "Block players from " .. kickCountryName, function(countryToggleFeature)
                if countryToggleFeature:IsToggled() then
                    if not table.contains(EnabledCountries, kickCountryName) then
                        table.insert(EnabledCountries, kickCountryName)
                    end
                else
                    for enabledCountryIndex = #EnabledCountries, 1, -1 do
                        if EnabledCountries[enabledCountryIndex] == kickCountryName then
                            table.remove(EnabledCountries, enabledCountryIndex)
                            break
                        end
                    end
                end
            end, false)
        end
