        FeatAdd(Utils.Joaat("purification_search"), "Purification Search", eFeatureType.InputText, "Search for a country to yeet")
        purificationFeature = FeatAdd(Utils.Joaat("PurificationMain"), "Get these THINGS out of my session", eFeatureType.Toggle, "Kick or crash players from currently selected countries default is kick", function(purificationToggle)
            purificationEnabled = purificationToggle:IsToggled()
            if purificationEnabled then
                rebuildEnabledCountries()
                if initRun and #EnabledCountries == 0 then
                    Script.QueueJob(function()
                        while initRun and #EnabledCountries == 0 do
                            if ShouldUnload() then
                                return
                            end
                            Script.Yield(500)
                        end
                        rebuildEnabledCountries()
                        if #EnabledCountries == 0 then
                            purificationEnabled = false
                            purificationToggle:SetBoolValue(false):OnClick()
                            return
                        end
                        if featurePlaneInstall.handlers.protection_purification_join == nil then
                            featurePlaneInstall.handlers.protection_purification_join = featurePlaneInstall:RegisterManagedEventHandler("protection_purification_join", eLuaEvent.ON_PLAYER_JOIN, onPurificationPlayerJoin)
                        end
                    end)
                    return
                end
                if #EnabledCountries == 0 then
                    notify("No countries selected!")
                    purificationEnabled = false
                    purificationToggle:SetBoolValue(false):OnClick()
                    return
                end
                if featurePlaneInstall.handlers.protection_purification_join == nil then
                    featurePlaneInstall.handlers.protection_purification_join = featurePlaneInstall:RegisterManagedEventHandler("protection_purification_join", eLuaEvent.ON_PLAYER_JOIN, onPurificationPlayerJoin)
                end
            elseif featurePlaneInstall.handlers.protection_purification_join ~= nil then
                featurePlaneInstall:RemoveManagedEventHandler("protection_purification_join")
                featurePlaneInstall.handlers.protection_purification_join = nil
            end
        end)

        function processPurificationMain()
            if ShouldUnload() then
                purificationEnabled = false
                if featurePlaneInstall.handlers.protection_purification_join ~= nil then
                    featurePlaneInstall:RemoveManagedEventHandler("protection_purification_join")
                    featurePlaneInstall.handlers.protection_purification_join = nil
                end
                return
            end
            if not purificationFeature or not purificationFeature:IsToggled() or not purificationEnabled or initRun then
                Script.Yield(2000)
                return
            end
            rebuildEnabledCountries()
            if #EnabledCountries == 0 then
                notify("No countries selected!")
                purificationEnabled = false
                purificationFeature:SetBoolValue(false):OnClick()
                if featurePlaneInstall.handlers.protection_purification_join ~= nil then
                    featurePlaneInstall:RemoveManagedEventHandler("protection_purification_join")
                    featurePlaneInstall.handlers.protection_purification_join = nil
                end
                return
            end
            Script.Yield(1000)
        end

        function table.contains(searchList, soughtValue)
            for _, listEntry in ipairs(searchList) do
                if listEntry == soughtValue then
                    return true
                end
            end
            return false
        end

