        function KS_ModderDisplayFeatureForReason(detectionReason)
            if type(detectionReason) ~= "string" then
                return H_MODDER_DISPLAY_OTHER
            end
            local lowerReason = detectionReason:lower()
            if lowerReason:find("modded health", 1, true) then
                return H_MODDER_DISPLAY_HEALTH
            end
            if lowerReason:find("ped spawn", 1, true) or lowerReason:find("spawned ped", 1, true) or lowerReason:find("vehicle spawn", 1, true) or lowerReason:find("spawned vehicle", 1, true) or lowerReason:find("ptfx", 1, true) or lowerReason:find("particle effect", 1, true) then
                return H_MODDER_DISPLAY_SPAWN
            end
            if lowerReason:find("car meet", 1, true) then
                return H_MODDER_DISPLAY_CAR_MEET
            end
            if lowerReason:find("duper", 1, true) or lowerReason:find("dupe", 1, true) then
                return H_MODDER_DISPLAY_DUPER
            end
            if lowerReason == "rac" or lowerReason:find("rockstar anti cheat", 1, true) or lowerReason:find("rac detection", 1, true) then
                return H_MODDER_DISPLAY_RAC
            end
            return H_MODDER_DISPLAY_OTHER
        end

        function KS_IsAuthoritativeKScriptDisplayDetection(detectionSlot, detectionReason)
            if not isKScriptUserRoleReason(detectionReason) then
                return false
            end
            local remotePlayerId = math.tointeger((tonumber(detectionSlot) or 0) - 1)
            if remotePlayerId == nil or remotePlayerId < 0 or remotePlayerId >= 32 then
                return false
            end
            local remoteStatusState = featurePlaneContext.KS_REMOTE_PLAYER_STATUS_STATE
            local remotePlayerStatus = type(remoteStatusState) == "table" and type(remoteStatusState.byPlayer) == "table" and remoteStatusState.byPlayer[remotePlayerId] or nil
            return type(remotePlayerStatus) == "table"
        end

        function KS_ShouldShowDetectedModder(detectionSlot, detectionReason)
            if KS_IsAuthoritativeKScriptDisplayDetection(detectionSlot, detectionReason) then
                return true
            end
            return FeatureMgr.IsFeatureEnabled(KS_ModderDisplayFeatureForReason(detectionReason))
        end

        function KS_HasAuthoritativeKScriptUserDetection()
            for detectionSlot, detectedName in pairs(detectedPlayerNames) do
                if detectedName ~= nil and KS_IsAuthoritativeKScriptDisplayDetection(detectionSlot, detectedPlayerReasons[detectionSlot]) then
                    return true
                end
            end
            return false
        end

        function KS_ForceDetectedModderDisplayForKScriptUser()
            if not KS_HasAuthoritativeKScriptUserDetection() then
                return false
            end
            local modderDisplayFeature = FeatureMgr.GetFeature(H_TOGGLE_MODDER_DISPLAY)
            if modderDisplayFeature ~= nil and not FeatureMgr.IsFeatureEnabled(H_TOGGLE_MODDER_DISPLAY) then
                modderDisplayFeature:SetValue(true)
            end
            return true
        end

