        savingSettings = false
        saveCurrentSettingsJob = (function()
            local settingsSchemaVersion = 1
            local maxSavedFeatures = 2048
            local maxScannedFeatures = 4096
            local maxTextValueLength = 4096
            local maxDescriptionLength = 256
            local maxEncodedBytes = 524288

            local function isSaveContextCurrent()
                return isFeaturePlaneInstallCurrent() and isRuntimeGenerationCurrent() and not isUnloadRequested()
            end

            local function isRealNumber(candidateNumber)
                return type(candidateNumber) == "number" and candidateNumber == candidateNumber
            end

            local function validateBoundedText(candidateText, maxLength)
                if type(candidateText) ~= "string" or maxLength < #candidateText or candidateText:find("\x00", 1, true) then
                    return nil
                end
                return candidateText
            end

            local function readFeatureSaveValue(targetFeature, featureType)
                local featureValue = nil
                if featureType == eFeatureType.Toggle then
                    featureValue = targetFeature:IsToggled()
                elseif featureType == eFeatureType.Combo then
                    featureValue = targetFeature:GetListIndex()
                elseif featureType ~= eFeatureType.SliderInt and featureType ~= eFeatureType.InputInt then
                    if featureType == eFeatureType.SliderFloat then
                        featureValue = targetFeature:GetFloatValue()
                    elseif featureType == eFeatureType.InputText then
                        featureValue = targetFeature:GetStringValue()
                    elseif featureType == eFeatureType.InputColor4 then
                        featureValue = { targetFeature:GetColor() }
                    end
                else
                    featureValue = targetFeature:GetIntValue()
                end
                if featureValue == nil then
                    return true, nil
                end
                if featureType == eFeatureType.Toggle then
                    if type(featureValue) ~= "boolean" then
                        return false, nil, "invalid_toggle"
                    end
                else
                    if featureType == eFeatureType.Combo or featureType == eFeatureType.SliderInt or featureType == eFeatureType.InputInt then
                        if isRealNumber(featureValue) and featureValue == math.floor(featureValue) then
                            goto acceptFeatureValue
                        end
                        local isIntegerValid = false
                        local integerFailureValue = nil
                        local integerErrorCode = "invalid_integer"
                        do
                            return isIntegerValid, integerFailureValue, integerErrorCode
                        end
                        goto acceptFeatureValue
                    end
                    if featureType == eFeatureType.SliderFloat then
                        if not isRealNumber(featureValue) then
                            return false, nil, "invalid_float"
                        end
                    elseif featureType == eFeatureType.InputText then
                        if not validateBoundedText(featureValue, maxTextValueLength) then
                            return false, nil, "invalid_string"
                        end
                    elseif featureType == eFeatureType.InputColor4 then
                        if type(featureValue) ~= "table" or #featureValue ~= 4 then
                            return false, nil, "invalid_color"
                        end
                        for colorChannelIndex = 1, 4 do
                            if not isRealNumber(featureValue[colorChannelIndex]) or featureValue[colorChannelIndex] < 0 or featureValue[colorChannelIndex] > 255 then
                                return false, nil, "invalid_color"
                            end
                        end
                    end
                end
                ::acceptFeatureValue::
                return true, featureValue
            end

            local function deleteFileIfExists(filePath)
                if FileMgr.DoesFileExist(filePath) then
                    FileMgr.DeleteFile(filePath)
                end
            end

            return function()
                if not isSaveContextCurrent() then
                    return false, "stale_generation"
                end
                if type(menuRootPath) ~= "string" or menuRootPath == "" or #menuRootPath > 32000 or menuRootPath:find("\x00", 1, true) then
                    return false, "invalid_settings_path"
                end
                local settingsFilePath = menuRootPath .. "\\DefaultConfig.json"
                local tempSettingsFilePath = settingsFilePath .. ".tmp"
                local savedFeatureEntries = {}
                local savedFeatureCount = 0
                local scannedFeatureCount = 0
                if contextFeatureRegistry then
                    if contextFeatureRegistry.hashAndName then
                        for featureHashKey, registeredFeatureName in pairs(contextFeatureRegistry.hashAndName) do
                            scannedFeatureCount = scannedFeatureCount + 1
                            if scannedFeatureCount > maxScannedFeatures then
                                return false, "feature_scan_limit"
                            end
                            if scannedFeatureCount % 25 == 0 then
                                Script.Yield(0)
                                if not isSaveContextCurrent() then
                                    return false, "stale_generation"
                                end
                            end
                            local featureHashNumber = tonumber(featureHashKey)
                            local registeredFeature = featureHashNumber and FeatureMgr.GetFeature(featureHashNumber)
                            if registeredFeature then
                                local registeredFeatureType = registeredFeature:GetType()
                                local isValueReadOk, savedValue, valueReadError = readFeatureSaveValue(registeredFeature, registeredFeatureType)
                                if not isValueReadOk then
                                    return false, valueReadError
                                end
                                if savedValue ~= nil then
                                    savedFeatureCount = savedFeatureCount + 1
                                    if savedFeatureCount > maxSavedFeatures then
                                        return false, "feature_count_limit"
                                    end
                                    local featureDescription = validateBoundedText(tostring(registeredFeatureName or ""), maxDescriptionLength)
                                    if not featureDescription then
                                        return false, "invalid_description"
                                    end
                                    savedFeatureEntries[tostring(featureHashNumber)] = { value = savedValue, description = featureDescription }
                                end
                            elseif isDev then
                                Logger.Log(eLogColor.YELLOW, "K-Script", ("Missing feature for hash %s"):format(tostring(featureHashKey)))
                            end
                        end
                    end
                else
                    return false, "feature_registry_unavailable"
                end
                if storedDisplayPositions.GameInfoDisplay then
                    if not isRealNumber(storedDisplayPositions.GameInfoDisplay.x) or not isRealNumber(storedDisplayPositions.GameInfoDisplay.y) then
                        return false, "invalid_game_info_position"
                    end
                    savedFeatureEntries.GameInfoDisplayPosX = { value = storedDisplayPositions.GameInfoDisplay.x, description = "Game Info Display X Position" }
                    savedFeatureEntries.GameInfoDisplayPosY = { value = storedDisplayPositions.GameInfoDisplay.y, description = "Game Info Display Y Position" }
                elseif isDev then
                    Logger.Log(eLogColor.YELLOW, "K-Script", "GameInfoDisplayPos not set, skipping save.")
                end
                if storedDisplayPositions.ModderDisplay then
                    if not isRealNumber(storedDisplayPositions.ModderDisplay.x) or not isRealNumber(storedDisplayPositions.ModderDisplay.y) then
                        return false, "invalid_modder_position"
                    end
                    savedFeatureEntries.ModderDisplayPosX = { value = storedDisplayPositions.ModderDisplay.x, description = "Modder Display X Position" }
                    savedFeatureEntries.ModderDisplayPosY = { value = storedDisplayPositions.ModderDisplay.y, description = "Modder Display Y Position" }
                elseif isDev then
                    Logger.Log(eLogColor.YELLOW, "K-Script", "ModderDisplayPos not set, skipping save.")
                end
                Script.Yield(0)
                if not isSaveContextCurrent() then
                    return false, "stale_generation"
                end
                local encodedSettingsJson = json.encode({ schemaVersion = settingsSchemaVersion, features = savedFeatureEntries }, { indent = true })
                if type(encodedSettingsJson) ~= "string" or encodedSettingsJson == "" then
                    return false, "json_encode_failed"
                end
                if #encodedSettingsJson > maxEncodedBytes then
                    return false, "encoded_size_limit"
                end
                Script.Yield(0)
                if not isSaveContextCurrent() then
                    return false, "stale_generation"
                end
                deleteFileIfExists(tempSettingsFilePath)
                if FileMgr.WriteFileContent(tempSettingsFilePath, encodedSettingsJson, false) ~= true then
                    deleteFileIfExists(tempSettingsFilePath)
                    return false, "temp_file_write_failed"
                end
                if FileMgr.ReadFileContent(tempSettingsFilePath) ~= encodedSettingsJson then
                    deleteFileIfExists(tempSettingsFilePath)
                    return false, "temp_file_verification_failed"
                end
                if not isSaveContextCurrent() then
                    deleteFileIfExists(tempSettingsFilePath)
                    return false, "stale_generation"
                end
                local finalWriteResult = FileMgr.WriteFileContent(settingsFilePath, encodedSettingsJson, false)
                deleteFileIfExists(tempSettingsFilePath)
                if finalWriteResult ~= true then
                    return false, "file_write_failed"
                end
                notify("Successfully saved DefaultConfig.json!")
                return true
            end
        end)()
        FeatAdd(Utils.Joaat("savekscript"), "Save Current Settings", eFeatureType.Button, "", function(saveSettingsFeature)
            return KSDispatchRuntimeFeature("savekscript", saveSettingsFeature, { invocationSource = "feature_button" })
