        FeatureMgr.AddPlayerFeature(Utils.Joaat("remotehostkick"), "Shared Host Kick", eFeatureType.Button, "Remotely Host Kicks People if another K-Script User is the Session Host.", function(sharedHostKickFeature)
            return KSDispatchPlayerFeature("remotehostkick", sharedHostKickFeature)
        end)
        KS_HOST_KICK_VT_GET_GAMER_INFO = 104
        KS_HOST_KICK_HANDLE_OFFSET = 200
        KS_HOST_KICK_BLACKLIST_OFFSET = 209736
        KS_HOST_KICK_REASON = 4
        KS_HOST_KICK_BLACKLIST_REASON = 0
        KS_HOST_KICK_STATE = { invalidBuffer = nil, responsePatched = false, queue = {}, busy = false }

        function KSRestoreHostKickResponse()
            if KS_HOST_KICK_STATE.responsePatched then
                for _, patchAddress in ipairs({ featurePlaneContext.KSHostKickResponsePatchA, featurePlaneContext.KSHostKickResponsePatchB }) do
                    if type(patchAddress) == "number" and patchAddress ~= 0 and Memory.ReadByte(patchAddress) & 255 == 14 then
                        Memory.WriteByte(patchAddress, 5)
                    end
                end
            end
            KS_HOST_KICK_STATE.responsePatched = false
        end

        function KSPatchHostKickResponse()
            if KS_HOST_KICK_STATE.responsePatched then
                return true
            end
            local responsePatchAddresses = { featurePlaneContext.KSHostKickResponsePatchA, featurePlaneContext.KSHostKickResponsePatchB }
            for _, checkedPatchAddress in ipairs(responsePatchAddresses) do
                if type(checkedPatchAddress) ~= "number" or checkedPatchAddress == 0 or Memory.ReadByte(checkedPatchAddress) & 255 ~= 5 then
                    return false
                end
            end
            for _, patchAddressToWrite in ipairs(responsePatchAddresses) do
                Memory.WriteByte(patchAddressToWrite, 14)
            end
            KS_HOST_KICK_STATE.responsePatched = true
            return true
        end

        function KSHostKickContextReady()
            local hostKickPatchFunction = KSPatchHostKickResponse
            return hostKickPatchFunction == "number" and hostKickPatchFunction
        end

        function KSRunHostKick(targetPlayerId)
            if not isFeaturePlaneInstallCurrent() or isUnloadRequested() then
                return "unloading"
            end
            if not KS_IsNetworkPlayerSessionReady() then
                return "notready"
            end
            if targetPlayerId == GTA.GetLocalPlayerId() then
                return "self"
            end
            if not NETWORK.NETWORK_IS_PLAYER_CONNECTED(targetPlayerId) then
                return "noconn"
            end
            if not NETWORK.NETWORK_IS_HOST() then
                return "nothost"
            end
            if not KSHostKickContextReady() then
                return "unresolved"
            end
            local targetNetPlayer = Players.GetById(targetPlayerId)
            local netPlayerAddress = targetNetPlayer and targetNetPlayer:GetAddress()
            if not netPlayerAddress or netPlayerAddress == 0 then
                return "noplayer"
            end
            local netPlayerVtable = Memory.ReadLong(netPlayerAddress)
            if not netPlayerVtable or netPlayerVtable == 0 then
                return "novtable"
            end
            local getGamerInfoFunction = Memory.ReadLong(netPlayerVtable + KS_HOST_KICK_VT_GET_GAMER_INFO)
            if not getGamerInfoFunction or getGamerInfoFunction == 0 then
                return "nogamerfn"
            end
            local returnValueBuffer = Memory.LuaCallCFunctionWithReturnValue(getGamerInfoFunction, netPlayerAddress)
            if not returnValueBuffer or returnValueBuffer == 0 then
                return "nogamerinfo"
            end
            local gamerInfoAddress = Memory.ReadLong(returnValueBuffer)
            local returnBufferSize = Memory.SizeOf(returnValueBuffer)
            if type(returnBufferSize) == "number" and returnBufferSize > 0 then
                Memory.Free(returnValueBuffer)
            end
            if not gamerInfoAddress or gamerInfoAddress == 0 then
                return "nogamerinfo"
            end
            local networkSessionAddress = Memory.ReadLong(featurePlaneContext.KSHostKickSessionPointer)
            if not networkSessionAddress or networkSessionAddress == 0 then
                return "nosession"
            end
            if not KS_HOST_KICK_STATE.invalidBuffer then
                KS_HOST_KICK_STATE.invalidBuffer = Memory.Alloc(16)
                if KS_HOST_KICK_STATE.invalidBuffer and KS_HOST_KICK_STATE.invalidBuffer ~= 0 then
                    Memory.MemSet(KS_HOST_KICK_STATE.invalidBuffer, 0, 16)
                end
            end
            if not KS_HOST_KICK_STATE.invalidBuffer or KS_HOST_KICK_STATE.invalidBuffer == 0 then
                return "noalloc"
            end
            local gamerHandleAddress = gamerInfoAddress + KS_HOST_KICK_HANDLE_OFFSET
            Memory.LuaCallCFunction(featurePlaneContext.KSHostKickFunction, networkSessionAddress, gamerHandleAddress, 0, KS_HOST_KICK_REASON, 0, KS_HOST_KICK_STATE.invalidBuffer)
            Memory.LuaCallCFunction(featurePlaneContext.KSHostKickBlacklistFunction, networkSessionAddress + KS_HOST_KICK_BLACKLIST_OFFSET, gamerHandleAddress, KS_HOST_KICK_BLACKLIST_REASON)
            return "ok"
        end

        function KSEnqueueHostKick(targetPlayerId)
            if #KS_HOST_KICK_STATE.queue >= 8 then
                notify("Host Kick queue is full.")
                return
            end
            KS_HOST_KICK_STATE.queue[#KS_HOST_KICK_STATE.queue + 1] = targetPlayerId
            if KS_HOST_KICK_STATE.busy then
                return
            end
            KS_HOST_KICK_STATE.busy = true
            if Script.QueueJob(function()
                while #KS_HOST_KICK_STATE.queue > 0 and isFeaturePlaneInstallCurrent() and not isUnloadRequested() do
                    local queuedPlayerId = table.remove(KS_HOST_KICK_STATE.queue, 1)
                    local queuedPlayerName = Players.GetName(queuedPlayerId) or tostring(queuedPlayerId)
                    local hostKickResult = KSRunHostKick(queuedPlayerId)
                    local hostKickMessage = ({
                        ok = ("Host kicked %s as a Rockstar Games administrator."):format(queuedPlayerName),
                        self = "You cannot Host Kick yourself.",
                        noconn = "Host Kick target is no longer connected.",
                        notready = "Host Kick requires a fully loaded online session.",
                        nothost = "Host Kick requires you to be the Session Host.",
                        unresolved = "Host Kick engine functions are unavailable for this game build.",
                        noplayer = "Host Kick could not resolve the target network player.",
                        novtable = "Host Kick could not resolve the target player interface.",
                        nogamerfn = "Host Kick could not resolve the target gamer-info function.",
                        nogamerinfo = "Host Kick could not read the target gamer information.",
                        nosession = "Host Kick could not read the network session.",
                        noalloc = "Host Kick could not allocate its call buffer.",
                        unloading = "Host Kick was cancelled because K-Script is unloading.",
                    })[hostKickResult] or ("Host Kick failed: %s"):format(tostring(hostKickResult))
                    notify(hostKickMessage)
                    yieldScriptMs(60)
                end
                KS_HOST_KICK_STATE.busy = false
            end) == false then
                KS_HOST_KICK_STATE.busy = false
                KS_HOST_KICK_STATE.queue = {}
                notify("Host Kick could not start its worker.")
            end
        end

