        function spawnWindmillsAtLscLocations()
            local windmillModelHash = Utils.Joaat("prop_windmill_01")
            local enabledLocationCount = 0
            local spawnedWindmillCount = 0
            for _, spawnLocation in ipairs(LSC_WINDMILL_SPAWN_LOCATIONS) do
                if enabledWindmillSpawnLocations[spawnLocation.state] then
                    enabledLocationCount = enabledLocationCount + 1
                end
            end
            if enabledLocationCount == 0 then
                return false, spawnedWindmillCount, enabledLocationCount
            end
            if not STREAMING.IS_MODEL_VALID(windmillModelHash) then
                return false, spawnedWindmillCount, enabledLocationCount
            end
            STREAMING.REQUEST_MODEL(windmillModelHash)
            local modelLoadAttempts = 0
            while not STREAMING.HAS_MODEL_LOADED(windmillModelHash) and modelLoadAttempts < 500 do
                STREAMING.REQUEST_MODEL(windmillModelHash)
                Script.Yield(10)
                modelLoadAttempts = modelLoadAttempts + 1
            end
            if not STREAMING.HAS_MODEL_LOADED(windmillModelHash) then
                STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(windmillModelHash)
                return false, spawnedWindmillCount, enabledLocationCount
            end

            local function spawnWindmillAtLocation(targetLocation)
                GTA.ForceScriptHost(Utils.Joaat("main_persistent"))
                Script.ExecuteAsScript("main_persistent", function()
                    STREAMING.REQUEST_COLLISION_AT_COORD(targetLocation.x, targetLocation.y, targetLocation.z)
                    STREAMING.REQUEST_COLLISION_FOR_MODEL(windmillModelHash)
                    STREAMING.REQUEST_ADDITIONAL_COLLISION_AT_COORD(targetLocation.x, targetLocation.y, targetLocation.z)
                    local windmillEntity = GTA.CreateWorldObject(windmillModelHash, targetLocation.x, targetLocation.y, targetLocation.z, true, true)
                    if windmillEntity ~= 0 and ENTITY.DOES_ENTITY_EXIST(windmillEntity) then
                        table.insert(yeetwindmills, windmillEntity)
                        ENTITY.SET_ENTITY_LOD_DIST(windmillEntity, 100000)
                        if not NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(windmillEntity) then
                            NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(windmillEntity)
                            local controlRequestAttempts = 0
                            while not NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(windmillEntity) and controlRequestAttempts < 50 do
                                Script.Yield(10)
                                controlRequestAttempts = controlRequestAttempts + 1
                            end
                        end
                        ENTITY.SET_ENTITY_ROTATION(windmillEntity, 90.0, 0.0, 0.0, 2, true)
                        ENTITY.FREEZE_ENTITY_POSITION(windmillEntity, true)
                        spawnedWindmillCount = spawnedWindmillCount + 1
                    end
                end)
            end

            for _, windmillLocation in ipairs(LSC_WINDMILL_SPAWN_LOCATIONS) do
                if enabledWindmillSpawnLocations[windmillLocation.state] then
                    spawnWindmillAtLocation(windmillLocation)
                end
            end
            STREAMING.SET_MODEL_AS_NO_LONGER_NEEDED(windmillModelHash)
            didSpawnLscWindmills = spawnedWindmillCount > 0
            return didSpawnLscWindmills, spawnedWindmillCount, enabledLocationCount
        end

