        FeatAdd(Utils.Joaat("louderRadion_Toggle"), "Enable Louder Radio", eFeatureType.Toggle, "Note: You can control the Radio Stations by using the normal Radio Wheel when holding 'Q'.", function(louderRadioFeature)
            while louderRadioFeature:IsToggled() and not ShouldUnload() do
