                        local playerPitch, playerRoll, playerYaw = ENTITY.GET_ENTITY_ROTATION(PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId()), 0)
                        if vehicleSpeed * 2.236936 > 15 then
                            ENTITY.SET_ENTITY_HEADING(currentVehicle, ENTITY.GET_ENTITY_HEADING(currentVehicle))
                            ENTITY.FREEZE_ENTITY_POSITION(currentVehicle, true)
                            Script.Yield(1)
                            ENTITY.FREEZE_ENTITY_POSITION(currentVehicle, false)
                            ENTITY.SET_ENTITY_ROTATION(currentVehicle, playerPitch, playerRoll, playerYaw, 0, true)
                            ENTITY.SET_ENTITY_VELOCITY(currentVehicle, velocityX, velocityY, velocityZ)
