                    if not revealPlayersFeature:IsToggled() then
                        revealPlayersFeature:Toggle()
                    end
                    local partyBusModelHash = Utils.Joaat("pbus2")
                    request_model(partyBusModelHash)
                    local busAngleStep = 2 * math.pi / volume
                    for busIndex = 1, volume do
                        local busAngle = (busIndex - 1) * busAngleStep + rot
                        local busOffsetX = size * math.cos(busAngle)
                        local circleRadius = size
                        local busAngleSine = math.sin(busAngle)
                        local spawnX, spawnY, spawnZ = ENTITY.GET_OFFSET_FROM_ENTITY_IN_WORLD_COORDS(PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId()), busOffsetX, circleRadius * busAngleSine, -35)
                        local partyBus = GTA.SpawnVehicle(partyBusModelHash, spawnX, spawnY, spawnZ, 0)
                        local partyBusNetId = NETWORK.NETWORK_GET_NETWORK_ID_FROM_ENTITY(partyBus)
