                            VEHICLE.SET_VEHICLE_EXTRA(partyBus, vehicleExtraId, -1)
                        end
                        VEHICLE.SET_VEHICLE_ENGINE_ON(partyBus, true, true, false)
                        VEHICLE.SET_VEHICLE_KEEP_ENGINE_ON_WHEN_ABANDONED(partyBus, true)
                        AUDIO.SET_VEHICLE_RADIO_ENABLED(partyBus, true)
                        AUDIO.SET_VEH_HAS_NORMAL_RADIO(partyBus)
                        AUDIO.SET_VEH_RADIO_STATION(partyBus, current_radio_station)
                        AUDIO.SET_VEHICLE_RADIO_LOUD(partyBus)
                        table.insert(party_buses, partyBus)
                    end
                else
                    local busSlotOffsets = {}
                    local slotAngleStep = 2 * math.pi / volume
                    for slotIndex = 1, volume do
                        local slotAngle = (slotIndex - 1) * slotAngleStep
                        local unrotatedX = size * math.cos(slotAngle)
                        local unrotatedY = size * math.sin(slotAngle)
                        busSlotOffsets[slotIndex] = {
                            x = unrotatedX * math.cos(math.rad(circleRotation)) - unrotatedY * math.sin(math.rad(circleRotation)),
                            y = unrotatedX * math.sin(math.rad(circleRotation)) + unrotatedY * math.cos(math.rad(circleRotation)),
                        }
                    end
                    for busSlotIndex, existingPartyBus in ipairs(party_buses) do
                        ENTITY.DETACH_ENTITY(existingPartyBus, false, false)
                        if PED.IS_PED_IN_ANY_VEHICLE(PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId()), true) then
                            local playerVehicle = PED.GET_VEHICLE_PED_IS_IN(PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId()), true)
                            StaticH = shouldKeepPartyBusesAtGround and -1 * ENTITY.GET_ENTITY_HEIGHT_ABOVE_GROUND(playerVehicle) + 1 or StaticH_b
                            ENTITY.ATTACH_ENTITY_TO_ENTITY(existingPartyBus, playerVehicle, -1, busSlotOffsets[busSlotIndex].x * xOffset, busSlotOffsets[busSlotIndex].y * yOffset, StaticH + height + heightp, yaw, roll, -1 * (360 / volume) + 360 / volume * busSlotIndex + rot, false, false, false, false, 2, true, 0)
                        else
                            StaticH = shouldKeepPartyBusesAtGround and -1 * ENTITY.GET_ENTITY_HEIGHT_ABOVE_GROUND(PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId())) + 1 or 0
                            ENTITY.ATTACH_ENTITY_TO_ENTITY(existingPartyBus, PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(GTA.GetLocalPlayerId()), -1, busSlotOffsets[busSlotIndex].x * xOffset, busSlotOffsets[busSlotIndex].y * yOffset, StaticH + height + heightp, yaw, roll, -1 * (360 / volume) + 360 / volume * busSlotIndex + rot, false, false, false, true, 2, true, 0)
                        end
                        AUDIO.SET_VEH_RADIO_STATION(existingPartyBus, current_radio_station)
                        AUDIO.SET_VEH_FORCED_RADIO_THIS_FRAME(existingPartyBus)
                        ENTITY.SET_ENTITY_VISIBLE(existingPartyBus, isPartyBusVisible)
                    end
                    for _, staticBus in ipairs(static_buses) do
                        AUDIO.SET_VEH_RADIO_STATION(staticBus, current_radio_station)
                        AUDIO.SET_VEH_FORCED_RADIO_THIS_FRAME(staticBus)
                    end
                end
                Script.Yield(10)
            end
            for _, busToDelete in ipairs(party_buses) do
                DeleteEnt(busToDelete)
            end
            party_buses = {}
            local mobileRadioFeatureToDisable = FeatureMgr.GetFeatureByName("Mobile Radio")
            if mobileRadioFeatureToDisable:IsToggled() then
                mobileRadioFeatureToDisable:Toggle()
            end
            local revealPlayersFeatureToDisable = FeatureMgr.GetFeatureByName("Reveal All Players")
            if revealPlayersFeatureToDisable:IsToggled() then
                revealPlayersFeatureToDisable:Toggle()
            end
            if AUDIO.GET_PLAYER_RADIO_STATION_NAME() ~= nil then
                current_radio_station = AUDIO.GET_PLAYER_RADIO_STATION_NAME()
                AUDIO.SET_RADIO_TO_STATION_NAME("OFF")
            end
            for _, staticBusToDelete in ipairs(static_buses) do
                DeleteEnt(staticBusToDelete)
            end
            static_buses = {}
        end)
