        FeatAdd(Utils.Joaat("louderRadio_animToggle"), "Animation", eFeatureType.Toggle, "Animate them buses!", function(animationToggleFeature)
            local louderRadioToggleFeature = FeatureMgr.GetFeature(Utils.Joaat("louderRadion_Toggle"))
            while louderRadioToggleFeature:IsToggled() and animationToggleFeature:IsToggled() and not ShouldUnload() do
                isPartyBusAnimationCycleActive = true
                if needsPartyBusSizeSnapshot then
                    oldSize = size
                    needsPartyBusSizeSnapshot = false
                end
                while size > animMin do
                    size = size - PARTY_BUS_ANIM_SIZE_STEP
                    yieldScriptMs(PARTY_BUS_ANIM_STEP_DELAY_MS)
                end
                while size < animMax do
                    size = size + PARTY_BUS_ANIM_SIZE_STEP
                    yieldScriptMs(PARTY_BUS_ANIM_STEP_DELAY_MS)
                end
                isPartyBusAnimationCycleActive = false
