                    Script.Yield(0)
                end
                size = oldSize
                needsPartyBusSizeSnapshot = true
            end
        end)
        local debugEventState = { featureHash = Utils.Joaat("dbug"), dataPtr = nil, recent = {}, lastPruneMs = 0 }
        featurePlaneContext.__ksDebugEvents = debugEventState

        function KS_ReleaseDebugEventBuffer()
            local debugEvents = featurePlaneContext.__ksDebugEvents
            if debugEvents.dataPtr ~= nil then
                Memory.Free(debugEvents.dataPtr)
                debugEvents.dataPtr = nil
            end
        end

        function KS_DebugEventNowMs()
            if isTableOrUserdata(Time) and type(Time.GetEpocheMs) == "function" then
                local convertToNumber = tonumber
                local rawEpochMs = Time.GetEpocheMs()
                return convertToNumber(rawEpochMs) or 0
            end
            return math.floor(os.clock() * 1000)
        end

        function KS_DebugEventShouldNotify(debugEventKey)
            local debugEvents = featurePlaneContext.__ksDebugEvents
            local currentTimeMs = KS_DebugEventNowMs()
            local previousSeenMs = debugEvents.recent[debugEventKey]
            debugEvents.recent[debugEventKey] = currentTimeMs
            if currentTimeMs - debugEvents.lastPruneMs >= 5000 then
                for recentEventKey, eventSeenMs in pairs(debugEvents.recent) do
                    if currentTimeMs - eventSeenMs >= 10000 then
                        debugEvents.recent[recentEventKey] = nil
                    end
                end
                debugEvents.lastPruneMs = currentTimeMs
            end
            return previousSeenMs == nil
        end

        function KS_EnsureDebugEventBuffer()
            local debugEvents = featurePlaneContext.__ksDebugEvents
            if debugEvents.dataPtr == nil then
                debugEvents.dataPtr = Memory.Alloc(448)
            end
            return debugEvents.dataPtr
        end

        FeatAdd(featurePlaneContext.__ksDebugEvents.featureHash, "Debug Mode", eFeatureType.Toggle, "More Advanced Game Info, notifies about Game Tasks and so on", function(debugModeFeature)
