        featurePlaneContext.__ksAdvancedDrawing = { enabled = false, suppressed = false, restoreGameInfo = false, restoreModder = false }

        function KS_SetAdvancedDrawingSuppressed(shouldSuppress)
            local advancedDrawingState = featurePlaneContext.__ksAdvancedDrawing
            shouldSuppress = shouldSuppress == true
            if shouldSuppress == advancedDrawingState.suppressed then
                return
            end
            if shouldSuppress then
                advancedDrawingState.restoreGameInfo = gameInfoDisplay == true
                advancedDrawingState.restoreModder = modderDisplay == true
                if advancedDrawingState.restoreGameInfo then
                    gameInfoDisplay = false
                end
                if advancedDrawingState.restoreModder then
                    modderDisplay = false
                end
            else
                if advancedDrawingState.restoreGameInfo then
                    gameInfoDisplay = true
                end
                if advancedDrawingState.restoreModder then
                    modderDisplay = true
                end
                advancedDrawingState.restoreGameInfo = false
                advancedDrawingState.restoreModder = false
            end
            advancedDrawingState.suppressed = shouldSuppress
        end

        local advancedDrawingFeature = FeatAdd(Utils.Joaat("disabledraw"), "Advanced Drawing", eFeatureType.Toggle, "Auto disables drawing of the Info Windows when you Enter Interiors, Shops etc...", function(advancedDrawingToggle)
