            local isUnloadPending = ShouldUnload()
            local isToggledMethod = advancedDrawingToggle.IsToggled
            advancedDrawingState.enabled = not isToggledMethod and isToggledMethod
            if not featurePlaneContext.__ksAdvancedDrawing.enabled then
                KS_SetAdvancedDrawingSuppressed(false)
            end
        end)
