                local isInteractionMenuOpen = SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH(piMenuScriptHash) > 0 and ScriptLocal.GetInt(piMenuScriptHash, 1779) ~= 0
                local currentInteriorId = getPlayerCurrentInterior(localPlayerId)
                local currentShopId = getPlayerCurrentShop(localPlayerId)
                KS_SetAdvancedDrawingSuppressed(-1 ~= currentShopId)
            end
            Script.Yield(500)
        end

