        local vehicleFlyCollidedEntityHandle = nil

        function getControl()
            if ShouldUnload() or vehicleFlyCollidedEntityHandle == nil then
                Script.Yield(100)
                return
            end
            if not FeatureMgr.IsFeatureEnabled(Utils.Joaat("vehicleflymode")) or not KS_IsNetworkPlayerSessionReady() then
                vehicleFlyCollidedEntityHandle = nil
                featurePlaneContext.__ksControlRequest.entity = 0
                featurePlaneContext.__ksControlRequest.deadlineMs = 0
                Script.Yield(250)
                return
            end
            local collidedEntityHandle = tonumber(vehicleFlyCollidedEntityHandle) or 0
            if collidedEntityHandle == 0 or type(ENTITY) ~= "table" or type(ENTITY.DOES_ENTITY_EXIST) ~= "function" or not ENTITY.DOES_ENTITY_EXIST(collidedEntityHandle) or ENTITY.IS_ENTITY_A_PED(collidedEntityHandle) or ENTITY.IS_ENTITY_AN_OBJECT(collidedEntityHandle) then
                vehicleFlyCollidedEntityHandle = nil
                featurePlaneContext.__ksControlRequest.entity = 0
                featurePlaneContext.__ksControlRequest.deadlineMs = 0
                Script.Yield(100)
                return
            end
            if NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(collidedEntityHandle) then
                vehicleFlyCollidedEntityHandle = nil
                featurePlaneContext.__ksControlRequest.entity = 0
                featurePlaneContext.__ksControlRequest.deadlineMs = 0
                Script.Yield(100)
                return
            end
            local currentTimeMs = getRuntimeNowMs()
            if featurePlaneContext.__ksControlRequest.entity ~= collidedEntityHandle then
                featurePlaneContext.__ksControlRequest.entity = collidedEntityHandle
                featurePlaneContext.__ksControlRequest.deadlineMs = currentTimeMs + 300
            end
            if currentTimeMs >= (tonumber(featurePlaneContext.__ksControlRequest.deadlineMs) or 0) then
                vehicleFlyCollidedEntityHandle = nil
                featurePlaneContext.__ksControlRequest.entity = 0
                featurePlaneContext.__ksControlRequest.deadlineMs = 0
                Script.Yield(100)
                return
            end
            NETWORK.NETWORK_REQUEST_CONTROL_OF_ENTITY(collidedEntityHandle)
            Script.Yield(50)
        end

        function ShouldCollideHandler(collidingEntityPointer, otherEntityPointer, unusedCollisionInfoA, unusedCollisionInfoB, unusedCollisionInfoC, unusedCollisionInfoD, unusedCollisionInfoE, unusedCollisionInfoF)
            if collidingEntityPointer == GTA.GetLocalVehicle() and FeatureMgr.IsFeatureEnabled(Utils.Joaat("vehicleflymode")) then
                vehicleFlyCollidedEntityHandle = GTA.PointerToHandle(otherEntityPointer)
            end
            return true
        end

        function lshift(valueToShift, bitCount)
            return valueToShift * 2 ^ bitCount
        end

        function rshift(valueToShift, bitCount)
            return math.floor(valueToShift / 2 ^ bitCount)
        end

