        local SYSTEM_EMOTE_MODE_ANIM_OPTIONS = {
            default = { EmoteLoop = true, EmoteMoving = true },
            stationary = { EmoteLoop = true, EmoteMoving = false },
            freeze = { EmoteStuck = true },
            freeze_alt = { EmoteStuck = true },
            once = false,
            noloop = false,
            fullcontrol = { EmoteLoop = true, EmoteMoving = true },
        }

        local function normalizeEmoteAliasAlnum(aliasInput)
            return tostring(aliasInput or ""):lower():gsub("^%s+", ""):gsub("%s+$", ""):gsub("[^%w]", "")
        end

        local function canonicalizeEmoteAlias(aliasText)
            return tostring(aliasText or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
        end

        local function collectSortedEmoteAliasKeys(aliasKeyedTable)
            local sortedAliasKeys = {}
            for aliasKey in pairs(aliasKeyedTable) do
                sortedAliasKeys[#sortedAliasKeys + 1] = aliasKey
            end
            table.sort(sortedAliasKeys, function(leftAlias, rightAlias)
                local leftAliasLower = tostring(leftAlias):lower()
                local rightAliasText = tostring(rightAlias)
                local leftTieBreakKey = rightAliasText
                local rightAliasLower = rightAliasText.lower(leftTieBreakKey)
                local rightTieBreakKey
                if leftAliasLower == rightAliasLower then
                    leftTieBreakKey = tostring(leftAlias)
                    rightTieBreakKey = tostring(rightAlias)
                end
                return leftTieBreakKey < rightTieBreakKey or leftAliasLower < rightAliasLower
            end)
            return sortedAliasKeys
        end

        local takenEmoteAliasSet = {}

        local function markEmoteAliasesTaken(emoteDefinitionsByAlias)
            for emoteAlias in pairs(emoteDefinitionsByAlias) do
                local canonicalEmoteAlias = canonicalizeEmoteAlias(emoteAlias)
                takenEmoteAliasSet[canonicalEmoteAlias] = true
            end
        end

        markEmoteAliasesTaken(emoteCatalog.Emotes)
        markEmoteAliasesTaken(emoteCatalog.Dances)
        markEmoteAliasesTaken(emoteCatalog.PropEmotes)
        local rejectedSystemEmoteCount = 0
        for systemEmoteDefinitionIndex, systemEmoteDefinition in ipairs(systemEmoteDefinitions) do
            local canonicalSystemEmoteAlias = canonicalizeEmoteAlias(systemEmoteDefinition.alias)
            local normalizedSystemEmoteAlias = normalizeEmoteAliasAlnum(canonicalSystemEmoteAlias)
            local systemEmoteModeName = canonicalizeEmoteAlias(systemEmoteDefinition.mode)
            if systemEmoteModeName == "" then
                systemEmoteModeName = "default"
            end
            local systemEmoteModeOptions = SYSTEM_EMOTE_MODE_ANIM_OPTIONS[systemEmoteModeName]
            local isSystemEmoteAliasTaken = takenEmoteAliasSet[canonicalSystemEmoteAlias]
            if canonicalSystemEmoteAlias ~= "" and normalizedSystemEmoteAlias ~= "" and systemEmoteDefinition.dict ~= "" and systemEmoteDefinition.anim ~= "" and systemEmoteDefinition.label ~= "" and systemEmoteModeOptions ~= nil then
                if isSystemEmoteAliasTaken then
                    rejectedSystemEmoteCount = rejectedSystemEmoteCount + 1
                    print("[K-Script] SYSTEM emote rejected: alias collision " .. canonicalSystemEmoteAlias)
                else
                    local systemEmoteEntry = { systemEmoteDefinition.dict, systemEmoteDefinition.anim, systemEmoteDefinition.label }
                    if systemEmoteModeOptions then
                        systemEmoteEntry.AnimationOptions = {
                            EmoteLoop = systemEmoteModeOptions.EmoteLoop,
                            EmoteMoving = systemEmoteModeOptions.EmoteMoving,
                            EmoteStuck = systemEmoteModeOptions.EmoteStuck,
                        }
                    end
                    emoteCatalog.Emotes[canonicalSystemEmoteAlias] = systemEmoteEntry
                    takenEmoteAliasSet[canonicalSystemEmoteAlias] = true
                end
            else
                rejectedSystemEmoteCount = rejectedSystemEmoteCount + 1
                print("[K-Script] SYSTEM emote rejected: malformed definition " .. tostring(systemEmoteDefinition.alias))
            end
        end
        if rejectedSystemEmoteCount > 0 then
            print("[K-Script] SYSTEM emote validation rejected " .. tostring(rejectedSystemEmoteCount) .. " definitions")
        end
        KS_SYSTEM_EMOTE_ALIASES = collectSortedEmoteAliasKeys(emoteCatalog.Emotes)
        KS_SYSTEM_DANCE_ALIASES = collectSortedEmoteAliasKeys(emoteCatalog.Dances)
        KS_SYSTEM_PROP_EMOTE_ALIASES = collectSortedEmoteAliasKeys(emoteCatalog.PropEmotes)
        local emoteSearchIndexList = {}
        local emoteSearchIndexByCanonical = {}

        local function countEmoteCharacterFrequencies(normalizedSearchText)
            local byteCountsByCode = {}
            for byteIndex = 1, #normalizedSearchText do
                local byteCode = normalizedSearchText:byte(byteIndex)
                byteCountsByCode[byteCode] = (byteCountsByCode[byteCode] or 0) + 1
            end
            return byteCountsByCode
        end

        local function addEmoteCatalogToSearchIndex(emoteDefinitionsByAlias, sortedAliasList)
            for _, emoteAlias in ipairs(sortedAliasList) do
                local canonicalAlias = canonicalizeEmoteAlias(emoteAlias)
                local normalizedAlias = normalizeEmoteAliasAlnum(emoteAlias)
                local emoteDefinition = emoteDefinitionsByAlias[emoteAlias]
                local emoteLabel = tostring(emoteDefinition[3] or emoteAlias)
                local searchWords = {}
                for searchWord in (canonicalAlias .. " " .. emoteLabel:lower()):gmatch("[%w]+") do
                    searchWords[#searchWords + 1] = searchWord
                end
                local searchIndexEntry = {
                    alias = emoteAlias,
                    canonical = canonicalAlias,
                    normalized = normalizedAlias,
                    label = emoteLabel,
                    words = searchWords,
                    characterCounts = countEmoteCharacterFrequencies(normalizedAlias),
                    definition = emoteDefinition,
                }
                emoteSearchIndexList[#emoteSearchIndexList + 1] = searchIndexEntry
                emoteSearchIndexByCanonical[canonicalAlias] = searchIndexEntry
            end
        end

        addEmoteCatalogToSearchIndex(emoteCatalog.Emotes, KS_SYSTEM_EMOTE_ALIASES)
        addEmoteCatalogToSearchIndex(emoteCatalog.Dances, KS_SYSTEM_DANCE_ALIASES)
        addEmoteCatalogToSearchIndex(emoteCatalog.PropEmotes, KS_SYSTEM_PROP_EMOTE_ALIASES)
        table.sort(emoteSearchIndexList, function(leftEntry, rightEntry)
            local leftSortKey = leftEntry.canonical
            local rightSortKey = rightEntry.canonical
            if leftSortKey == rightSortKey then
                leftSortKey = tostring(leftEntry.alias)
                rightSortKey = tostring(rightEntry.alias)
            end
            return leftSortKey < rightSortKey
        end)

        function KSParseEmoteCommand(commandInputText)
            local commandName, commandArgumentText = tostring(commandInputText or ""):match("^%s*/([%a]+)%s+(.-)%s*$")
            if not commandName or commandName:lower() ~= "e" then
                return nil
            end
            local emoteQuery = tostring(commandArgumentText or ""):gsub("^%s+", ""):gsub("%s+$", "")
            local canonicalQuery = canonicalizeEmoteAlias(emoteQuery)
            return {
                query = emoteQuery,
                canonical = canonicalQuery,
                normalized = normalizeEmoteAliasAlnum(emoteQuery),
                cancel = canonicalQuery == "c" or canonicalQuery == "cancel",
            }
        end

        local function boundedEmoteLevenshteinDistance(queryText, candidateText, maxDistance)
            local queryLength = #queryText
            local candidateLength = #candidateText
            if queryLength == 0 or maxDistance < math.abs(queryLength - candidateLength) or queryLength > 48 or candidateLength > 48 then
                return maxDistance + 1
            end
            local previousDistanceRow = {}
            for prefixLength = 0, candidateLength do
                previousDistanceRow[prefixLength] = prefixLength
            end
            for queryIndex = 1, queryLength do
                local currentDistanceRow = { [0] = queryIndex }
                local rowMinimumDistance = currentDistanceRow[0]
                local queryByte = queryText:byte(queryIndex)
                for candidateIndex = 1, candidateLength do
                    local diagonalDistance = previousDistanceRow[candidateIndex - 1]
                    local candidateByte = candidateText:byte(candidateIndex)
                    local cellDistance = math.min(previousDistanceRow[candidateIndex] + 1, currentDistanceRow[candidateIndex - 1] + 1, diagonalDistance + (queryByte == candidateByte and 0 or 1))
                    currentDistanceRow[candidateIndex] = cellDistance
                    if rowMinimumDistance > cellDistance then
                        rowMinimumDistance = cellDistance
                    end
                end
                if maxDistance < rowMinimumDistance then
                    return maxDistance + 1
                end
                previousDistanceRow = currentDistanceRow
            end
            return previousDistanceRow[candidateLength]
        end

        local function findEmoteSubsequenceMatch(queryText, candidateText)
            local queryByteIndex = 1
            local matchStartPosition = 0
            for candidateByteIndex = 1, #candidateText do
                if candidateText:byte(candidateByteIndex) == queryText:byte(queryByteIndex) then
                    if matchStartPosition == 0 then
                        matchStartPosition = candidateByteIndex
                    end
                    queryByteIndex = queryByteIndex + 1
                    if queryByteIndex > #queryText then
                        return true, candidateByteIndex - matchStartPosition + 1 - #queryText, matchStartPosition
                    end
                end
            end
            return false, 0, 0
        end

        function KSFindEmoteSuggestions(commandText, maxSuggestions)
            local parsedCommand = KSParseEmoteCommand(commandText)
            if not parsedCommand or parsedCommand.cancel then
                return {}, 0
            end
            local exactIndexEntry = emoteSearchIndexByCanonical[parsedCommand.canonical]
            if exactIndexEntry then
                local exactSuggestion = {
                    alias = exactIndexEntry.alias,
                    label = exactIndexEntry.label,
                    definition = exactIndexEntry.definition,
                    rank = 1,
                    distance = 0,
                    position = 1,
                }
                return { exactSuggestion }, 1, exactSuggestion
            end
            local rankedSuggestions = {}
            local normalizedQuery = parsedCommand.normalized
            local queryLength = #normalizedQuery
            local matchTier = 2
            for _, prefixEntry in ipairs(emoteSearchIndexList) do
                if normalizedQuery == "" or prefixEntry.normalized:sub(1, queryLength) == normalizedQuery then
                    rankedSuggestions[#rankedSuggestions + 1] = {
                        alias = prefixEntry.alias,
                        label = prefixEntry.label,
                        definition = prefixEntry.definition,
                        rank = 2,
                        distance = #prefixEntry.normalized - queryLength,
                        position = 1,
                    }
                end
            end
            if #rankedSuggestions == 0 then
                matchTier = 3
                for _, wordPrefixEntry in ipairs(emoteSearchIndexList) do
                    local shortestRemainingLength = nil
                    for _, entryWord in ipairs(wordPrefixEntry.words) do
                        if entryWord:sub(1, queryLength) == normalizedQuery then
                            local remainingWordLength = #entryWord - queryLength
                            if shortestRemainingLength == nil or shortestRemainingLength > remainingWordLength then
                                shortestRemainingLength = remainingWordLength
                            end
                        end
                    end
                    if shortestRemainingLength ~= nil then
                        rankedSuggestions[#rankedSuggestions + 1] = {
                            alias = wordPrefixEntry.alias,
                            label = wordPrefixEntry.label,
                            definition = wordPrefixEntry.definition,
                            rank = 3,
                            distance = shortestRemainingLength,
                            position = 1,
                        }
                    end
                end
            end
            if #rankedSuggestions == 0 then
                matchTier = 4
                for _, substringEntry in ipairs(emoteSearchIndexList) do
                    local substringPosition = substringEntry.normalized:find(normalizedQuery, 1, true)
                    if substringPosition then
                        rankedSuggestions[#rankedSuggestions + 1] = {
                            alias = substringEntry.alias,
                            label = substringEntry.label,
                            definition = substringEntry.definition,
                            rank = 4,
                            distance = substringPosition - 1,
                            position = substringPosition,
                        }
                    end
                end
            end
            if #rankedSuggestions == 0 then
                matchTier = 5
                for _, subsequenceEntry in ipairs(emoteSearchIndexList) do
                    local isSubsequenceMatch, subsequenceGapCount, subsequenceStart = findEmoteSubsequenceMatch(normalizedQuery, subsequenceEntry.normalized)
                    if isSubsequenceMatch then
                        rankedSuggestions[#rankedSuggestions + 1] = {
                            alias = subsequenceEntry.alias,
                            label = subsequenceEntry.label,
                            definition = subsequenceEntry.definition,
                            rank = 5,
                            distance = subsequenceGapCount,
                            position = subsequenceStart,
                        }
                    end
                end
            end
            if #rankedSuggestions == 0 and queryLength >= 3 then
                matchTier = 6
                local queryCharacterCounts = countEmoteCharacterFrequencies(normalizedQuery)
                for _, fuzzyEntry in ipairs(emoteSearchIndexList) do
                    local lengthDifference = math.abs(#fuzzyEntry.normalized - queryLength)
                    if lengthDifference <= 2 then
                        local sharedCharacterCount = 0
                        for characterByte, queryCharacterCount in pairs(queryCharacterCounts) do
                            sharedCharacterCount = sharedCharacterCount + math.min(queryCharacterCount, fuzzyEntry.characterCounts[characterByte] or 0)
                        end
                        if sharedCharacterCount >= math.max(queryLength, #fuzzyEntry.normalized) - 2 then
                            local editDistance = boundedEmoteLevenshteinDistance(normalizedQuery, fuzzyEntry.normalized, 2)
                            if editDistance <= 2 then
                                rankedSuggestions[#rankedSuggestions + 1] = {
                                    alias = fuzzyEntry.alias,
                                    label = fuzzyEntry.label,
                                    definition = fuzzyEntry.definition,
                                    rank = 6,
                                    distance = editDistance,
                                    position = lengthDifference,
                                }
                            end
                        end
                    end
                end
            end
            table.sort(rankedSuggestions, function(leftSuggestion, rightSuggestion)
                if leftSuggestion.distance ~= rightSuggestion.distance then
                    return leftSuggestion.distance < rightSuggestion.distance
                end
                if leftSuggestion.position ~= rightSuggestion.position then
                    return leftSuggestion.position < rightSuggestion.position
                end
                local leftAlias = tostring(leftSuggestion.alias)
                local rightAlias = tostring(rightSuggestion.alias)
                local leftAliasLower = leftAlias:lower()
                local rightAliasLower = rightAlias:lower()
                if leftAliasLower ~= rightAliasLower then
                    return leftAliasLower < rightAliasLower
                end
                return leftAlias < rightAlias
            end)
            local suggestionCount = #rankedSuggestions
            local topSuggestions = {}
            local suggestionLimit = math.min(tonumber(maxSuggestions) or 5, 5)
            for suggestionIndex = 1, math.min(suggestionCount, suggestionLimit) do
                topSuggestions[suggestionIndex] = rankedSuggestions[suggestionIndex]
            end
            local unambiguousSuggestion = nil
            if suggestionCount == 1 then
                unambiguousSuggestion = rankedSuggestions[1]
            elseif suggestionCount > 1 and matchTier >= 5 then
                local firstSuggestion = rankedSuggestions[1]
                local secondSuggestion = rankedSuggestions[2]
                if not (firstSuggestion.distance < secondSuggestion.distance) then
                    if firstSuggestion.distance ~= secondSuggestion.distance then
                        goto returnSuggestions
                    end
                    if not (firstSuggestion.position < secondSuggestion.position) then
                        goto returnSuggestions
                    end
                end
                unambiguousSuggestion = firstSuggestion
            end
            ::returnSuggestions::
            return topSuggestions, suggestionCount, unambiguousSuggestion
        end

        function KSResolveEmoteCommand(parsedEmoteCommand)
            if not parsedEmoteCommand or parsedEmoteCommand.cancel then
                return nil
            end
            return emoteSearchIndexByCanonical[parsedEmoteCommand.canonical]
        end

        function KSTabCompleteEmoteCommand(chatInputText)
            local matchingSuggestions, matchingSuggestionCount, completionSuggestion = KSFindEmoteSuggestions(chatInputText, 1)
            if not completionSuggestion then
                return chatInputText, false
            end
            return "/e " .. tostring(completionSuggestion.alias), true
        end

        for systemEmoteAliasIndex, systemEmoteAliasName in ipairs(KS_SYSTEM_EMOTE_ALIASES) do
            FeatAdd(Utils.Joaat(systemEmoteAliasName), systemEmoteAliasName, eFeatureType.Button, "", function(emoteAliasButton)
                Script.QueueJob(OnEmotePlay, emoteCatalog.Emotes[systemEmoteAliasName])
            end, true)
        end
        for systemDanceAliasIndex, systemDanceAliasName in ipairs(KS_SYSTEM_DANCE_ALIASES) do
            FeatAdd(Utils.Joaat(systemDanceAliasName), systemDanceAliasName, eFeatureType.Button, "", function(danceAliasButton)
                Script.QueueJob(OnEmotePlay, emoteCatalog.Dances[systemDanceAliasName])
            end, true)
        end
        for systemPropEmoteAliasIndex, systemPropEmoteAliasName in ipairs(KS_SYSTEM_PROP_EMOTE_ALIASES) do
            FeatAdd(Utils.Joaat(systemPropEmoteAliasName), systemPropEmoteAliasName, eFeatureType.Button, "", function(propEmoteAliasButton)
                Script.QueueJob(OnEmotePlay, emoteCatalog.PropEmotes[systemPropEmoteAliasName])
            end, true)
        end
        local isCancelEmotesByXEnabled = false

        function CancelEmotesTick()
            if not isCancelEmotesByXEnabled then
                Script.Yield(2000)
                return
            end
            if ShouldUnload() then
                return
            end
            if PAD.IS_CONTROL_PRESSED(0, 73) then
                EmoteCancel()
            end
            Script.Yield(50)
        end

        FeatAdd(Utils.Joaat("canceldpemotes"), "Cancel Emotes By Pressing X", eFeatureType.Toggle, "", function(cancelEmotesToggle)
            isCancelEmotesByXEnabled = cancelEmotesToggle:IsToggled()
        end)

        function playDance(danceNumber)
            function LoadAnim(animDictName)
                if not STREAMING.HAS_ANIM_DICT_LOADED(animDictName) then
                    STREAMING.REQUEST_ANIM_DICT(animDictName)
                    while not STREAMING.HAS_ANIM_DICT_LOADED(animDictName) do
                        Script.Yield(50)
                    end
                end
                return
            end

            local danceCount = #danceAnimList
            if not danceNumber or type(danceNumber) ~= "number" then
                danceNumber = math.random(danceCount)
                while danceAnimList[danceNumber] and danceAnimList[danceNumber].disabled do
                    danceNumber = math.random(danceCount)
                    Script.Yield(0)
                end
                notify("You randomly selected dance #" .. danceNumber .. "\nYou can play this dance again using /dance " .. danceNumber)
            end
            if danceCount < danceNumber or danceNumber <= 0 then
                notify("There are only " .. danceCount .. " dances, select a number inbetween or random (no input)")
                return
            end
            if danceAnimList[danceNumber] and danceAnimList[danceNumber].disabled then
                notify("Dance " .. danceNumber .. " is disabled")
                return
            end
            LoadAnim(danceAnimList[danceNumber].dict)
            TASK.TASK_PLAY_ANIM(PLAYER.GET_PLAYER_PED(-1), danceAnimList[danceNumber].dict, danceAnimList[danceNumber].anim, 3.0, 3.0, -1, 1, 0, false, false, false)
            isEmotePlaying = true
            STREAMING.REMOVE_ANIM_DICT(danceAnimList[danceNumber].dict)
        end

        FeatAdd(Utils.Joaat("acceptAlerts"), "Auto Accept Join Messages", eFeatureType.Toggle, "Will block Join and a few Error Messages", function(acceptAlertsToggle) end)
        local poolVisibilityToggleFeature = FeatAdd(Utils.Joaat("poolToggle"), "Make Yourself visible for K-Script Users", eFeatureType.Toggle, "This will either put you inside the Pool which makes your Session visible to other K-Script Users if Enabled or it will hide you when Diabled.", function(poolVisibilityToggle)
            if poolVisibilityToggle:IsToggled() then
                isInPool = true
            else
                isInPool = false
            end
        end)
