        function requestScript(scriptName)
            SCRIPT.REQUEST_SCRIPT(scriptName)
            while not SCRIPT.HAS_SCRIPT_LOADED(scriptName) do
                Script.Yield(0)
            end
        end

        function loadAndStartScriptThread(scriptName, stackSize)
            if not SCRIPT.DOES_SCRIPT_EXIST(scriptName) then
                return false
            end
            local loadDeadlineMs = Time.GetEpocheMs() + 1000
            while not SCRIPT.HAS_SCRIPT_LOADED(scriptName) and loadDeadlineMs > Time.GetEpocheMs() do
                SCRIPT.REQUEST_SCRIPT(scriptName)
                Script.Yield(0)
            end
            if not SCRIPT.HAS_SCRIPT_LOADED(scriptName) then
                return false
            end
            if stackSize <= 0 then
                stackSize = 512
            end
            local scriptThreadId = SYSTEM.START_NEW_SCRIPT(scriptName, stackSize)
            SCRIPT.SET_SCRIPT_AS_NO_LONGER_NEEDED(scriptName)
            return true, scriptThreadId
        end

        FeatAdd(Utils.Joaat("stopfm"), "Restart Freemode Script", eFeatureType.Button, "", function(freemodeRestartFeature)
            return KSDispatchRuntimeFeature("stopfm", freemodeRestartFeature)
        end, true)
