        function closeSpawnHex(numberToFormat)
            numberToFormat = tonumber(numberToFormat)
            return numberToFormat and ("0x%X"):format(numberToFormat) or "nil"
        end

        function closeSpawnLog(logColor, messageHeading, logLines)
            if Logger == nil or type(Logger.Log) ~= "function" then
                return
            end
            local detailText = type(logLines) == "table" and table.concat(logLines, "\n") or tostring(logLines or "")
            local fullMessage = tostring(messageHeading or "Close-spawn diagnostic")
            if detailText ~= "" then
                fullMessage = fullMessage .. "\n" .. detailText
            end
            pcall(Logger.Log, logColor, "K-Script Developer | Close Spawn", fullMessage)
        end

        function closeSpawnIsValidNetId(candidateNetId)
            candidateNetId = tonumber(candidateNetId)
            return candidateNetId ~= nil and -1 ~= candidateNetId and candidateNetId ~= 65535 and candidateNetId ~= 4294967295
        end

        function closeSpawnUpdatePedVehicleCache(updateReason, ownerPlayerId, ownerPlayerName, hasVehicle, rawVehicleId, isInVehicle)
            local existingCacheEntry = closeSpawnPedVehicleCache[ownerPlayerId]
            if not hasVehicle then
                if existingCacheEntry then
                    closeSpawnPedVehicleCache[ownerPlayerId] = nil
                end
                return
            end
            local vehicleNetId = tonumber(rawVehicleId)
            if not closeSpawnIsValidNetId(vehicleNetId) then
                return
            end
            closeSpawnPedVehicleCache[ownerPlayerId] = { netId = vehicleNetId, playerName = ownerPlayerName, inVehicle = isInVehicle }
        end

        function closeSpawnFindCachedPedVehicle(objectNetId, senderPlayerId)
            objectNetId = tonumber(objectNetId)
            if not closeSpawnIsValidNetId(objectNetId) then
                return nil, nil
            end
            local senderCacheEntry = closeSpawnPedVehicleCache[senderPlayerId]
            if senderCacheEntry and tonumber(senderCacheEntry.netId) == objectNetId then
                return senderCacheEntry, senderPlayerId
            end
            for cachedPlayerId, cacheEntry in pairs(closeSpawnPedVehicleCache) do
                if tonumber(cacheEntry.netId) == objectNetId then
                    return cacheEntry, cachedPlayerId
                end
            end
            return nil, nil
        end

        function closeSpawnRememberPersonalVehicleEvent(senderPlayerId, vehicleObjectId)
            senderPlayerId = tonumber(senderPlayerId)
            vehicleObjectId = tonumber(vehicleObjectId)
            if senderPlayerId == nil or not closeSpawnIsValidNetId(vehicleObjectId) then
                return false
            end
            closeSpawnPendingPersonalVehicles[senderPlayerId] = {
                objectId = vehicleObjectId,
                expiresAtMs = getRuntimeNowMs() + KS_CLOSE_SPAWN_PERSONAL_VEHICLE_WINDOW_MS,
            }
            return true
        end

        function closeSpawnHasPendingPersonalVehicle(ownerPlayerId, vehicleObjectId, shouldConsume)
            ownerPlayerId = tonumber(ownerPlayerId)
            vehicleObjectId = tonumber(vehicleObjectId)
            local pendingVehicleEvent = ownerPlayerId ~= nil and closeSpawnPendingPersonalVehicles[ownerPlayerId] or nil
            if type(pendingVehicleEvent) ~= "table" then
                return false
            end
            if (tonumber(pendingVehicleEvent.expiresAtMs) or 0) < getRuntimeNowMs() then
                closeSpawnPendingPersonalVehicles[ownerPlayerId] = nil
                return false
            end
            if tonumber(pendingVehicleEvent.objectId) ~= vehicleObjectId then
                return false
            end
            if shouldConsume == true then
                closeSpawnPendingPersonalVehicles[ownerPlayerId] = nil
            end
            return true
        end

        local syncProtectionEnabledFlags = {
            closeSpawn = false,
            objectSpawn = false,
            pedSpawn = false,
            vehicleSpawn = false,
            crashTask = false,
        }

        function KS_DispatchBlameKillIncomingSync(isCreationSync, syncModelHash, syncPosition, syncObjectInfo, syncNodes, hasPlayerStateOrCameraNode)
            if hasPlayerStateOrCameraNode ~= true then
                return true
            end
            if type(KSBlameKillRemoteCameraDataHandler) == "function" then
                return KSBlameKillRemoteCameraDataHandler(isCreationSync, syncModelHash, syncPosition, syncObjectInfo, syncNodes)
            end
            return true
        end

        function blockCloseSpawn(isCreateEvent, entityModelHash, spawnPosition, syncObjectInfo, syncNodeList, pedGameStateNode, pedCreationNode, vehicleCreationNode)
            local localPlayerId = GTA.GetLocalPlayerId()
            local isFreemodeMaleModel = entityModelHash == freemodeMaleHash
            local isFromOtherPlayer = syncObjectInfo.PlayerId ~= localPlayerId
            local senderPlayerName = nil
            if isFromOtherPlayer and isFreemodeMaleModel and syncObjectInfo.ObjectType == 11 then
                senderPlayerName = Players.GetName(syncObjectInfo.PlayerId) or "Player " .. syncObjectInfo.PlayerId
                local pedGameStateData = pedGameStateNode ~= nil and pedGameStateNode:As("CPedGameStateDataNode") or nil
                if pedGameStateData then
                    closeSpawnUpdatePedVehicleCache(isCreateEvent and "CREATE" or "SYNC", syncObjectInfo.PlayerId, senderPlayerName, pedGameStateData.hasVehicle, pedGameStateData.vehicleID, pedGameStateData.inVehicle)
                end
            end
            if not isFromOtherPlayer then
                return true
            end
            if spawnPosition == nil or spawnPosition.x == nil or spawnPosition.y == nil or spawnPosition.z == nil then
                return false
            end
            if isCreateEvent ~= true then
                return true
            end
            local vehicleCreationData = vehicleCreationNode ~= nil and vehicleCreationNode:As("CVehicleCreationDataNode") or nil
            local cachedPedVehicle, vehicleOwnerPlayerId = closeSpawnFindCachedPedVehicle(syncObjectInfo.ObjectID, syncObjectInfo.PlayerId)
            local isPendingPersonalVehicle = vehicleCreationData ~= nil and closeSpawnHasPendingPersonalVehicle
            if blockedHashed[entityModelHash] then
                if cachedPedVehicle or isPendingPersonalVehicle then
                    blockedHashed[entityModelHash] = nil
                else
                    return false
                end
            end
            local localPedPosition = getLocalPedPosition()
            if manhattanDistance(spawnPosition, localPedPosition) >= closeSpawnRadiusFeature:GetIntValue() then
                return true
            end
            local pedCreationData = pedCreationNode ~= nil and pedCreationNode:As("CPedCreationDataNode") or nil
            if pedCreationData then
                if isFreemodeMaleModel and syncObjectInfo.ObjectType == 11 then
                    local isRemoteObject = syncObjectInfo.IsRemote
                    if isRemoteObject then
                        if isRemoteObject then
                            return true
                        end
                        goto afterPedCreationChecks
                    end
                end
                if isFreemodeMaleModel and syncObjectInfo.ObjectType == 6 and pedCreationData.IsRespawnObjId and pedCreationData.RespawnFlaggedForRemoval and syncObjectInfo.IsRemote then
                    return true
                end
                ::afterPedCreationChecks::
            end
            if vehicleCreationData and (cachedPedVehicle or isPendingPersonalVehicle) then
                if not senderPlayerName then
                    senderPlayerName = Players.GetName(syncObjectInfo.PlayerId) or "Player " .. syncObjectInfo.PlayerId
                end
                if isPendingPersonalVehicle then
                    closeSpawnUpdatePedVehicleCache("PERSONAL_VEHICLE_SET", syncObjectInfo.PlayerId, senderPlayerName, true, syncObjectInfo.ObjectID, false)
                    closeSpawnHasPendingPersonalVehicle(syncObjectInfo.PlayerId, syncObjectInfo.ObjectID, true)
                    cachedPedVehicle = closeSpawnPedVehicleCache[syncObjectInfo.PlayerId]
                    vehicleOwnerPlayerId = syncObjectInfo.PlayerId
                end
                if isDev then
                    local vehicleModelHash = vehicleCreationData.modelHash
                    local vehicleModelName = GTA.GetModelNameFromHash(vehicleModelHash)
                    local objectTypeName = eNetObjectTypeNames[syncObjectInfo.ObjectType] or tostring(syncObjectInfo.ObjectType)
                    local vehicleStatusName = kScriptVehicleStatusNames and kScriptVehicleStatusNames[vehicleCreationData.status] or tostring(vehicleCreationData.status)
                    local populationTypeName = kScriptPopulationTypeNames and kScriptPopulationTypeNames[vehicleCreationData.popType] or tostring(vehicleCreationData.popType)
                    local vehicleOwnerName = cachedPedVehicle.playerName or Players.GetName(vehicleOwnerPlayerId) or tostring(vehicleOwnerPlayerId)
                    closeSpawnLog(eLogColor.LIGHTGREEN, "CVehicleCreationDataNode :: MATCHED PLAYER VEHICLEID", {
                        ("Create Sender   : %s"):format(senderPlayerName),
                        ("Vehicle Owner   : %s"):format(vehicleOwnerName),
                        ("Ped VehicleID   : %s"):format(closeSpawnHex(cachedPedVehicle.netId)),
                        ("Create ObjectID : %s"):format(closeSpawnHex(syncObjectInfo.ObjectID)),
                        ("Create Vehicle  : %s"):format(vehicleModelName),
                        ("Create Hash     : %s"):format(closeSpawnHex(vehicleModelHash)),
                        ("Object Type     : %s"):format(objectTypeName),
                        ("Is Remote       : %s"):format(tostring(syncObjectInfo.IsRemote)),
                        ("Status          : %s"):format(vehicleStatusName),
                        ("Population      : %s"):format(populationTypeName),
                        ("inVehicle       : %s"):format(tostring(cachedPedVehicle.inVehicle)),
                    })
                    notify(("Close Spawn: allowing player vehicle %s from %s"):format(vehicleModelName, vehicleOwnerName))
                end
                return true
            end
            if FeatureMgr.IsFeatureEnabled(notifyProtectionsFeatureHash) then
                if not senderPlayerName then
                    senderPlayerName = Players.GetName(syncObjectInfo.PlayerId) or "Player " .. syncObjectInfo.PlayerId
                end
                notify(string.format("Blocked Close Entity Spawn: %s from %s", GTA.GetModelNameFromHash(entityModelHash), senderPlayerName))
            end
            if FeatureMgr.IsFeatureEnabled(cacheBlockedEntitiesFeatureHash) and not isFreemodeMaleModel then
                blockedHashed[entityModelHash] = true
            end
            return false
        end

        local closeSpawnProtectionToggleFeature = FeatAdd(Utils.Joaat("closespawnProt1"), "Close Spawn Protection", eFeatureType.Toggle, "blocks entities from spawning on you or around you in a set radius\nThis can false positive", function(closeSpawnToggleFeature)
            local isCloseSpawnEnabled = closeSpawnToggleFeature:IsToggled()
            syncProtectionEnabledFlags.closeSpawn = isCloseSpawnEnabled
        end)
        local closeSpawnProtectionDefaulted = closeSpawnProtectionToggleFeature.SetDefaultValue(closeSpawnProtectionToggleFeature, true)
        local closeSpawnProtectionReset = closeSpawnProtectionDefaulted.Reset(closeSpawnProtectionDefaulted)
        closeSpawnProtectionReset.OnClick(closeSpawnProtectionReset)
        toBlockObjects = {
            [Utils.Joaat("ar_prop_ar_neon_gate_01a")] = true,
            [Utils.Joaat("ar_prop_ar_neon_gate_03a")] = true,
            [Utils.Joaat("ar_prop_ar_neon_gate_05a")] = true,
