            [Utils.Joaat("ar_prop_ar_neon_gate_02b")] = true,
            [Utils.Joaat("ar_prop_ar_neon_gate4x_02a")] = true,
            [Utils.Joaat("ar_prop_ar_neon_gate8x_02a")] = true,
            [Utils.Joaat("ar_prop_ar_neon_gate4x_05a")] = true,
            [Utils.Joaat("ar_prop_ar_neon_gate8x_05a")] = true,
            [Utils.Joaat("ar_prop_ar_neon_gate4x_03a")] = true,
            [Utils.Joaat("ar_prop_ar_neon_gate8x_03a")] = true,
            [Utils.Joaat("ar_prop_ar_neon_gate4x_01a")] = true,
            [Utils.Joaat("ar_prop_ar_neon_gate8x_01a")] = true,
