            [Utils.Joaat("h4_prop_x17_sub")] = true,
            [Utils.Joaat("prop_temp_carrier")] = true,
            [Utils.Joaat("prop_cj_big_boat")] = true,
        }

        function ObjectProtection(isCreateEvent, entityModelHash, spawnPosition, syncObjectInfo, syncNodeList)
            for _, syncNode in ipairs(syncNodeList) do
                if syncNode:GetNodeType() == eSyncDataNode.CObjectCreationDataNode then
                    local objectCreationData = syncNode:As("CObjectCreationDataNode")
                    if objectCreationData then
                        local objectModelHash = objectCreationData.modelHash
                        if toBlockObjects[objectModelHash] and isCreateEvent then
                            local senderPlayerName = Players.GetName(syncObjectInfo.PlayerId) or "Player " .. syncObjectInfo.PlayerId
                            if FeatureMgr.IsFeatureEnabled(notifyProtectionsFeatureHash) then
                                local objectModelName = GTA.GetModelNameFromHash(objectModelHash)
                                notify(string.format("Blocked Object Spawn: %s from %s", objectModelName, senderPlayerName))
                            end
                            return false
                        end
                    end
                end
            end
