        function PedProtection(isCreateEvent, entityModelHash, spawnPosition, syncObjectInfo, syncNodeList)
            local netObjectType = syncObjectInfo.ObjectType
            for _, syncNode in ipairs(syncNodeList) do
                if syncNode:GetNodeType() == eSyncDataNode.CPedCreationDataNode then
                    local pedCreationData = syncNode:As("CPedCreationDataNode")
                    if pedCreationData and isCreateEvent then
                        local pedModelHash = pedCreationData.modelHash
                        if entityModelHash ~= freemodeMaleHash and entityModelHash ~= freemodeFemaleHash then
                            goto checkBlockedPedModel
                        end
                        if netObjectType == 11 then
                            local isRemoteObject = syncObjectInfo.IsRemote
                            if isRemoteObject then
                                if isRemoteObject then
                                    return true
                                end
                                goto afterRespawnCheck
                            end
                        end
                        if netObjectType == 6 and pedCreationData.IsRespawnObjId and pedCreationData.RespawnFlaggedForRemoval and syncObjectInfo.IsRemote then
                            return true
                        end
                        ::afterRespawnCheck::
                        ::checkBlockedPedModel::
                        if toBlockPeds[pedModelHash] then
                            if FeatureMgr.IsFeatureEnabled(notifyProtectionsFeatureHash) then
                                local senderPlayerName = Players.GetName(syncObjectInfo.PlayerId) or "Player " .. syncObjectInfo.PlayerId
                                local pedModelName = GTA.GetModelNameFromHash(pedModelHash)
                                notify(string.format("Blocked Ped: %s from %s", pedModelName, senderPlayerName))
                            end
                            return false
                        end
                    end
                end
            end
            return true
        end

