        function vehProtection(isCreateEvent, entityModelHash, spawnPosition, syncObjectInfo, syncNodeList)
            local senderPlayerName = Players.GetName(syncObjectInfo.PlayerId) or "Player " .. syncObjectInfo.PlayerId
            for _, syncNode in ipairs(syncNodeList) do
                if syncNode:GetNodeType() == eSyncDataNode.CVehicleCreationDataNode then
                    local vehicleCreationData = syncNode:As("CVehicleCreationDataNode")
                    if vehicleCreationData then
                        local vehicleModelHash = vehicleCreationData.modelHash
                        if toBlockVehicles[vehicleModelHash] then
                            if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                                notify(string.format("Blocked Vehicle '%s' from %s", GTA.GetModelNameFromHash(vehicleModelHash), senderPlayerName))
                            end
                            return false
                        end
                    end
                end
            end
            return true
        end

