        function KS_ReadObjectTaskBit(taskDataBytes, isZeroBasedArray, bitOffset)
            local dataByte = taskDataBytes[math.floor(bitOffset / 8) + (isZeroBasedArray and 0 or 1)]
            if type(dataByte) ~= "number" or dataByte ~= dataByte or dataByte % 1 ~= 0 then
                return nil
            end
            if dataByte < 0 and dataByte >= -128 then
                dataByte = dataByte + 256
            end
            if dataByte < 0 or dataByte > 255 then
                return nil
            end
            return dataByte >> 7 - bitOffset % 8 & 1
        end

        function KS_ValidateScriptedObjectTaskData(scriptedTaskNode, taskDataBitCount)
            if taskDataBitCount < KS_OBJECT_SCRIPTED_ANIMATION_MIN_DATA_BITS then
                return false, "truncated_scripted_animation"
            end
            local taskSpecificData = scriptedTaskNode.taskSpecificData
            local taskDataLuaType = type(taskSpecificData)
            if taskDataLuaType ~= "table" and taskDataLuaType ~= "userdata" then
                return false, "unreadable_scripted_animation_data"
            end
            local zeroIndexReadOk, zeroIndexEntry = pcall(function()
                return taskSpecificData[0]
            end)
            local oneIndexReadOk, oneIndexEntry = pcall(function()
                return taskSpecificData[1]
            end)
            local isZeroIndexed = zeroIndexReadOk and zeroIndexEntry ~= nil
            if not isZeroIndexed and (not oneIndexReadOk or oneIndexEntry == nil) then
                return false, "unreadable_scripted_animation_data"
            end
            local bitCursor = 0

            local function readTaskBits(bitWidth)
                if bitCursor + bitWidth > taskDataBitCount then
                    return nil
                end
                local decodedBits = 0
                for _ = 1, bitWidth do
                    local nextBit = KS_ReadObjectTaskBit(taskSpecificData, isZeroIndexed, bitCursor)
                    if nextBit == nil then
                        return nil
                    end
                    decodedBits = decodedBits << 1 | nextBit
                    bitCursor = bitCursor + 1
                end
                return decodedBits
            end

            local function skipFlaggedByteField()
                for _ = 1, 4 do
                    local flagBit = readTaskBits(1)
                    if flagBit == nil then
                        return false
                    end
                    if flagBit == 1 then
                        return true
                    end
                end
                return readTaskBits(8) ~= nil
            end

            local animStateCode = readTaskBits(2)
            if animStateCode == nil then
                return false, "unreadable_scripted_animation_data"
            end
            if animStateCode > 2 then
                return false, "invalid_scripted_animation_state"
            end
            local playbackCode = readTaskBits(2)
            if playbackCode == nil then
                return false, "unreadable_scripted_animation_data"
            end
            if playbackCode > 2 then
                return false, "invalid_scripted_animation_playback"
            end
            if playbackCode == 2 then
                return false, "oversized_scripted_animation_blend"
            end
            if readTaskBits(32) == nil or readTaskBits(32) == nil or not skipFlaggedByteField() or not skipFlaggedByteField() then
                return false, "truncated_scripted_animation"
            end
            local animationFlags = readTaskBits(31)
            if animationFlags == nil then
                return false, "truncated_scripted_animation"
            end
            local extraWordOmittedFlag = readTaskBits(1)
            if extraWordOmittedFlag == nil then
                return false, "truncated_scripted_animation"
            end
            if extraWordOmittedFlag == 0 and readTaskBits(32) == nil then
                return false, "truncated_scripted_animation"
            end
            if readTaskBits(1) == nil then
                return false, "truncated_scripted_animation"
            end
            local firstByteFieldFlag = readTaskBits(1)
            local secondByteFieldFlag = readTaskBits(1)
            local thirdByteFieldFlag = readTaskBits(1)
            local fourthByteFieldFlag = readTaskBits(1)
            local extendedBlockFlag = readTaskBits(1)
            if firstByteFieldFlag == nil or secondByteFieldFlag == nil or thirdByteFieldFlag == nil or fourthByteFieldFlag == nil or extendedBlockFlag == nil then
                return false, "truncated_scripted_animation"
            end
            if extendedBlockFlag == 1 and (readTaskBits(19) == nil or readTaskBits(32) == nil) then
                return false, "truncated_scripted_animation"
            end
            if firstByteFieldFlag == 1 and readTaskBits(8) == nil then
                return false, "truncated_scripted_animation"
            end
            if secondByteFieldFlag == 1 and readTaskBits(8) == nil then
                return false, "truncated_scripted_animation"
            end
            if thirdByteFieldFlag == 1 and readTaskBits(8) == nil then
                return false, "truncated_scripted_animation"
            end
            if fourthByteFieldFlag == 1 and readTaskBits(8) == nil then
                return false, "truncated_scripted_animation"
            end
            if bitCursor ~= taskDataBitCount then
                return false, "noncanonical_scripted_animation_size"
            end
            if animationFlags & KS_OBJECT_SCRIPTED_ANIMATION_UNSAFE_FLAGS ~= 0 then
                return false, "ped_only_scripted_animation_flags"
            end
            return true
        end

        function KS_ValidateObjectTaskNode(taskNode, objectModelHash)
            local taskType = taskNode and taskNode.taskType or nil
            local taskDataBits = taskNode and taskNode.taskDataSize or nil
            if type(taskType) ~= "number" or taskType ~= taskType or taskType < 0 or taskType > 1023 or taskType % 1 ~= 0 then
                return false, "invalid_task_type", taskType, taskDataBits
            end
            if type(taskDataBits) ~= "number" or taskDataBits ~= taskDataBits or taskDataBits < 0 or taskDataBits > KS_OBJECT_TASK_MAX_DATA_BITS or taskDataBits % 1 ~= 0 then
                return false, "invalid_task_data_size", taskType, taskDataBits
            end
            if taskType == KS_OBJECT_TASK_SCRIPTED_ANIMATION then
                local isScriptedDataValid, scriptedDataFailReason = KS_ValidateScriptedObjectTaskData(taskNode, taskDataBits)
                return isScriptedDataValid, scriptedDataFailReason, taskType, taskDataBits
            end
            if taskType ~= KS_OBJECT_TASK_PARACHUTE then
                return true, nil, taskType, taskDataBits
            end
            if taskDataBits ~= KS_OBJECT_PARACHUTE_STATE_BITS then
                return false, "invalid_parachute_state_size", taskType, taskDataBits
            end
            if KS_OBJECT_PARACHUTE_MODELS[objectModelHash] ~= true then
                return false, "incompatible_parachute_model", taskType, taskDataBits
            end
            return true, nil, taskType, taskDataBits
        end

