        }
        validAnimalTasks = {
            [97] = true,
            [120] = true,
            [134] = true,
            [218] = true,
            [219] = true,
            [273] = true,
            [274] = true,
            [278] = true,
            [279] = true,
            [319] = true,
            [320] = true,
            [217] = true,
            [215] = true,
            [216] = true,
            [532] = true,
        }
        cachedRadiusValue = nil

        function KSValidateIncomingAttachmentEnvelope(sourceNetObject, attachNode, attachNodeType, sourceEntity)
            if attachNode == nil then
                return false, "unreadable_attachment_node"
            end
            if attachNode.attached ~= true then
                return true
            end
            local sourceObjectId = sourceNetObject and tonumber(sourceNetObject.ObjectID) or nil
            local targetObjectId = tonumber(attachNode.attachedObjectID)
            if targetObjectId == nil then
                return false, "invalid_target_object_id"
            end
            if sourceObjectId ~= nil and sourceObjectId == targetObjectId then
                return false, "direct_self_attachment", "objectId=" .. tostring(sourceObjectId)
            end
            local targetNetObject = NetworkObjectMgr.GetNetworkObject(targetObjectId)
            local targetEntity = nil
            if targetNetObject ~= nil and targetNetObject.ObjectType ~= 3 then
                targetEntity = targetNetObject:GetEntity()
            end
            if sourceEntity == nil and sourceObjectId ~= nil and sourceObjectId > 0 and targetEntity ~= nil then
                local chainEntity = targetEntity
                local visitedAddresses = {}
                for chainDepth = 1, 100 do
                    if chainEntity == nil then
                        break
                    end
                    local entityAddress = chainEntity:GetAddress()
                    if entityAddress == nil or entityAddress < 65536 then
                        return false, "pending_target_invalid_address", "depth=" .. tostring(chainDepth)
                    end
                    if visitedAddresses[entityAddress] then
                        return false, "pending_target_cycle", "address=" .. tostring(entityAddress)
                    end
                    visitedAddresses[entityAddress] = true
                    local chainNetObject = chainEntity.NetObject
                    if chainNetObject ~= nil and tonumber(chainNetObject.ObjectID) == sourceObjectId then
                        return false, "pending_attachment_cycle", string.format("sourceObject=%s targetObject=%s depth=%s", tostring(sourceObjectId), tostring(targetObjectId), tostring(chainDepth))
                    end
                    local attachmentExtension = chainEntity:GetAttachmentExtension()
                    if not attachmentExtension or not attachmentExtension.AttachParent then
                        chainEntity = nil
                    end
                    if chainDepth == 100 and chainEntity ~= nil then
                        return false, "pending_target_over_depth", "depth=100"
                    end
                end
            end
            if attachNodeType ~= eSyncDataNode.CPhysicalAttachDataNode then
                return true
            end
            local localPlayerId = GTA.GetLocalPlayerId()
            if sourceNetObject == nil then
                return true
            end
            local ownObjectId = tonumber(KSGetOwnObjectID()) or 0
            local isTargetLocalPlayer = ownObjectId > 0 and targetObjectId == ownObjectId
            if not isTargetLocalPlayer and targetNetObject ~= nil and targetNetObject.ObjectType == 11 then
                isTargetLocalPlayer = targetNetObject.PlayerId == localPlayerId
            end
            if not isTargetLocalPlayer then
                return true
            end
            local attachmentFlags = tonumber(attachNode.attachmentFlags)
            return false, "remote_physical_attachment_to_local_player", string.format("sourceObject=%s targetObject=%s state=%s myBone=%s otherBone=%s", tostring(sourceObjectId), tostring(targetObjectId), tostring(attachmentFlags and attachmentFlags & 15 or "n/a"), tostring(attachNode.attachmentMyBone), tostring(attachNode.attachmentOtherBone))
        end

        function KS_CanApplyPhysicalAttachment(sourceEntity, attachSyncData, syncNodeType)
            local isPedAttachNode = syncNodeType == eSyncDataNode.CPedAttachDataNode

            local function rejectAttachment(rejectReason, rejectDetail)
                return false, rejectReason, rejectDetail
            end

            local sourceAddress = sourceEntity:GetAddress()
            if not sourceAddress or sourceAddress < 65536 then
                return rejectAttachment("invalid_source_address", "source=" .. tostring(sourceAddress))
            end

            local function getValidEntityAddress(candidateEntity)
                if not candidateEntity then
                    return nil
                end
                local entityAddress = candidateEntity:GetAddress()
                if not entityAddress or entityAddress < 65536 then
                    return nil
                end
                return entityAddress
            end

            local function isExtensionOwnedBy(attachExtension, expectedOwnerAddress)
                if not attachExtension or not attachExtension.ThisEntity then
                    return false
                end
                return getValidEntityAddress(attachExtension.ThisEntity) == expectedOwnerAddress
            end

            local function validateParentChain(chainEntity, forbiddenAddress, canRootLackExtension, canChainContainForbidden)
                local visitedParentAddresses = {}
                local parentDepth = 0
                local forbiddenEntityDepth = nil
                while chainEntity do
                    parentDepth = parentDepth + 1
                    local chainEntityAddress = getValidEntityAddress(chainEntity)
                    if not chainEntityAddress then
                        return false, "invalid_address", "depth=" .. tostring(parentDepth)
                    end
                    if visitedParentAddresses[chainEntityAddress] then
                        return false, "cycle", "address=" .. tostring(chainEntityAddress)
                    end
                    if parentDepth > 100 then
                        return false, "over_depth", "depth=" .. tostring(parentDepth)
                    end
                    if forbiddenAddress and chainEntityAddress == forbiddenAddress then
                        if canChainContainForbidden ~= true then
                            return false, "forbidden_entity", "address=" .. tostring(chainEntityAddress)
                        end
                        forbiddenEntityDepth = parentDepth
                    end
                    visitedParentAddresses[chainEntityAddress] = true
                    local chainEntityExtension = chainEntity:GetAttachmentExtension()
                    if not chainEntityExtension then
                        if canRootLackExtension == true and parentDepth == 1 then
                            return true
                        end
                        return false, "missing_extension", "address=" .. tostring(chainEntityAddress)
                    end
                    if not isExtensionOwnedBy(chainEntityExtension, chainEntityAddress) then
                        return false, "extension_owner_mismatch", "address=" .. tostring(chainEntityAddress)
                    end
                    chainEntity = chainEntityExtension.AttachParent
                end
                return true, nil, nil, forbiddenEntityDepth
            end

            local function validateChildList(parentExtension, forbiddenChildAddress)
                if not parentExtension then
                    return true
                end
                local visitedChildAddresses = {}
                local childCount = 0
                local childEntity = parentExtension.AttachChild
                while childEntity do
                    childCount = childCount + 1
                    local childAddress = getValidEntityAddress(childEntity)
                    if not childAddress then
                        return false, "invalid_address", "depth=" .. tostring(childCount)
                    end
                    if visitedChildAddresses[childAddress] then
                        return false, "cycle", "address=" .. tostring(childAddress)
                    end
                    if childCount > 100 then
                        return false, "over_depth", "depth=" .. tostring(childCount)
                    end
                    if forbiddenChildAddress and childAddress == forbiddenChildAddress then
                        return false, "duplicate_source", "address=" .. tostring(childAddress)
                    end
                    visitedChildAddresses[childAddress] = true
                    local childExtension = childEntity:GetAttachmentExtension()
                    if not childExtension or not isExtensionOwnedBy(childExtension, childAddress) then
                        return false, childExtension and "extension_owner_mismatch" or "missing_extension", "address=" .. tostring(childAddress)
                    end
                    childEntity = childExtension.AttachSibling
                end
                return true
            end

            local sourceExtension = sourceEntity:GetAttachmentExtension()
            if sourceExtension and not isExtensionOwnedBy(sourceExtension, sourceAddress) then
                return rejectAttachment("source_extension_owner_mismatch", "source=" .. tostring(sourceAddress))
            end
            local previousParentEntity = sourceExtension and sourceExtension.AttachParent or nil
            local previousParentAddress = getValidEntityAddress(previousParentEntity)

            local function validatePreviousParent()
                if not previousParentEntity then
                    return true
                end
                if not previousParentAddress then
                    return false, "invalid_previous_parent_address"
                end
                local parentChainOk, parentChainReason, parentChainDetail = validateParentChain(previousParentEntity, sourceAddress, false)
                if not parentChainOk then
                    return false, "previous_parent_" .. tostring(parentChainReason), parentChainDetail
                end
                local previousParentExtension = previousParentEntity:GetAttachmentExtension()
                local parentChildrenOk, parentChildrenReason, parentChildrenDetail = validateChildList(previousParentExtension, nil)
                if not parentChildrenOk then
                    return false, "previous_parent_child_" .. tostring(parentChildrenReason), parentChildrenDetail
                end
                return true
            end

            if not attachSyncData.attached then
                if not sourceExtension or sourceExtension.AttachFlags & 15 < 2 or not previousParentEntity then
                    return true
                end
                local detachParentOk, detachParentReason, detachParentDetail = validatePreviousParent()
                if not detachParentOk then
                    return rejectAttachment(detachParentReason, detachParentDetail)
                end
                return true
            end
            local rawAttachFlags = isPedAttachNode and attachSyncData.attachFlags or attachSyncData.attachmentFlags
            if rawAttachFlags == nil then
                return rejectAttachment("missing_attachment_flags")
            end
            local attachState = rawAttachFlags & 15
            if isPedAttachNode then
                if attachState ~= 2 and (attachState < 5 or attachState > 13) then
                    return rejectAttachment("unsupported_ped_state", "state=" .. tostring(attachState))
                end
            elseif attachState ~= 2 and attachState ~= 3 then
                return rejectAttachment("unsupported_physical_state", "state=" .. tostring(attachState))
            end
            if isPedAttachNode and rawAttachFlags & 8192 ~= 0 then
                return rejectAttachment("ped_do_not_network_sync_flag", "flags=" .. tostring(rawAttachFlags))
            end
            local isDirectAttachState = isPedAttachNode and attachState ~= 8 or not isPedAttachNode and attachState == 2
            if isDirectAttachState and not isPedAttachNode then
                local childBoneIndex = tonumber(attachSyncData.attachmentMyBone)
                if childBoneIndex == nil then
                    return rejectAttachment("missing_child_bone")
                end
                if -1 ~= childBoneIndex then
                    if childBoneIndex < 0 then
                        return rejectAttachment("negative_child_bone", "bone=" .. tostring(childBoneIndex))
                    end
                    local sourceHandle = GTA.PointerToHandle(sourceEntity)
                    if not sourceHandle or sourceHandle == 0 or ENTITY.DOES_ENTITY_EXIST(sourceHandle) ~= true then
                        return rejectAttachment("invalid_source_handle", "handle=" .. tostring(sourceHandle))
                    end
                    local sourceBoneCount = tonumber(ENTITY.GET_ENTITY_BONE_COUNT(sourceHandle))
                    if not sourceBoneCount or childBoneIndex >= sourceBoneCount then
                        return rejectAttachment("child_bone_out_of_range", string.format("bone=%s boneCount=%s", tostring(childBoneIndex), tostring(sourceBoneCount)))
                    end
                end
            end
            local previousParentOk, previousParentReason, previousParentDetail = validatePreviousParent()
            if not previousParentOk then
                return rejectAttachment(previousParentReason, previousParentDetail)
            end
            local targetNetObject = NetworkObjectMgr.GetNetworkObject(attachSyncData.attachedObjectID)
            if not targetNetObject or targetNetObject.ObjectType == 3 then
                return true
            end
            local targetEntity = targetNetObject:GetEntity()
            if not targetEntity then
                return true
            end
            local targetAddress = getValidEntityAddress(targetEntity)
            if not targetAddress then
                return rejectAttachment("invalid_target_address")
            end
            if sourceAddress == targetAddress then
                return rejectAttachment("self_attachment", "address=" .. tostring(sourceAddress))
            end
            local isTargetPreviousParent = previousParentAddress == targetAddress
            local targetExtension = targetEntity:GetAttachmentExtension()
            local targetChainOk, targetChainReason, targetChainDetail, sourceDepthInTargetChain = validateParentChain(targetEntity, sourceAddress, true, true)
            if not targetChainOk then
                return rejectAttachment("target_parent_" .. tostring(targetChainReason), targetChainDetail)
            end
            if sourceDepthInTargetChain ~= nil then
                if (targetExtension and (tonumber(targetExtension.AttachFlags) or 0) & 15 or 0) ~= 1 or sourceDepthInTargetChain > 2 then
                    return true
                end
                local sourceChildrenOk, sourceChildrenReason, sourceChildrenDetail = validateChildList(sourceExtension, nil)
                if not sourceChildrenOk then
                    return rejectAttachment("source_child_" .. tostring(sourceChildrenReason), sourceChildrenDetail)
                end
                if sourceExtension ~= nil then
                    return rejectAttachment("cached_extension_lifetime_reverse_detach", "address=" .. tostring(targetAddress))
                end
                return true
            end
            local forbiddenTargetChildAddress = nil
            if not isTargetPreviousParent then
                forbiddenTargetChildAddress = sourceAddress
            end
            if targetExtension then
                local targetChildrenOk, targetChildrenReason, targetChildrenDetail = validateChildList(targetExtension, forbiddenTargetChildAddress)
                if not targetChildrenOk then
                    return rejectAttachment("target_child_" .. tostring(targetChildrenReason), targetChildrenDetail)
                end
            end
            if not isDirectAttachState then
                return true
            end
            if sourceExtension and sourceExtension.AttachFlags & 15 == 1 and not isTargetPreviousParent then
                local cachedChainOk, cachedChainReason, cachedChainDetail = validateParentChain(previousParentEntity, targetAddress, false)
                if not cachedChainOk then
                    return rejectAttachment("cached_extension_lifetime_" .. tostring(cachedChainReason), cachedChainDetail)
                end
            end
            return true
        end

        function taskPatch(isCreateSync, entityModelHash, syncedPosition, netObject, syncNodes)
            local syncedEntity = netObject:GetEntity()
            local senderPlayerName = Players.GetName(netObject.PlayerId)
            if not senderPlayerName then
                senderPlayerName = "Player "
                senderPlayerName = senderPlayerName .. netObject.PlayerId
            end

            local function checkObjectTaskNode(objectStateNode)
                local objectStateData = objectStateNode:As("CObjectGameStateDataNode")
                if not objectStateData then
                    if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                        if isDev then
                            notify(string.format("Blocked Unreadable Object Task Sync from %s", senderPlayerName))
                        else
                            notify(string.format("Blocked Object Task Crash Attempt from %s", senderPlayerName))
                        end
                    end
                    return false
                end
                local isObjectTaskValid, taskRejectReason, objectTaskType, objectTaskDataBits = KS_ValidateObjectTaskNode(objectStateData, entityModelHash)
                if isObjectTaskValid then
                    return true
                end
                if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                    local objectTaskName = taskNames[objectTaskType] or "Unknown"
                    if isDev then
                        local objectModelName = GTA.GetModelNameFromHash(entityModelHash) or "Unknown"
                        notify(string.format("Blocked Unsafe Object Task Sync: %s (%s|task=%s|bits=%s|%s) from %s", objectTaskName, objectModelName, tostring(objectTaskType), tostring(objectTaskDataBits), taskRejectReason, senderPlayerName))
                    else
                        notify(string.format("Blocked %s Crash Attempt from %s", objectTaskName, senderPlayerName))
                    end
                end
                return false
            end

            local function checkAnimalTaskTree(taskTreeNode)
                if toBlockNoBipedPeds[entityModelHash] ~= true then
                    return true
                end
                local animalTaskTree = taskTreeNode:As("CPedTaskTreeDataNode")
                if not animalTaskTree or not animalTaskTree.taskTreeData or #animalTaskTree.taskTreeData == 0 then
                    return true
                end
                local rootTaskType = animalTaskTree.taskTreeData[1].taskType
                if validAnimalTasks[rootTaskType] then
                    return true
                end
                if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                    notify(string.format("Invalid Animal Task %s [%s] on %s: from %s", isCreateSync and "Create" or "Sync", rootTaskType, GTA.GetModelNameFromHash(entityModelHash), senderPlayerName))
                end
                return false
            end

            local function rejectAttachmentCrash(attachNodeType)
                notify(string.format("Blocked %s Attachment Crash Attempt from %s", attachNodeType == eSyncDataNode.CPedAttachDataNode and "Ped" or "Physical", senderPlayerName))
                return false
            end

            if not syncedEntity then
                for _, entitylessSyncNode in ipairs(syncNodes) do
                    local entitylessNodeType = entitylessSyncNode:GetNodeType()
                    if entitylessNodeType == eSyncDataNode.CObjectGameStateDataNode then
                        if not checkObjectTaskNode(entitylessSyncNode) then
                            return false
                        end
                    elseif entitylessNodeType == eSyncDataNode.CPedTaskTreeDataNode then
                        if not checkAnimalTaskTree(entitylessSyncNode) then
                            return false
                        end
                    elseif entitylessNodeType == eSyncDataNode.CPhysicalAttachDataNode or entitylessNodeType == eSyncDataNode.CPedAttachDataNode then
                        local entitylessAttachData = entitylessSyncNode:As(entitylessNodeType == eSyncDataNode.CPedAttachDataNode and "CPedAttachDataNode" or "CPhysicalAttachDataNode")
                        local isEntitylessAttachValid, entitylessAttachReason, entitylessAttachDetail = KSValidateIncomingAttachmentEnvelope(netObject, entitylessAttachData, entitylessNodeType, syncedEntity)
                        if isEntitylessAttachValid ~= true then
                            return rejectAttachmentCrash(entitylessNodeType)
                        end
                    end
                end
                return true
            end
            local vehicleModelInfo = nil
            if syncedEntity:IsVehicle() and syncedEntity.ModelInfo then
                vehicleModelInfo = CVehicleModelInfo.FromBaseModelInfo(syncedEntity.ModelInfo)
                if not vehicleModelInfo then
                    notify(string.format("Blocked Invalid Entity Info Crash from %s", senderPlayerName))
                    return false
                end
            end
            for _, syncNode in ipairs(syncNodes) do
                local nodeType = syncNode:GetNodeType()
                if nodeType == eSyncDataNode.CObjectGameStateDataNode and not checkObjectTaskNode(syncNode) then
                    return false
                end
                if nodeType == eSyncDataNode.CPhysicalAttachDataNode or nodeType == eSyncDataNode.CPedAttachDataNode then
                    local attachData = syncNode:As(nodeType == eSyncDataNode.CPedAttachDataNode and "CPedAttachDataNode" or "CPhysicalAttachDataNode")
                    local isAttachAllowed, attachRejectReason, attachRejectDetail = KSValidateIncomingAttachmentEnvelope(netObject, attachData, nodeType, syncedEntity)
                    if isAttachAllowed and attachData then
                        local applyRejectReason, applyRejectDetail
                        isAttachAllowed, applyRejectReason, applyRejectDetail = KS_CanApplyPhysicalAttachment(syncedEntity, attachData, nodeType)
                    end
                    if isAttachAllowed ~= true then
                        return rejectAttachmentCrash(nodeType)
                    end
                end
                if nodeType == eSyncDataNode.CVehicleTaskDataNode then
                    local vehicleTaskData = syncNode:As("CVehicleTaskDataNode")
                    if vehicleTaskData then
                        local vehicleTaskType = vehicleTaskData.taskType
                        local vehicleTaskValidator = mismatchTasks[vehicleTaskType]
                        local vehicleTaskDataSize = vehicleTaskData.taskDataSize
                        if vehicleTaskDataSize > 255 then
                            if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                                notify(string.format("Blocked Task Data Overflow Crash: %d from %s", vehicleTaskDataSize, senderPlayerName))
                            end
                            return false
                        end
                        if vehicleTaskValidator then
                            local isVehicleTaskMismatch = true
                            if vehicleModelInfo and vehicleTaskValidator(vehicleModelInfo) then
                                isVehicleTaskMismatch = false
                            end
                            if isVehicleTaskMismatch then
                                local vehicleTaskName = taskNames[vehicleTaskType] or "Unknown"
                                local vehicleModelName = GTA.GetModelNameFromHash(entityModelHash)
                                local netObjectTypeName = eNetObjectTypeNames[netObject.ObjectType]
                                if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                                    notify(string.format("Blocked Task Mismatch Crash: %s (%s|%s|%d) from %s", vehicleTaskName, vehicleModelName, netObjectTypeName, vehicleTaskType, senderPlayerName))
                                end
                                return false
                            end
                        end
                    end
                end
                if nodeType == eSyncDataNode.CVehicleProximityMigrationDataNode then
                    local migrationData = syncNode:As("CVehicleProximityMigrationDataNode")
                    if migrationData then
                        local migrationTaskType = migrationData.taskType
                        local migrationTaskValidator = mismatchTasks[migrationTaskType]
                        local migrationDataSize = migrationData.taskMigrationDataSize
                        if migrationDataSize > 255 then
                            if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                                notify(string.format("Blocked Task Migration Data Overflow Crash: %d from %s", migrationDataSize, senderPlayerName))
                            end
                            return false
                        end
                        if migrationTaskValidator then
                            local isMigrationTaskMismatch = true
                            if vehicleModelInfo and migrationTaskValidator(vehicleModelInfo) then
                                isMigrationTaskMismatch = false
                            end
                            if isMigrationTaskMismatch then
                                local migrationTaskName = taskNames[migrationTaskType] or "Unknown"
                                local migrationModelName = GTA.GetModelNameFromHash(entityModelHash)
                                local migrationObjectTypeName = eNetObjectTypeNames[netObject.ObjectType]
                                if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                                    notify(string.format("Blocked Task Migration Mismatch Crash: %s (%s|%s|%d) from %s", migrationTaskName, migrationModelName, migrationObjectTypeName, migrationTaskType, senderPlayerName))
                                end
                                return false
                            end
                        end
                    end
                end
                if nodeType == eSyncDataNode.CPedTaskTreeDataNode then
                    local pedTaskTree = syncNode:As("CPedTaskTreeDataNode")
                    if pedTaskTree and pedTaskTree.taskTreeData and #pedTaskTree.taskTreeData > 0 then
                        for _, taskTreeEntry in ipairs(pedTaskTree.taskTreeData) do
                            if tonumber(taskTreeEntry.taskType) == 506 and syncedEntity:IsVehicle() ~= true then
                                if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                                    notify(string.format("Blocked Ped Task Crash: CTaskVehicleNoDriver (506) on %s from %s", GTA.GetModelNameFromHash(entityModelHash), senderPlayerName))
                                end
                                return false
                            end
                        end
                        if not checkAnimalTaskTree(syncNode) then
                            return false
                        end
                    end
                end
                if syncNode:GetNodeType() == eSyncDataNode.CVehicleAppearanceDataNode then
                    local appearanceData = syncNode:As("CVehicleAppearanceDataNode")
                    if appearanceData then
                        local vehicleKitIndex = appearanceData.kitIndex or 0
                        local kitModCount = 0
                        if appearanceData.allKitMods then
                            for _ in pairs(appearanceData.allKitMods) do
                                kitModCount = kitModCount + 1
                            end
                        end
                        local appearanceModelName = GTA.GetModelNameFromHash(entityModelHash) or "Unknown"
                        if vehicleKitIndex > 2 or kitModCount > 13 then
                            if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                                notify(string.format("Blocked IVK Crash from: %s | '%s'", senderPlayerName, appearanceModelName))
                            end
                            return false
                        end
                    end
                end
            end
            return true
        end

        local crashProtectionFeature = FeatAdd(Utils.Joaat("crashProt1"), "Crash Protection", eFeatureType.Toggle, "OP Crash Protection frfr", function(crashProtectionToggle)
            local isCrashProtectionEnabled = crashProtectionToggle:IsToggled()
            syncProtectionEnabledFlags.crashTask = isCrashProtectionEnabled
        end)
        local crashProtectionWithDefault = crashProtectionFeature.SetDefaultValue(crashProtectionFeature, true)
        local crashProtectionAfterReset = crashProtectionWithDefault.Reset(crashProtectionWithDefault)
        crashProtectionAfterReset.OnClick(crashProtectionAfterReset)

        function KS_DispatchIncomingSyncProtections(isCreateSync, syncModelHash, syncPosition, syncNetObject, syncDataNodes)
            local hasPlayerStateOrCameraNode = false
            local hasObjectCreationNode = false
            local hasPedCreationNode = false
            local hasVehicleCreationNode = false
            local hasTaskPatchNode = false
            local pedGameStateNode = nil
            local pedCreationNode = nil
            local vehicleCreationNode = nil
            for _, syncNode in ipairs(syncDataNodes) do
                local nodeName = syncNode:GetNodeName()
                if nodeName == "CPlayerGameStateDataNode" or nodeName == "CPlayerCameraDataNode" then
                    hasPlayerStateOrCameraNode = true
                end
                if nodeName == "CPedGameStateDataNode" then
                    pedGameStateNode = syncNode
                elseif nodeName == "CObjectCreationDataNode" then
                    hasObjectCreationNode = true
                elseif nodeName == "CPedCreationDataNode" then
                    hasPedCreationNode = true
                    pedCreationNode = syncNode
                elseif nodeName == "CVehicleCreationDataNode" then
                    hasVehicleCreationNode = true
                    vehicleCreationNode = syncNode
                elseif nodeName == "CObjectGameStateDataNode" or nodeName == "CVehicleTaskDataNode" or nodeName == "CVehicleProximityMigrationDataNode" or nodeName == "CPedTaskTreeDataNode" or nodeName == "CVehicleAppearanceDataNode" or nodeName == "CPhysicalAttachDataNode" or nodeName == "CPedAttachDataNode" then
                    hasTaskPatchNode = true
                end
            end
            if KS_DispatchBlameKillIncomingSync(isCreateSync, syncModelHash, syncPosition, syncNetObject, syncDataNodes, hasPlayerStateOrCameraNode) == false then
                return false
            end
            if syncProtectionEnabledFlags.closeSpawn and blockCloseSpawn(isCreateSync, syncModelHash, syncPosition, syncNetObject, syncDataNodes, pedGameStateNode, pedCreationNode, vehicleCreationNode) == false then
                return false
            end
            if syncProtectionEnabledFlags.objectSpawn and hasObjectCreationNode and ObjectProtection(isCreateSync, syncModelHash, syncPosition, syncNetObject, syncDataNodes) == false then
                return false
            end
            if syncProtectionEnabledFlags.pedSpawn and hasPedCreationNode and PedProtection(isCreateSync, syncModelHash, syncPosition, syncNetObject, syncDataNodes) == false then
                return false
            end
            if syncProtectionEnabledFlags.vehicleSpawn and hasVehicleCreationNode and vehProtection(isCreateSync, syncModelHash, syncPosition, syncNetObject, syncDataNodes) == false then
                return false
            end
            if syncProtectionEnabledFlags.crashTask and hasTaskPatchNode and taskPatch(isCreateSync, syncModelHash, syncPosition, syncNetObject, syncDataNodes) == false then
                return false
            end
            return true
        end

        KS_BLAME_KILL_INCOMING_HANDLER_ID = featurePlaneInstall.RegisterManagedEventHandler(featurePlaneInstall, "protection_incoming_sync", eLuaEvent.CAN_APPLY_NODE_DATA, KS_DispatchIncomingSyncProtections)
        featurePlaneInstall.handlers.protection_explosion = nil

        function blockExplosions1(eventSender, netEventId, eventBuffer)
            if not ShouldUnload() then
                local explosionSender = eventSender
                if explosionSender == nil then
                    return
                end
                if netEventId == 17 and explosionSender then
                    if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                        notify(("Blocked Explosion from: %s"):format(explosionSender:GetName()))
                    end
                    return true
                end
                if netEventId == 16 and explosionSender then
                    if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                        notify(("Blocked Fire from: %s"):format(explosionSender:GetName()))
                    end
                    return true
                end
            end
        end

        local blockExplosionsFeature = FeatAdd(Utils.Joaat("blockExplos1"), "Block Explosions", eFeatureType.Toggle, "Blocks all explosion & fire events in game, Yes this blocks legit ones too.", function(explosionToggleFeature)
            if explosionToggleFeature:IsToggled() then
                if featurePlaneInstall.handlers.protection_explosion == nil then
                    featurePlaneInstall.handlers.protection_explosion = featurePlaneInstall:RegisterManagedEventHandler("protection_explosion", eLuaEvent.NET_EVENT, blockExplosions1)
                end
            elseif featurePlaneInstall.handlers.protection_explosion ~= nil then
