                if netEventId == 33 then
                    local worldStateDataType, didReadWorldStateType = eventBuffer:ReadUns(4)
                    if didReadWorldStateType and worldStateDataType == 4 and ptfxSender then
                        if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                            notify(("Blocked PTFX #2 from: %s"):format(ptfxSender:GetName()))
                        end
                        return true
                    end
                end
                if netEventId == 74 and ptfxSender then
                    if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                        notify(("Blocked PTFX from: %s"):format(ptfxSender:GetName()))
                    end
                    return true
                end
            end
        end

