        function readGameEvents()
            local isDebugModeEnabled = FeatureMgr.IsFeatureEnabled(featurePlaneContext.__ksDebugEvents.featureHash)
            if not isDebugModeEnabled or ShouldUnload() then
                if not isDebugModeEnabled then
                    KS_ReleaseDebugEventBuffer()
                end
                Script.Yield(5000)
                return
            end
            local pendingEventCount = 1
            if type(SCRIPT.GET_NUMBER_OF_EVENTS) == "function" then
                pendingEventCount = tonumber(SCRIPT.GET_NUMBER_OF_EVENTS(1)) or 0
            end
            if pendingEventCount <= 0 then
                Script.Yield(50)
                return
            end
            for eventIndex = 0, math.min(pendingEventCount - 1, 31) do
                local networkEventType = SCRIPT.GET_EVENT_AT_INDEX(1, eventIndex)
                if networkEventType == 226 then
                    if KS_DebugEventShouldNotify("cloud:226") then
                        notify("The Game is requesting the Tunables from the Cloud Servers!")
                    end
                elseif networkEventType == 161 then
                    if KS_DebugEventShouldNotify("session:161") then
                        FeatureMgr.GetFeatureByName("Notify On Player Join"):SetValue(false)
                        FeatureMgr.GetFeatureByName("Notify On Player Leave"):SetValue(false)
                        notify("You have been Desync Kicked")
                        FeatureMgr.GetFeatureByName("Notify On Player Join"):SetValue(true)
                        FeatureMgr.GetFeatureByName("Notify On Player Leave"):SetValue(true)
                    end
                elseif networkEventType == 160 then
                    if KS_DebugEventShouldNotify("session:160") then
                        notify("You`ve been removed from the Session, due to a long Game Stall")
                    end
                elseif networkEventType == 169 then
                    if KS_DebugEventShouldNotify("invite:169") then
                        notify("The invite you just sent, successfully arrived!")
                    end
                elseif networkEventType == 153 or networkEventType == 154 then
                    local scriptEventBuffer = KS_EnsureDebugEventBuffer()
                    if scriptEventBuffer ~= nil and Memory.MemSet(scriptEventBuffer, 0, 448) ~= 0 and SCRIPT.GET_EVENT_DATA(1, eventIndex, scriptEventBuffer, 56) then
                        local scriptPlayerName = tostring(Memory.ReadString(scriptEventBuffer) or "Unknown")
                        local scriptThreadId = Memory.ReadInt(scriptEventBuffer + 168)
                        local scriptName = tostring(SCRIPT.GET_NAME_OF_SCRIPT_WITH_THIS_ID(scriptThreadId) or "Unknown")
                        local notifyDedupeKey = ("script:%d:%s:%s"):format(networkEventType, scriptPlayerName, scriptName)
                        if KS_DebugEventShouldNotify(notifyDedupeKey) then
                            notify(networkEventType == 153 and ("%s has joined Script: %s"):format(scriptPlayerName, scriptName) or ("%s has left Script: %s"):format(scriptPlayerName, scriptName))
                        end
                    end
                elseif networkEventType == 184 then
                    local joinResultBuffer = KS_EnsureDebugEventBuffer()
                    if joinResultBuffer ~= nil and Memory.MemSet(joinResultBuffer, 0, 448) ~= 0 and SCRIPT.GET_EVENT_DATA(1, eventIndex, joinResultBuffer, 2) then
                        local didJoinSucceed = Memory.ReadInt(joinResultBuffer) == 1
                        if KS_DebugEventShouldNotify("session_join:" .. tostring(didJoinSucceed)) then
                            notify(("Session Join Succeeded? (%s)"):format(didJoinSucceed and "Success!" or "Failed!"))
                        end
                    end
                end
            end
            Script.Yield(50)
        end

        local hostResolverNativeFns = {
            hostQueue = isTableOrUserdata(Players) and type(Players.Get) == "function" and type(ePlayerListSort) == "table" and ePlayerListSort.HOST_QUEUE ~= nil and Players.Get or nil,
            networkHost = isTableOrUserdata(NETWORK) and type(NETWORK.NETWORK_GET_HOST_PLAYER_INDEX) == "function" and NETWORK.NETWORK_GET_HOST_PLAYER_INDEX or nil,
            scriptHost = isTableOrUserdata(NETWORK) and type(NETWORK.NETWORK_GET_HOST_OF_SCRIPT) == "function" and NETWORK.NETWORK_GET_HOST_OF_SCRIPT or nil,
            playerActive = isTableOrUserdata(NETWORK) and type(NETWORK.NETWORK_IS_PLAYER_ACTIVE) == "function" and NETWORK.NETWORK_IS_PLAYER_ACTIVE or nil,
            connectedCount = isTableOrUserdata(NETWORK) and type(NETWORK.NETWORK_GET_NUM_CONNECTED_PLAYERS) == "function" and NETWORK.NETWORK_GET_NUM_CONNECTED_PLAYERS or nil,
        }
        featurePlaneContext.__ksHostResolver = hostResolverNativeFns

        function KS_HostQueueCandidateId(hostQueueEntry)
            local candidatePlayerId = tonumber(hostQueueEntry)
            if candidatePlayerId ~= nil then
                return candidatePlayerId
            end
            if not isTableOrUserdata(hostQueueEntry) then
                return nil
            end
            local fieldLookupOk, fieldPlayerId = pcall(function()
                return hostQueueEntry.PlayerId or hostQueueEntry.playerId or hostQueueEntry.Id or hostQueueEntry.id
            end)
            if not fieldLookupOk or not tonumber(fieldPlayerId) then
                candidatePlayerId = nil
            end
            if candidatePlayerId ~= nil then
                return candidatePlayerId
            end
            for _, getterMethodName in ipairs({ "GetId", "GetPlayerId", "GetIndex" }) do
                local getterLookupOk, getterMethod = pcall(function()
                    return hostQueueEntry[getterMethodName]
                end)
                if getterLookupOk and type(getterMethod) == "function" then
                    local getterCallOk, getterPlayerId = pcall(getterMethod, hostQueueEntry)
                    if getterCallOk and tonumber(getterPlayerId) ~= nil then
                        return tonumber(getterPlayerId)
                    end
                end
            end
            return nil
        end

        function KS_HostQueuePlayerId()
            if featurePlaneContext.__ksHostResolver.hostQueue == nil then
                return nil, "host-queue-api-unavailable"
            end
            local hostQueueCallOk, hostQueueEntries = pcall(featurePlaneContext.__ksHostResolver.hostQueue, ePlayerListSort.HOST_QUEUE, "")
            if not hostQueueCallOk then
                return nil, "host-queue-call-failed"
            end
            if type(hostQueueEntries) ~= "table" then
                return nil, "host-queue-result-unavailable"
            end
            for _, queueEntry in pairs(hostQueueEntries) do
                local queuePlayerId = KS_HostQueueCandidateId(queueEntry)
                if queuePlayerId ~= nil and queuePlayerId >= 0 and queuePlayerId < 32 then
                    return queuePlayerId, "index"
                end
            end
            return nil, "host-queue-empty"
        end

        function KS_NativeNetworkHostPlayerId()
            if featurePlaneContext.__ksHostResolver.networkHost == nil then
                return nil, "network-host-native-unavailable"
            end
            local nativeCallOk, nativeHostIndex = pcall(featurePlaneContext.__ksHostResolver.networkHost)
            if not nativeCallOk then
                return nil, "network-host-native-failed"
            end
            local hostPlayerId = tonumber(nativeHostIndex)
            if hostPlayerId == nil or hostPlayerId < 0 or hostPlayerId >= 32 then
                return nil, "invalid-index"
            end
            return hostPlayerId, "index"
        end

        function KS_NormalizeHostPlayer(hostPlayerId, resolverSource, failureReason)
            local hostPlayerRecord = {
                available = false,
                player_id = nil,
                name = nil,
                rockstar_id = nil,
                host_token = nil,
                source = resolverSource,
                failure_reason = failureReason,
            }
            hostPlayerId = tonumber(hostPlayerId)
            if hostPlayerId == nil or hostPlayerId < 0 or hostPlayerId >= 32 or hostPlayerId ~= math.floor(hostPlayerId) then
                return hostPlayerRecord
            end
            if featurePlaneContext.__ksHostResolver.playerActive ~= nil then
                local activeCheckOk, isPlayerActive = pcall(featurePlaneContext.__ksHostResolver.playerActive, hostPlayerId)
                if activeCheckOk and isPlayerActive ~= true and isPlayerActive ~= 1 then
                    hostPlayerRecord.failure_reason = "player-inactive"
                    return hostPlayerRecord
                end
            end
            local hostPlayerObject = Players.GetById(hostPlayerId)
            if hostPlayerObject == nil then
                hostPlayerRecord.failure_reason = "player-object-unavailable"
                return hostPlayerRecord
            end
            local hostGamerInfo = hostPlayerObject:GetGamerInfo()
            hostPlayerRecord.player_id = hostPlayerId
            hostPlayerRecord.available = true
            hostPlayerRecord.name = Players.GetName(hostPlayerId) or "Unknown"
            hostPlayerRecord.rockstar_id = hostGamerInfo ~= nil and toCanonicalPlayerIdentifier(hostGamerInfo.RockstarId) or nil
            hostPlayerRecord.host_token = hostGamerInfo ~= nil and tostring(hostGamerInfo.HostKey or "") or nil
            hostPlayerRecord.failure_reason = nil
            return hostPlayerRecord
        end

        function KS_ResetHostInfo(resetReason)
            local previousHostInfo = type(featurePlaneContext.__ksHostInfo) == "table" and featurePlaneContext.__ksHostInfo or nil
            local previousNetworkHost = previousHostInfo ~= nil and previousHostInfo.network_host or nil
            local previousNetworkHostId = previousHostInfo ~= nil and previousHostInfo.previous_network_host_id or nil
            if previousNetworkHost ~= nil and previousNetworkHost.available == true then
                previousNetworkHostId = previousNetworkHost.player_id
            end
            local clearedHostInfo = {}
            local convertToString = tostring
            local runtimeEdition = featurePlaneContext.KS_RUNTIME_EDITION
            if not runtimeEdition then
                if isGameVersionEnhanced then
                    runtimeEdition = "enhanced"
                    if runtimeEdition then
                        goto runtimeEditionResolved
                    end
                end
                runtimeEdition = "legacy"
            end
            ::runtimeEditionResolved::
            clearedHostInfo.edition = convertToString(runtimeEdition)
            clearedHostInfo.resolver = "none"
            clearedHostInfo.available = false
            clearedHostInfo.state = resetReason
            clearedHostInfo.network_host = KS_NormalizeHostPlayer(nil, "none", resetReason)
            clearedHostInfo.script_host = KS_NormalizeHostPlayer(nil, "script-host-native", resetReason)
            clearedHostInfo.network_host_player_id = nil
            clearedHostInfo.network_host_name = nil
            clearedHostInfo.network_host_available = false
            clearedHostInfo.network_host_source = "none"
            clearedHostInfo.script_host_player_id = nil
            clearedHostInfo.script_host_name = nil
            clearedHostInfo.script_host_available = false
            clearedHostInfo.script_host_source = "script-host-native"
            clearedHostInfo.connected_players = 0
            clearedHostInfo.local_is_host = false
            clearedHostInfo.migration = false
            clearedHostInfo.previous_network_host_id = previousNetworkHostId
            clearedHostInfo.failure_reason = resetReason
            featurePlaneContext.__ksHostInfo = clearedHostInfo
            return featurePlaneContext.__ksHostInfo
        end

        function KS_ResolveLegacyNetworkHost()
            local queueHostId, queueResultCategory = KS_HostQueuePlayerId()
            if queueHostId ~= nil then
                return queueHostId, queueResultCategory, "cherax-host-queue", false
            end
            local nativeHostId, nativeResultCategory = KS_NativeNetworkHostPlayerId()
            return nativeHostId, nativeResultCategory, "network-host-native-fallback", true
        end

        function KS_ResolveEnhancedNetworkHost()
            local nativeHostId, nativeResultCategory = KS_NativeNetworkHostPlayerId()
            if nativeHostId ~= nil then
                return nativeHostId, nativeResultCategory, "network-host-native", false
            end
            local queueHostId, queueResultCategory = KS_HostQueuePlayerId()
            return queueHostId, queueResultCategory, "cherax-host-queue-fallback", true
        end

        function KS_ResolveFreemodeScriptHost()
            if featurePlaneContext.__ksHostResolver.scriptHost == nil then
                return KS_NormalizeHostPlayer(nil, "script-host-native", "script-host-native-unavailable")
            end
            local scriptHostCallOk, resolvedScriptHostId = pcall(featurePlaneContext.__ksHostResolver.scriptHost, "freemode", -1, 0)
            if not scriptHostCallOk then
                return KS_NormalizeHostPlayer(nil, "script-host-native", "script-host-native-failed")
            end
            return KS_NormalizeHostPlayer(tonumber(resolvedScriptHostId), "script-host-native", "index")
        end

        function KS_ResolveHostInfo()
            local convertToString = tostring
            local runtimeEdition = featurePlaneContext.KS_RUNTIME_EDITION
            if not runtimeEdition then
                if isGameVersionEnhanced then
                    runtimeEdition = "enhanced"
                    if runtimeEdition then
                        goto editionResolved
                    end
                end
                runtimeEdition = "legacy"
            end
            ::editionResolved::
            local editionName = convertToString(runtimeEdition)
            local networkHostId, hostResultCategory, hostResolverSource, isFallbackAttempted
            if editionName == "legacy" then
                networkHostId, hostResultCategory, hostResolverSource, isFallbackAttempted = KS_ResolveLegacyNetworkHost()
            else
                networkHostId, hostResultCategory, hostResolverSource, isFallbackAttempted = KS_ResolveEnhancedNetworkHost()
            end
            local networkHostRecord = KS_NormalizeHostPlayer(networkHostId, hostResolverSource, hostResultCategory)
            if not networkHostRecord.available then
                local fallbackHostId, fallbackResultCategory, fallbackResolverSource
                if editionName == "legacy" then
                    fallbackHostId, fallbackResultCategory = KS_NativeNetworkHostPlayerId()
                    fallbackResolverSource = "network-host-native-fallback"
                else
                    fallbackHostId, fallbackResultCategory = KS_HostQueuePlayerId()
                    fallbackResolverSource = "cherax-host-queue-fallback"
                end
                local fallbackHostRecord = KS_NormalizeHostPlayer(fallbackHostId, fallbackResolverSource, fallbackResultCategory)
                if fallbackHostRecord.available then
                    hostResolverSource = fallbackResolverSource
                    hostResultCategory = fallbackResultCategory
                    networkHostId = fallbackHostId
                    networkHostRecord = fallbackHostRecord
                    isFallbackAttempted = true
                end
            end
            local scriptHostRecord = KS_ResolveFreemodeScriptHost()
            if not scriptHostRecord.available and isTableOrUserdata(NETWORK) and type(NETWORK.NETWORK_IS_HOST_OF_THIS_SCRIPT) == "function" then
                local scriptHostCheckOk, isLocalScriptHost = pcall(NETWORK.NETWORK_IS_HOST_OF_THIS_SCRIPT)
                if scriptHostCheckOk and (isLocalScriptHost == true or isLocalScriptHost == 1) then
                    scriptHostRecord = KS_NormalizeHostPlayer(GTA.GetLocalPlayerId(), "script-host-local-fallback", "local-script-host")
                end
            end
            local previousHostInfo = type(featurePlaneContext.__ksHostInfo) == "table" and featurePlaneContext.__ksHostInfo or nil
            local previousNetworkHost = previousHostInfo ~= nil and previousHostInfo.network_host or nil
            local previousNetworkHostId = previousHostInfo ~= nil and previousHostInfo.previous_network_host_id or nil
            if previousNetworkHost ~= nil and previousNetworkHost.available == true then
                previousNetworkHostId = previousNetworkHost.player_id
            end
            if previousHostInfo ~= nil and (previousHostInfo.failure_reason == "no-session" or previousHostInfo.failure_reason == "session-transition") then
                previousNetworkHostId = nil
            end
            local isHostMigration = previousNetworkHostId ~= nil
            local connectedPlayerCount = 0
            if featurePlaneContext.__ksHostResolver.connectedCount ~= nil then
                local countCallOk, nativeConnectedCount = pcall(featurePlaneContext.__ksHostResolver.connectedCount)
                if countCallOk then
                    connectedPlayerCount = tonumber(nativeConnectedCount) or 0
                end
            end
            if connectedPlayerCount <= 0 and featurePlaneContext.__ksHostResolver.playerActive ~= nil then
                for playerIndex = 0, 31 do
                    local activeCheckOk, isSlotActive = pcall(featurePlaneContext.__ksHostResolver.playerActive, playerIndex)
                    if activeCheckOk and (isSlotActive == true or isSlotActive == 1) then
                        connectedPlayerCount = connectedPlayerCount + 1
                    end
                end
            end
            local hostResolveState
            if networkHostRecord.available and scriptHostRecord.available then
                hostResolveState = "active"
                if hostResolveState then
                    goto hostStateResolved
                end
            end
            if not networkHostRecord.available then
                hostResolveState = scriptHostRecord.available
                if not hostResolveState then
                    goto skipPartialState
                end
            end
            hostResolveState = "partial"
            ::skipPartialState::
            if not hostResolveState then
                hostResolveState = "unavailable"
            end
            ::hostStateResolved::
            local resolvedHostInfo = {
                edition = editionName,
                resolver = hostResolverSource,
                available = networkHostRecord.available,
                state = hostResolveState,
                network_host = networkHostRecord,
                script_host = scriptHostRecord,
                network_host_player_id = networkHostRecord.player_id,
                network_host_name = networkHostRecord.name,
                network_host_available = networkHostRecord.available,
                network_host_source = networkHostRecord.source,
                script_host_player_id = scriptHostRecord.player_id,
                script_host_name = scriptHostRecord.name,
                script_host_available = scriptHostRecord.available,
                script_host_source = scriptHostRecord.source,
                connected_players = math.max(0, math.min(32, connectedPlayerCount)),
                local_is_host = networkHostRecord.available and networkHostRecord.player_id == GTA.GetLocalPlayerId(),
                migration = isHostMigration,
                previous_network_host_id = networkHostRecord.available and networkHostRecord.player_id or previousNetworkHostId,
                raw_result_category = hostResultCategory,
                failure_reason = networkHostRecord.failure_reason,
                fallback_attempted = isFallbackAttempted == true,
                player_zero_accepted = networkHostId == 0,
            }
            featurePlaneContext.__ksHostInfo = resolvedHostInfo
            return featurePlaneContext.__ksHostInfo
        end

        function KS_IsHostMonitorSessionReady()
            if isUnloadRequested() or maintransitionActive then
                return false
            end
            if not isTableOrUserdata(NETWORK) then
                return false
            end
            local sessionActiveNative = type(NETWORK.NETWORK_IS_SESSION_ACTIVE) == "function" and NETWORK.NETWORK_IS_SESSION_ACTIVE or NETWORK.NETWORK_IS_SESSION_STARTED
            if type(sessionActiveNative) ~= "function" then
                return false
            end
            local sessionCheckOk, sessionActiveResult = pcall(sessionActiveNative)
            if not sessionCheckOk or sessionActiveResult ~= true and sessionActiveResult ~= 1 then
                return false
            end
            if not isTableOrUserdata(GTA) or type(GTA.GetLocalPlayerId) ~= "function" then
                return false
            end
            local localPlayerId = tonumber(GTA.GetLocalPlayerId())
            if localPlayerId == nil or localPlayerId < 0 or localPlayerId >= 32 then
                return false
            end
            if featurePlaneContext.__ksHostResolver.playerActive ~= nil then
                local playerActiveOk, localPlayerActiveResult = pcall(featurePlaneContext.__ksHostResolver.playerActive, localPlayerId)
                if playerActiveOk then
                    return localPlayerActiveResult == true or localPlayerActiveResult == 1
                end
            end
            if isTableOrUserdata(Players) and type(Players.GetById) == "function" then
                local getPlayerOk, localPlayer = pcall(Players.GetById, localPlayerId)
                if getPlayerOk then
                    return localPlayer ~= nil
                end
            end
            return true
        end

        function KS_IsDisplayPlayerActive(queriedPlayerId)
            queriedPlayerId = tonumber(queriedPlayerId)
            if queriedPlayerId == nil or queriedPlayerId < 0 or queriedPlayerId >= 32 then
                return false
            end
            local activeCheckOk, playerActiveResult = pcall(NETWORK.NETWORK_IS_PLAYER_ACTIVE, math.floor(queriedPlayerId))
            return activeCheckOk and (playerActiveResult == true or playerActiveResult == 1)
        end

        function KS_GetLiveVoiceChatters()
            local voiceChatterNames = {}
            local localPlayerId = GTA.GetLocalPlayerId()
            for scanPlayerId = 0, 31 do
                if KS_IsDisplayPlayerActive(scanPlayerId) then
                    local headsetCheckOk, hasHeadsetResult = pcall(NETWORK.NETWORK_PLAYER_HAS_HEADSET, scanPlayerId)
                    if headsetCheckOk and (hasHeadsetResult == true or hasHeadsetResult == 1) then
                        local nameLookupOk, chatterLabel = pcall(Players.GetName, scanPlayerId)
                        if not nameLookupOk or not tostring(chatterLabel or "Unknown") then
                            chatterLabel = "Unknown"
                        end
                        if scanPlayerId == localPlayerId then
                            chatterLabel = chatterLabel .. " (You)"
                        end
                        local talkingCheckOk, isTalkingResult = pcall(NETWORK.NETWORK_IS_PLAYER_TALKING, scanPlayerId)
                        if talkingCheckOk and (isTalkingResult == true or isTalkingResult == 1) then
                            chatterLabel = chatterLabel .. " (Talking)"
                        end
                        voiceChatterNames[#voiceChatterNames + 1] = chatterLabel
                    end
                end
            end
            return voiceChatterNames
        end

