        function logGamerInfo(targetPlayerId)
            if ShouldUnload() then
                return
            end
            targetPlayerId = tonumber(targetPlayerId)
            if targetPlayerId == nil or targetPlayerId < 0 or targetPlayerId >= 32 then
                return
            end
            targetPlayerId = math.floor(targetPlayerId)
            if targetPlayerId == GTA.GetLocalPlayerId() then
                return
            end
            if not KS_IsDisplayPlayerActive(targetPlayerId) then
                return
            end
            local targetPlayer = Players.GetById(targetPlayerId)
            if not targetPlayer then
                return
            end
            local detectionIndex = targetPlayerId + 1
            local targetPlayerName = targetPlayer:GetName()
            local gamerInfo = targetPlayer:GetGamerInfo()
            if not gamerInfo then
                return
            end
            local canonicalRockstarId = toCanonicalPlayerIdentifier(gamerInfo.RockstarId)
            if KS_ReassertAuthoritativeKScriptIdentity(targetPlayerId, canonicalRockstarId, targetPlayerName) then
                LookupModderReasonForPlayer(targetPlayerId, canonicalRockstarId, targetPlayerName, gamerInfo.HostKey)
                return
            end
            local isFriendTagged = (Players.GetTags(targetPlayerId) or ""):find("%[F%]", 1, true) ~= nil
            local targetPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(targetPlayerId)
            if targetPed == nil or targetPed == 0 or not ENTITY.DOES_ENTITY_EXIST(targetPed) then
                return
            end
            local playerVehicle = PED.GET_VEHICLE_PED_IS_IN(targetPed, false)
            if playerVehicle ~= nil and playerVehicle ~= 0 and ENTITY.DOES_ENTITY_EXIST(playerVehicle) then
                local vehicleModel = ENTITY.GET_ENTITY_MODEL(playerVehicle)
                if vehicleModel == Utils.Joaat("oppressor") or vehicleModel == Utils.Joaat("oppressor2") then
                    local antiOppressorAction = FeatureMgr.GetFeature(Utils.Joaat("antiopressorloop")):GetListIndex()
                    if FeatureMgr.IsFeatureEnabled(Utils.Joaat("exclfriendsantiopressorloop")) and IsPlayerFriend(targetPlayerId) then
                        return
                    end
                    if antiOppressorAction ~= 0 then
                        notify(("Player %s is using an Oppressor"):format(Players.GetName(targetPlayerId)))
                    end
                    if antiOppressorAction == 1 then
                        FeatureMgr.GetFeatureByName("Delete Player Vehicle", targetPlayerId):TriggerCallback()
                    elseif antiOppressorAction == 2 then
                        FeatureMgr.GetFeatureByName("Vehicle Kick", targetPlayerId):TriggerCallback()
                    elseif antiOppressorAction == 3 then
                        FeatureMgr.GetFeatureByName("Blow Vehicle Engine", targetPlayerId):TriggerCallback()
                    elseif antiOppressorAction == 4 then
                        FeatureMgr.GetFeatureByName("Smart Kick", targetPlayerId):TriggerCallback()
                    elseif antiOppressorAction == 5 then
                        FeatureMgr.GetFeatureByName("Crash Player", targetPlayerId):TriggerCallback()
                    end
                    Script.Yield(1500)
                    return
                end
            end
            if detectedPlayerReasons[detectionIndex] ~= nil and detectedPlayerNames[detectionIndex] ~= targetPlayerName then
                detectedPlayerNames[detectionIndex] = nil
                detectedPlayerReasons[detectionIndex] = nil
                KS_LOCAL_MODDER_WEBHOOK_REPORTED[targetPlayerId] = nil
            end
            local existingDetectionReason = detectedPlayerReasons[detectionIndex]
            if isKScriptUserRoleReason(existingDetectionReason) then
                detectedPlayerNames[detectionIndex] = targetPlayerName
                return
            end
            if existingDetectionReason == "Rockstar Administrator" then
                return
            end
            if KS_CheckFreeShoppingBalance(targetPlayerId, canonicalRockstarId, targetPlayerName) then
                return
            end
            if detectedPlayerReasons[detectionIndex] ~= "Rockstar Anti Cheat" then
                for _, reportReasonEntry in ipairs({
                    { eReportReason.CODE_TAMPERING, "Code Tampering" },
                    { eReportReason.CRC_CODE_CRCS, "Invalid CRC Code Check" },
                    { eReportReason.CRC_COMPROMISED, "Compromised CRC Check" },
                    { eReportReason.CRC_EXE_SIZE, "Modified Application size" },
                    { eReportReason.CRC_NOT_REPLIED, "CRC Check didnt reply" },
                    { eReportReason.CRC_REQUEST_FLOOD, "CRC Check Request Flood" },
                    { eReportReason.GAME_SERVER_CASH_BANK, "Cash Tamper (Bank)" },
                    { eReportReason.GAME_SERVER_CASH_WALLET, "Cash Tamper (Wallet)" },
                    { eReportReason.GAME_SERVER_INVENTORY, "Inventory Tamper" },
                    { eReportReason.GAME_SERVER_SERVER_INTEGRITY, "Game Server Integrity Check failed" },
                    { eReportReason.SCRIPT_CHEAT_DETECTION, "Cheat Detected" },
                    { eReportReason.TELEMETRY_BLOCK, "Blocking Telemetry" },
                }) do
                    local reportReasonLabel = reportReasonEntry[2]
                    if targetPlayer:IsReportBitSet(reportReasonEntry[1]) then
                        notify(("%s was detected by RAC, Reason: %s"):format(targetPlayerName, reportReasonLabel))
                        detectedPlayerNames[detectionIndex] = targetPlayerName
                        detectedPlayerReasons[detectionIndex] = "Rockstar Anti Cheat"
                        ModderDB.AddModderByPlayerId(targetPlayerId, "Rockstar Anti Cheat")
                        KS_ReportDetectedModder(targetPlayerId, targetPlayerName, "Rockstar Anti Cheat: " .. reportReasonLabel, canonicalRockstarId)
                        Script.Yield(0)
                        return
                    end
                end
            end
            local hasDaiveKitFirstFlag = PED.GET_PED_CONFIG_FLAG(targetPed, 141, true)
            local hasDaiveKitSecondFlag = PED.GET_PED_CONFIG_FLAG(targetPed, 144, true)
            if hasDaiveKitFirstFlag and hasDaiveKitSecondFlag then
                if detectedPlayerReasons[detectionIndex] == nil then
                    notify(("Detected %s for DaiveKit User"):format(targetPlayerName))
                end
                detectedPlayerNames[detectionIndex] = targetPlayerName
                detectedPlayerReasons[detectionIndex] = "DaiveKit User"
                KS_ReportDetectedModder(targetPlayerId, targetPlayerName, "DaiveKit User", canonicalRockstarId)
            end
            local maxHealth = ENTITY.GET_ENTITY_MAX_HEALTH(targetPed)
            if maxHealth > 328 then
                if detectedPlayerReasons[detectionIndex] == nil then
                    notify(("Detected %s for Modded Health %d"):format(targetPlayerName, maxHealth))
                end
                detectedPlayerNames[detectionIndex] = targetPlayerName
                detectedPlayerReasons[detectionIndex] = ("Modded Health (%i)"):format(maxHealth)
                KS_ReportDetectedModder(targetPlayerId, targetPlayerName, detectedPlayerReasons[detectionIndex], canonicalRockstarId)
            end
            local pedArmour = PED.GET_PED_ARMOUR(targetPed)
            if pedArmour > 50 and pedArmour ~= 100 then
                if detectedPlayerReasons[detectionIndex] == nil then
                    notify(("Detected %s for Modded Armour %d"):format(targetPlayerName, pedArmour))
                end
                detectedPlayerNames[detectionIndex] = targetPlayerName
                detectedPlayerReasons[detectionIndex] = ("Modded Armour (%i)"):format(pedArmour)
                KS_ReportDetectedModder(targetPlayerId, targetPlayerName, detectedPlayerReasons[detectionIndex], canonicalRockstarId)
            end
            if ENTITY.GET_ENTITY_HEALTH(targetPed) < 0 and ENTITY.GET_ENTITY_SPEED(targetPed) > 1 and not PED.IS_PED_RAGDOLL(targetPed) then
                if detectedPlayerReasons[detectionIndex] == nil then
                    notify(("Detected %s Undead OTR"):format(targetPlayerName))
                end
                detectedPlayerNames[detectionIndex] = targetPlayerName
                detectedPlayerReasons[detectionIndex] = "Undead OTR"
                KS_ReportDetectedModder(targetPlayerId, targetPlayerName, "Undead OTR", canonicalRockstarId)
            end
            local latestModderDbDetection = checkDetections(gamerInfo.RockstarId)
            if latestModderDbDetection == nil then
                return
            end
            if (latestModderDbDetection == "YMCA" or latestModderDbDetection == "GIT") and detectedPlayerReasons[detectionIndex] ~= "YimMenu" then
                if detectedPlayerReasons[detectionIndex] == nil then
                    notify(("Detected %s is using Yim Menu or a Menu that Skidded from Yim"):format(targetPlayerName))
                end
                detectedPlayerNames[detectionIndex] = targetPlayerName
                detectedPlayerReasons[detectionIndex] = "YimMenu"
                return
            end
            if latestModderDbDetection == "FRLY" then
                detectedPlayerNames[detectionIndex] = targetPlayerName
                detectedPlayerReasons[detectionIndex] = "Forced Relay"
            end
            if latestModderDbDetection == detectedPlayerReasons[detectionIndex] or detectedPlayerReasons[detectionIndex] ~= nil then
                return
            end
            if detectedPlayerReasons[detectionIndex] == nil then
                notify(("Detected %s for %s"):format(targetPlayerName, latestModderDbDetection))
            end
            detectedPlayerNames[detectionIndex] = targetPlayerName
            detectedPlayerReasons[detectionIndex] = latestModderDbDetection
        end

