        local function rebuildAdminRidSet()
            adminRIDSet = {}
            if type(adminRIDList) ~= "table" then
                return
            end
            for _, rawAdminRid in ipairs(adminRIDList) do
                local canonicalAdminRid = toCanonicalPlayerIdentifier(rawAdminRid)
                if canonicalAdminRid then
                    adminRIDSet[canonicalAdminRid] = true
                end
            end
        end

        rebuildAdminRidSet()

        function KS_GetPlayerEncounterRecord(targetPlayerId, canonicalRid)
            local identityLookupState = featurePlaneContext.__ksServerIdentityLookupState
            if type(identityLookupState) ~= "table" then
                identityLookupState = { nextPlayerId = -1, lastByPlayer = {} }
                featurePlaneContext.__ksServerIdentityLookupState = identityLookupState
            end
            identityLookupState.encounterByPlayer = type(identityLookupState.encounterByPlayer) == "table" and identityLookupState.encounterByPlayer or {}
            local encounterRecord = identityLookupState.encounterByPlayer[targetPlayerId]
            if type(encounterRecord) ~= "table" or encounterRecord.rid ~= canonicalRid then
                encounterRecord = { rid = canonicalRid, adminLogged = false, blacklistDecisionToken = nil }
                identityLookupState.encounterByPlayer[targetPlayerId] = encounterRecord
            end
            return encounterRecord
        end

        KS_BLACKLIST_REMOVAL_STATE = KS_BLACKLIST_REMOVAL_STATE or { byPlayer = {} }
        KS_BLACKLIST_DROP_KICK_RETRY_MS = 10000

        function KS_IsBlacklistTargetPresent(targetPlayerId, expectedRid, blacklistDecision)
            if NETWORK.NETWORK_IS_PLAYER_ACTIVE(targetPlayerId) ~= true then
                return false
            end
            local targetPlayer = Players.GetById(targetPlayerId)
            local gamerInfo = targetPlayer ~= nil and targetPlayer:GetGamerInfo() or nil
            local currentRid = gamerInfo ~= nil and toCanonicalPlayerIdentifier(gamerInfo.RockstarId) or nil
            if currentRid == nil or currentRid ~= expectedRid or not isFeaturePlaneInstallCurrent() then
                return false
            end
            if type(blacklistDecision) ~= "table" then
                return true
            end
            local remoteStatusState = featurePlaneContext.KS_REMOTE_PLAYER_STATUS_STATE
            local playerStatus = type(remoteStatusState) == "table" and type(remoteStatusState.byPlayer) == "table" and remoteStatusState.byPlayer[targetPlayerId] or nil
            if type(playerStatus) ~= "table" or playerStatus.canonical_player_id ~= expectedRid or type(playerStatus.blacklist_decision) ~= "table" or playerStatus.blacklist_decision.token ~= blacklistDecision.token then
                return false
            end
            for _, matchedTarget in ipairs(type(blacklistDecision.matched_targets) == "table" and blacklistDecision.matched_targets or {}) do
                if matchedTarget.type == "ROCKSTAR_ACCOUNT" and toCanonicalPlayerIdentifier(matchedTarget.id) ~= expectedRid then
                    return false
                end
                if matchedTarget.type == "CREW" then
                    if type(featurePlaneContext.KSResolveCrewIdentity) ~= "function" then
                        return false
                    end
                    local crewIdentity = featurePlaneContext.KSResolveCrewIdentity(targetPlayerId, expectedRid, true)
                    if type(crewIdentity) ~= "table" or toCanonicalPlayerIdentifier(crewIdentity.id) ~= matchedTarget.id then
                        return false
                    end
                end
            end
            return true
        end

        local queueBlacklistActionResultReport = nil

        function KS_StopBlacklistRemoval(targetPlayerId)
            local removalEntry = KS_BLACKLIST_REMOVAL_STATE.byPlayer[targetPlayerId]
            KS_BLACKLIST_REMOVAL_STATE.byPlayer[targetPlayerId] = nil
            if type(removalEntry) == "table" and type(removalEntry.decision) == "table" and removalEntry.reported ~= true then
                removalEntry.reported = true
                queueBlacklistActionResultReport(removalEntry.decision, targetPlayerId, removalEntry.rid, "TARGET_LEFT", "Player left before blacklist removal completed.")
            end
        end

        function queueBlacklistActionResultReport(blacklistDecision, targetPlayerId, targetRid, resultCode, resultMessage)
            if type(blacklistDecision) ~= "table" or type(blacklistDecision.token) ~= "string" or type(featurePlaneContext.KSReportBlacklistActionResult) ~= "function" or not isTableOrUserdata(Script) or type(Script.QueueJob) ~= "function" then
                return false
            end
            return Script.QueueJob(function()
                if not isFeaturePlaneInstallCurrent() or ShouldUnload() then
                    return
                end
                featurePlaneContext.KSReportBlacklistActionResult(blacklistDecision.token, resultCode, targetPlayerId, targetRid, resultMessage)
            end) ~= false
        end

        local blacklistFeatureActionsById = {}
        local dropKickBlacklistAction = { safety = "BLACKLIST_TRIGGER_ALLOWED" }

        function dropKickBlacklistAction.run(targetPlayerId, expectedRid, blacklistDecision)
            if not KS_IsBlacklistTargetPresent(targetPlayerId, expectedRid, blacklistDecision) then
                return "STALE_TARGET", "Stable player identity no longer matches."
            end
            local dropKickFeature = FeatureMgr.GetFeatureByName("Drop Kick", targetPlayerId)
            if dropKickFeature == nil or type(dropKickFeature.TriggerCallback) ~= "function" then
                return "ACTION_UNAVAILABLE", "Registered Drop Kick feature is unavailable."
            end
            local triggerOk = pcall(function()
                dropKickFeature:TriggerCallback()
            end)
            return triggerOk and "ACTION_EXECUTED" or "ACTION_FAILED", triggerOk and "Registered Drop Kick action executed." or "Registered Drop Kick action failed."
        end

        blacklistFeatureActionsById.DROP_KICK = dropKickBlacklistAction

        function KS_RunBlacklistRemoval(targetPlayerId, targetRid, removalEntry)
            while nil and KS_BLACKLIST_REMOVAL_STATE.byPlayer[targetPlayerId] == removalEntry and not ShouldUnload() do
                if not KS_IsBlacklistTargetPresent(targetPlayerId, targetRid, removalEntry.decision) then
                    if type(removalEntry.decision) == "table" and removalEntry.reported ~= true then
                        removalEntry.reported = true
                        queueBlacklistActionResultReport(removalEntry.decision, targetPlayerId, targetRid, "TARGET_LEFT", "Player identity left or changed before removal.")
                    end
                    break
                end
                local isRemovalDispatched = false
                local dispatchMessage = "Drop Kick blacklist removal dispatched."
                if NETWORK.NETWORK_IS_HOST() then
                    isRemovalDispatched = KSRunHostKick(targetPlayerId) == "ok"
                    dispatchMessage = "SC administrator blacklist removal dispatched."
                else
                    local dropKickFeature = FeatureMgr.GetFeatureByName("Drop Kick", targetPlayerId)
                    if dropKickFeature ~= nil and type(dropKickFeature.TriggerCallback) == "function" then
                        isRemovalDispatched = pcall(function()
                            dropKickFeature:TriggerCallback()
                        end)
                    end
                end
                if isRemovalDispatched and type(removalEntry.decision) == "table" and removalEntry.reported ~= true then
                    removalEntry.reported = true
                    queueBlacklistActionResultReport(removalEntry.decision, targetPlayerId, targetRid, "ACTION_EXECUTED", dispatchMessage)
                end
                yieldScriptMs(KS_BLACKLIST_DROP_KICK_RETRY_MS, 10000)
            end
            if KS_BLACKLIST_REMOVAL_STATE.byPlayer[targetPlayerId] == removalEntry then
                KS_BLACKLIST_REMOVAL_STATE.byPlayer[targetPlayerId] = nil
            end
        end

        function KS_QueueBlacklistRemoval(targetPlayerId, targetRid, blacklistDecision)
            targetPlayerId = tonumber(targetPlayerId)
            targetRid = toCanonicalPlayerIdentifier(targetRid)
            if targetPlayerId == nil or targetRid == nil or not isTableOrUserdata(Script) or type(Script.QueueJob) ~= "function" or type(Script.Yield) ~= "function" then
                return false
            end
            local existingRemovalEntry = KS_BLACKLIST_REMOVAL_STATE.byPlayer[targetPlayerId]
            local decisionToken = type(blacklistDecision) == "table" and blacklistDecision.token or "legacy:" .. targetRid
            if type(existingRemovalEntry) == "table" and existingRemovalEntry.rid == targetRid and existingRemovalEntry.decisionToken == decisionToken then
                return true
            end
            local removalEntry = { rid = targetRid, decision = blacklistDecision, decisionToken = decisionToken, reported = false }
            KS_BLACKLIST_REMOVAL_STATE.byPlayer[targetPlayerId] = removalEntry
            local queueJobResult = Script.QueueJob(KS_RunBlacklistRemoval, targetPlayerId, targetRid, removalEntry)
            if queueJobResult == false then
                KS_BLACKLIST_REMOVAL_STATE.byPlayer[targetPlayerId] = nil
                if type(blacklistDecision) == "table" then
                    removalEntry.reported = true
                    queueBlacklistActionResultReport(blacklistDecision, targetPlayerId, targetRid, "ACTION_FAILED", "Blacklist removal job was not admitted.")
                end
            end
            return queueJobResult ~= false
        end

        function KS_HandleRockstarAdminEncounter(adminPlayerId, adminRid, adminName)
            local encounterRecord = KS_GetPlayerEncounterRecord(adminPlayerId, adminRid)
            if encounterRecord.adminLogged then
                return false
            end
            encounterRecord.adminLogged = true
            notify(("Detected %s as Rockstar Administrator!"):format(adminName))
            logLegacyFeatureAction("admin-detected", ("%s encountered a Rockstar Admin %s(%s) (Game: %s)"):format(SOCIALCLUB.SC_ACCOUNT_INFO_GET_NICKNAME(), adminName, adminRid, getGameVersion(isGameVersionEnhanced)))
            if not KS_ReassertAuthoritativeKScriptIdentity(adminPlayerId, adminRid, adminName) then
                detectedPlayerNames[adminPlayerId + 1] = adminName
                detectedPlayerReasons[adminPlayerId + 1] = "Rockstar Administrator"
            end
            return true
        end

        function KS_HandleBlacklistedPlayerEncounter(targetPlayerId, targetRid, targetName, blacklistDecision)
            if KS_IsDeveloperFeaturePlaneLoad() then
                return false
            end
            local encounterRecord = KS_GetPlayerEncounterRecord(targetPlayerId, targetRid)
            local decisionToken = type(blacklistDecision) == "table" and blacklistDecision.token or "legacy:" .. targetRid
            if encounterRecord.blacklistDecisionToken == decisionToken then
                return false
            end
            encounterRecord.blacklistDecisionToken = decisionToken
            local decisionType = type(blacklistDecision) == "table" and blacklistDecision.type or "KICK"
            logLegacyFeatureAction("blacklist-detected", ("%s encountered a Blacklisted Player %s(%s) (Game: %s, Decision: %s)"):format(SOCIALCLUB.SC_ACCOUNT_INFO_GET_NICKNAME(), targetName, targetRid, getGameVersion(isGameVersionEnhanced), decisionType))
            if decisionType == "LOG_ONLY" then
                notify(("Blacklist match logged for %s."):format(tostring(targetName or targetRid)))
                return true
            end
            if type(blacklistDecision) == "table" and blacklistDecision.result ~= "ACTION_QUEUED" then
                return true
            end
            if decisionType == "KICK" then
                if not FeatureMgr.IsFeatureEnabled(Utils.Joaat("PlayerBlockIncomingEntitySyncs"), targetPlayerId) then
                    local blockSyncsFeature = FeatureMgr.GetFeatureByName("Block In Syncs", targetPlayerId)
                    local blockScriptEventsFeature = FeatureMgr.GetFeatureByName("Block In SE", targetPlayerId)
                    if blockSyncsFeature then
                        blockSyncsFeature:Toggle()
                    end
                    if blockScriptEventsFeature then
                        blockScriptEventsFeature:Toggle()
                    end
                end
                KS_QueueBlacklistRemoval(targetPlayerId, targetRid, blacklistDecision)
                return true
            end
            if decisionType ~= "FEATURE_ACTION" then
                queueBlacklistActionResultReport(blacklistDecision, targetPlayerId, targetRid, "ACTION_UNAVAILABLE", "Blacklist decision type is unavailable.")
                return false
            end
            local featureAction = blacklistFeatureActionsById[blacklistDecision.action_id]
            if type(featureAction) ~= "table" or featureAction.safety ~= "BLACKLIST_TRIGGER_ALLOWED" or type(featureAction.run) ~= "function" then
                queueBlacklistActionResultReport(blacklistDecision, targetPlayerId, targetRid, "ACTION_UNAVAILABLE", "Blacklist feature action is not registered.")
                return false
            end
            if Script.QueueJob(function()
                if not isFeaturePlaneInstallCurrent() or ShouldUnload() then
                    return
                end
                local resultCode, resultMessage = featureAction.run(targetPlayerId, targetRid, blacklistDecision)
                queueBlacklistActionResultReport(blacklistDecision, targetPlayerId, targetRid, resultCode, resultMessage)
            end) == false then
                queueBlacklistActionResultReport(blacklistDecision, targetPlayerId, targetRid, "ACTION_FAILED", "Blacklist feature action job was not admitted.")
                return false
            end
            return true
        end

        function KS_ApplyAuthoritativePlayerEncounter(targetPlayerId, targetRid, targetName)
            local remoteStatusState = featurePlaneContext.KS_REMOTE_PLAYER_STATUS_STATE
            local playerStatus = type(remoteStatusState) == "table" and type(remoteStatusState.byPlayer) == "table" and remoteStatusState.byPlayer[targetPlayerId] or nil
            if type(playerStatus) ~= "table" or playerStatus.canonical_player_id ~= targetRid then
                return false
            end
            if playerStatus.is_rockstar_admin == true then
                KS_HandleRockstarAdminEncounter(targetPlayerId, targetRid, targetName)
            end
            if playerStatus.is_blacklisted == true then
                KS_HandleBlacklistedPlayerEncounter(targetPlayerId, targetRid, targetName, playerStatus.blacklist_decision)
            end
            return true
        end

        local function refreshPlayerServerIdentityLookup(targetPlayerId, isJoinEvent)
            targetPlayerId = tonumber(targetPlayerId)
            if targetPlayerId == nil or targetPlayerId < 0 or targetPlayerId >= 32 or targetPlayerId == GTA.GetLocalPlayerId() then
                return false
            end
            local targetPlayer = Players.GetById(targetPlayerId)
            local gamerInfo = targetPlayer ~= nil and targetPlayer:GetGamerInfo() or nil
            local currentRid = gamerInfo ~= nil and toCanonicalPlayerIdentifier(gamerInfo.RockstarId) or nil
            if currentRid == nil then
                return false
            end
            local identityLookupState = featurePlaneContext.__ksServerIdentityLookupState
            if type(identityLookupState) ~= "table" then
                identityLookupState = { nextPlayerId = -1, lastByPlayer = {} }
                featurePlaneContext.__ksServerIdentityLookupState = identityLookupState
            end
            identityLookupState.lastByPlayer = type(identityLookupState.lastByPlayer) == "table" and identityLookupState.lastByPlayer or {}
            identityLookupState.encounterByPlayer = type(identityLookupState.encounterByPlayer) == "table" and identityLookupState.encounterByPlayer or {}
            local previousLookup = identityLookupState.lastByPlayer[targetPlayerId]
            if type(previousLookup) == "table" and previousLookup.rid ~= currentRid then
                clearRemotePlayerStatus(targetPlayerId)
                identityLookupState.encounterByPlayer[targetPlayerId] = nil
            end
            local hasPreviousLookup = type(previousLookup) == "table"
            local targetName = Players.GetName(targetPlayerId)
            if isJoinEvent == true and hasPreviousLookup then
                KS_ApplyAuthoritativePlayerEncounter(targetPlayerId, currentRid, targetName)
                return true
            end
            local modderLookupName = targetName
            local isModderLookupAccepted = LookupModderReasonForPlayer(targetPlayerId, currentRid, modderLookupName, gamerInfo.HostKey)
            identityLookupState.lastByPlayer[targetPlayerId] = {
                rid = currentRid,
                joinQueued = hasPreviousLookup or isJoinEvent == true and (hasPreviousLookup or modderLookupName),
            }
            KS_ApplyAuthoritativePlayerEncounter(targetPlayerId, currentRid, targetName)
            return isModderLookupAccepted ~= false
        end

        function KS_ServerIdentityLookupTick()
            for scanPlayerId = 0, 31 do
                refreshPlayerServerIdentityLookup(scanPlayerId, false)
                if scanPlayerId % 8 == 7 then
                    Script.Yield(0)
                end
            end
            Script.Yield(5000)
        end

        function onPlayerJoin(joiningPlayerId)
            if maintransitionActive or featurePlaneContext.__ksTransitionWatch.active == true then
                return
            end
            if joiningPlayerId == GTA.GetLocalPlayerId() then
                return
            end
            local joiningPlayer = Players.GetById(joiningPlayerId)
            if not joiningPlayer then
                return
            end
            local gamerInfo = joiningPlayer:GetGamerInfo()
            if not gamerInfo then
                return
            end
            local joiningRid = toCanonicalPlayerIdentifier(gamerInfo.RockstarId)
            if not joiningRid then
                return
            end
            if not next(adminRIDSet) then
                rebuildAdminRidSet()
            end
            if adminRIDSet[joiningRid] then
                KS_HandleRockstarAdminEncounter(joiningPlayerId, joiningRid, Players.GetName(joiningPlayerId))
            end
            refreshPlayerServerIdentityLookup(joiningPlayerId, true)
        end

        function onPlayerLeave(leavingPlayerId)
            KS_FREE_SHOPPING_PROBES[leavingPlayerId] = nil
            KS_FREE_SHOPPING_REPORTED[leavingPlayerId] = nil
            KS_StopBlacklistRemoval(leavingPlayerId)
            if type(KS_WEAPON_DAMAGE_GUARD) == "table" and type(KS_WEAPON_DAMAGE_GUARD.senders) == "table" then
                KS_WEAPON_DAMAGE_GUARD.senders[tonumber(leavingPlayerId) or leavingPlayerId] = nil
            end
            featurePlaneInstall.paidRemovalProvider:releaseTarget(leavingPlayerId, true, "player_left")
            clearRemotePlayerStatus(leavingPlayerId)
            if type(KSClearBlameKillRecipientPassthrough) == "function" then
                KSClearBlameKillRecipientPassthrough(leavingPlayerId)
            end
            if type(KS_BLAME_KILL_PREARM) == "table" and type(KS_BLAME_KILL_PREARM.remoteOrbitalFreeCameraUntilMs) == "table" then
                KS_BLAME_KILL_PREARM.remoteOrbitalFreeCameraUntilMs[leavingPlayerId] = nil
            end
            if closeSpawnPedVehicleCache[leavingPlayerId] then
                closeSpawnPedVehicleCache[leavingPlayerId] = nil
            end
            closeSpawnPendingPersonalVehicles[leavingPlayerId] = nil
            if spoofedPid[leavingPlayerId] then
                spoofedPid[leavingPlayerId] = false
                spoofedVehicle = {}
            end
            if largeObjectDumpedPlayerIds[leavingPlayerId] then
                if not maintransitionActive and featurePlaneContext.__ksTransitionWatch.active ~= true then
                    local largeObjectCleanupFeature = FeatureMgr.GetFeature(Utils.Joaat("largeObjDmpCleanup1"))
                    if largeObjectCleanupFeature then
                        largeObjectCleanupFeature:OnClick()
                    end
                end
                largeObjectDumpedPlayerIds[leavingPlayerId] = nil
            end
            if detectedPlayerNames[leavingPlayerId + 1] ~= nil or detectedPlayerReasons[leavingPlayerId + 1] ~= nil then
                detectedPlayerNames[leavingPlayerId + 1] = nil
                detectedPlayerReasons[leavingPlayerId + 1] = nil
            end
            KS_LOCAL_MODDER_WEBHOOK_REPORTED[leavingPlayerId] = nil
            if leavingPlayerId == GTA.GetLocalPlayerId() then
                if hostShareServerActive then
                    hostShareServerActive = false
                end
                for dumpedPlayerId in pairs(largeObjectDumpedPlayerIds) do
                    largeObjectDumpedPlayerIds[dumpedPlayerId] = nil
                end
            end
            if hostSharePID ~= nil and hostSharePID == leavingPlayerId then
                hostSharePID = nil
                hostShareServerActive = false
            end
            if lastPTFXEventTimes[leavingPlayerId + 1] ~= nil then
                lastPTFXEventTimes[leavingPlayerId + 1] = nil
            end
            if lastSoundEventTimes[leavingPlayerId + 1] ~= nil then
                lastSoundEventTimes[leavingPlayerId + 1] = nil
            end
            if netEventblacklist[leavingPlayerId + 1] ~= nil then
                netEventblacklist[leavingPlayerId + 1] = nil
            end
            if worldStateEventblacklist[leavingPlayerId + 1] ~= nil then
                worldStateEventblacklist[leavingPlayerId + 1] = nil
            end
            if lastWorldStateEventTimes[leavingPlayerId + 1] ~= nil then
                lastWorldStateEventTimes[leavingPlayerId + 1] = nil
            end
            if sentHostShareEventPlayers[leavingPlayerId + 1] ~= nil then
                sentHostShareEventPlayers[leavingPlayerId + 1] = nil
            end
            local serverIdentityLookupState = featurePlaneContext.__ksServerIdentityLookupState
            if type(serverIdentityLookupState) == "table" and type(serverIdentityLookupState.lastByPlayer) == "table" then
                serverIdentityLookupState.lastByPlayer[leavingPlayerId] = nil
            end
            if type(serverIdentityLookupState) == "table" and type(serverIdentityLookupState.encounterByPlayer) == "table" then
                serverIdentityLookupState.encounterByPlayer[leavingPlayerId] = nil
            end
        end

