                VK_sorted[#VK_sorted + 1] = { id = vkKeyId, name = vkKeyEntry.name, key = vkKeyEntry.key }
            end
            table.sort(VK_sorted, function(firstKeyEntry, secondKeyEntry)
                return firstKeyEntry.key < secondKeyEntry.key
            end)
            keyOptions = {}
            keyByName = {}
            keyByIndex = {}
            for sortedKeyIndex, sortedKeyEntry in ipairs(VK_sorted) do
                keyOptions[sortedKeyIndex] = sortedKeyEntry.name
                keyByName[sortedKeyEntry.name] = { key = sortedKeyEntry.key, idx = sortedKeyIndex }
                keyByIndex[sortedKeyIndex] = { name = sortedKeyEntry.name, key = sortedKeyEntry.key }
            end
