            local openKeyComboForDefault = openKeyFeature
            openKeyComboForDefault.SetListIndex(openKeyComboForDefault, 8)
        end

        InitEmoteHotkeyOptions()
        emoteHotkeyWasDown = false

        function CheckEmoteHotkey()
            local selectedKeyIndex = openKeyFeature:GetListIndex() + 1
            if selectedKeyIndex < 1 then
                Script.Yield(100)
                return
            end
            local isSelectedKeyMapped = VK_KEY[keyOptions[selectedKeyIndex]] ~= nil
            if isSelectedKeyMapped and not emoteHotkeyWasDown then
                openval:SetBoolValue(true)
                focusRequested = false
            end
            emoteHotkeyWasDown = isSelectedKeyMapped
            Script.Yield(25)
        end

        openval = FeatAdd(Utils.Joaat("open_emote_box"), "Open Emote Box", eFeatureType.Toggle, "Toggle the emote input")
        emoteX = FeatAdd(Utils.Joaat("emote_x"), "Emote X Pos %", eFeatureType.SliderFloat, "Horizontal position (as % of screen)")
        emoteY = FeatAdd(Utils.Joaat("emote_y"), "Emote Y Pos %", eFeatureType.SliderFloat, "Vertical position (as % of screen)")
        inputColor = FeatAdd(Utils.Joaat("emote_input_color"), "Border Color", eFeatureType.InputColor4, "Color of the window border")
        bgColor = FeatAdd(Utils.Joaat("BgColor"), "BG Color", eFeatureType.InputColor4, "Color of the background surrounding the box")
        InputText = FeatAdd(Utils.Joaat("InputTextColor"), "Input Text Color", eFeatureType.InputColor4, "Color of the input Box")
        local emoteXSliderForMin = emoteX
        emoteXSliderForMin.SetMinValue(emoteXSliderForMin, 0.0)
        local emoteXSliderForMax = emoteX
