        function DrawWindowBorder(rectLeft, rectTop, rectWidth, rectHeight, lineRed, lineGreen, lineBlue, lineAlpha)
            ImGui.AddLine(rectLeft, rectTop, rectLeft + rectWidth, rectTop, lineRed, lineGreen, lineBlue, lineAlpha, borderThickness)
            ImGui.AddLine(rectLeft + rectWidth, rectTop, rectLeft + rectWidth, rectTop + rectHeight, lineRed, lineGreen, lineBlue, lineAlpha, borderThickness)
            ImGui.AddLine(rectLeft + rectWidth, rectTop + rectHeight, rectLeft, rectTop + rectHeight, lineRed, lineGreen, lineBlue, lineAlpha, borderThickness)
            ImGui.AddLine(rectLeft, rectTop + rectHeight, rectLeft, rectTop, lineRed, lineGreen, lineBlue, lineAlpha, borderThickness)
        end

        function emotetext()
            if not openval:GetBoolValue() then
                focusRequested = false
                KSResetEmoteSuggestions()
                return
            end
            KSRefreshEmoteSuggestions()
            local textLineHeight = ImGui.GetTextLineHeight()
            local totalWindowHeight = windowHeight + #EMOTE_SUGGESTIONS * (textLineHeight + 2)
            local displayWidth, displayHeight = ImGui.GetDisplaySize()
            local windowPosX = displayWidth * emoteX:GetFloatValue() - windowWidth / 2
            local windowPosY = displayHeight * emoteY:GetFloatValue()
            local borderRed, borderGreen, borderBlue, borderAlpha = inputColor:GetColor()
            local backgroundRed, backgroundGreen, backgroundBlue, backgroundAlpha = bgColor:GetColor()
            local inputFrameRed, inputFrameGreen, inputFrameBlue, inputFrameAlpha = InputText:GetColor()
            ImGui.AddRectFilled(windowPosX, windowPosY, windowPosX + windowWidth, windowPosY + totalWindowHeight, backgroundRed, backgroundGreen, backgroundBlue, backgroundAlpha)
            DrawWindowBorder(windowPosX, windowPosY, windowWidth, totalWindowHeight, borderRed, borderGreen, borderBlue, borderAlpha)
            ImGui.SetNextWindowPos(windowPosX, windowPosY, ImGuiCond.Always)
            ImGui.SetNextWindowSize(windowWidth, totalWindowHeight, ImGuiCond.Always)
            if ImGui.Begin("Emote Input", true, ImGuiWindowFlags.NoTitleBar | ImGuiWindowFlags.NoResize | ImGuiWindowFlags.NoMove | ImGuiWindowFlags.NoBackground | ImGuiWindowFlags.NoSavedSettings) then
                ImGui.SetCursorPosX((windowWidth - inputBoxWidth) / 2)
                ImGui.SetCursorPosY(3)
                if not focusRequested then
                    ImGui.SetKeyboardFocusHere()
                    focusRequested = true
                end
                ImGui.PushItemWidth(inputBoxWidth)
                local inputTextFlags = ImGuiInputTextFlags.EnterReturnsTrue
                if EMOTE_TAB_COMPLETION then
                    inputTextFlags = inputTextFlags | ImGuiInputTextFlags.AllowTabInput
                end
                ImGui.PushStyleColor(ImGuiCol.FrameBg, inputFrameRed / 255, inputFrameGreen / 255, inputFrameBlue / 255, inputFrameAlpha / 255)
                local editedInputText, isInputSubmitted = ImGui.InputText("##emote_input", STRING_BUFFER, inputTextFlags)
                ImGui.PopStyleColor()
                ImGui.PopItemWidth()
                local hasTabCharacter = editedInputText:find("\t", 1, true) ~= nil
                if hasTabCharacter then
                    local inputWithoutTabs = editedInputText:gsub("\t", "")
                    local tabCompletedCommand, isTabCompleted = KSTabCompleteEmoteCommand(inputWithoutTabs)
                    STRING_BUFFER = isTabCompleted and tabCompletedCommand or inputWithoutTabs
                    EMOTE_SUGGESTION_BUFFER = nil
                    KSRefreshEmoteSuggestions()
                    if isTabCompleted then
                        ImGui.SetKeyboardFocusHere(-1)
                        focusRequested = true
                    end
                elseif editedInputText ~= STRING_BUFFER then
                    STRING_BUFFER = editedInputText
                    EMOTE_SUGGESTION_BUFFER = nil
                    KSRefreshEmoteSuggestions()
                end
                if isInputSubmitted and ImGui.IsKeyPressed(ImGuiKey.Enter) and not hasTabCharacter then
                    local submittedCommand = STRING_BUFFER
                    local parsedEmoteCommand = KSParseEmoteCommand(submittedCommand)
                    if parsedEmoteCommand then
                        if parsedEmoteCommand.cancel then
                            Script.QueueJob(EmoteCancel)
                        else
                            local resolvedEmote = KSResolveEmoteCommand(parsedEmoteCommand)
                            if resolvedEmote then
                                Script.QueueJob(OnEmotePlay, resolvedEmote.definition)
                            else
                                notify("'" .. parsedEmoteCommand.query .. "' is not a valid emote!")
                            end
                        end
                    elseif submittedCommand:find("/dance") then
                        local danceName = submittedCommand:gsub("/dance ", "")
                        Script.QueueJob(playDance, danceName)
                    else
                        notify("Invalid command: use /e or /dance")
                    end
                    openval:SetBoolValue(false)
                    STRING_BUFFER = ""
                    KSResetEmoteSuggestions()
                end
                for _, emoteSuggestion in ipairs(EMOTE_SUGGESTIONS) do
                    local suggestionLabel = tostring(emoteSuggestion.label or emoteSuggestion.alias)
                    if #suggestionLabel > 42 then
                        suggestionLabel = suggestionLabel:sub(1, 39) .. "..."
                    end
                    ImGui.SetCursorPosX((windowWidth - inputBoxWidth) / 2)
                    ImGui.TextUnformatted("/e " .. tostring(emoteSuggestion.alias) .. " - " .. suggestionLabel)
                end
                if ImGui.IsMouseClicked(0) and not ImGui.IsWindowHovered() then
                    focusRequested = false
                end
            end
            ImGui.End()
        end

