        function KSGetOwnObjectID()
            local localPed = GTA.GetLocalPed()
            local localPedType = type(localPed)
            if localPedType ~= "table" and localPedType ~= "userdata" then
                return 0
            end
            local pedNetObject = localPed.NetObject
            local netObjectType = type(pedNetObject)
            if netObjectType ~= "table" and netObjectType ~= "userdata" then
                return 0
            end
            return tonumber(pedNetObject.ObjectID) or 0
        end

        function KSResetBlameKillSessionReadiness()
            KS_BLAME_KILL_PREARM.sessionStableSinceMs = 0
        end

        function KSIsBlameKillSessionFullyLoaded(nowMs)
            nowMs = tonumber(nowMs) or getRuntimeNowMs()

            local function markSessionNotReady()
                KSResetBlameKillSessionReadiness()
                return false
            end

            if not KS_IsNetworkPlayerSessionReady() then
                return markSessionNotReady()
            end
            if not isTableOrUserdata(NETWORK) or not isTableOrUserdata(DLC) or not isTableOrUserdata(PLAYER) or not isTableOrUserdata(ENTITY) or type(PLAYER.PLAYER_PED_ID) ~= "function" or type(ENTITY.DOES_ENTITY_EXIST) ~= "function" then
                return markSessionNotReady()
            end
            if type(NETWORK.NETWORK_IS_SESSION_STARTED) == "function" and NETWORK.NETWORK_IS_SESSION_STARTED() ~= true then
                return markSessionNotReady()
            end
            if type(NETWORK.NETWORK_IS_IN_TRANSITION) == "function" and NETWORK.NETWORK_IS_IN_TRANSITION() == true then
                return markSessionNotReady()
            end
            if type(DLC.GET_IS_LOADING_SCREEN_ACTIVE) == "function" and DLC.GET_IS_LOADING_SCREEN_ACTIVE() == true then
                return markSessionNotReady()
            end
            if type(DLC.GET_IS_INITIAL_LOADING_SCREEN_ACTIVE) == "function" and DLC.GET_IS_INITIAL_LOADING_SCREEN_ACTIVE() == true then
                return markSessionNotReady()
            end
            local playerPed = PLAYER.PLAYER_PED_ID()
            if playerPed == nil or playerPed == 0 or ENTITY.DOES_ENTITY_EXIST(playerPed) ~= true or (tonumber(KSGetOwnObjectID()) or 0) <= 0 then
                return markSessionNotReady()
            end
            local stableSinceMs = tonumber(KS_BLAME_KILL_PREARM.sessionStableSinceMs) or 0
            if stableSinceMs <= 0 or nowMs < stableSinceMs then
                KS_BLAME_KILL_PREARM.sessionStableSinceMs = nowMs
                return false
            end
            return nowMs - stableSinceMs >= KS_BLAME_KILL_SESSION_STABLE_MS
        end

