        function KSWeaponDamageNormalizeHash(rawHash)
            local numericHash = tonumber(rawHash)
            if numericHash == nil then
                return 0
            end
            local unsignedHash = math.floor(numericHash)
            if unsignedHash < 0 then
                unsignedHash = unsignedHash + 4294967296
            end
            return unsignedHash % 4294967296
        end

        function KSWeaponDamageHash(weaponName)
            return KSWeaponDamageNormalizeHash(Utils.Joaat(weaponName))
        end

        KS_WEAPON_DAMAGE_HASH_EXPLOSION = KSWeaponDamageHash("WEAPON_EXPLOSION")
        KS_WEAPON_DAMAGE_HASH_UNARMED = KSWeaponDamageHash("WEAPON_UNARMED")
        KS_WEAPON_DAMAGE_STUN_HASHES = { [KSWeaponDamageHash("WEAPON_STUNGUN")] = true, [KSWeaponDamageHash("WEAPON_STUNGUN_MP")] = true }
        KS_WEAPON_DAMAGE_SLOW_HASHES = {}
        for slowDamageWeaponIndex, slowDamageWeaponName in ipairs({
            "WEAPON_GRENADE",
            "WEAPON_STICKYBOMB",
