            KS_WEAPON_DAMAGE_SLOW_HASHES[KSWeaponDamageHash(slowDamageWeaponName)] = true
        end
        KS_WEAPON_DAMAGE_GUARD = {
            parserVersion = KS_WEAPON_DAMAGE_PARSER_VERSION,
            senders = {},
            resetReason = "startup",
            resetAtMs = getRuntimeNowMs(),
        }
        featurePlaneContext.__ksWeaponDamageGuard = KS_WEAPON_DAMAGE_GUARD

        function KSWeaponDamageIsBoundHostObject(hostObject)
            local hostObjectType = type(hostObject)
            return hostObjectType == "table" or hostObjectType == "userdata"
        end

        function KSResetWeaponDamageGuard(resetReason)
            KS_WEAPON_DAMAGE_GUARD.senders = {}
            KS_WEAPON_DAMAGE_GUARD.resetReason = tostring(resetReason or "manual")
            KS_WEAPON_DAMAGE_GUARD.resetAtMs = getRuntimeNowMs()
        end

        function KSWeaponDamageReader(eventBuffer)
            return { buffer = eventBuffer, bits = 0, error = nil }
        end

        function KSWeaponDamageReadUns(bitReader, bitCount, fieldName)
            if bitReader.error ~= nil then
                return nil
            end
            local unsignedValue, readOk = bitReader.buffer:ReadUns(bitCount)
            if readOk ~= true then
                bitReader.error = ("truncated_%s_at_bit_%d"):format(fieldName, bitReader.bits)
                return nil
            end
            bitReader.bits = bitReader.bits + bitCount
            return tonumber(unsignedValue)
        end

        function KSWeaponDamageReadInt(bitReader, bitCount, fieldName)
            if bitReader.error ~= nil then
                return nil
            end
            local signedValue, readOk = bitReader.buffer:ReadInt(bitCount)
            if readOk ~= true then
                bitReader.error = ("truncated_%s_at_bit_%d"):format(fieldName, bitReader.bits)
                return nil
            end
            bitReader.bits = bitReader.bits + bitCount
            return tonumber(signedValue)
        end

        function KSWeaponDamageReadBool(bitReader, fieldName)
            if bitReader.error ~= nil then
                return nil
            end
            local isBitSet, readOk = bitReader.buffer:ReadBool()
            if readOk ~= true then
                bitReader.error = ("truncated_%s_at_bit_%d"):format(fieldName, bitReader.bits)
                return nil
            end
            bitReader.bits = bitReader.bits + 1
            return isBitSet == true
        end

        function KSWeaponDamageReadSignedFloat(bitReader, bitCount, maxMagnitude, fieldName)
            local quantizedValue = KSWeaponDamageReadInt(bitReader, bitCount, fieldName)
            if quantizedValue == nil then
                return nil, nil
            end
            return quantizedValue / ((1 << bitCount - 1) - 1) * maxMagnitude, quantizedValue
        end

        function KSWeaponDamageReadVector(bitReader, maxMagnitude, fieldPrefix)
            local decodedVector = { raw = {} }
            local rawComponentsX = decodedVector.raw
            local scaledX, quantizedX = KSWeaponDamageReadSignedFloat(bitReader, 16, maxMagnitude, fieldPrefix .. "_x")
            rawComponentsX.x = quantizedX
            decodedVector.x = scaledX
            local rawComponentsY = decodedVector.raw
            local scaledY, quantizedY = KSWeaponDamageReadSignedFloat(bitReader, 16, maxMagnitude, fieldPrefix .. "_y")
            rawComponentsY.y = quantizedY
            decodedVector.y = scaledY
            local rawComponentsZ = decodedVector.raw
            local scaledZ, quantizedZ = KSWeaponDamageReadSignedFloat(bitReader, 16, maxMagnitude, fieldPrefix .. "_z")
            rawComponentsZ.z = quantizedZ
            decodedVector.z = scaledZ
            if bitReader.error ~= nil then
                return nil
            end
            return decodedVector
        end

        function KSGetWeaponDamageEventData(eventBuffer, senderPlayer)
            if not KSWeaponDamageIsBoundHostObject(eventBuffer) or type(eventBuffer.ReadUns) ~= "function" or type(eventBuffer.ReadInt) ~= "function" or type(eventBuffer.ReadBool) ~= "function" then
                return nil, "invalid_buffer"
            end
            if not KSWeaponDamageIsBoundHostObject(senderPlayer) or tonumber(senderPlayer.PlayerId) == nil then
                return nil, "invalid_sender"
            end
            local canSeekBuffer = type(eventBuffer.Seek) == "function"
            if canSeekBuffer then
                eventBuffer:Seek(0)
            end
            local bitReader = KSWeaponDamageReader(eventBuffer)
            local damageEvent = {
                parserVersion = KS_WEAPON_DAMAGE_PARSER_VERSION,
                senderId = tonumber(senderPlayer.PlayerId),
                damageType = KSWeaponDamageReadUns(bitReader, 2, "damage_type"),
                weaponHash = KSWeaponDamageNormalizeHash(KSWeaponDamageReadUns(bitReader, 32, "weapon_hash")),
                override = KSWeaponDamageReadBool(bitReader, "override"),
                hitWeapon = KSWeaponDamageReadBool(bitReader, "hit_entity_weapon"),
                hitWeaponAmmoAttachment = KSWeaponDamageReadBool(bitReader, "hit_weapon_ammo_attachment"),
                silenced = KSWeaponDamageReadBool(bitReader, "silenced"),
                flags = KSWeaponDamageReadUns(bitReader, 25, "damage_flags"),
                meleeDamage = KSWeaponDamageReadBool(bitReader, "melee_damage"),
            }
            if damageEvent.meleeDamage == true then
                damageEvent.actionResultId = KSWeaponDamageReadUns(bitReader, 32, "action_result_id")
                damageEvent.meleeId = KSWeaponDamageReadUns(bitReader, 16, "melee_id")
                damageEvent.meleeResultId = KSWeaponDamageReadUns(bitReader, 32, "melee_result_id")
            end
            if damageEvent.override == true then
                damageEvent.weaponDamage = KSWeaponDamageReadUns(bitReader, 17, "weapon_damage")
                damageEvent.damage = damageEvent.weaponDamage
            end
            damageEvent.aggregated = KSWeaponDamageReadBool(bitReader, "aggregated")
            if damageEvent.aggregated == true then
                damageEvent.aggregationCount = KSWeaponDamageReadUns(bitReader, 5, "aggregation_count")
            end
            damageEvent.victim = KSWeaponDamageReadBool(bitReader, "victim_player")
            if damageEvent.victim == true then
                damageEvent.hitPosition = KSWeaponDamageReadVector(bitReader, 90.0, "victim_hit_position")
            end
            if damageEvent.damageType == 3 then
                damageEvent.damageTime = KSWeaponDamageReadUns(bitReader, 32, "damage_time")
                damageEvent.shouldKill = KSWeaponDamageReadBool(bitReader, "will_kill_player")
                if damageEvent.meleeDamage == true then
                    damageEvent.hitObjectID = KSWeaponDamageReadUns(bitReader, 13, "melee_hit_object_id")
                end
                damageEvent.useLargeDistance = KSWeaponDamageReadBool(bitReader, "use_large_distance")
                damageEvent.playerDistance = KSWeaponDamageReadUns(bitReader, damageEvent.useLargeDistance == true and 16 or 11, "player_distance")
            else
                damageEvent.parentID = KSWeaponDamageReadUns(bitReader, 13, "parent_id")
            end
            if damageEvent.damageType ~= nil then
                if damageEvent.damageType < 2 then
                    damageEvent.hitPosition = KSWeaponDamageReadVector(bitReader, 90.0, "entity_hit_position")
                    if damageEvent.damageType == 1 then
                        damageEvent.hasVehicleData = KSWeaponDamageReadBool(bitReader, "has_vehicle_data")
                        if damageEvent.hasVehicleData == true then
                            damageEvent.tyreIndex = KSWeaponDamageReadUns(bitReader, 4, "tyre_index")
                            damageEvent.suspensionIndex = KSWeaponDamageReadUns(bitReader, 4, "suspension_index")
                        end
                    end
                end
            else
                damageEvent.component = KSWeaponDamageReadUns(bitReader, 5, "component")
            end
            damageEvent.firstBullet = KSWeaponDamageReadBool(bitReader, "first_bullet")
            damageEvent.hasHitDirection = KSWeaponDamageReadBool(bitReader, "has_hit_direction")
            if damageEvent.hasHitDirection == true then
                damageEvent.hitDirection = KSWeaponDamageReadVector(bitReader, 6.2831855, "hit_direction")
            end
            damageEvent.bitsRead = bitReader.bits
            local parseError = bitReader.error
            if canSeekBuffer then
                eventBuffer:Seek(0)
            end
            if parseError ~= nil then
                return nil, parseError
            end
            return damageEvent
        end

        function KSIsBlameKillEvent(damageEvent, senderPlayer)
            if type(damageEvent) ~= "table" or not KSWeaponDamageIsBoundHostObject(senderPlayer) then
                return false
            end
            local senderPlayerId = tonumber(senderPlayer.PlayerId)
            local ownObjectId = tonumber(KSGetOwnObjectID())
            local claimedParentId = tonumber(damageEvent.parentID)
            if senderPlayerId == nil or senderPlayerId == GTA.GetLocalPlayerId() then
                return false
            end
            if damageEvent.damageType ~= 2 then
                return false
            end
            if ownObjectId == nil or ownObjectId == 0 or claimedParentId ~= ownObjectId then
                return false
            end
            return true, "remote sender claimed own ObjectID as DAMAGE_PED parent"
        end

        function KSRecordBlameKillDetection(senderPlayer)
            if not KSWeaponDamageIsBoundHostObject(senderPlayer) then
                return false
            end
            local senderPlayerId = tonumber(senderPlayer.PlayerId)
            if senderPlayerId == nil or senderPlayerId < 0 or senderPlayerId >= 32 then
                return false
            end
            local senderName = senderPlayer:GetName() or "Unknown"
            local gamerInfo = senderPlayer:GetGamerInfo()
            local rockstarId = KSWeaponDamageIsBoundHostObject(gamerInfo) and tonumber(gamerInfo.RockstarId) or nil
            local detectionKey = rockstarId and rockstarId > 0 and tostring(rockstarId) or tostring(senderPlayerId) .. ":" .. senderName
            local isFirstDetection = KSBlameKillDetections[detectionKey] ~= true
            KSBlameKillDetections[detectionKey] = true
            local detectedListIndex = senderPlayerId + 1
            if detectedPlayerReasons[detectedListIndex] == nil or detectedPlayerReasons[detectedListIndex] == "Blame Kill" then
                detectedPlayerNames[detectedListIndex] = senderName
                detectedPlayerReasons[detectedListIndex] = "Blame Kill"
            end
            if isFirstDetection then
                ModderDB.AddModderByPlayerId(senderPlayerId, "Blame Kill")
                KS_ReportDetectedModder(senderPlayerId, senderName, "Blame Kill", rockstarId)
            end
            return isFirstDetection
        end

        KS_WEAPON_DAMAGE_GUARD_MODES = { [0] = "Off", [2] = "Enforce" }

        function KSGetWeaponDamageGuardMode()
            if FeatureMgr.IsFeatureEnabled(H_MODDED_WEAPON_DAMAGE_PROTECTION) == true then
                return 2, KS_WEAPON_DAMAGE_GUARD_MODES[2]
            end
            return 0, KS_WEAPON_DAMAGE_GUARD_MODES[0]
        end

        function KSWeaponDamageRawVectorKey(decodedVector)
            local rawComponents = type(decodedVector) == "table" and decodedVector.raw or nil
            if type(rawComponents) ~= "table" then
                return "-"
            end
            return table.concat({ tostring(rawComponents.x), tostring(rawComponents.y), tostring(rawComponents.z) }, ",")
        end

        function KSWeaponDamageSenderState(senderId, nowMs)
            local normalizedSenderId = tonumber(senderId) or -1
            local existingState = KS_WEAPON_DAMAGE_GUARD.senders[normalizedSenderId]
            if existingState ~= nil then
                return existingState
            end
            local newSenderState = {
                senderId = normalizedSenderId,
                createdAtMs = nowMs,
                eventTimes = { values = {}, first = 1 },
                vehicleTimes = { values = {}, first = 1 },
                fingerprints = {},
                fingerprintCount = 0,
                ring = {},
                notificationTimes = {},
                counters = { allowed = 0, observed = 0, blocked = 0, parsed = 0 },
                summaryStartedMs = nowMs,
                detailWindowStartedMs = nowMs,
                detailCount = 0,
                lastBlockDetailMs = 0,
                lastIncidentDumpMs = 0,
                rateBlockUntilMs = 0,
            }
            KS_WEAPON_DAMAGE_GUARD.senders[normalizedSenderId] = newSenderState
            return newSenderState
        end

        function KSWeaponDamageQueueRate(timestampQueue, nowMs, windowMs)
            local queuedTimestamps = timestampQueue.values
            queuedTimestamps[#queuedTimestamps + 1] = nowMs
            local firstInWindowIndex = timestampQueue.first
            while firstInWindowIndex <= #queuedTimestamps and windowMs < nowMs - queuedTimestamps[firstInWindowIndex] do
                firstInWindowIndex = firstInWindowIndex + 1
            end
            timestampQueue.first = firstInWindowIndex
            local eventsInWindow = #queuedTimestamps - firstInWindowIndex + 1
            if firstInWindowIndex > 64 then
                local compactedTimestamps = {}
                for timestampIndex = firstInWindowIndex, #queuedTimestamps do
                    compactedTimestamps[#compactedTimestamps + 1] = queuedTimestamps[timestampIndex]
                end
                timestampQueue.values = compactedTimestamps
                timestampQueue.first = 1
            end
            return eventsInWindow
        end

        function KSWeaponDamageFingerprint(damageEvent)
            return table.concat({
                tostring(damageEvent.damageType),
                tostring(damageEvent.weaponHash),
                tostring(damageEvent.override),
                tostring(damageEvent.hitWeapon),
                tostring(damageEvent.hitWeaponAmmoAttachment),
                tostring(damageEvent.silenced),
                tostring(damageEvent.flags),
                tostring(damageEvent.meleeDamage),
                tostring(damageEvent.actionResultId),
                tostring(damageEvent.meleeId),
                tostring(damageEvent.meleeResultId),
                tostring(damageEvent.weaponDamage),
                tostring(damageEvent.aggregated),
                tostring(damageEvent.aggregationCount),
                tostring(damageEvent.victim),
                tostring(damageEvent.damageTime),
                tostring(damageEvent.shouldKill),
                tostring(damageEvent.parentID),
                tostring(damageEvent.hitObjectID),
                tostring(damageEvent.useLargeDistance),
                tostring(damageEvent.playerDistance),
                KSWeaponDamageRawVectorKey(damageEvent.hitPosition),
                tostring(damageEvent.hasVehicleData),
                tostring(damageEvent.tyreIndex),
                tostring(damageEvent.suspensionIndex),
                tostring(damageEvent.component),
                tostring(damageEvent.firstBullet),
                tostring(damageEvent.hasHitDirection),
                KSWeaponDamageRawVectorKey(damageEvent.hitDirection),
            }, ":")
        end

        function KSWeaponDamageAddSignal(verdict, signalName, signalWeight)
            verdict.signals[#verdict.signals + 1] = signalName
            verdict.score = verdict.score + (tonumber(signalWeight) or 0)
        end

        function KSWeaponDamageSetRule(verdict, ruleId, ruleDetail)
            if verdict.rule ~= nil then
                return
            end
            verdict.rule = ruleId
            verdict.detail = ruleDetail
            verdict.wouldBlock = true
        end

        function KSWeaponDamageEntityPosition(rawEntityHandle)
            local entityHandle = tonumber(rawEntityHandle) or 0
            if entityHandle == 0 or ENTITY.DOES_ENTITY_EXIST(entityHandle) ~= true then
                return nil
            end
            return ENTITY.GET_ENTITY_COORDS(entityHandle, true)
        end

        function KSWeaponDamageDistance(fromPosition, toPosition)
            if not KSWeaponDamageIsBoundHostObject(fromPosition) or not KSWeaponDamageIsBoundHostObject(toPosition) then
                return nil
            end
            return SYSTEM.VDIST(fromPosition.x, fromPosition.y, fromPosition.z, toPosition.x, toPosition.y, toPosition.z)
        end

        function KSResolveWeaponDamageContext(damageEvent, senderPlayer)
            local damageContext = {
                senderName = senderPlayer:GetName() or "Unknown",
                senderId = tonumber(damageEvent.senderId),
                parentResolved = false,
                parentOwnerMatches = nil,
                senderPedHandle = 0,
                senderVehicleHandle = 0,
                localVehicleHandle = 0,
            }
            local senderGamerInfo = senderPlayer:GetGamerInfo()
            damageContext.senderRid = KSWeaponDamageIsBoundHostObject(senderGamerInfo) and tonumber(senderGamerInfo.RockstarId) or nil
            local senderPedPointer = Players.GetCPed(damageContext.senderId)
            if KSWeaponDamageIsBoundHostObject(senderPedPointer) then
                damageContext.senderPedHandle = tonumber(GTA.PointerToHandle(senderPedPointer)) or 0
            end
            if damageContext.senderPedHandle ~= 0 and ENTITY.DOES_ENTITY_EXIST(damageContext.senderPedHandle) == true then
                damageContext.senderPosition = KSWeaponDamageEntityPosition(damageContext.senderPedHandle)
                damageContext.selectedWeapon = KSWeaponDamageNormalizeHash(WEAPON.GET_SELECTED_PED_WEAPON(damageContext.senderPedHandle))
                if PED.IS_PED_IN_ANY_VEHICLE(damageContext.senderPedHandle, false) == true then
                    damageContext.senderVehicleHandle = tonumber(PED.GET_VEHICLE_PED_IS_IN(damageContext.senderPedHandle, false)) or 0
                end
            end
            local localPedHandle = tonumber(PLAYER.PLAYER_PED_ID()) or 0
            damageContext.localPedHandle = localPedHandle
            damageContext.localPosition = KSWeaponDamageEntityPosition(localPedHandle)
            damageContext.distanceToSender = KSWeaponDamageDistance(damageContext.localPosition, damageContext.senderPosition)
            if localPedHandle ~= 0 and PED.IS_PED_IN_ANY_VEHICLE(localPedHandle, false) == true then
                damageContext.localVehicleHandle = tonumber(PED.GET_VEHICLE_PED_IS_IN(localPedHandle, false)) or 0
            end
            if damageContext.localVehicleHandle ~= 0 then
                damageContext.localVehicleModel = tonumber(ENTITY.GET_ENTITY_MODEL(damageContext.localVehicleHandle))
                local localVehiclePointer = GTA.HandleToPointer(damageContext.localVehicleHandle)
                local localVehicleNetObject = KSWeaponDamageIsBoundHostObject(localVehiclePointer) and localVehiclePointer.NetObject or nil
                damageContext.localVehicleObjectId = KSWeaponDamageIsBoundHostObject(localVehicleNetObject) and tonumber(localVehicleNetObject.ObjectID) or nil
            end
            if damageEvent.parentID ~= nil and tonumber(damageEvent.parentID) ~= 0 then
                local parentNetObject = NetworkObjectMgr.GetNetworkObject(damageEvent.parentID, true)
                local parentLookupType = type(parentNetObject)
                local isParentObjectValid = parentLookupType == "table" or parentLookupType == "userdata"
                damageContext.parentObject = isParentObjectValid and parentNetObject or nil
                damageContext.parentLookupType = parentLookupType
                if isParentObjectValid then
                    damageContext.parentResolved = true
                    damageContext.parentOwner = tonumber(parentNetObject.PlayerId)
                    damageContext.parentPendingOwner = tonumber(parentNetObject.PendingPlayerId)
                    local parentOwnerSlot = damageContext.parentOwner
                    if parentOwnerSlot ~= nil then
                        parentOwnerSlot = damageContext.parentOwner
                        if parentOwnerSlot >= 0 then
                            parentOwnerSlot = damageContext.parentOwner
                        end
                    end
                    damageContext.parentOwnershipKnown = parentOwnerSlot < 32
                    damageContext.parentObjectType = tonumber(parentNetObject.ObjectType)
                    damageContext.parentObjectTypeName = eNetObjectTypeNames and eNetObjectTypeNames[parentNetObject.ObjectType] or tostring(parentNetObject.ObjectType)
                    damageContext.parentOwnerMatches = damageContext.parentOwner == damageContext.senderId
                    if damageContext.parentObjectType ~= 3 then
                        local parentEntityPointer = parentNetObject:GetEntity()
                        damageContext.parentEntity = KSWeaponDamageIsBoundHostObject(parentEntityPointer) and parentEntityPointer or nil
                        if damageContext.parentEntity ~= nil then
                            damageContext.parentHandle = tonumber(GTA.PointerToHandle(parentEntityPointer)) or 0
                            if damageContext.parentHandle ~= 0 and ENTITY.DOES_ENTITY_EXIST(damageContext.parentHandle) == true then
                                damageContext.parentModel = tonumber(ENTITY.GET_ENTITY_MODEL(damageContext.parentHandle))
                                damageContext.parentPosition = KSWeaponDamageEntityPosition(damageContext.parentHandle)
                            end
                        end
                    end
                end
            end
            damageContext.weaponValid = damageEvent.weaponHash == KS_WEAPON_DAMAGE_HASH_EXPLOSION
            damageContext.expectedDamage = tonumber(WEAPON.GET_WEAPON_DAMAGE(damageEvent.weaponHash)) or 0
            local resolvedDamage = damageEvent.weaponDamage
            if not resolvedDamage then
                if damageContext.expectedDamage > 0 then
                    resolvedDamage = damageContext.expectedDamage
                    if resolvedDamage then
                        goto applyResolvedDamage
                    end
                end
                resolvedDamage = nil
            end
            ::applyResolvedDamage::
            damageEvent.damage = resolvedDamage
            return damageContext
        end

        function KSValidateWeaponDamageEvent(damageEvent, damageContext, modeIndex, modeName)
            local verdict = {
                modeIndex = modeIndex,
                modeName = modeName,
                score = 0,
                signals = {},
                rule = nil,
                detail = nil,
                wouldBlock = false,
                block = false,
                rate = 0,
                vehicleRate = 0,
                fingerprintRepeats = 0,
            }
            local damageFlags = tonumber(damageEvent.flags) or 0
            if damageEvent.meleeDamage ~= (damageFlags & KS_WEAPON_DAMAGE_FLAG_MELEE ~= 0) then
                KSWeaponDamageSetRule(verdict, "WDG-STRUCT-MELEE-FLAG", "melee boolean disagrees with MeleeDamage flag")
            end
            if damageEvent.override == true and (tonumber(damageEvent.weaponDamage) or 0) > 9999 and damageEvent.weaponHash ~= KS_WEAPON_DAMAGE_HASH_EXPLOSION then
                KSWeaponDamageSetRule(verdict, "WDG-STRUCT-EXCESSIVE-DAMAGE", "non-explosion override damage exceeds 9999")
            end
            if damageEvent.weaponHash == KS_WEAPON_DAMAGE_HASH_EXPLOSION and damageEvent.silenced == true then
                KSWeaponDamageSetRule(verdict, "WDG-STRUCT-SILENCED-EXPLOSION", "explosion damage cannot be silenced")
            end
            if KS_WEAPON_DAMAGE_STUN_HASHES[damageEvent.weaponHash] == true and damageFlags & KS_WEAPON_DAMAGE_FLAG_IGNORE_REMOTE_DISTANCE ~= 0 then
                KSWeaponDamageSetRule(verdict, "WDG-STRUCT-REMOTE-STUN", "stun damage bypassed the remote-distance check")
            end
            if damageEvent.damageType == 3 and damageEvent.meleeDamage == true and ((tonumber(damageEvent.hitObjectID) or 0) == 0 or damageEvent.useLargeDistance == true) then
                KSWeaponDamageSetRule(verdict, "WDG-STRUCT-REMOTE-MELEE", "player melee damage has no hit object or uses large distance")
            end
            if damageFlags & ~KS_WEAPON_DAMAGE_KNOWN_FLAG_MASK ~= 0 then
                KSWeaponDamageAddSignal(verdict, "unknown_damage_flag_bit24", 1)
            end
            if damageEvent.weaponHash == 0 then
                KSWeaponDamageAddSignal(verdict, "zero_weapon_hash", 1)
            elseif damageContext.weaponValid ~= true then
                KSWeaponDamageAddSignal(verdict, "invalid_weapon_hash", 10)
                KSWeaponDamageSetRule(verdict, "WDG-STRUCT-INVALID-WEAPON", "weapon hash is not recognized by the active game build")
            end
            if damageEvent.parentID ~= nil then
                if damageEvent.parentID ~= 0 and damageContext.parentResolved ~= true then
                    KSWeaponDamageAddSignal(verdict, "parent_object_unresolved", 1)
                end
            elseif damageContext.parentOwnershipKnown == true then
                if damageContext.parentOwnerMatches == false then
                    KSWeaponDamageAddSignal(verdict, "parent_owner_mismatch", 10)
                    KSWeaponDamageSetRule(verdict, "WDG-SOURCE-OWNER-MISMATCH", ("parent owner %s/%s does not match sender %s"):format(tostring(damageContext.parentOwner), tostring(damageContext.parentPendingOwner), tostring(damageContext.senderId)))
                end
            end
            if damageContext.selectedWeapon ~= nil and damageContext.selectedWeapon ~= 0 and damageContext.senderVehicleHandle == 0 and damageEvent.damageType >= 2 and damageEvent.weaponHash ~= 0 and damageEvent.weaponHash ~= KS_WEAPON_DAMAGE_HASH_EXPLOSION and damageContext.selectedWeapon ~= damageEvent.weaponHash then
                KSWeaponDamageAddSignal(verdict, "selected_weapon_mismatch", 1)
            end
            if damageEvent.override == true and damageContext.expectedDamage > 0 and (tonumber(damageEvent.weaponDamage) or 0) > math.max(1000, damageContext.expectedDamage * 20) then
                KSWeaponDamageAddSignal(verdict, "override_far_above_weapon_damage", 2)
            end
            if damageEvent.damageType == 1 and damageContext.localVehicleHandle == 0 then
                KSWeaponDamageAddSignal(verdict, "local_player_not_in_vehicle", 0)
            end
            return verdict
        end

        function KSWeaponDamagePruneFingerprints(senderState, nowMs)
            if senderState.fingerprintCount <= 128 then
                return
            end
            local keptFingerprintCount = 0
            for fingerprintKey, fingerprintEntry in pairs(senderState.fingerprints) do
                if nowMs - (tonumber(fingerprintEntry.lastMs) or 0) > 3000 then
                    senderState.fingerprints[fingerprintKey] = nil
                else
                    keptFingerprintCount = keptFingerprintCount + 1
                end
            end
            senderState.fingerprintCount = keptFingerprintCount
            if keptFingerprintCount <= 128 then
                return
            end
            senderState.fingerprints = {}
            senderState.fingerprintCount = 0
        end

        function KSWeaponDamageApplyRateChecks(damageEvent, senderState, verdict, nowMs)
            verdict.rate = KSWeaponDamageQueueRate(senderState.eventTimes, nowMs, 1000)
            if damageEvent.damageType == 1 then
                verdict.vehicleRate = KSWeaponDamageQueueRate(senderState.vehicleTimes, nowMs, 1000)
            else
                local vehicleTimestamps = senderState.vehicleTimes.values
                local firstVehicleInWindowIndex = senderState.vehicleTimes.first
                while firstVehicleInWindowIndex <= #vehicleTimestamps and nowMs - vehicleTimestamps[firstVehicleInWindowIndex] > 1000 do
                    firstVehicleInWindowIndex = firstVehicleInWindowIndex + 1
                end
                senderState.vehicleTimes.first = firstVehicleInWindowIndex
                verdict.vehicleRate = #vehicleTimestamps - firstVehicleInWindowIndex + 1
            end
            local fingerprintKey = KSWeaponDamageFingerprint(damageEvent)
            verdict.fingerprint = fingerprintKey
            local fingerprintEntry = senderState.fingerprints[fingerprintKey]
            if fingerprintEntry == nil then
                fingerprintEntry = { windowStartedMs = nowMs, lastMs = nowMs, count = 0, blockedUntilMs = 0, suppressed = 0 }
                senderState.fingerprints[fingerprintKey] = fingerprintEntry
                senderState.fingerprintCount = senderState.fingerprintCount + 1
                KSWeaponDamagePruneFingerprints(senderState, nowMs)
            end
            local repeatWindowMs = 500
            local maxRepeatsInWindow = 24
            if KS_WEAPON_DAMAGE_SLOW_HASHES[damageEvent.weaponHash] == true then
                maxRepeatsInWindow = 8
                repeatWindowMs = 750
            elseif damageEvent.damageType == 1 then
                maxRepeatsInWindow = 14
                repeatWindowMs = 500
            end
            if repeatWindowMs < nowMs - fingerprintEntry.windowStartedMs then
                fingerprintEntry.windowStartedMs = nowMs
                fingerprintEntry.count = 0
            end
            fingerprintEntry.count = fingerprintEntry.count + 1
            fingerprintEntry.lastMs = nowMs
            verdict.fingerprintRepeats = fingerprintEntry.count
            if nowMs < fingerprintEntry.blockedUntilMs then
                fingerprintEntry.suppressed = fingerprintEntry.suppressed + 1
                verdict.suppressed = fingerprintEntry.suppressed
                KSWeaponDamageSetRule(verdict, "WDG-REPLAY-HOLD", "matching event remains inside the replay suppression window")
            elseif nowMs < senderState.rateBlockUntilMs then
                KSWeaponDamageSetRule(verdict, "WDG-RATE-HOLD", "sender remains inside the impossible-rate suppression window")
            elseif maxRepeatsInWindow < fingerprintEntry.count then
                fingerprintEntry.blockedUntilMs = nowMs + 3000
                fingerprintEntry.suppressed = 1
                verdict.suppressed = 1
                KSWeaponDamageSetRule(verdict, "WDG-REPEATED-FINGERPRINT", ("same semantic packet repeated %d times in %dms"):format(fingerprintEntry.count, repeatWindowMs))
            elseif KS_WEAPON_DAMAGE_SLOW_HASHES[damageEvent.weaponHash] == true then
                if verdict.rate > 24 then
                    senderState.rateBlockUntilMs = nowMs + 2500
                    KSWeaponDamageSetRule(verdict, "WDG-SLOW-WEAPON-RATE", ("projectile/explosive weapon reached %d events/s"):format(verdict.rate))
                end
            elseif damageEvent.damageType == 1 then
                if verdict.vehicleRate > 64 then
                    senderState.rateBlockUntilMs = nowMs + 2500
                    KSWeaponDamageSetRule(verdict, "WDG-VEHICLE-DAMAGE-RATE", ("vehicle damage reached %d events/s"):format(verdict.vehicleRate))
                end
            elseif verdict.rate > 120 then
                senderState.rateBlockUntilMs = nowMs + 2500
                KSWeaponDamageSetRule(verdict, "WDG-GLOBAL-DAMAGE-RATE", ("weapon damage reached %d events/s"):format(verdict.rate))
            end
            verdict.block = verdict.wouldBlock == true
        end

        function KSWeaponDamageMaybeNotify(senderState, damageContext, verdict, nowMs)
            if verdict.block ~= true or FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) ~= true then
                return
            end
            local notifyRuleKey = tostring(verdict.rule or "weapon_damage")
            local lastNotifiedMs = tonumber(senderState.notificationTimes[notifyRuleKey])
            if lastNotifiedMs ~= nil and nowMs - lastNotifiedMs < 4000 then
                return
            end
            senderState.notificationTimes[notifyRuleKey] = nowMs
            local ruleLabel = tostring(verdict.rule or "weapon_damage")
            local blockKindLabel
            if ruleLabel:find("RATE", 1, true) == nil and ruleLabel:find("REPEATED", 1, true) == nil then
                blockKindLabel = ruleLabel:find("HOLD", 1, true)
                if blockKindLabel == nil then
                    goto applyForgedFallback
                end
            end
            blockKindLabel = "looped"
            ::applyForgedFallback::
            if not blockKindLabel then
                blockKindLabel = "forged"
            end
            notify(("Blocked %s Weapon Damage Event from %s (%s; %s suppressed)."):format(blockKindLabel, tostring(damageContext.senderName), ruleLabel, tostring(verdict.suppressed or 1)))
        end

        function KSProcessWeaponDamageEvent(eventBuffer, senderPlayer)
            local guardModeIndex, guardModeName = KSGetWeaponDamageGuardMode()
            local damageEvent, parseError = KSGetWeaponDamageEventData(eventBuffer, senderPlayer)
            local nowMs = getRuntimeNowMs()
            local isSenderBound = KSWeaponDamageIsBoundHostObject(senderPlayer)
            local senderPlayerId = isSenderBound and tonumber(senderPlayer.PlayerId) or -1
            local senderName = isSenderBound and senderPlayer:GetName() or "Unknown"
            local parseFailSenderState = KSWeaponDamageSenderState(senderPlayerId, nowMs)
            if type(damageEvent) ~= "table" then
                local parseFailVerdict = {
                    modeIndex = guardModeIndex,
                    modeName = guardModeName,
                    rule = "WDG-PARSE-FAILED",
                    detail = parseError,
                    signals = { "malformed_event" },
                    score = 10,
                    wouldBlock = true,
                    block = guardModeIndex == 2,
                    rate = 0,
                    vehicleRate = 0,
                    fingerprintRepeats = 0,
                }
                KSWeaponDamageMaybeNotify(parseFailSenderState, { senderName = senderName, senderId = senderPlayerId }, parseFailVerdict, nowMs)
                return false, nil, nil, parseFailVerdict
            end
            local damageContext = KSResolveWeaponDamageContext(damageEvent, senderPlayer)
            local validationVerdict = KSValidateWeaponDamageEvent(damageEvent, damageContext, guardModeIndex, guardModeName)
            local senderState = KSWeaponDamageSenderState(damageEvent.senderId, nowMs)
            KSWeaponDamageApplyRateChecks(damageEvent, senderState, validationVerdict, nowMs)
            local isBlameKill, blameKillReason = KSIsBlameKillEvent(damageEvent, senderPlayer)
            KSWeaponDamageMaybeNotify(senderState, damageContext, validationVerdict, nowMs)
            return isBlameKill, blameKillReason, damageEvent, validationVerdict
        end

        function KSReadWeaponDamageForBlameKill(eventBuffer, senderPlayer)
            return KSProcessWeaponDamageEvent(eventBuffer, senderPlayer)
        end

        function KSResetBlameKillPrearm()
            KS_BLAME_KILL_PREARM.wasEnabled = false
            KS_BLAME_KILL_PREARM.emissions = {}
            KS_BLAME_KILL_PREARM.restoreEmissions = {}
            KS_BLAME_KILL_PREARM.policyAllowed = false
            KS_BLAME_KILL_PREARM.policyReason = "reset"
            KS_BLAME_KILL_PREARM.pvpUntilMs = 0
            KS_BLAME_KILL_PREARM.featureSuspendUntilMs = 0
            KS_BLAME_KILL_PREARM.featureSuspendReason = nil
            KS_BLAME_KILL_PREARM.recipientPassthroughUntilMs = {}
            KS_BLAME_KILL_PREARM.recipientPassthroughEmissions = {}
            KS_BLAME_KILL_PREARM.recipientPassthroughReasons = {}
            KS_BLAME_KILL_PREARM.recipientPassthroughIdentities = {}
            KS_BLAME_KILL_PREARM.lastPvpSampleMs = 0
            KS_BLAME_KILL_PREARM.lastIncomingCombatSampleMs = 0
            KS_BLAME_KILL_PREARM.incomingCombatCursor = 1
            KS_BLAME_KILL_PREARM.remotePlayerSnapshotMs = -1
            KS_BLAME_KILL_PREARM.remotePlayerSnapshot = {}
            KS_BLAME_KILL_PREARM.trackedProjectiles = {}
            KS_BLAME_KILL_PREARM.projectileDiscovery = {}
            KS_BLAME_KILL_PREARM.fireHazards = {}
            KS_BLAME_KILL_PREARM.lastExplosiveSampleMs = 0
            KS_BLAME_KILL_PREARM.lastVehicleCombatSampleMs = 0
            KS_BLAME_KILL_PREARM.lastOrbitalCombatSampleMs = 0
            KS_BLAME_KILL_PREARM.localOrbitalSampleMs = 0
            KS_BLAME_KILL_PREARM.localOrbitalReleaseActive = false
            KS_BLAME_KILL_PREARM.lastRemoteOrbitalCombatSampleMs = 0
            KS_BLAME_KILL_PREARM.remoteOrbitalCursor = 1
            KS_BLAME_KILL_PREARM.remoteOrbitalFreeCameraUntilMs = {}
            KS_BLAME_KILL_PREARM.lastVehicleWeaponHash = 0
            KS_BLAME_KILL_PREARM.lastVehicleWeaponEntity = 0
            KS_BLAME_KILL_PREARM.lastVehicleWeaponMs = 0
            KS_BLAME_KILL_PREARM.genuineNodeValues = {}
            KSResetBlameKillSessionReadiness()
            KS_BLAME_KILL_PREARM.restorePending = false
        end

        function KSBlameKillPrearmEmissionKey(recipientPlayerId, isExclusive)
            return (isExclusive and "exclusive:" or "broadcast:") .. tostring(recipientPlayerId == nil and "all" or recipientPlayerId)
        end

        function KSBlameKillPrearmEmissionCount(emissionCounters, emissionKey)
            local emissionEntry = emissionCounters[emissionKey]
            if type(emissionEntry) ~= "table" then
                emissionEntry = { count = 0 }
                emissionCounters[emissionKey] = emissionEntry
            end
            emissionEntry.count = emissionEntry.count + 1
            return emissionEntry.count
        end

        function KSGetLocalPlayerAimedRemotePlayerId(localPlayerId)
            local aimEntityPtr = KS_BLAME_KILL_PREARM.aimEntityPtr
            if aimEntityPtr == nil or aimEntityPtr == 0 then
                return
            end
            Memory.WriteInt(aimEntityPtr, 0)
            local hasAimTarget = PLAYER.GET_ENTITY_PLAYER_IS_FREE_AIMING_AT(localPlayerId, aimEntityPtr) == true
            if not hasAimTarget then
                Memory.WriteInt(aimEntityPtr, 0)
                hasAimTarget = PLAYER.GET_PLAYER_TARGET_ENTITY(localPlayerId, aimEntityPtr) == true
            end
            if not hasAimTarget then
                return
            end
            local aimedEntity = Memory.ReadInt(aimEntityPtr)
            if aimedEntity == 0 or ENTITY.DOES_ENTITY_EXIST(aimedEntity) ~= true then
                return
            end

            local function resolveRemotePlayerFromPed(candidatePed)
                local pedHandle = tonumber(candidatePed) or 0
                if pedHandle == 0 or ENTITY.DOES_ENTITY_EXIST(pedHandle) ~= true or PED.IS_PED_A_PLAYER(pedHandle) ~= true then
                    return
                end
                local remotePlayerId = tonumber(NETWORK.NETWORK_GET_PLAYER_INDEX_FROM_PED(pedHandle))
                if remotePlayerId == nil or remotePlayerId < 0 or remotePlayerId >= 32 or remotePlayerId == localPlayerId or NETWORK.NETWORK_IS_PLAYER_ACTIVE(remotePlayerId) ~= true or PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(remotePlayerId) ~= pedHandle then
                    return
                end
                return remotePlayerId
            end

            if ENTITY.IS_ENTITY_A_PED(aimedEntity) == true then
                local aimedPlayerId = resolveRemotePlayerFromPed(aimedEntity)
                if aimedPlayerId ~= nil then
                    return aimedPlayerId, aimedEntity
                end
                return
            end
            if ENTITY.IS_ENTITY_A_VEHICLE(aimedEntity) ~= true then
                return
            end
            for seatIndex = -1, math.max(0, tonumber(VEHICLE.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS(aimedEntity)) or 0) - 1 do
                local seatPed = VEHICLE.GET_PED_IN_VEHICLE_SEAT(aimedEntity, seatIndex, false)
                local seatPlayerId = resolveRemotePlayerFromPed(seatPed)
                if seatPlayerId ~= nil then
                    return seatPlayerId, aimedEntity
                end
            end
        end

        function KSIsBlameKillFriendlyFireMethod()
            if type(KSGetBlameKillPrearmMethod) ~= "function" then
                return true
            end
            return KSGetBlameKillPrearmMethod() == 0
        end

        function KSResolveBlameKillRemotePlayerFromPed(candidatePed, localPlayerId)
            local pedHandle = tonumber(candidatePed)
            if pedHandle == nil or pedHandle == 0 or ENTITY.DOES_ENTITY_EXIST(pedHandle) ~= true or PED.IS_PED_A_PLAYER(pedHandle) ~= true then
                return
            end
            local remotePlayerId = tonumber(NETWORK.NETWORK_GET_PLAYER_INDEX_FROM_PED(pedHandle))
            if remotePlayerId == nil or remotePlayerId < 0 or remotePlayerId >= 32 or remotePlayerId == localPlayerId or NETWORK.NETWORK_IS_PLAYER_ACTIVE(remotePlayerId) ~= true or PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(remotePlayerId) ~= pedHandle then
                return
            end
            return remotePlayerId
        end

        function KSGetBlameKillRemotePlayerSnapshot(callerNowMs)
            local nowMs = tonumber(callerNowMs) or getRuntimeNowMs()
            local lastSnapshotMs = tonumber(KS_BLAME_KILL_PREARM.remotePlayerSnapshotMs) or -1
            if lastSnapshotMs >= 0 and nowMs >= lastSnapshotMs and nowMs - lastSnapshotMs < KS_BLAME_KILL_REMOTE_PLAYER_SNAPSHOT_MS then
                return KS_BLAME_KILL_PREARM.remotePlayerSnapshot
            end
            local localPlayerId = GTA.GetLocalPlayerId()
            local remotePlayers = {}
            for slotPlayerId = 0, 31 do
                if slotPlayerId ~= localPlayerId and NETWORK.NETWORK_IS_PLAYER_ACTIVE(slotPlayerId) == true then
                    local playerPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(slotPlayerId)
                    if playerPed ~= 0 and ENTITY.DOES_ENTITY_EXIST(playerPed) == true then
                        remotePlayers[#remotePlayers + 1] = { playerId = slotPlayerId, playerPed = playerPed, positionKnown = false }
                    end
                end
            end
            KS_BLAME_KILL_PREARM.remotePlayerSnapshotMs = nowMs
            KS_BLAME_KILL_PREARM.remotePlayerSnapshot = remotePlayers
            return remotePlayers
        end

        function KSGetBlameKillRemotePlayerPosition(remotePlayerEntry)
            if type(remotePlayerEntry) ~= "table" then
                return 0.0, 0.0, 0.0
            end
            if remotePlayerEntry.positionKnown ~= true then
                local posX, posY, posZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_COORDS(remotePlayerEntry.playerPed, true))
                remotePlayerEntry.z = posZ
                remotePlayerEntry.y = posY
                remotePlayerEntry.x = posX
                remotePlayerEntry.positionKnown = true
            end
            return remotePlayerEntry.x, remotePlayerEntry.y, remotePlayerEntry.z
        end

        function KSIsBlameKillLocalMeleeScanActive(localPed, meleeTargetEntity)
            if tonumber(meleeTargetEntity) ~= nil and tonumber(meleeTargetEntity) ~= 0 then
                return true
            end
            if PED.IS_PED_IN_MELEE_COMBAT(localPed) == true or PED.IS_PED_PERFORMING_MELEE_ACTION(localPed) == true or PED.IS_PED_RUNNING_MELEE_TASK(localPed) == true then
                return true
            end
            for _, meleeControlId in ipairs({ 24, 140, 141, 142, 257, 263, 264 }) do
                if KSIsBlameKillControlPressed(meleeControlId) then
                    return true
                end
            end
            return false
        end

        function KSBlameKillMeleeThreatensTarget(attackerEntity, targetEntity, assumeMeleeActive)
            local attackerPed = tonumber(attackerEntity) or 0
            local targetPed = tonumber(targetEntity) or 0
            if attackerPed == 0 or targetPed == 0 or attackerPed == targetPed or ENTITY.DOES_ENTITY_EXIST(attackerPed) ~= true or ENTITY.DOES_ENTITY_EXIST(targetPed) ~= true or PED.IS_PED_IN_ANY_VEHICLE(attackerPed, false) == true then
                return false
            end
            if PED.GET_MELEE_TARGET_FOR_PED(attackerPed) == targetPed then
                return true, "melee_exact_target"
            end
            local isPerformingMeleeAction = PED.IS_PED_PERFORMING_MELEE_ACTION(attackerPed) == true
            local isRunningMeleeTask = PED.IS_PED_RUNNING_MELEE_TASK(attackerPed) == true
            local isInMeleeCombat = PED.IS_PED_IN_MELEE_COMBAT(attackerPed)
            if assumeMeleeActive ~= true and not isPerformingMeleeAction and not isRunningMeleeTask and isInMeleeCombat ~= true then
                return false
            end
            local selectedWeaponHash = tonumber(WEAPON.GET_SELECTED_PED_WEAPON(attackerPed)) or 0
            local unarmedWeaponHash = tonumber(Utils.Joaat("WEAPON_UNARMED")) or 0
            if selectedWeaponHash < 0 then
                selectedWeaponHash = selectedWeaponHash + 4294967296
            end
            if unarmedWeaponHash < 0 then
                unarmedWeaponHash = unarmedWeaponHash + 4294967296
            end
            local isUnarmed = selectedWeaponHash == unarmedWeaponHash
            if not isUnarmed and not isPerformingMeleeAction and not isRunningMeleeTask then
                return false
            end
            local attackerX, attackerY, attackerZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_COORDS(attackerPed, true))
            local targetX, targetY, targetZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_COORDS(targetPed, true))
            local deltaX = targetX - attackerX
            local deltaY = targetY - attackerY
            local deltaZ = targetZ - attackerZ
            local distanceSquared = deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ
            if distanceSquared > KS_BLAME_KILL_MELEE_NEAR_RADIUS * KS_BLAME_KILL_MELEE_NEAR_RADIUS then
                return false
            end
            if PED.IS_PED_IN_COMBAT(attackerPed, targetPed) == true then
                return true, "melee_combat_target"
            end
            if isUnarmed and PED.IS_PED_FACING_PED(attackerPed, targetPed, KS_BLAME_KILL_MELEE_FACING_ANGLE) == true then
                return true, "melee_facing_target"
            end
            if (isPerformingMeleeAction or isRunningMeleeTask) and distanceSquared <= KS_BLAME_KILL_MELEE_STRIKE_RADIUS * KS_BLAME_KILL_MELEE_STRIKE_RADIUS then
                return true, "melee_close_strike"
            end
            return false
        end

        function KSGetBlameKillRecipientIdentity(requestedPlayerId)
            local recipientPlayerId = tonumber(requestedPlayerId)
            if recipientPlayerId == nil or recipientPlayerId < 0 or recipientPlayerId >= 32 or recipientPlayerId == GTA.GetLocalPlayerId() or NETWORK.NETWORK_IS_PLAYER_ACTIVE(recipientPlayerId) ~= true then
                return
            end
            local recipientPlayer = Players.GetById(recipientPlayerId)
            local gamerInfo = recipientPlayer and recipientPlayer:GetGamerInfo() or nil
            local recipientRockstarId = gamerInfo and tostring(gamerInfo.RockstarId or "") or ""
            local recipientPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(recipientPlayerId)
            local recipientCPed = Players.GetCPed(recipientPlayerId)
            local netObjectId = recipientCPed and recipientCPed.NetObject and tonumber(recipientCPed.NetObject.ObjectID) or 0
            if not recipientRockstarId:match("^%d+$") or recipientRockstarId == "0" then
                recipientRockstarId = ""
            end
            if recipientPed == 0 or ENTITY.DOES_ENTITY_EXIST(recipientPed) ~= true then
                return
            end
            return {
                playerId = recipientPlayerId,
                rockstarId = recipientRockstarId,
                objectId = math.max(0, netObjectId),
                playerPed = recipientPed,
            }
        end

        function KSBlameKillRecipientIdentityMatches(expectedIdentity, currentIdentity)
            if type(expectedIdentity) ~= "table" or type(currentIdentity) ~= "table" or tonumber(expectedIdentity.playerId) ~= tonumber(currentIdentity.playerId) or expectedIdentity.playerPed ~= currentIdentity.playerPed then
                return false
            end
            local expectedRockstarId = tostring(expectedIdentity.rockstarId or "")
            local currentRockstarId = tostring(currentIdentity.rockstarId or "")
            local expectedObjectId = tonumber(expectedIdentity.objectId) or 0
            local currentObjectId = tonumber(currentIdentity.objectId) or 0
            if expectedRockstarId ~= "" and currentRockstarId ~= "" and expectedRockstarId ~= currentRockstarId then
                return false
            end
            if expectedObjectId > 0 and currentObjectId > 0 and expectedObjectId ~= currentObjectId then
                return false
            end
            return true
        end

        function KSMarkBlameKillEntityRecipients(entityHandle, nowMs, passthroughDurationMs, passthroughReason)
            local targetEntity = tonumber(entityHandle) or 0
            if targetEntity == 0 or ENTITY.DOES_ENTITY_EXIST(targetEntity) ~= true then
                return false
            end
            local localPlayerId = GTA.GetLocalPlayerId()
            local hasMarkedRecipient = false

            local function markPedRecipient(candidatePed)
                local remotePlayerId = KSResolveBlameKillRemotePlayerFromPed(candidatePed, localPlayerId)
                if remotePlayerId ~= nil and KSMarkBlameKillRecipientPassthrough(remotePlayerId, nowMs + passthroughDurationMs, nowMs, passthroughReason) then
                    hasMarkedRecipient = true
                end
            end

            if ENTITY.IS_ENTITY_A_PED(targetEntity) == true then
                markPedRecipient(targetEntity)
                return hasMarkedRecipient
            end
            if ENTITY.IS_ENTITY_A_VEHICLE(targetEntity) ~= true then
                return false
            end
            for seatIndex = -1, math.max(0, tonumber(VEHICLE.GET_VEHICLE_MAX_NUMBER_OF_PASSENGERS(targetEntity)) or 0) - 1 do
                local occupantPed = VEHICLE.GET_PED_IN_VEHICLE_SEAT(targetEntity, seatIndex, false)
                if occupantPed ~= 0 then
                    markPedRecipient(occupantPed)
                end
            end
            return hasMarkedRecipient
        end

        function KSBlameKillRemotePlayerTargetsLocal(remotePlayerId, localPed, localVehicle, remotePlayerPed, isFreeAimingOverride)
            if PLAYER.IS_PLAYER_TARGETTING_ENTITY(remotePlayerId, localPed) == true then
                return true, "incoming_exact_ped_aim_passthrough"
            end
            if localVehicle ~= 0 and PLAYER.IS_PLAYER_TARGETTING_ENTITY(remotePlayerId, localVehicle) == true then
                return true, "incoming_exact_vehicle_aim_passthrough"
            end
            local isRemoteFreeAiming = isFreeAimingOverride
            if isRemoteFreeAiming == nil then
                isRemoteFreeAiming = PLAYER.IS_PLAYER_FREE_AIMING(remotePlayerId) == true
            end
            if isRemoteFreeAiming ~= true then
                return false
            end
            return false
        end

        function KSBlameKillRemoteAimCorridorThreatensLocal(remotePlayerId, remotePed, localPed, localVehicle, isFreeAimingOverride)
            local isRemoteFreeAiming = isFreeAimingOverride
            if isRemoteFreeAiming == nil then
                isRemoteFreeAiming = PLAYER.IS_PLAYER_FREE_AIMING(remotePlayerId) == true
            end
            if not isRemoteFreeAiming then
                return false, false
            end
            local aimOriginEntity = remotePed
            local aimOriginKind = "ped"
            local weaponEntity = WEAPON.GET_CURRENT_PED_WEAPON_ENTITY_INDEX(remotePed, 0)
            if weaponEntity ~= 0 then
                if ENTITY.DOES_ENTITY_EXIST(weaponEntity) == true then
                    aimOriginEntity = weaponEntity
                    aimOriginKind = "weapon"
                end
            elseif PED.IS_PED_IN_ANY_VEHICLE(remotePed, false) == true then
                local remoteVehicle = PED.GET_VEHICLE_PED_IS_IN(remotePed, false)
                if remoteVehicle ~= 0 and ENTITY.DOES_ENTITY_EXIST(remoteVehicle) == true then
                    aimOriginEntity = remoteVehicle
                    aimOriginKind = "vehicle"
                end
            end
            local originX, originY, originZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_COORDS(aimOriginEntity, true))
            if aimOriginKind == "ped" then
                originZ = originZ + 0.7
            end
            local localPedX, localPedY, localPedZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_COORDS(localPed, true))
            local deltaX = localPedX - originX
            local deltaY = localPedY - originY
            local deltaZ = localPedZ - originZ
            local distanceToLocal = math.sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ)
            local forwardX, forwardY, forwardZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_FORWARD_VECTOR(aimOriginEntity))
            local corridorLength = math.max(40.0, distanceToLocal + 20.0)
            local corridorEndX = originX + forwardX * corridorLength
            local corridorEndY = originY + forwardY * corridorLength
            local corridorEndZ = originZ + forwardZ * corridorLength
            local pathRadius, nearRadius = KSGetBlameKillRemoteAimRadii(remotePed)
            local isCorridorThreat = KSBlameKillRemoteAimThreatensEntity(localPed, originX, originY, originZ, corridorEndX, corridorEndY, corridorEndZ, pathRadius, nearRadius)
            if not isCorridorThreat and localVehicle ~= 0 then
                isCorridorThreat = KSBlameKillRemoteAimThreatensEntity(localVehicle, originX, originY, originZ, corridorEndX, corridorEndY, corridorEndZ, pathRadius, nearRadius)
            end
            return true, isCorridorThreat, aimOriginKind
        end

        function KSRefreshBlameKillIncomingCombatPassthrough(nowMs, localPed)
            if nowMs - (tonumber(KS_BLAME_KILL_PREARM.lastIncomingCombatSampleMs) or 0) < KS_BLAME_KILL_INCOMING_COMBAT_SAMPLE_MS then
                return
            end
            KS_BLAME_KILL_PREARM.lastIncomingCombatSampleMs = nowMs
            local localVehicle = 0
            if PED.IS_PED_IN_ANY_VEHICLE(localPed, false) == true then
                localVehicle = PED.GET_VEHICLE_PED_IS_IN(localPed, false)
            end
            local remotePlayers = KSGetBlameKillRemotePlayerSnapshot(nowMs)
            local remotePlayerCount = #remotePlayers
            if remotePlayerCount == 0 then
                KS_BLAME_KILL_PREARM.incomingCombatCursor = 1
                return
            end
            local startCursor = math.max(1, math.min(remotePlayerCount, tonumber(KS_BLAME_KILL_PREARM.incomingCombatCursor) or 1))
            local sampleBudget = math.min(remotePlayerCount, KS_BLAME_KILL_INCOMING_PLAYER_BUDGET)
            for sampleOffset = 0, sampleBudget - 1 do
                local playerEntry = remotePlayers[(startCursor + sampleOffset - 1) % remotePlayerCount + 1]
                local remotePlayerId = playerEntry.playerId
                local remotePed = playerEntry.playerPed
                local isIncomingThreat, threatReason = KSBlameKillRemotePlayerTargetsLocal(remotePlayerId, localPed, localVehicle, remotePed, false)
                local wasTargetingLocal = isIncomingThreat == true
                if not isIncomingThreat then
                    local isMeleeThreat, meleeThreatKind = KSBlameKillMeleeThreatensTarget(remotePed, localPed)
                    isIncomingThreat = isMeleeThreat == true
                    if isIncomingThreat then
                        threatReason = "incoming_" .. tostring(meleeThreatKind) .. "_passthrough"
                    end
                end
                if not isIncomingThreat and wasTargetingLocal then
                    local wasCorridorEvaluated, isCorridorThreat = KSBlameKillRemoteAimCorridorThreatensLocal(remotePlayerId, remotePed, localPed, localVehicle, true)
                    if isCorridorThreat then
                        isIncomingThreat = true
                        threatReason = "incoming_remote_aim_corridor_passthrough"
                    end
                end
                if isIncomingThreat then
                    KSMarkBlameKillRecipientPassthrough(remotePlayerId, nowMs + KS_BLAME_KILL_PVP_COOLDOWN_MS, nowMs, threatReason or "incoming_player_combat_passthrough")
                end
            end
            KS_BLAME_KILL_PREARM.incomingCombatCursor = (startCursor + sampleBudget - 1) % remotePlayerCount + 1
        end

        function KSClearBlameKillRecipientPassthrough(rawPlayerId)
            local recipientPlayerId = tonumber(rawPlayerId)
            if recipientPlayerId == nil then
                return
            end
            KS_BLAME_KILL_PREARM.recipientPassthroughUntilMs[recipientPlayerId] = nil
            KS_BLAME_KILL_PREARM.recipientPassthroughReasons[recipientPlayerId] = nil
            KS_BLAME_KILL_PREARM.recipientPassthroughIdentities[recipientPlayerId] = nil
            local emissionKey = KSBlameKillPrearmEmissionKey(recipientPlayerId, true)
            KS_BLAME_KILL_PREARM.recipientPassthroughEmissions[emissionKey] = nil
            KS_BLAME_KILL_PREARM.emissions[emissionKey] = nil
            KS_BLAME_KILL_PREARM.restoreEmissions[emissionKey] = nil
        end

        function KSMarkBlameKillRecipientPassthrough(rawPlayerId, passthroughUntilMs, nowMs, passthroughReason)
            local recipientPlayerId = tonumber(rawPlayerId)
            if recipientPlayerId == nil or recipientPlayerId == GTA.GetLocalPlayerId() then
                return false
            end
            nowMs = tonumber(nowMs) or getRuntimeNowMs()
            passthroughUntilMs = tonumber(passthroughUntilMs) or nowMs
            if nowMs >= passthroughUntilMs then
                return false
            end
            local currentIdentity = KSGetBlameKillRecipientIdentity(recipientPlayerId)
            if currentIdentity == nil then
                KSClearBlameKillRecipientPassthrough(recipientPlayerId)
                return false
            end
            local untilMsByPlayer = KS_BLAME_KILL_PREARM.recipientPassthroughUntilMs
            local existingUntilMs = tonumber(untilMsByPlayer[recipientPlayerId]) or 0
            local storedIdentity = KS_BLAME_KILL_PREARM.recipientPassthroughIdentities[recipientPlayerId]
            if nowMs >= existingUntilMs or not KSBlameKillRecipientIdentityMatches(storedIdentity, currentIdentity) then
                KSClearBlameKillRecipientPassthrough(recipientPlayerId)
                local emissionKey = KSBlameKillPrearmEmissionKey(recipientPlayerId, true)
                KS_BLAME_KILL_PREARM.recipientPassthroughEmissions[emissionKey] = nil
                KS_BLAME_KILL_PREARM.emissions[emissionKey] = nil
                existingUntilMs = 0
            end
            if passthroughUntilMs > existingUntilMs then
                untilMsByPlayer[recipientPlayerId] = passthroughUntilMs
            end
            if type(storedIdentity) ~= "table" or (tonumber(storedIdentity.objectId) or 0) <= 0 then
                KS_BLAME_KILL_PREARM.recipientPassthroughIdentities[recipientPlayerId] = currentIdentity
            end
            KS_BLAME_KILL_PREARM.recipientPassthroughReasons[recipientPlayerId] = tostring(passthroughReason or "recipient_passthrough")
            return true
        end

        function KSRefreshBlameKillRecipientPassthrough(nowMs)
            nowMs = tonumber(nowMs) or getRuntimeNowMs()
            local untilMsByPlayer = KS_BLAME_KILL_PREARM.recipientPassthroughUntilMs
            local localPlayerId = GTA.GetLocalPlayerId()
            local localPed = PLAYER.PLAYER_PED_ID()
            KSRefreshBlameKillIncomingCombatPassthrough(nowMs, localPed)
            local aimedPlayerId, aimedEntity = KSGetLocalPlayerAimedRemotePlayerId(localPlayerId)
            if aimedPlayerId ~= nil and aimedEntity ~= nil then
                local isAimedEntityVehicle = ENTITY.IS_ENTITY_A_VEHICLE(aimedEntity)
                KSMarkBlameKillEntityRecipients(aimedEntity, nowMs, KS_BLAME_KILL_PVP_COOLDOWN_MS, isAimedEntityVehicle == true and "aimed_player_vehicle_passthrough" or "aimed_player_passthrough")
            end
            local meleeTargetPed = PED.GET_MELEE_TARGET_FOR_PED(localPed)
            local meleeTargetPlayerId = KSResolveBlameKillRemotePlayerFromPed(meleeTargetPed, localPlayerId)
            if meleeTargetPlayerId ~= nil then
                KSMarkBlameKillRecipientPassthrough(meleeTargetPlayerId, nowMs + KS_BLAME_KILL_PVP_COOLDOWN_MS, nowMs, "melee_target_passthrough")
            end
            if KSIsBlameKillLocalMeleeScanActive(localPed, meleeTargetPed) then
                for _, remotePlayerInfo in ipairs(KSGetBlameKillRemotePlayerSnapshot(nowMs)) do
                    local threatenedPlayerId = remotePlayerInfo.playerId
                    local isMeleeThreat, meleeThreatReason = KSBlameKillMeleeThreatensTarget(localPed, remotePlayerInfo.playerPed, true)
                    if isMeleeThreat == true then
                        KSMarkBlameKillRecipientPassthrough(threatenedPlayerId, nowMs + KS_BLAME_KILL_PVP_COOLDOWN_MS, nowMs, tostring(meleeThreatReason) .. "_passthrough")
                    end
                end
            end
            if not KSIsBlameKillFriendlyFireMethod() and (aimedPlayerId ~= nil or PED.IS_PED_IN_MELEE_COMBAT(localPed) == true) then
                KS_BLAME_KILL_PREARM.pvpUntilMs = nowMs + KS_BLAME_KILL_PVP_COOLDOWN_MS
            end
            KSRefreshBlameKillDirectFirePassthrough(nowMs)
            KSRefreshBlameKillExplosivePassthrough(nowMs)
            KSRefreshBlameKillVehicleInteractionPassthrough(nowMs)
            KSRefreshBlameKillOrbitalPassthrough(nowMs)
            KSRefreshBlameKillRemoteOrbitalPassthrough(nowMs)
            for recipientPlayerId, passthroughUntilMs in pairs(untilMsByPlayer) do
                local currentIdentity = KSGetBlameKillRecipientIdentity(recipientPlayerId)
                local storedIdentity = KS_BLAME_KILL_PREARM.recipientPassthroughIdentities[recipientPlayerId]
                if not (nowMs >= (tonumber(passthroughUntilMs) or 0)) and currentIdentity ~= nil and KSBlameKillRecipientIdentityMatches(storedIdentity, currentIdentity) then
                    if (tonumber(storedIdentity.objectId) or 0) <= 0 and (tonumber(currentIdentity.objectId) or 0) > 0 then
                        KS_BLAME_KILL_PREARM.recipientPassthroughIdentities[recipientPlayerId] = currentIdentity
                    end
                else
                    KSClearBlameKillRecipientPassthrough(recipientPlayerId)
                end
            end
        end

        function KSIsBlameKillRecipientPassthrough(rawPlayerId, nowMs)
            local recipientPlayerId = tonumber(rawPlayerId)
            if recipientPlayerId == nil or not KSIsBlameKillFriendlyFireMethod() then
                return false
            end
            nowMs = tonumber(nowMs) or getRuntimeNowMs()
            return KS_BLAME_KILL_PREARM.recipientPassthroughIdentities[recipientPlayerId] ~= nil
        end

        function KSIsBlameKillPvpInputActive(nowMs)
            if KSIsBlameKillFriendlyFireMethod() then
                return false
            end
            return nowMs < (tonumber(KS_BLAME_KILL_PREARM.pvpUntilMs) or 0)
        end

        function KSBlameKillDistanceSqToSegment(pointX, pointY, pointZ, segmentStartX, segmentStartY, segmentStartZ, segmentEndX, segmentEndY, segmentEndZ)
            local segmentDeltaX = segmentEndX - segmentStartX
            local segmentDeltaY = segmentEndY - segmentStartY
            local segmentDeltaZ = segmentEndZ - segmentStartZ
            local startToPointX = pointX - segmentStartX
            local startToPointY = pointY - segmentStartY
            local startToPointZ = pointZ - segmentStartZ
            local segmentLengthSq = segmentDeltaX * segmentDeltaX + segmentDeltaY * segmentDeltaY + segmentDeltaZ * segmentDeltaZ
            local projectionFraction = 0.0
            if segmentLengthSq > 1.0E-4 then
                projectionFraction = math.max(0.0, math.min((startToPointX * segmentDeltaX + startToPointY * segmentDeltaY + startToPointZ * segmentDeltaZ) / segmentLengthSq, 1.0))
            end
            local offsetFromClosestX = pointX - (segmentStartX + segmentDeltaX * projectionFraction)
            local offsetFromClosestY = pointY - (segmentStartY + segmentDeltaY * projectionFraction)
            local offsetFromClosestZ = pointZ - (segmentStartZ + segmentDeltaZ * projectionFraction)
            return offsetFromClosestX * offsetFromClosestX + offsetFromClosestY * offsetFromClosestY + offsetFromClosestZ * offsetFromClosestZ, projectionFraction, math.sqrt(segmentLengthSq)
        end

        function KSBlameKillVectorComponents(vectorOrX, componentY, componentZ)
            if type(vectorOrX) == "table" or type(vectorOrX) == "userdata" then
                return tonumber(vectorOrX.x) or 0.0, tonumber(vectorOrX.y) or 0.0, tonumber(vectorOrX.z) or 0.0
            end
            return tonumber(vectorOrX) or 0.0, tonumber(componentY) or 0.0, tonumber(componentZ) or 0.0
        end

        function KSBlameKillNormalizedWeaponHash(weaponHash)
            local unsignedHash = tonumber(weaponHash) or 0
            if unsignedHash < 0 then
                unsignedHash = unsignedHash + 4294967296
            end
            return unsignedHash
        end

        function KSGetBlameKillProjectileProfile(weaponHash, weaponDamageType)
            local projectileProfile = KS_BLAME_KILL_DELAYED_PROJECTILES[KSBlameKillNormalizedWeaponHash(weaponHash)]
            if type(projectileProfile) == "table" then
                return tonumber(projectileProfile.damageType) or weaponDamageType, tonumber(projectileProfile.discoveryMs) or KS_BLAME_KILL_PROJECTILE_DISCOVERY_MS
            end
            if weaponDamageType == 5 or weaponDamageType == 6 then
                return weaponDamageType, KS_BLAME_KILL_PROJECTILE_DISCOVERY_MS
            end
        end

        function KSIsBlameKillControlPressed(controlId)
            return PAD.IS_CONTROL_PRESSED(0, controlId) == true
        end

        function KSIsBlameKillAttackActive(attackerPed, shouldCheckVehicleAttackControls)
            if KSIsBlameKillControlPressed(24) or PED.IS_PED_SHOOTING(attackerPed) == true then
                return true
            end
            if shouldCheckVehicleAttackControls == true then
                for _, attackControlId in ipairs({ 69, 70, 92, 114, 331 }) do
                    if KSIsBlameKillControlPressed(attackControlId) then
                        return true
                    end
                end
            end
            return false
        end

        function KSArmBlameKillProjectileDiscovery(weaponHash, weaponDamageType, nowMs, isAttacking)
            local projectileDamageType, discoveryWindowMs = KSGetBlameKillProjectileProfile(weaponHash, weaponDamageType)
            if projectileDamageType ~= nil and isAttacking == true then
                local normalizedWeaponHash = KSBlameKillNormalizedWeaponHash(weaponHash)
                KS_BLAME_KILL_PREARM.projectileDiscovery[normalizedWeaponHash] = { weaponHash = weaponHash, damageType = projectileDamageType, untilMs = nowMs + discoveryWindowMs }
            end
            return projectileDamageType
        end

        function KSIsBlameKillDirectFireDamageType(damageType)
            return damageType == 3 or damageType == 4 or damageType == 10
        end

        function KSGetBlameKillExplosiveTrajectory(shooterPed, shooterVehicle)
            local camX, camY, camZ = KSBlameKillVectorComponents(CAM.GET_GAMEPLAY_CAM_COORD())
            local camPitchDeg, camRollDeg, camYawDeg = KSBlameKillVectorComponents(CAM.GET_GAMEPLAY_CAM_ROT(2))
            local pitchRadians = math.rad(camPitchDeg)
            local yawRadians = math.rad(camYawDeg)
            local horizontalScale = math.abs(math.cos(pitchRadians))
            local sinYaw = math.sin(yawRadians)
            local cosYaw = math.cos(yawRadians)
            local sinPitch = math.sin(pitchRadians)
            local rayEndX = camX + -sinYaw * horizontalScale * KS_BLAME_KILL_EXPLOSIVE_MAX_RANGE
            local rayEndY = camY + cosYaw * horizontalScale * KS_BLAME_KILL_EXPLOSIVE_MAX_RANGE
            local rayEndZ = camZ + sinPitch * KS_BLAME_KILL_EXPLOSIVE_MAX_RANGE
            local ignoredEntity = tonumber(shooterVehicle) or tonumber(shooterPed) or 0
            local shapeTestHandle = SHAPETEST.START_EXPENSIVE_SYNCHRONOUS_SHAPE_TEST_LOS_PROBE(camX, camY, camZ, rayEndX, rayEndY, rayEndZ, -1, ignoredEntity, 7)
            local rayResultBuffer = KS_BLAME_KILL_PREARM.explosiveRayBuffer
            SHAPETEST.GET_SHAPE_TEST_RESULT(shapeTestHandle, rayResultBuffer, rayResultBuffer + 8, rayResultBuffer + 32, rayResultBuffer + 56)
            local hitEntity = 0
            if Memory.ReadByte(rayResultBuffer) ~= 0 then
                rayEndX = Memory.ReadFloat(rayResultBuffer + 8)
                rayEndY = Memory.ReadFloat(rayResultBuffer + 16)
                rayEndZ = Memory.ReadFloat(rayResultBuffer + 24)
                hitEntity = tonumber(Memory.ReadInt(rayResultBuffer + 56)) or 0
            end
            return camX, camY, camZ, rayEndX, rayEndY, rayEndZ, hitEntity
        end

        function KSMarkBlameKillRecipientsNearSegment(nowMs, segmentStartX, segmentStartY, segmentStartZ, segmentEndX, segmentEndY, segmentEndZ, pathRadius, impactRadius, holdDurationMs, passthroughReason, hitEntity)
            KSMarkBlameKillEntityRecipients(hitEntity, nowMs, holdDurationMs, tostring(passthroughReason or "trajectory_passthrough") .. ":exact_hit")
            local pathRadiusSq = pathRadius * pathRadius
            local impactRadiusSq = impactRadius * impactRadius
            for _, remotePlayer in ipairs(KSGetBlameKillRemotePlayerSnapshot(nowMs)) do
                local remotePlayerId = remotePlayer.playerId
                local playerX, playerY, playerZ = KSGetBlameKillRemotePlayerPosition(remotePlayer)
                local impactDeltaX = playerX - segmentEndX
                local impactDeltaY = playerY - segmentEndY
                local impactDeltaZ = playerZ - segmentEndZ
                if pathRadiusSq >= KSBlameKillDistanceSqToSegment(playerX, playerY, playerZ, segmentStartX, segmentStartY, segmentStartZ, segmentEndX, segmentEndY, segmentEndZ) or impactRadiusSq >= impactDeltaX * impactDeltaX + impactDeltaY * impactDeltaY + impactDeltaZ * impactDeltaZ then
                    KSMarkBlameKillRecipientPassthrough(remotePlayerId, nowMs + holdDurationMs, nowMs, passthroughReason)
                end
            end
        end

        function KSMarkBlameKillDirectFireTrajectory(nowMs, shooterPed, weaponHash, damageType, isAimingOrFiring, passthroughReason, shooterVehicle)
            if isAimingOrFiring ~= true or not KSIsBlameKillDirectFireDamageType(damageType) then
                return false
            end
            local startX, startY, startZ, endX, endY, endZ, hitEntity = KSGetBlameKillExplosiveTrajectory(shooterPed, shooterVehicle)
            KSMarkBlameKillRecipientsNearSegment(nowMs, startX, startY, startZ, endX, endY, endZ, KS_BLAME_KILL_DIRECT_FIRE_PATH_RADIUS, KS_BLAME_KILL_DIRECT_FIRE_PATH_RADIUS, KS_BLAME_KILL_PVP_COOLDOWN_MS, ("%s:%u"):format(passthroughReason or "direct_fire_passthrough", weaponHash), hitEntity)
            return true
        end

        function KSRefreshBlameKillDirectFirePassthrough(nowMs)
            local localPed = PLAYER.PLAYER_PED_ID()
            local selectedWeaponHash = WEAPON.GET_SELECTED_PED_WEAPON(localPed)
            local weaponDamageType = WEAPON.GET_WEAPON_DAMAGE_TYPE(selectedWeaponHash)
            local isAiming = KSIsBlameKillControlPressed(25)
            local isAttacking = KSIsBlameKillAttackActive(localPed, false)
            KSMarkBlameKillDirectFireTrajectory(nowMs, localPed, selectedWeaponHash, weaponDamageType, isAiming or isAttacking, isAiming and "direct_fire_aim_prefire_passthrough" or "hip_fire_trajectory_passthrough")
        end

        function KSDiscoverBlameKillProjectile(ownerPed, weaponHash, damageType, nowMs)
            local projectilePositionBuffer = KS_BLAME_KILL_PREARM.projectilePositionBuffer
            local projectileEntityPtr = KS_BLAME_KILL_PREARM.projectileEntityPtr
            if projectilePositionBuffer == nil or projectilePositionBuffer == 0 or projectileEntityPtr == nil or projectileEntityPtr == 0 then
                return
            end
            Memory.WriteInt(projectileEntityPtr, 0)
            local projectileQueryOk, isProjectileFound = pcall(MISC.GET_PROJECTILE_OF_PROJECTILE_TYPE_WITHIN_DISTANCE, ownerPed, weaponHash, KS_BLAME_KILL_EXPLOSIVE_MAX_RANGE, projectilePositionBuffer, projectileEntityPtr, false)
            if not projectileQueryOk or isProjectileFound ~= true then
                return
            end
            local projectileEntity = tonumber(Memory.ReadInt(projectileEntityPtr)) or 0
            if projectileEntity == 0 or ENTITY.DOES_ENTITY_EXIST(projectileEntity) ~= true then
                return
            end
            local projectileX, projectileY, projectileZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_COORDS(projectileEntity, true))
            local trackedProjectile = KS_BLAME_KILL_PREARM.trackedProjectiles[projectileEntity]
            if type(trackedProjectile) ~= "table" then
                trackedProjectile = {
                    x = projectileX,
                    y = projectileY,
                    z = projectileZ,
                    weaponHash = weaponHash,
                    damageType = damageType,
                }
                KS_BLAME_KILL_PREARM.trackedProjectiles[projectileEntity] = trackedProjectile
            end
            trackedProjectile.weaponHash = weaponHash
            trackedProjectile.damageType = damageType
            trackedProjectile.lastSeenMs = nowMs
        end

        function KSRefreshBlameKillTrackedProjectiles(nowMs)
            for projectileEntity, trackedProjectile in pairs(KS_BLAME_KILL_PREARM.trackedProjectiles) do
                if type(trackedProjectile) == "table" then
                    if ENTITY.DOES_ENTITY_EXIST(projectileEntity) == true then
                        local projectileX, projectileY, projectileZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_COORDS(projectileEntity, true))
                        local velocityX, velocityY, velocityZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_VELOCITY(projectileEntity))
                        local speedSq = velocityX * velocityX + velocityY * velocityY + velocityZ * velocityZ
                        local leadSeconds = speedSq >= KS_BLAME_KILL_FAST_PROJECTILE_SPEED_SQ and KS_BLAME_KILL_FAST_PROJECTILE_LEAD_SECONDS or 0.35
                        local blastRadius = trackedProjectile.damageType == 6 and KS_BLAME_KILL_FIRE_RADIUS or KS_BLAME_KILL_EXPLOSIVE_BLAST_RADIUS
                        local pathRadius = speedSq > 0.25 and KS_BLAME_KILL_EXPLOSIVE_PATH_RADIUS or 0.5
                        KSMarkBlameKillRecipientsNearSegment(nowMs, tonumber(trackedProjectile.x) or projectileX, tonumber(trackedProjectile.y) or projectileY, tonumber(trackedProjectile.z) or projectileZ, projectileX + velocityX * leadSeconds, projectileY + velocityY * leadSeconds, projectileZ + velocityZ * leadSeconds, pathRadius, blastRadius, KS_BLAME_KILL_EXPLOSIVE_MIN_HOLD_MS, ("live_projectile_passthrough:%u"):format(tonumber(trackedProjectile.weaponHash) or 0))
                        trackedProjectile.z = projectileZ
                        trackedProjectile.y = projectileY
                        trackedProjectile.x = projectileX
                        trackedProjectile.lastSeenMs = nowMs
                    end
                else
                    if type(trackedProjectile) == "table" and trackedProjectile.damageType == 6 and trackedProjectile.x ~= nil and nowMs - (tonumber(trackedProjectile.lastSeenMs) or 0) <= 250 then
                        KS_BLAME_KILL_PREARM.fireHazards[projectileEntity] = {
                            x = trackedProjectile.x,
                            y = trackedProjectile.y,
                            z = trackedProjectile.z,
                            untilMs = nowMs + KS_BLAME_KILL_FIRE_HAZARD_MS,
                        }
                    end
                    KS_BLAME_KILL_PREARM.trackedProjectiles[projectileEntity] = nil
                end
            end
        end

        function KSRefreshBlameKillFireHazards(nowMs)
            for hazardKey, fireHazard in pairs(KS_BLAME_KILL_PREARM.fireHazards) do
                if type(fireHazard) == "table" and not (nowMs >= (tonumber(fireHazard.untilMs) or 0)) then
                    KSMarkBlameKillRecipientsNearSegment(nowMs, fireHazard.x, fireHazard.y, fireHazard.z, fireHazard.x, fireHazard.y, fireHazard.z, 0.5, KS_BLAME_KILL_FIRE_RADIUS, KS_BLAME_KILL_PVP_COOLDOWN_MS, "local_fire_hazard_passthrough")
                else
                    KS_BLAME_KILL_PREARM.fireHazards[hazardKey] = nil
                end
            end
        end

        function KSRefreshBlameKillExplosivePassthrough(nowMs)
            if nowMs - (tonumber(KS_BLAME_KILL_PREARM.lastExplosiveSampleMs) or 0) < KS_BLAME_KILL_EXPLOSIVE_SAMPLE_MS then
                return
            end
            KS_BLAME_KILL_PREARM.lastExplosiveSampleMs = nowMs
            local localPlayerPed = PLAYER.PLAYER_PED_ID()
            local selectedWeaponHash = WEAPON.GET_SELECTED_PED_WEAPON(localPlayerPed)
            local weaponDamageType = WEAPON.GET_WEAPON_DAMAGE_TYPE(selectedWeaponHash)
            local isAiming = KSIsBlameKillControlPressed(25)
            local isAttacking = KSIsBlameKillAttackActive(localPlayerPed, false)
            local explosiveDamageType = KSArmBlameKillProjectileDiscovery(selectedWeaponHash, weaponDamageType, nowMs, isAttacking)
            local aimTrajectory = nil
            if explosiveDamageType ~= nil and (isAiming or isAttacking) then
                aimTrajectory = { KSGetBlameKillExplosiveTrajectory(localPlayerPed) }
                KSMarkBlameKillRecipientsNearSegment(nowMs, aimTrajectory[1], aimTrajectory[2], aimTrajectory[3], aimTrajectory[4], aimTrajectory[5], aimTrajectory[6], KS_BLAME_KILL_EXPLOSIVE_PATH_RADIUS, explosiveDamageType == 6 and KS_BLAME_KILL_FIRE_RADIUS or KS_BLAME_KILL_EXPLOSIVE_BLAST_RADIUS, KS_BLAME_KILL_EXPLOSIVE_MIN_HOLD_MS, ("explosive_weapon_prefire_passthrough:%u"):format(selectedWeaponHash), aimTrajectory[7])
            end
            for discoveryWeaponKey, discoveryEntry in pairs(KS_BLAME_KILL_PREARM.projectileDiscovery) do
                if type(discoveryEntry) == "table" and not (nowMs >= (tonumber(discoveryEntry.untilMs) or 0)) then
                    KSDiscoverBlameKillProjectile(localPlayerPed, discoveryEntry.weaponHash, discoveryEntry.damageType, nowMs)
                else
                    KS_BLAME_KILL_PREARM.projectileDiscovery[discoveryWeaponKey] = nil
                end
            end
            KSRefreshBlameKillTrackedProjectiles(nowMs)
            KSRefreshBlameKillFireHazards(nowMs)
            if not isAttacking or explosiveDamageType == nil then
                return
            end
            local originX, originY, originZ, endX, endY, endZ
            if aimTrajectory ~= nil then
                originX, originY, originZ, endX, endY, endZ = table.unpack(aimTrajectory)
            else
                originX, originY, originZ, endX, endY, endZ = KSGetBlameKillExplosiveTrajectory(localPlayerPed)
            end
            local blastRadius = explosiveDamageType == 6 and KS_BLAME_KILL_FIRE_RADIUS or KS_BLAME_KILL_EXPLOSIVE_BLAST_RADIUS
            if explosiveDamageType == 6 then
                KS_BLAME_KILL_PREARM.fireHazards.weapon = { x = endX, y = endY, z = endZ, untilMs = nowMs + KS_BLAME_KILL_FIRE_HAZARD_MS }
            end
            local trajectoryLength = math.sqrt((endX - originX) ^ 2 + (endY - originY) ^ 2 + (endZ - originZ) ^ 2)
            local holdMs = math.max(KS_BLAME_KILL_EXPLOSIVE_MIN_HOLD_MS, math.min(KS_BLAME_KILL_EXPLOSIVE_MAX_HOLD_MS, math.floor(1000 + trajectoryLength * 12)))
            KSMarkBlameKillRecipientsNearSegment(nowMs, originX, originY, originZ, endX, endY, endZ, KS_BLAME_KILL_EXPLOSIVE_PATH_RADIUS, blastRadius, holdMs, ("explosive_trajectory_passthrough:%u"):format(selectedWeaponHash), aimTrajectory and aimTrajectory[7] or 0)
        end

        function KSMarkBlameKillVehicleForwardRecipients(nowMs, vehicleHandle, pathRadius, blastRadius, holdMs, passthroughReason)
            local vehicleX, vehicleY, vehicleZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_COORDS(vehicleHandle, true))
            local forwardX, forwardY, forwardZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_FORWARD_VECTOR(vehicleHandle))
            local muzzleX = vehicleX + forwardX * 2.0
            local muzzleY = vehicleY + forwardY * 2.0
            local muzzleZ = vehicleZ + forwardZ * 2.0
            KSMarkBlameKillRecipientsNearSegment(nowMs, muzzleX, muzzleY, muzzleZ, muzzleX + forwardX * KS_BLAME_KILL_EXPLOSIVE_MAX_RANGE, muzzleY + forwardY * KS_BLAME_KILL_EXPLOSIVE_MAX_RANGE, muzzleZ + forwardZ * KS_BLAME_KILL_EXPLOSIVE_MAX_RANGE, pathRadius, blastRadius, holdMs, passthroughReason)
        end

        function KSRefreshBlameKillVehicleInteractionPassthrough(nowMs)
            local localPed = PLAYER.PLAYER_PED_ID()
            if PED.IS_PED_IN_ANY_VEHICLE(localPed, false) ~= true then
                KS_BLAME_KILL_PREARM.lastVehicleWeaponHash = 0
                KS_BLAME_KILL_PREARM.lastVehicleWeaponEntity = 0
                KS_BLAME_KILL_PREARM.lastVehicleWeaponMs = 0
                return
            end
            local currentVehicle = PED.GET_VEHICLE_PED_IS_IN(localPed, false)
            if currentVehicle == 0 or ENTITY.DOES_ENTITY_EXIST(currentVehicle) ~= true then
                return
            end
            local isAttackActive = KSIsBlameKillAttackActive(localPed, true)
            local isAttackOrAimActive = isAttackActive or KSIsBlameKillControlPressed(25)
            local lastCombatSampleMs = tonumber(KS_BLAME_KILL_PREARM.lastVehicleCombatSampleMs) or 0
            if (isAttackOrAimActive and KS_BLAME_KILL_PVP_SAMPLE_MS or KS_BLAME_KILL_VEHICLE_COMBAT_SAMPLE_MS) > nowMs - lastCombatSampleMs then
                return
            end
            KS_BLAME_KILL_PREARM.lastVehicleCombatSampleMs = nowMs
            if VEHICLE.GET_PED_IN_VEHICLE_SEAT(currentVehicle, -1, false) == localPed then
                local vehicleX, vehicleY, vehicleZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_COORDS(currentVehicle, true))
                local velocityX, velocityY, velocityZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_VELOCITY(currentVehicle))
                if velocityX * velocityX + velocityY * velocityY + velocityZ * velocityZ >= 16.0 then
                    local pathEndX = vehicleX + velocityX * KS_BLAME_KILL_VEHICLE_PATH_SECONDS
                    local pathEndY = vehicleY + velocityY * KS_BLAME_KILL_VEHICLE_PATH_SECONDS
                    local pathEndZ = vehicleZ + velocityZ * KS_BLAME_KILL_VEHICLE_PATH_SECONDS
                    for _, remotePlayer in ipairs(KSGetBlameKillRemotePlayerSnapshot(nowMs)) do
                        local remotePlayerId = remotePlayer.playerId
                        local isTouchingVehicle = ENTITY.IS_ENTITY_TOUCHING_ENTITY(currentVehicle, remotePlayer.playerPed) == true
                        local playerX, playerY, playerZ = KSGetBlameKillRemotePlayerPosition(remotePlayer)
                        local pathDistanceSq = KSBlameKillDistanceSqToSegment(playerX, playerY, playerZ, vehicleX, vehicleY, vehicleZ, pathEndX, pathEndY, pathEndZ)
                        if isTouchingVehicle or pathDistanceSq <= KS_BLAME_KILL_VEHICLE_PATH_RADIUS ^ 2 then
                            KSMarkBlameKillRecipientPassthrough(remotePlayerId, nowMs + KS_BLAME_KILL_PVP_COOLDOWN_MS, nowMs, isTouchingVehicle and "vehicle_contact_passthrough" or "vehicle_path_passthrough")
                        end
                    end
                end
            end
            local lockOnTargetPtr = KS_BLAME_KILL_PREARM.aimEntityPtr
            if lockOnTargetPtr ~= nil and lockOnTargetPtr ~= 0 then
                Memory.WriteInt(lockOnTargetPtr, 0)
                if VEHICLE.GET_VEHICLE_LOCK_ON_TARGET(currentVehicle, lockOnTargetPtr) == true then
                    KSMarkBlameKillEntityRecipients(Memory.ReadInt(lockOnTargetPtr), nowMs, KS_BLAME_KILL_PVP_COOLDOWN_MS, "vehicle_lock_on_passthrough")
                end
            end
            local weaponHash = WEAPON.GET_SELECTED_PED_WEAPON(localPed)
            local hasVehicleWeapon = false
            local vehicleWeaponPtr = KS_BLAME_KILL_PREARM.vehicleWeaponPtr
            if vehicleWeaponPtr ~= nil and vehicleWeaponPtr ~= 0 then
                Memory.WriteInt(vehicleWeaponPtr, 0)
                if WEAPON.GET_CURRENT_PED_VEHICLE_WEAPON(localPed, vehicleWeaponPtr) == true then
                    weaponHash = Memory.ReadInt(vehicleWeaponPtr)
                    hasVehicleWeapon = true
                    KS_BLAME_KILL_PREARM.lastVehicleWeaponHash = weaponHash
                    KS_BLAME_KILL_PREARM.lastVehicleWeaponEntity = currentVehicle
                    KS_BLAME_KILL_PREARM.lastVehicleWeaponMs = nowMs
                end
            end
            if not hasVehicleWeapon and tonumber(KS_BLAME_KILL_PREARM.lastVehicleWeaponEntity) == currentVehicle and nowMs - (tonumber(KS_BLAME_KILL_PREARM.lastVehicleWeaponMs) or 0) <= KS_BLAME_KILL_VEHICLE_WEAPON_CACHE_MS then
                weaponHash = tonumber(KS_BLAME_KILL_PREARM.lastVehicleWeaponHash) or weaponHash
                hasVehicleWeapon = weaponHash ~= 0
            end
            local canVehicleFireWeapons = hasVehicleWeapon or VEHICLE.DOES_VEHICLE_HAVE_WEAPONS(currentVehicle) == true
            local weaponDamageType = WEAPON.GET_WEAPON_DAMAGE_TYPE(weaponHash)
            local projectileProfileDamageType = KSArmBlameKillProjectileDiscovery(weaponHash, weaponDamageType, nowMs, isAttackActive)
            if isAttackOrAimActive and hasVehicleWeapon then
                local projectileDamageType = KSGetBlameKillProjectileProfile(weaponHash, weaponDamageType)
                if projectileDamageType ~= nil then
                    local prefireStartX, prefireStartY, prefireStartZ, prefireEndX, prefireEndY, prefireEndZ, prefireHitEntity = KSGetBlameKillExplosiveTrajectory(localPed, currentVehicle)
                    KSMarkBlameKillRecipientsNearSegment(nowMs, prefireStartX, prefireStartY, prefireStartZ, prefireEndX, prefireEndY, prefireEndZ, KS_BLAME_KILL_EXPLOSIVE_PATH_RADIUS, projectileDamageType == 6 and KS_BLAME_KILL_FIRE_RADIUS or KS_BLAME_KILL_EXPLOSIVE_BLAST_RADIUS, KS_BLAME_KILL_EXPLOSIVE_MIN_HOLD_MS, ("vehicle_weapon_prefire_passthrough:%u"):format(weaponHash), prefireHitEntity)
                elseif weaponDamageType == 14 then
                    local cannonPrefireStartX, cannonPrefireStartY, cannonPrefireStartZ, cannonPrefireEndX, cannonPrefireEndY, cannonPrefireEndZ = KSGetBlameKillExplosiveTrajectory(localPed, currentVehicle)
                    KSMarkBlameKillRecipientsNearSegment(nowMs, cannonPrefireStartX, cannonPrefireStartY, cannonPrefireStartZ, cannonPrefireEndX, cannonPrefireEndY, cannonPrefireEndZ, KS_BLAME_KILL_EXPLOSIVE_PATH_RADIUS, KS_BLAME_KILL_EXPLOSIVE_PATH_RADIUS, KS_BLAME_KILL_PVP_COOLDOWN_MS, ("vehicle_water_cannon_prefire_passthrough:%u"):format(weaponHash))
                else
                    KSMarkBlameKillDirectFireTrajectory(nowMs, localPed, weaponHash, weaponDamageType, true, "vehicle_weapon_prefire_passthrough", currentVehicle)
                end
            elseif isAttackOrAimActive and canVehicleFireWeapons then
                local capabilityStartX, capabilityStartY, capabilityStartZ, capabilityEndX, capabilityEndY, capabilityEndZ, capabilityHitEntity = KSGetBlameKillExplosiveTrajectory(localPed, currentVehicle)
                KSMarkBlameKillRecipientsNearSegment(nowMs, capabilityStartX, capabilityStartY, capabilityStartZ, capabilityEndX, capabilityEndY, capabilityEndZ, KS_BLAME_KILL_EXPLOSIVE_PATH_RADIUS, KS_BLAME_KILL_EXPLOSIVE_BLAST_RADIUS, KS_BLAME_KILL_EXPLOSIVE_MIN_HOLD_MS, "vehicle_weapon_capability_prefire_passthrough", capabilityHitEntity)
            end
            if isAttackOrAimActive and canVehicleFireWeapons then
                local forwardPathRadius
                if projectileProfileDamageType ~= nil then
                    forwardPathRadius = KS_BLAME_KILL_EXPLOSIVE_BLAST_RADIUS
                    if forwardPathRadius then
                        goto markForwardRecipients
                    end
                end
                if hasVehicleWeapon then
                    forwardPathRadius = KS_BLAME_KILL_FIXED_VEHICLE_PATH_RADIUS
                    if forwardPathRadius then
                        goto markForwardRecipients
                    end
                end
                forwardPathRadius = KS_BLAME_KILL_EXPLOSIVE_BLAST_RADIUS
                ::markForwardRecipients::
                KSMarkBlameKillVehicleForwardRecipients(nowMs, currentVehicle, forwardPathRadius, KS_BLAME_KILL_EXPLOSIVE_BLAST_RADIUS, KS_BLAME_KILL_EXPLOSIVE_MIN_HOLD_MS, "fixed_vehicle_weapon_prefire_passthrough")
            end
            if isAttackActive and projectileProfileDamageType ~= nil then
                local projectileStartX, projectileStartY, projectileStartZ, projectileEndX, projectileEndY, projectileEndZ = KSGetBlameKillExplosiveTrajectory(localPed, currentVehicle)
                KSMarkBlameKillRecipientsNearSegment(nowMs, projectileStartX, projectileStartY, projectileStartZ, projectileEndX, projectileEndY, projectileEndZ, KS_BLAME_KILL_EXPLOSIVE_PATH_RADIUS, projectileProfileDamageType == 6 and KS_BLAME_KILL_FIRE_RADIUS or KS_BLAME_KILL_EXPLOSIVE_BLAST_RADIUS, KS_BLAME_KILL_EXPLOSIVE_MIN_HOLD_MS, ("vehicle_projectile_trajectory_passthrough:%u"):format(weaponHash))
            elseif isAttackActive and weaponDamageType == 14 then
                local cannonStartX, cannonStartY, cannonStartZ, cannonEndX, cannonEndY, cannonEndZ = KSGetBlameKillExplosiveTrajectory(localPed, currentVehicle)
                KSMarkBlameKillRecipientsNearSegment(nowMs, cannonStartX, cannonStartY, cannonStartZ, cannonEndX, cannonEndY, cannonEndZ, KS_BLAME_KILL_EXPLOSIVE_PATH_RADIUS, KS_BLAME_KILL_EXPLOSIVE_PATH_RADIUS, KS_BLAME_KILL_PVP_COOLDOWN_MS, ("water_cannon_trajectory_passthrough:%u"):format(weaponHash))
            else
                KSMarkBlameKillDirectFireTrajectory(nowMs, localPed, weaponHash, weaponDamageType, isAttackActive, "vehicle_direct_fire_trajectory_passthrough", currentVehicle)
            end
        end

        function KSMarkBlameKillOrbitalImpactRecipients(nowMs, impactX, impactY)
            local blastRadiusSq = KS_BLAME_KILL_ORBITAL_BLAST_RADIUS ^ 2
            local playersInBlastCount = 0
            local markedRecipientCount = 0
            for _, remotePlayer in ipairs(KSGetBlameKillRemotePlayerSnapshot(nowMs)) do
                local playerX, playerY = KSGetBlameKillRemotePlayerPosition(remotePlayer)
                local deltaX = playerX - impactX
                local deltaY = playerY - impactY
                if blastRadiusSq > deltaX * deltaX + deltaY * deltaY then
                    playersInBlastCount = playersInBlastCount + 1
                    if KSMarkBlameKillRecipientPassthrough(remotePlayer.playerId, nowMs + KS_BLAME_KILL_REMOTE_COMBAT_HOLD_MS, nowMs, "orbital_cannon_impact_passthrough") == true then
                        markedRecipientCount = markedRecipientCount + 1
                    end
                end
            end
            return playersInBlastCount, markedRecipientCount
        end

        function KSIsBlameKillLocalOrbitalSamplingReady()
            if isUnloadRequested() or maintransitionActive then
                return false
            end
            if NETWORK.NETWORK_IS_SESSION_ACTIVE() ~= true then
                return false
            end
            if NETWORK.NETWORK_IS_SESSION_STARTED() ~= true then
                return false
            end
            if NETWORK.NETWORK_IS_IN_TRANSITION() == true then
                return false
            end
            if DLC.GET_IS_LOADING_SCREEN_ACTIVE() == true or DLC.GET_IS_INITIAL_LOADING_SCREEN_ACTIVE() == true then
                return false
            end
            local localPlayerId = tonumber(GTA.GetLocalPlayerId())
            return localPlayerId ~= nil and localPlayerId >= 0 and localPlayerId < 32
        end

        function KSIsBlameKillLocalOrbitalReleaseActive(nowMs)
            nowMs = tonumber(nowMs) or getRuntimeNowMs()
            local orbitalSampleMs = tonumber(KS_BLAME_KILL_PREARM.localOrbitalSampleMs) or 0
            return KS_BLAME_KILL_PREARM.localOrbitalReleaseActive == true and orbitalSampleMs > 0 and nowMs >= orbitalSampleMs
        end

        function KSRefreshBlameKillOrbitalPassthrough(nowMs)
            if nowMs - (tonumber(KS_BLAME_KILL_PREARM.lastOrbitalCombatSampleMs) or 0) < KS_BLAME_KILL_ORBITAL_COMBAT_SAMPLE_MS then
                return KSIsBlameKillLocalOrbitalReleaseActive(nowMs)
            end
            KS_BLAME_KILL_PREARM.lastOrbitalCombatSampleMs = nowMs
            local isSamplingReady = KSIsBlameKillLocalOrbitalSamplingReady()
            local isLocalOrbitalActive, orbitalFlags, orbitalFlagsGlobal, orbitalAuxValue, orbitalAuxGlobal = KSGetBlameKillLocalOrbitalCannonState()
            local isReleaseActive = isSamplingReady and isLocalOrbitalActive
            KS_BLAME_KILL_PREARM.localOrbitalSampleMs = nowMs
            KS_BLAME_KILL_PREARM.localOrbitalReleaseActive = isReleaseActive
            if not isReleaseActive then
                return false
            end
            local getCameraCoord = type(CAM.GET_FINAL_RENDERED_CAM_COORD) == "function" and CAM.GET_FINAL_RENDERED_CAM_COORD or CAM.GET_GAMEPLAY_CAM_COORD
            local camX, camY = KSBlameKillVectorComponents(getCameraCoord())
            local impactRecipientCount, markedRecipientCount = KSMarkBlameKillOrbitalImpactRecipients(nowMs, camX, camY)
            return true
        end

        function KSGetBlameKillLocalOrbitalCannonState()
            local localPlayerId = tonumber(GTA.GetLocalPlayerId())
            local playerBDBase = tonumber(globalPlayerBDBaseCached) or 0
            if localPlayerId == nil or localPlayerId < 0 or localPlayerId >= 32 or playerBDBase <= 0 then
                return false, 0, 0
            end
            local playerBDSlotBase = playerBDBase + 1 + localPlayerId * 468
            local orbitalFlagsGlobal = playerBDSlotBase + 429
            local orbitalAuxGlobal = playerBDSlotBase + 438
            local orbitalFlags = tonumber(ScriptGlobal.GetInt(orbitalFlagsGlobal)) or 0
            return orbitalFlags & 1 ~= 0, orbitalFlags, orbitalFlagsGlobal, tonumber(ScriptGlobal.GetInt(orbitalAuxGlobal)) or 0, orbitalAuxGlobal
        end

        function KSGetBlameKillOrbitalCannonState(rawPlayerId)
            local targetPlayerId = tonumber(rawPlayerId)
            local playerBDBase = tonumber(globalPlayerBDBaseCached) or 0
            if targetPlayerId == nil or targetPlayerId < 0 or targetPlayerId >= 32 or playerBDBase <= 0 then
                return false, 0, 0
            end
            local playerBDSlotBase = playerBDBase + 1 + targetPlayerId * 468
            local orbitalFlagsGlobal = playerBDSlotBase + 429
            local orbitalAuxGlobal = playerBDSlotBase + 438
            local orbitalFlags = tonumber(ScriptGlobal.GetInt(orbitalFlagsGlobal)) or 0
            return orbitalFlags & 1 ~= 0, orbitalFlags, orbitalFlagsGlobal, tonumber(ScriptGlobal.GetInt(orbitalAuxGlobal)) or 0, orbitalAuxGlobal
        end

        function KSCanAllowLegitimateOrbitalNetEvent(senderPlayer, netEventId)
            if netEventId ~= 16 and netEventId ~= 17 then
                return false, "not_orbital_event"
            end
            if senderPlayer == nil or not FeatureMgr.IsFeatureEnabled(H_BLAME_KILL_PROTECTION) or not KSIsBlameKillFriendlyFireMethod() or not KSIsBlameKillSessionFullyLoaded() then
                return false, "protection_not_ready"
            end
            local senderPlayerId = tonumber(senderPlayer.PlayerId)
            if senderPlayerId == nil or senderPlayerId < 0 or senderPlayerId >= 32 or senderPlayerId == GTA.GetLocalPlayerId() or NETWORK.NETWORK_IS_PLAYER_ACTIVE(senderPlayerId) ~= true then
                return false, "invalid_sender"
            end
            local nowMs = getRuntimeNowMs()
            if KS_BLAME_KILL_PREARM.recipientPassthroughReasons[senderPlayerId] ~= "incoming_orbital_cannon_passthrough" or not KSIsBlameKillRecipientPassthrough(senderPlayerId, nowMs) then
                return false, "no_orbital_passthrough"
            end
            local isSenderOrbitalActive, orbitalFlags, orbitalFlagsGlobal, orbitalAuxValue, orbitalAuxGlobal = KSGetBlameKillOrbitalCannonState(senderPlayerId)
            if not isSenderOrbitalActive then
                return false, "orbital_state_inactive", orbitalFlags, orbitalFlagsGlobal, orbitalAuxValue, orbitalAuxGlobal
            end
            return true, "verified_orbital_passthrough", orbitalFlags, orbitalFlagsGlobal, orbitalAuxValue, orbitalAuxGlobal
        end

        function KSMarkBlameKillRemoteOrbitalFreeCamera(rawPlayerId, nowMs)
            local remotePlayerId = tonumber(rawPlayerId)
            if remotePlayerId == nil or remotePlayerId == GTA.GetLocalPlayerId() then
                return
            end
            nowMs = tonumber(nowMs) or getRuntimeNowMs()
            KS_BLAME_KILL_PREARM.remoteOrbitalFreeCameraUntilMs[remotePlayerId] = nowMs + KS_BLAME_KILL_REMOTE_ORBITAL_CAMERA_HOLD_MS
        end

        function KSRefreshBlameKillRemoteOrbitalPassthrough(nowMs)
            if nowMs - (tonumber(KS_BLAME_KILL_PREARM.lastRemoteOrbitalCombatSampleMs) or 0) < KS_BLAME_KILL_REMOTE_ORBITAL_SAMPLE_MS then
                return
            end
            KS_BLAME_KILL_PREARM.lastRemoteOrbitalCombatSampleMs = nowMs
            local freeCameraUntilByPlayer = KS_BLAME_KILL_PREARM.remoteOrbitalFreeCameraUntilMs
            for freeCameraPlayerId, freeCameraUntilMs in pairs(freeCameraUntilByPlayer) do
                if nowMs >= (tonumber(freeCameraUntilMs) or 0) or NETWORK.NETWORK_IS_PLAYER_ACTIVE(freeCameraPlayerId) ~= true then
                    freeCameraUntilByPlayer[freeCameraPlayerId] = nil
                end
            end
            local remotePlayers = KSGetBlameKillRemotePlayerSnapshot(nowMs)
            local remotePlayerCount = #remotePlayers
            if remotePlayerCount == 0 then
                KS_BLAME_KILL_PREARM.remoteOrbitalCursor = 1
                return
            end
            local startCursor = math.max(1, math.min(remotePlayerCount, tonumber(KS_BLAME_KILL_PREARM.remoteOrbitalCursor) or 1))
            local sampleBudget = math.min(remotePlayerCount, KS_BLAME_KILL_REMOTE_ORBITAL_PLAYER_BUDGET)
            for sampleOffset = 0, sampleBudget - 1 do
                local sampledPlayerId = remotePlayers[(startCursor + sampleOffset - 1) % remotePlayerCount + 1].playerId
                local isOrbitalActive, orbitalFlags, orbitalFlagsGlobal = KSGetBlameKillOrbitalCannonState(sampledPlayerId)
                if isOrbitalActive then
                    local wasPassthroughMarked = KSMarkBlameKillRecipientPassthrough(sampledPlayerId, nowMs + KS_BLAME_KILL_REMOTE_COMBAT_HOLD_MS, nowMs, "incoming_orbital_cannon_passthrough") == true
                end
            end
            KS_BLAME_KILL_PREARM.remoteOrbitalCursor = (startCursor + sampleBudget - 1) % remotePlayerCount + 1
        end

        function KSGetBlameKillEntityObjectId(rawEntityHandle)
            local entityHandle = tonumber(rawEntityHandle) or 0
            if entityHandle == 0 or ENTITY.DOES_ENTITY_EXIST(entityHandle) ~= true then
                return 0
            end
            local entityPointer = GTA.HandleToPointer(entityHandle)
            local netObject = entityPointer and entityPointer.NetObject or nil
            return netObject and tonumber(netObject.ObjectID) or 0
        end

        function KSBlameKillRemoteAimThreatensEntity(rawTargetEntity, aimStartX, aimStartY, aimStartZ, aimEndX, aimEndY, aimEndZ, pathRadius, nearRadius)
            local targetEntity = tonumber(rawTargetEntity) or 0
            if targetEntity == 0 or ENTITY.DOES_ENTITY_EXIST(targetEntity) ~= true then
                return false
            end
            local entityX, entityY, entityZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_COORDS(targetEntity, true))
            return KSBlameKillDistanceSqToSegment(entityX, entityY, entityZ, aimStartX, aimStartY, aimStartZ, aimEndX, aimEndY, aimEndZ) <= pathRadius * pathRadius
        end

        function KSGetBlameKillRemoteAimRadii(shooterPed)
            local pathRadius = KS_BLAME_KILL_REMOTE_DIRECT_PATH_RADIUS
            local nearRadius = KS_BLAME_KILL_REMOTE_DIRECT_NEAR_RADIUS
            local selectedWeaponHash = WEAPON.GET_SELECTED_PED_WEAPON(shooterPed)
            local weaponDamageType = WEAPON.GET_WEAPON_DAMAGE_TYPE(selectedWeaponHash)
            local projectileDamageType = KSGetBlameKillProjectileProfile(selectedWeaponHash, weaponDamageType)
            local shooterVehicle = 0
            local hasVehicleWeapons = shooterPed
            if PED.IS_PED_IN_ANY_VEHICLE(hasVehicleWeapons, false) == true then
                hasVehicleWeapons = shooterPed
                shooterVehicle = PED.GET_VEHICLE_PED_IS_IN(hasVehicleWeapons, false)
            end
            if projectileDamageType == nil and shooterVehicle ~= 0 then
                local vehicleWeaponHashPtr = KS_BLAME_KILL_PREARM.incomingVehicleWeaponPtr
                if vehicleWeaponHashPtr ~= nil and vehicleWeaponHashPtr ~= 0 then
                    Memory.WriteInt(vehicleWeaponHashPtr, 0)
                    hasVehicleWeapons = WEAPON.GET_CURRENT_PED_VEHICLE_WEAPON(shooterPed, vehicleWeaponHashPtr)
                    if hasVehicleWeapons == true then
                        local vehicleWeaponHash = Memory.ReadInt(vehicleWeaponHashPtr)
                        local vehicleWeaponDamageType = WEAPON.GET_WEAPON_DAMAGE_TYPE(vehicleWeaponHash)
                        hasVehicleWeapons = KSGetBlameKillProjectileProfile(vehicleWeaponHash, vehicleWeaponDamageType)
                        projectileDamageType = hasVehicleWeapons
                    end
                end
            end
            if shooterVehicle ~= 0 then
                hasVehicleWeapons = VEHICLE.DOES_VEHICLE_HAVE_WEAPONS(shooterVehicle)
            end
            local isExplosiveWeapon = projectileDamageType ~= nil or hasVehicleWeapons
            if isExplosiveWeapon then
                pathRadius = KS_BLAME_KILL_EXPLOSIVE_PATH_RADIUS
                if projectileDamageType ~= 6 or not KS_BLAME_KILL_FIRE_RADIUS then
                    nearRadius = KS_BLAME_KILL_EXPLOSIVE_BLAST_RADIUS
                end
            end
            return pathRadius, nearRadius, isExplosiveWeapon
        end

        function KSResolveBlameKillIncomingOwner(incomingNetObject)
            if incomingNetObject == nil then
                return
            end
            local localPlayerId = GTA.GetLocalPlayerId()

            local function toActiveRemotePlayerId(candidatePlayerId)
                local numericPlayerId = tonumber(candidatePlayerId)
                local resolvedPlayerId
                if numericPlayerId ~= nil and numericPlayerId >= 0 and numericPlayerId < 32 and numericPlayerId ~= localPlayerId then
                    resolvedPlayerId = NETWORK.NETWORK_IS_PLAYER_ACTIVE(numericPlayerId)
                    if resolvedPlayerId == true and numericPlayerId then
                        goto returnResolvedPlayerId
                    end
                end
                resolvedPlayerId = nil
                ::returnResolvedPlayerId::
                return resolvedPlayerId
            end

            local entityPointer = incomingNetObject:GetEntity()
            if entityPointer ~= nil then
                local entityHandle = GTA.PointerToHandle(entityPointer)
                if entityHandle ~= 0 and ENTITY.IS_ENTITY_A_PED(entityHandle) == true then
                    local pedOwnerPlayerId = toActiveRemotePlayerId(NETWORK.NETWORK_GET_PLAYER_INDEX_FROM_PED(entityHandle))
                    if pedOwnerPlayerId ~= nil then
                        return pedOwnerPlayerId
                    end
                end
            end
            return toActiveRemotePlayerId(incomingNetObject.PlayerId) or toActiveRemotePlayerId(incomingNetObject.PendingPlayerId)
        end

        function KSGetBlameKillIncomingNodeIdentity(syncNode)
            if syncNode == nil then
                return nil, "nil"
            end
            local nodeName = syncNode:GetNodeName()
            if nodeName ~= nil and tostring(nodeName) ~= "" then
                return nil, tostring(nodeName)
            end
            return syncNode:GetNodeType(), "unavailable"
        end

        function KSBlameKillRemoteCameraDataImpl(syncPosition, senderNetObject, syncNodes)
            if not FeatureMgr.IsFeatureEnabled(H_BLAME_KILL_PROTECTION) or not KSIsBlameKillFriendlyFireMethod() or not KSIsBlameKillSessionFullyLoaded() or senderNetObject == nil then
                return
            end
            local gameStateNode = nil
            local cameraNode = nil
            for _, incomingNode in ipairs(syncNodes or {}) do
                local nodeType, nodeName = KSGetBlameKillIncomingNodeIdentity(incomingNode)
                if gameStateNode == nil then
                    if nodeName ~= "CPlayerGameStateDataNode" and nodeName ~= "Player Game State" and nodeType ~= eSyncDataNode.CPlayerGameStateDataNode then
                        if cameraNode == nil and (nodeName == "CPlayerCameraDataNode" or nodeName == "Player Camera" or nodeType == eSyncDataNode.CPlayerCameraDataNode) then
                            cameraNode = incomingNode:As("CPlayerCameraDataNode")
                        end
                    else
                        gameStateNode = incomingNode:As("CPlayerGameStateDataNode")
                    end
                elseif cameraNode == nil then
                    if nodeName == "CPlayerCameraDataNode" or nodeName == "Player Camera" or nodeType == eSyncDataNode.CPlayerCameraDataNode then
                        cameraNode = incomingNode:As("CPlayerCameraDataNode")
                    end
                end
            end
            local lockOnTargetId
            if gameStateNode ~= nil then
                lockOnTargetId = tonumber(gameStateNode.LockOnTargetID)
                if lockOnTargetId then
                    goto lockOnTargetResolved
                end
                lockOnTargetId = 0
                if lockOnTargetId then
                    goto lockOnTargetResolved
                end
            end
            lockOnTargetId = 0
            ::lockOnTargetResolved::
            local cameraTargetId
            if cameraNode ~= nil then
                cameraTargetId = tonumber(cameraNode.targetId)
                if cameraTargetId then
                    goto cameraTargetResolved
                end
                cameraTargetId = 0
                if cameraTargetId then
                    goto cameraTargetResolved
                end
            end
            cameraTargetId = 0
            ::cameraTargetResolved::
            local isFreeCameraActive = cameraNode ~= nil
            local hasPlayerAimOffset = cameraNode ~= nil and not isFreeCameraActive
            if lockOnTargetId <= 0 and cameraTargetId <= 0 and not isFreeCameraActive and not hasPlayerAimOffset then
                return
            end
            local senderPlayerId = KSResolveBlameKillIncomingOwner(senderNetObject)
            if senderPlayerId == nil then
                return
            end
            local senderPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(senderPlayerId)
            local localPed = PLAYER.PLAYER_PED_ID()
            if senderPed == 0 or localPed == 0 or ENTITY.DOES_ENTITY_EXIST(senderPed) ~= true or ENTITY.DOES_ENTITY_EXIST(localPed) ~= true then
                return
            end
            local localObjectId = tonumber(KSGetOwnObjectID()) or 0
            local localVehicle = 0
            if PED.IS_PED_IN_ANY_VEHICLE(localPed, false) == true then
                localVehicle = PED.GET_VEHICLE_PED_IS_IN(localPed, false)
            end
            local localVehicleObjectId = KSGetBlameKillEntityObjectId(localVehicle)
            local nowMs = getRuntimeNowMs()

            local function markSenderPassthrough(passthroughReason)
                return KSMarkBlameKillRecipientPassthrough(senderPlayerId, nowMs + KS_BLAME_KILL_REMOTE_COMBAT_HOLD_MS, nowMs, passthroughReason)
            end

            local function isPositiveTargetId(candidateTargetId)
                return (tonumber(candidateTargetId) or 0) > 0
            end

            if lockOnTargetId > 0 and isPositiveTargetId(lockOnTargetId) then
                markSenderPassthrough("incoming_homing_lock_passthrough")
            end
            if isFreeCameraActive then
                KSMarkBlameKillRemoteOrbitalFreeCamera(senderPlayerId, nowMs)
                if KSGetBlameKillOrbitalCannonState(senderPlayerId) then
                    markSenderPassthrough("incoming_orbital_cannon_passthrough")
                end
            end
            local hasCameraTarget = cameraNode ~= nil and not isFreeCameraActive and isPositiveTargetId
            if hasCameraTarget and hasPlayerAimOffset then
                markSenderPassthrough("incoming_camera_entity_target_passthrough")
            elseif hasCameraTarget then
                local isTargetingLocal, targetMatchReason = KSBlameKillRemotePlayerTargetsLocal(senderPlayerId, localPed, localVehicle, senderPed, false)
                if isTargetingLocal then
                    markSenderPassthrough("camera_node_" .. tostring(targetMatchReason))
                end
            elseif hasPlayerAimOffset then
                local isFreeAimTargetingLocal, freeAimTargetReason = KSBlameKillRemotePlayerTargetsLocal(senderPlayerId, localPed, localVehicle, senderPed, true)
                if isFreeAimTargetingLocal then
                    markSenderPassthrough("camera_node_" .. tostring(freeAimTargetReason))
                else
                    local aimOffset = cameraNode.playerToTargetAimOffset
                    if aimOffset ~= nil then
                        local senderX, senderY, senderZ = KSBlameKillVectorComponents(ENTITY.GET_ENTITY_COORDS(senderPed, true))
                        local aimOffsetX, aimOffsetY, aimOffsetZ = KSBlameKillVectorComponents(aimOffset)
                        local aimEndX = senderX - aimOffsetX
                        local aimEndY = senderY - aimOffsetY
                        local aimEndZ = senderZ - aimOffsetZ
                        local aimPathRadius, aimNearRadius, isExplosiveAim = KSGetBlameKillRemoteAimRadii(senderPed)
                        if KSBlameKillRemoteAimThreatensEntity(localPed, senderX, senderY, senderZ, aimEndX, aimEndY, aimEndZ, aimPathRadius, aimNearRadius) or KSBlameKillRemoteAimThreatensEntity(localVehicle, senderX, senderY, senderZ, aimEndX, aimEndY, aimEndZ, aimPathRadius, aimNearRadius) then
                            markSenderPassthrough(isExplosiveAim and "incoming_explosive_path_passthrough" or "incoming_camera_path_passthrough")
                        end
                    end
                end
            end
        end

        function KSBlameKillRemoteCameraDataHandler(isCreateSync, syncModelHash, syncPosition, syncNetObject, syncNodes)
            KSBlameKillRemoteCameraDataImpl(syncPosition, syncNetObject, syncNodes)
            return true
        end

        function KSBlameKillPvpSampler()
            local nowMs = getRuntimeNowMs()
            if nowMs - (tonumber(KS_BLAME_KILL_PREARM.lastPvpSampleMs) or 0) < KS_BLAME_KILL_PVP_SAMPLE_MS then
                return
            end
            KS_BLAME_KILL_PREARM.lastPvpSampleMs = nowMs
            local isProtectionEnabled = FeatureMgr.IsFeatureEnabled(H_BLAME_KILL_PROTECTION)
            local isOrbitalPassthroughActive = false
            if isProtectionEnabled and KSIsBlameKillFriendlyFireMethod() then
                isOrbitalPassthroughActive = KSRefreshBlameKillOrbitalPassthrough(nowMs) == true
            end
            if isProtectionEnabled and KSIsBlameKillSessionFullyLoaded(nowMs) then
                KSRefreshBlameKillRecipientPassthrough(nowMs)
                return
            end
            if isProtectionEnabled and isOrbitalPassthroughActive then
                return
            end
            for recipientPlayerId in pairs(KS_BLAME_KILL_PREARM.recipientPassthroughUntilMs) do
                KSClearBlameKillRecipientPassthrough(recipientPlayerId)
            end
            KS_BLAME_KILL_PREARM.trackedProjectiles = {}
            KS_BLAME_KILL_PREARM.projectileDiscovery = {}
            KS_BLAME_KILL_PREARM.fireHazards = {}
        end

        function KSEvaluateBlameKillPrearmPolicy()
            if not FeatureMgr.IsFeatureEnabled(H_BLAME_KILL_PROTECTION) then
                return false, "disabled"
            end
            local nowMs = getRuntimeNowMs()
            if nowMs < (tonumber(KS_BLAME_KILL_PREARM.featureSuspendUntilMs) or 0) then
                return false, "feature_compatibility"
            end
            KS_BLAME_KILL_PREARM.featureSuspendUntilMs = 0
            KS_BLAME_KILL_PREARM.featureSuspendReason = nil
            local isSessionLoaded = KSIsBlameKillSessionFullyLoaded(nowMs)
            local isOrbitalReleaseActive = KSIsBlameKillFriendlyFireMethod() and KSIsBlameKillLocalOrbitalReleaseActive(nowMs)
            if not isSessionLoaded and not isOrbitalReleaseActive then
                return false, "session_loading"
            end
            if NETWORK.NETWORK_IS_ACTIVITY_SESSION() == true then
                return false, "activity_session"
            end
            if NETWORK.NETWORK_IS_IN_TUTORIAL_SESSION() == true then
                return false, "tutorial_session"
            end
            if NETWORK.NETWORK_IS_IN_TRANSITION() == true then
                return false, "transition"
            end
            if NETWORK.NETWORK_GET_NUM_CONNECTED_PLAYERS() <= 1 then
                return false, "no_remote_players"
            end
            if KSIsBlameKillPvpInputActive(nowMs) then
                return false, "pvp_input"
            end
            return true, "freemode_idle"
        end

        function KSRefreshBlameKillPrearmPolicy()
            local isPolicyAllowed, policyReason = KSEvaluateBlameKillPrearmPolicy()
            local wasPolicyAllowed = KS_BLAME_KILL_PREARM.policyAllowed == true
            if wasPolicyAllowed ~= isPolicyAllowed then
                if isPolicyAllowed then
                    KS_BLAME_KILL_PREARM.emissions = {}
                    KS_BLAME_KILL_PREARM.restoreEmissions = {}
                    KS_BLAME_KILL_PREARM.restorePending = false
                elseif wasPolicyAllowed then
                    KS_BLAME_KILL_PREARM.restoreEmissions = {}
                    KS_BLAME_KILL_PREARM.restorePending = true
                end
            end
            KS_BLAME_KILL_PREARM.policyAllowed = isPolicyAllowed
            KS_BLAME_KILL_PREARM.policyReason = policyReason
            KS_BLAME_KILL_PREARM.wasEnabled = FeatureMgr.IsFeatureEnabled(H_BLAME_KILL_PROTECTION) == true
            return isPolicyAllowed, policyReason
        end

        function KSWaitForBlameKillRecipientRelease(recipientPlayerId, waitTimeoutMs)
            local emissionKey = KSBlameKillPrearmEmissionKey(recipientPlayerId, true)
            local deadlineMs = getRuntimeNowMs() + math.max(0, tonumber(waitTimeoutMs) or 0)
            local isStillPassthrough
            repeat
                local emissionRecord = KS_BLAME_KILL_PREARM.recipientPassthroughEmissions[emissionKey]
                local emissionCount = type(emissionRecord) == "table" and tonumber(emissionRecord.count) or 0
                if emissionCount >= KS_BLAME_KILL_FEATURE_RELEASE_MIN_EMISSIONS then
                    return true, emissionCount
                end
                yieldScriptMs(KS_BLAME_KILL_FEATURE_RELEASE_POLL_MS, KS_BLAME_KILL_FEATURE_RELEASE_POLL_MS)
                if deadlineMs <= getRuntimeNowMs() then
                    break
                end
                isStillPassthrough = KSIsBlameKillRecipientPassthrough(recipientPlayerId)
            until not isStillPassthrough
            local finalEmissionRecord = KS_BLAME_KILL_PREARM.recipientPassthroughEmissions[emissionKey]
            return false, type(finalEmissionRecord) == "table" and tonumber(finalEmissionRecord.count) or 0
        end

        function KSPrepareBlameKillSensitiveFeature(rawFeatureKind, requestedDurationMs, rawTargetPlayerId)
            if not FeatureMgr.IsFeatureEnabled(H_BLAME_KILL_PROTECTION) then
                return false
            end
            if type(KSGetBlameKillPrearmMethod) == "function" and KSGetBlameKillPrearmMethod() ~= 0 then
                return false
            end
            local featureKind = tostring(rawFeatureKind or "")
            if featureKind ~= "invflag" and featureKind ~= "lobbycorrupt" then
                return false
            end
            local passthroughDurationMs = math.max(0, math.min(tonumber(requestedDurationMs) or 0, 10000))
            local startMs = getRuntimeNowMs()
            if featureKind == "invflag" then
                local targetPlayerId = tonumber(rawTargetPlayerId)
                if targetPlayerId == nil then
                    return false
                end
                if not KSMarkBlameKillRecipientPassthrough(targetPlayerId, startMs + KS_BLAME_KILL_FEATURE_RELEASE_LEAD_MS + passthroughDurationMs, startMs, "invflag_target_passthrough") then
                    return false
                end
                KSRefreshBlameKillPrearmPolicy()
                local isReleased, releasedEmissionCount = KSWaitForBlameKillRecipientRelease(targetPlayerId, KS_BLAME_KILL_FEATURE_RELEASE_LEAD_MS)
                if not isReleased then
                    KSClearBlameKillRecipientPassthrough(targetPlayerId)
                    return false
                end
                local releasedAtMs = getRuntimeNowMs()
                KSMarkBlameKillRecipientPassthrough(targetPlayerId, releasedAtMs + passthroughDurationMs, releasedAtMs, "invflag_target_passthrough")
                return true
            end
            KS_BLAME_KILL_PREARM.featureSuspendUntilMs = math.max(tonumber(KS_BLAME_KILL_PREARM.featureSuspendUntilMs) or 0, startMs + KS_BLAME_KILL_FEATURE_RELEASE_LEAD_MS + passthroughDurationMs)
            KS_BLAME_KILL_PREARM.featureSuspendReason = featureKind
            KSRefreshBlameKillPrearmPolicy()
            yieldScriptMs(KS_BLAME_KILL_FEATURE_RELEASE_LEAD_MS, KS_BLAME_KILL_FEATURE_RELEASE_LEAD_MS)
            return true
        end

        function KSRememberBlameKillGenuineNodeValue(nodeName, fieldName, genuineValue)
            if genuineValue == nil then
                return
            end
            local nodeFieldKey = tostring(nodeName) .. "." .. tostring(fieldName)
            local genuineNodeValues = KS_BLAME_KILL_PREARM.genuineNodeValues
            if genuineNodeValues[nodeFieldKey] == nil then
                genuineNodeValues[nodeFieldKey] = { value = genuineValue }
            end
        end

        function KSGetBlameKillGenuineNodeValue(nodeName, fieldName, fallbackValue)
            local nodeNameText = tostring(nodeName)
            local fieldNameText = tostring(fieldName)
            local storedEntry = KS_BLAME_KILL_PREARM.genuineNodeValues[nodeNameText .. "." .. fieldNameText]
            if type(storedEntry) == "table" and storedEntry.value ~= nil then
                return storedEntry.value
            end
            return fallbackValue
        end

        function KSApplyBlameKillPrearmMutation(syncNodeType, syncNodeData)
            if syncNodeType ~= eSyncDataNode.CPlayerGameStateDataNode then
                return
            end
            local wasFriendlyFireAllowed = syncNodeData.bIsFriendlyFireAllowed
            KSRememberBlameKillGenuineNodeValue("CPlayerGameStateDataNode", "bIsFriendlyFireAllowed", wasFriendlyFireAllowed)
            syncNodeData.bIsFriendlyFireAllowed = false
            return "Friendly Fire", "CPlayerGameStateDataNode", "bIsFriendlyFireAllowed", wasFriendlyFireAllowed, false
        end

        function KSApplyBlameKillGenuineNode(syncNodeType, syncNodeData, shouldForceFriendlyFire)
            if syncNodeType ~= eSyncDataNode.CPlayerGameStateDataNode then
                return
            end
            local wasFriendlyFireAllowed = syncNodeData.bIsFriendlyFireAllowed
            local shouldAllowFriendlyFire
            if shouldForceFriendlyFire == true then
                shouldAllowFriendlyFire = true
            else
                shouldAllowFriendlyFire = KSGetBlameKillGenuineNodeValue("CPlayerGameStateDataNode", "bIsFriendlyFireAllowed", wasFriendlyFireAllowed)
                if shouldAllowFriendlyFire == nil then
                    shouldAllowFriendlyFire = wasFriendlyFireAllowed
                end
            end
            syncNodeData.bIsFriendlyFireAllowed = shouldAllowFriendlyFire
            return "Friendly Fire", "CPlayerGameStateDataNode", "bIsFriendlyFireAllowed", wasFriendlyFireAllowed, shouldAllowFriendlyFire
        end

        function KSIsBlameKillPrearmRestoreNode(syncNodeType)
            return syncNodeType == eSyncDataNode.CPlayerGameStateDataNode
        end

        function KSShouldTriggerBlameKillPrearmExclusiveSync(targetPlayerId, syncEntityInfo)
            if syncEntityInfo == nil or syncEntityInfo.NetObject == nil then
                return false
            end
            local ownObjectId = tonumber(KSGetOwnObjectID())
            local syncObjectId = tonumber(syncEntityInfo.NetObject.ObjectID)
            local recipientPlayerId = tonumber(targetPlayerId)
            if ownObjectId == nil or ownObjectId == 0 or syncObjectId ~= ownObjectId or recipientPlayerId == nil or recipientPlayerId == GTA.GetLocalPlayerId() then
                return false
            end
            local isPolicyAllowed = KSRefreshBlameKillPrearmPolicy()
            if isPolicyAllowed then
                return true
            end
            local activeEmissions
            if isPolicyAllowed then
                activeEmissions = KS_BLAME_KILL_PREARM.emissions
                if activeEmissions then
                    goto checkActiveEmissions
                end
            end
            if KS_BLAME_KILL_PREARM.restorePending then
                activeEmissions = KS_BLAME_KILL_PREARM.restoreEmissions
                if activeEmissions then
                    goto checkActiveEmissions
                end
            end
            activeEmissions = nil
            ::checkActiveEmissions::
            if activeEmissions == nil then
                return false
            end
            local emissionKey = KSBlameKillPrearmEmissionKey(recipientPlayerId, true)
            return type(activeEmissions[emissionKey]) ~= "table"
        end

        function KSApplyBlameKillPrearmNode(syncNodeType, syncNodeData, syncEntityInfo, isExclusiveSync, targetPlayerId)
            if not isExclusiveSync then
                return
            end
            if not KSIsBlameKillPrearmRestoreNode(syncNodeType) then
                return
            end
            if syncNodeData == nil or syncEntityInfo == nil then
                return
            end
            local netObject = syncEntityInfo.NetObject
            local ownObjectId = tonumber(KSGetOwnObjectID())
            local nodeObjectId = netObject and tonumber(netObject.ObjectID) or nil
            if ownObjectId == nil or ownObjectId == 0 or nodeObjectId ~= ownObjectId then
                return
            end
            local isPolicyAllowed, policyReason = KSRefreshBlameKillPrearmPolicy()
            local emissionKey = KSBlameKillPrearmEmissionKey(targetPlayerId, isExclusiveSync)
            if isPolicyAllowed and KSIsBlameKillFriendlyFireMethod() and isExclusiveSync ~= true then
                return
            end
            if isPolicyAllowed and isExclusiveSync == true and KSIsBlameKillRecipientPassthrough then
                local restoredLabel, restoredNodeName, restoredFieldName, restoredPreviousValue, restoredNewValue = KSApplyBlameKillGenuineNode(syncNodeType, syncNodeData, true)
                if restoredLabel == nil then
                    return
                end
                syncNodeData.Updated = true
                local recipientEmissionCount = KSBlameKillPrearmEmissionCount(KS_BLAME_KILL_PREARM.recipientPassthroughEmissions, emissionKey)
                return
            end
            if isPolicyAllowed then
                local mutatedLabel, mutatedNodeName, mutatedFieldName, mutatedPreviousValue, mutatedNewValue = KSApplyBlameKillPrearmMutation(syncNodeType, syncNodeData)
                if mutatedLabel == nil then
                    return
                end
                syncNodeData.Updated = true
                local prearmEmissionCount = KSBlameKillPrearmEmissionCount(KS_BLAME_KILL_PREARM.emissions, emissionKey)
                return
            end
            if not KS_BLAME_KILL_PREARM.restorePending or not KSIsBlameKillPrearmRestoreNode(syncNodeType) then
                return
            end
            if KSApplyBlameKillGenuineNode(syncNodeType, syncNodeData) == nil then
                return
            end
            syncNodeData.Updated = true
            local restoreEmissionCount = KSBlameKillPrearmEmissionCount(KS_BLAME_KILL_PREARM.restoreEmissions, emissionKey)
        end

        local blameKillProtectionFeature = FeatAdd(H_BLAME_KILL_PROTECTION, "Blame Kill Protection", eFeatureType.Toggle, "", function(toggledFeature)
