                end
                if netEventId == 6 then
                    local isBlameKill, blameKillReason, damageEventData, damageGuardVerdict = KSReadWeaponDamageForBlameKill(eventBuffer, senderPlayer)
                    if isBlameKill and FeatureMgr.IsFeatureEnabled(H_BLAME_KILL_PROTECTION) then
