                        if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                            notify(("Blocked Blame Kill by %s"):format(senderPlayer:GetName()))
                        end
                        return true
                    end
                    if type(damageGuardVerdict) == "table" and damageGuardVerdict.block == true then
