        function KSRemoteControlNowMs()
            if (type(Time) == "table" or type(Time) == "userdata") and type(Time.GetEpocheMs) == "function" then
                local parseNumber = tonumber
                local rawEpochMs = Time.GetEpocheMs()
                local epochMs = parseNumber(rawEpochMs)
                if epochMs ~= nil then
                    return epochMs
                end
            end
            if type(os) == "table" and type(os.time) == "function" then
                return os.time() * 1000
            end
            return nil
        end

        function KSGetVerifiedRemoteControlRole(remotePlayerId, claimedRockstarId)
            remotePlayerId = tonumber(remotePlayerId)
            if remotePlayerId == nil or remotePlayerId == GTA.GetLocalPlayerId() then
                return nil
            end
            local remoteStatusState = featurePlaneContext.KS_REMOTE_PLAYER_STATUS_STATE
            if type(remoteStatusState) ~= "table" or type(remoteStatusState.byPlayer) ~= "table" then
                return nil
            end
            local playerStatus = remoteStatusState.byPlayer[remotePlayerId]
            local nowMs = KSRemoteControlNowMs()
            if type(playerStatus) ~= "table" or playerStatus.is_kscript_user ~= true or nowMs == nil or nowMs >= tonumber(playerStatus.expires_at_ms or 0) then
                return nil
            end
            local normalizedRole = tostring(playerStatus.kscript_role or ""):lower()
            if normalizedRole == "administrator" then
                normalizedRole = "admin"
            end
            if normalizedRole ~= "developer" and normalizedRole ~= "admin" then
                return nil
            end
            local canonicalRockstarId = toCanonicalPlayerIdentifier(claimedRockstarId)
            if canonicalRockstarId == nil or playerStatus.canonical_player_id ~= canonicalRockstarId then
                return nil
            end
            return normalizedRole
        end

        function KSApplyRemoteTeleport(adminPlayerId, adminName)
            local adminPed = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(tonumber(adminPlayerId) or -1)
            local localPed = PLAYER.PLAYER_PED_ID()
            if adminPed == nil or adminPed == 0 or localPed == nil or localPed == 0 or ENTITY.DOES_ENTITY_EXIST(adminPed) ~= true or ENTITY.DOES_ENTITY_EXIST(localPed) ~= true then
                notify("Remote teleport failed: player entity unavailable")
                return false
            end
            local adminCoords = V3.New(ENTITY.GET_ENTITY_COORDS(adminPed, false))
            if adminCoords == nil or tonumber(adminCoords.x) == nil or tonumber(adminCoords.y) == nil or tonumber(adminCoords.z) == nil then
                notify("Remote teleport failed: player position unavailable")
                return false
            end
            local entityToTeleport = localPed
            if PED.IS_PED_IN_ANY_VEHICLE(localPed, false) then
                local localVehicle = PED.GET_VEHICLE_PED_IS_IN(localPed, false)
                if localVehicle ~= nil and localVehicle ~= 0 and ENTITY.DOES_ENTITY_EXIST(localVehicle) == true then
                    entityToTeleport = localVehicle
                end
            end
            ENTITY.SET_ENTITY_COORDS(entityToTeleport, adminCoords.x, adminCoords.y, adminCoords.z + 1.0, false, false, false)
            notify(("Remote admin %s teleported you to them"):format(tostring(adminName or "Unknown")))
            return true
        end

        featurePlaneInstall.runtimeControlSeen = { byId = {}, order = {} }

        function KSRuntimeControlFindPlayer(rockstarIdToFind)
            local canonicalRockstarId = toCanonicalPlayerIdentifier(rockstarIdToFind)
            if canonicalRockstarId == nil then
                return nil
            end
            for slotPlayerId = 0, 31 do
                if slotPlayerId ~= GTA.GetLocalPlayerId() and NETWORK.NETWORK_IS_PLAYER_ACTIVE(slotPlayerId) == true then
                    local candidatePlayer = Players.GetById(slotPlayerId)
                    local gamerInfo = candidatePlayer ~= nil and candidatePlayer:GetGamerInfo() or nil
                    if gamerInfo ~= nil and toCanonicalPlayerIdentifier(gamerInfo.RockstarId) == canonicalRockstarId then
                        return slotPlayerId, candidatePlayer, canonicalRockstarId
                    end
                end
            end
            return nil
        end

        function KSRuntimeControlVerifiedStatus(statusPlayerId, claimedRockstarId)
            local remoteStatusState = featurePlaneContext.KS_REMOTE_PLAYER_STATUS_STATE
            local playerStatus = type(remoteStatusState) == "table" and type(remoteStatusState.byPlayer) == "table" and remoteStatusState.byPlayer[statusPlayerId] or nil
            local nowMs = KSRemoteControlNowMs()
            local canonicalRockstarId = toCanonicalPlayerIdentifier(claimedRockstarId)
            if type(playerStatus) ~= "table" or playerStatus.is_kscript_user ~= true or nowMs == nil or nowMs >= tonumber(playerStatus.expires_at_ms or 0) or canonicalRockstarId == nil or playerStatus.canonical_player_id ~= canonicalRockstarId then
                return nil
            end
            return playerStatus
        end

        function KSRuntimeControlRemember(commandId, commandResult)
            local seenCommands = featurePlaneInstall.runtimeControlSeen
            seenCommands.byId[commandId] = commandResult
            seenCommands.order[#seenCommands.order + 1] = commandId
            if #seenCommands.order > 64 then
                local evictedCommandId = table.remove(seenCommands.order, 1)
                seenCommands.byId[evictedCommandId] = nil
            end
            return commandResult
        end

        function KSDispatchRuntimeControlAction(actionName, recipientPlayerId, targetPlayerId)
            actionName = tostring(actionName or "")
            if actionName ~= "host_kick" and actionName ~= "remote_unload" and actionName ~= "remote_teleport" and actionName ~= "remote_crash" then
                return false
            end
            if actionName == "host_kick" then
                local hostInfo = KS_ResolveHostInfo()
                if type(hostInfo) ~= "table" or type(hostInfo.network_host) ~= "table" or not hostInfo.network_host.player_id then
                    recipientPlayerId = nil
                end
            end
            recipientPlayerId = tonumber(recipientPlayerId)
            local recipientPlayer = recipientPlayerId ~= nil and Players.GetById(recipientPlayerId) or nil
            local recipientGamerInfo = recipientPlayer ~= nil and recipientPlayer:GetGamerInfo() or nil
            local recipientRockstarId = recipientGamerInfo ~= nil and toCanonicalPlayerIdentifier(recipientGamerInfo.RockstarId) or nil
            if recipientPlayerId == GTA.GetLocalPlayerId() or recipientRockstarId == nil or KSRuntimeControlVerifiedStatus(recipientPlayerId, recipientRockstarId) == nil then
                notify("Authenticated runtime command failed: recipient unavailable")
                return false
            end
            local requestPayload = { action = actionName, recipient_rockstar_id = recipientRockstarId }
            if actionName == "host_kick" then
                targetPlayerId = tonumber(targetPlayerId)
                local targetPlayer = targetPlayerId ~= nil and Players.GetById(targetPlayerId) or nil
                local targetGamerInfo = targetPlayer ~= nil and targetPlayer:GetGamerInfo() or nil
                local targetRockstarId = targetGamerInfo ~= nil and toCanonicalPlayerIdentifier(targetGamerInfo.RockstarId) or nil
                if targetRockstarId == nil or targetPlayerId == recipientPlayerId or targetPlayerId == GTA.GetLocalPlayerId() then
                    notify("Authenticated host kick failed: target unavailable")
                    return false
                end
                requestPayload.target_rockstar_id = targetRockstarId
            end
            local runtimeBridge = __ks_bridge_v3
            if type(runtimeBridge) ~= "table" or runtimeBridge.version ~= 3 or type(runtimeBridge.request) ~= "function" then
                return false
            end
            local requestStatus, requestResponse = runtimeBridge.request("runtime.control.create", requestPayload, 10000)
            local isAccepted = requestStatus == "ok"
            if not isAccepted then
                notify("Authenticated runtime command was rejected")
            end
            return isAccepted
        end

        function KSHandleRuntimeControlCommand(controlCommand)
            if type(controlCommand) ~= "table" or not isFeaturePlaneInstallCurrent() or tonumber(controlCommand.load_generation) ~= runtimeLoadGeneration or type(controlCommand.command_id) ~= "string" or #controlCommand.command_id ~= 32 or not controlCommand.command_id:match("^[0-9a-f]+$") then
                return "rejected_session"
            end
            local cachedResult = featurePlaneInstall.runtimeControlSeen.byId[controlCommand.command_id]
            if cachedResult ~= nil then
                return cachedResult
            end
            local nowMs = KSRemoteControlNowMs()
            if nowMs == nil or nowMs >= tonumber(controlCommand.expires_at_ms or 0) then
                return KSRuntimeControlRemember(controlCommand.command_id, "rejected_stale")
            end
            local senderPlayerId, senderPlayer, senderRockstarId = KSRuntimeControlFindPlayer(controlCommand.sender_rockstar_id)
            local senderStatus = senderPlayerId ~= nil and KSRuntimeControlVerifiedStatus(senderPlayerId, senderRockstarId) or nil
            if senderPlayer == nil or senderStatus == nil then
                return KSRuntimeControlRemember(controlCommand.command_id, "rejected_session")
            end
            local senderRole = tostring(senderStatus.kscript_role or ""):lower()
            if senderRole == "administrator" then
                senderRole = "admin"
            end
            if controlCommand.action == "host_kick" then
                if NETWORK.NETWORK_IS_HOST() ~= true then
                    return KSRuntimeControlRemember(controlCommand.command_id, "rejected_host")
                end
                local targetPlayerId = KSRuntimeControlFindPlayer(controlCommand.target_rockstar_id)
                if targetPlayerId == nil or targetPlayerId == senderPlayerId or targetPlayerId == GTA.GetLocalPlayerId() then
                    return KSRuntimeControlRemember(controlCommand.command_id, "rejected_target")
                end
                if KSRuntimeControlVerifiedStatus(targetPlayerId, controlCommand.target_rockstar_id) ~= nil and senderRole ~= "developer" and senderRole ~= "admin" then
                    return KSRuntimeControlRemember(controlCommand.command_id, "rejected_target")
                end
                NETWORK.NETWORK_SESSION_KICK_PLAYER(targetPlayerId)
                return KSRuntimeControlRemember(controlCommand.command_id, "executed")
            elseif controlCommand.action == "remote_teleport" then
                if senderRole ~= "developer" and senderRole ~= "admin" then
                    return KSRuntimeControlRemember(controlCommand.command_id, "rejected_invalid")
                end
                return KSRuntimeControlRemember(controlCommand.command_id, KSApplyRemoteTeleport(senderPlayerId, controlCommand.sender_name) and "executed" or "execution_failed")
            elseif controlCommand.action ~= "remote_unload" then
                if controlCommand.action ~= "remote_crash" then
                    return KSRuntimeControlRemember(controlCommand.command_id, "rejected_invalid")
                end
            end
            if controlCommand.action == "remote_crash" and senderRole ~= "developer" or controlCommand.action == "remote_unload" and senderRole ~= "developer" and senderRole ~= "admin" then
                return KSRuntimeControlRemember(controlCommand.command_id, "rejected_invalid")
            end
            return KSRuntimeControlRemember(controlCommand.command_id, "executed")
        end

        featurePlaneContext.KSDispatchRuntimeControlAction = KSDispatchRuntimeControlAction
        featurePlaneContext.KSRuntimeControlHandler = KSHandleRuntimeControlCommand

        function scriptedGameEvent(eventSender, eventArgs)
            if ShouldUnload() then
                return false
            end
            if not eventSender then
                return false
            end
            local senderName = eventSender:GetName() or ""
            local senderRockstarId = (eventSender:GetGamerInfo() or {}).RockstarId or 0
            local senderPlayerId = eventSender.PlayerId
            if #eventArgs == 4 and eventArgs[1] == SCRIPT_EVENT.PERSONAL_VEHICLE_SET and tonumber(eventArgs[3]) == tonumber(senderPlayerId) then
                closeSpawnRememberPersonalVehicleEvent(senderPlayerId, eventArgs[4])
            end

            local function isProtectionEnabled(protectionFeatureName)
                return FeatureMgr.IsFeatureEnabled(Utils.Joaat("scriptEventProtections")) and FeatureMgr.IsFeatureEnabled(Utils.Joaat(protectionFeatureName))
            end

            local function notifyProtectionBlocked(protectionMessage)
                if FeatureMgr.IsFeatureEnabled(Utils.Joaat("notifyProtections")) then
                    notify(protectionMessage)
                end
            end

            if isProtectionEnabled("blockSHCrash") and #eventArgs == 9 and eventArgs[1] == lexisEvent[1] and eventArgs[4] == lexisEvent[4] and eventArgs[5] == lexisEvent[5] and eventArgs[6] == lexisEvent[6] and eventArgs[7] == lexisEvent[7] and eventArgs[8] == lexisEvent[8] and eventArgs[9] == lexisEvent[9] then
                notifyProtectionBlocked(("Blocked SH Crash from %s"):format(senderName))
                return true
            end
            if #eventArgs == 11 then
                if isProtectionEnabled("blockInfiniteLoading") and eventArgs[1] == aptEvent[1] and eventArgs[4] == aptEvent[4] and eventArgs[5] == aptEvent[5] and eventArgs[6] == aptEvent[6] and eventArgs[7] == aptEvent[7] and eventArgs[8] == aptEvent[8] and eventArgs[9] == aptEvent[9] and eventArgs[10] == aptEvent[10] and eventArgs[11] == aptEvent[11] then
                    notifyProtectionBlocked(("Blocked Infinite Loading from %s"):format(senderName))
                    return true
                end
                if isProtectionEnabled("blockApartmentInvite") and eventArgs[1] == SCRIPT_EVENT.SCRIPT_EVENT_INVITE_NEARBY_PLAYERS_INTO_APARTMENT then
                    notifyProtectionBlocked(("Blocked Apartment Invite from %s"):format(senderName))
                    return true
                end
            end
            if isProtectionEnabled("blockRemoveWanted") and eventArgs[1] == SCRIPT_EVENT.SCRIPT_EVENT_FM_EVENT_GIVE_WANTED_LEVEL then
                notifyProtectionBlocked(("Blocked Remove Wanted from %s"):format(senderName))
                return true
            end
            if isProtectionEnabled("blockGiveWanted") and eventArgs[1] == SCRIPT_EVENT.SCRIPT_EVENT_FREEMODE_CONTENT_GIVE_WANTED_LEVEL then
                notifyProtectionBlocked(("Blocked Give Wanted from %s"):format(senderName))
                return true
            end
            if isProtectionEnabled("blockSoundSpam1k") and eventArgs[1] == SCRIPT_EVENT.INVITE_TO_HEIST_ISLAND_BEACH_PARTY then
                notifyProtectionBlocked(("Blocked Sound Spam from %s"):format(senderName))
                return true
            end
            if isProtectionEnabled("blockTickerMessage") and eventArgs[1] == SCRIPT_EVENT.SCRIPT_EVENT_TICKER_MESSAGE then
                notifyProtectionBlocked(("Blocked Ticker Message from %s"):format(senderName))
                return true
            end
            if isProtectionEnabled("blockInsuranceScam") and eventArgs[1] == SCRIPT_EVENT.SCRIPT_EVENT_CAR_INSURANCE and eventArgs[3] == 64 and eventArgs[4] == 369209303 then
                notifyProtectionBlocked(("Blocked Insurance Scam from %s"):format(senderName))
                return true
            end
            if isProtectionEnabled("blockPhoneInviteSpam") and eventArgs[1] == jinxphonespam[1] and eventArgs[3] == jinxphonespam[3] and eventArgs[4] == jinxphonespam[4] then
                notifyProtectionBlocked(("Blocked Phone Invite Spam from %s"):format(senderName))
                return true
            end
            local eventHash = eventArgs[1]
            local missionInviteEventHash = SCRIPT_EVENT.SCRIPT_EVENT_INVITE_PLAYER_ONTO_MISSION
            if isProtectionEnabled("blockMissionInvite") and eventHash == missionInviteEventHash and senderName ~= "CMsgJoinRequest" then
                local missionId = eventArgs[4]
                local missionName = activities[missionId]
                if not missionName then
                    missionName = tostring(missionId)
                    logLegacyFeatureAction("eventhook", ("%s tried to send %s(%i) into %s"):format(senderName, Players.GetName(GTA.GetLocalPlayerId()), Cherax.GetUID(), missionName))
                end
                notifyProtectionBlocked(("Blocked Mission Invite (%s) from %s"):format(missionName, senderName))
                return true
            end
            if isProtectionEnabled("blockMissionConfirm") and eventArgs[1] == SCRIPT_EVENT.SCRIPT_EVENT_CONFIRMATION_LAUNCH_MISSION and senderName ~= "CMsgJoinRequest" then
                return true
            end
            return false
        end

        function ClampWindowToScreen()
            local displayWidth, displayHeight = ImGui.GetDisplaySize()
            local windowPosX, windowPosY = ImGui.GetWindowPos()
            local currentWindowWidth, currentWindowHeight = ImGui.GetWindowSize()
            local clampedPosX = math.max(0, math.min(displayWidth - currentWindowWidth, windowPosX))
            local clampedPosY = math.max(0, math.min(displayHeight - currentWindowHeight, windowPosY))
            if clampedPosX ~= windowPosX or clampedPosY ~= windowPosY then
                ImGui.SetWindowPos(clampedPosX, clampedPosY)
            end
        end

        function drawModders(isForcedVisible)
            if type(detectedPlayerNames) ~= "table" then
                detectedPlayerNames = {}
            end
            if type(detectedPlayerReasons) ~= "table" then
                detectedPlayerReasons = {}
            end
            local hasAuthoritativeUserDetection = KS_HasAuthoritativeKScriptUserDetection()
            isForcedVisible = isForcedVisible == true or isForcedVisible
            local isGuiToggleEnabled = FeatureMgr.GetFeatureByName("Toggle GUI"):GetBoolValue()
            local displayWidth, displayHeight = ImGui.GetDisplaySize()
            local linePadding = 10
            local lineHeight = 10
            local listContentHeight = 0
            local detectedModderCount = 0
            local visibleModderCount = 0
            for countedPlayerSlot, countedPlayerName in pairs(detectedPlayerNames) do
                local countedDetectionReason = detectedPlayerReasons[countedPlayerSlot]
                if countedPlayerName ~= nil and countedDetectionReason ~= nil then
                    detectedModderCount = detectedModderCount + 1
                    if KS_ShouldShowDetectedModder(countedPlayerSlot, countedDetectionReason) then
                        visibleModderCount = visibleModderCount + 1
                        listContentHeight = listContentHeight + lineHeight + linePadding
                    end
                end
            end
            local modderWindowSize = { width = 300, height = math.max(listContentHeight + 6 * linePadding, 32) }
            if not windowPositionSet then
                local savedWindowPosition = storedDisplayPositions.ModderDisplay
                local preferredPosY = savedWindowPosition and savedWindowPosition.y or displayHeight - 50 - modderWindowSize.height
                local initialPosX = math.max(0, math.min(displayWidth - modderWindowSize.width, savedWindowPosition and savedWindowPosition.x or (displayWidth - modderWindowSize.width) / 2 - 400))
                local initialPosY = math.max(0, math.min(displayHeight - modderWindowSize.height, preferredPosY))
                ImGui.SetNextWindowPos(initialPosX, initialPosY, ImGuiCond.Always)
                ImGui.SetNextWindowSize(modderWindowSize.width, modderWindowSize.height, ImGuiCond.Always)
                windowPositionSet = true
            end
            local windowFlags = ImGuiWindowFlags.AlwaysAutoResize | ImGuiWindowFlags.NoCollapse | ImGuiWindowFlags.NoScrollbar
            if not isGuiToggleEnabled then
                windowFlags = windowFlags | ImGuiWindowFlags.NoMove
            end
            if modderDisplay or isForcedVisible then
                ImGui.Begin("K-Script - Detected Modders", true, windowFlags)
                local currentPosX, currentPosY = ImGui.GetWindowPos()
                local currentWindowPosition = V2.New(currentPosX, currentPosY)
                storedDisplayPositions.ModderDisplay = currentWindowPosition
                if detectedModderCount == 0 then
                    ImGui.TextColored(255, 255, 255, 255, "There are no Modders detected yet.")
                elseif visibleModderCount == 0 then
                    ImGui.TextColored(255, 255, 255, 255, "All detected modders are hidden by display filters.")
                else
                    for listedPlayerSlot, listedPlayerName in pairs(detectedPlayerNames) do
                        local displayedReason = detectedPlayerReasons[listedPlayerSlot]
                        local shouldListModder = displayedReason ~= nil and KS_ShouldShowDetectedModder
                        if shouldListModder and string.find(displayedReason, "Model Swap From") then
                            displayedReason = "Model Swap"
                        end
                        if listedPlayerName ~= nil and shouldListModder then
                            ImGui.TextColored(255, 255, 255, 255, ("%s (%s)"):format(listedPlayerName, displayedReason))
                        end
                    end
                    ImGui.TextColored(255, 255, 255, 255, ("Total Modders Displayed: %i"):format(visibleModderCount))
                end
                ClampWindowToScreen()
                ImGui.End()
            end
        end

