    function rebuildInfoTextCache()
        local nowSeconds = os.clock()
        if nowSeconds - infoTextCache.lastUpdate < infoTextCache.interval then
            return
        end
        infoTextCache.lastUpdate = nowSeconds
        local infoLines = {}
        local maxObjectCount = PoolMgr.GetMaxObjectCount()
        if infoFeatureCache.showGeneral then
            local localDateParts = os.date("*t")
            infoLines[#infoLines + 1] = INFO_DISPLAY_WEEKDAY_NAMES[localDateParts.wday] .. " " .. INFO_DISPLAY_MONTH_NAMES[localDateParts.month] .. " " .. localDateParts.day .. " " .. string.format("%02d:%02d:%02d", localDateParts.hour, localDateParts.min, localDateParts.sec) .. " " .. localDateParts.year
            infoLines[#infoLines + 1] = "FPS: " .. string.format("%.0f", ImGui.GetFrameRate())
            infoLines[#infoLines + 1] = "Matchmaking Region: " .. tostring(currentMatchmakingRegionName)
            infoLines[#infoLines + 1] = "Nat Type: " .. tostring(currentNatTypeName)
            infoLines[#infoLines + 1] = "Host Queue Factor: " .. tostring(currentHostQueueFactorName)
            infoLines[#infoLines + 1] = ""
        end
        if infoFeatureCache.showPools and maxObjectCount ~= 0 then
            infoLines[#infoLines + 1] = "Camera Pool: " .. PoolMgr.GetCurrentCameraCount() .. " / " .. PoolMgr.GetMaxCameraCount()
            infoLines[#infoLines + 1] = "Object Pool: " .. PoolMgr.GetCurrentObjectCount() .. " / " .. maxObjectCount
            infoLines[#infoLines + 1] = "Ped Pool: " .. PoolMgr.GetCurrentPedCount() .. " / " .. PoolMgr.GetMaxPedCount()
            infoLines[#infoLines + 1] = "Pickup Pool: " .. PoolMgr.GetCurrentPickupCount() .. " / " .. PoolMgr.GetMaxPickupCount()
            infoLines[#infoLines + 1] = "Vehicle Pool: " .. PoolMgr.GetCurrentVehicleCount() .. " / " .. PoolMgr.GetMaxVehicleCount()
            infoLines[#infoLines + 1] = ""
            infoLines[#infoLines + 1] = "Rendered Objects: " .. #PoolMgr.GetRenderedObjects()
            infoLines[#infoLines + 1] = "Rendered Peds: " .. #PoolMgr.GetRenderedPeds()
            infoLines[#infoLines + 1] = "Rendered Vehicles: " .. #PoolMgr.GetRenderedVehicles()
            infoLines[#infoLines + 1] = ""
        end
        if infoFeatureCache.showHosts then
            local hostInfo = type(featurePlaneContext.__ksHostInfo) == "table" and featurePlaneContext.__ksHostInfo or KS_ResetHostInfo("not-resolved")
            infoLines[#infoLines + 1] = "Session Host: " .. tostring(hostInfo.network_host.name or "Unavailable")
            infoLines[#infoLines + 1] = "Script Host: " .. tostring(hostInfo.script_host.name or "Unavailable")
            infoLines[#infoLines + 1] = "Connected Players: " .. tostring(hostInfo.connected_players or 0) .. " / 32"
            infoLines[#infoLines + 1] = ""
        end
        if infoFeatureCache.showVoiceChat then
            infoLines[#infoLines + 1] = "VoiceChat Players:"
            local voiceChatterNames = KS_GetLiveVoiceChatters()
            if #voiceChatterNames == 0 then
                infoLines[#infoLines + 1] = "No Voice Chatters in this Session."
            else
                for _, voiceChatterName in ipairs(voiceChatterNames) do
                    infoLines[#infoLines + 1] = voiceChatterName
                end
            end
        end
        if infoFeatureCache.showTransition and maintransitionActive and maxObjectCount ~= 0 then
            infoLines[#infoLines + 1] = ""
            local transitionState = getTransitionState()
            local transitionStateName = "N/A"
            if transitionState ~= nil and transitionState ~= 0 then
                transitionStateName = getTransitionStateName(transitionState)
            end
            local nowEpochSeconds = os.time()
            if timerStart == nil or lastState ~= transitionStateName then
                timerStart = nowEpochSeconds
                lastState = transitionStateName
            end
            local elapsedStateSeconds = nowEpochSeconds - timerStart
            local elapsedTimerText = string.format("(%02d:%02d)", math.floor(elapsedStateSeconds / 60), elapsedStateSeconds % 60)
            infoLines[#infoLines + 1] = "Transition Monitor:"
            infoLines[#infoLines + 1] = transitionStateName .. " " .. elapsedTimerText
        end
        infoTextCache.lines = infoLines
    end

    function KS_GameMonitorSnapshotTick()
        updateInfoFeatureCache()
        if FeatureMgr.IsFeatureEnabled(H_TOGGLE_GAME_INFO_DISPLAY) then
            KS_GameMonitorRefreshNetworkValues(false)
            if maintransitionActive and infoFeatureCache.showTransition then
                local isLoadingScreenActive = DLC.GET_IS_LOADING_SCREEN_ACTIVE()
                local isInitialLoadingScreenActive = DLC.GET_IS_INITIAL_LOADING_SCREEN_ACTIVE()
                if PoolMgr.GetMaxObjectCount() ~= 0 then
                    if not isLoadingScreenActive or isInitialLoadingScreenActive then
                        goto rebuildInfoText
                    end
                    if initRun then
                        goto rebuildInfoText
                    end
                end
                maintransitionActive = false
            end
            ::rebuildInfoText::
            rebuildInfoTextCache()
        end
        Script.Yield(250)
    end

