    function KSBlameKillEdition()
        local stringify = tostring
        local runtimeEdition = featurePlaneContext.KS_RUNTIME_EDITION
        if not runtimeEdition then
            if isGameVersionEnhanced then
                runtimeEdition = "enhanced"
                if runtimeEdition then
                    goto normalizeEdition
                end
            end
            runtimeEdition = "legacy"
        end
        ::normalizeEdition::
        return stringify(runtimeEdition):lower() == "enhanced" and "enhanced" or "legacy"
    end

    function KSBlameKillPlayerName(targetPlayerId)
        local playerName = Players.GetName(targetPlayerId)
        if type(playerName) == "string" and playerName ~= "" then
            return playerName
        end
        return "Player " .. tostring(targetPlayerId)
    end

    function KSBlameKillRestorePatch(patchKey)
        local blameKillState = featurePlaneInstall.sessionBlameKill
        local patchEntries = blameKillState.patches[patchKey]
        if blameKillState.owned[patchKey] ~= true or type(patchEntries) ~= "table" then
            return
        end
        for _, patchEntry in ipairs(patchEntries) do
            if Memory.ReadByte(patchEntry.address) & 255 == patchEntry.patched then
                Memory.WriteByte(patchEntry.address, patchEntry.original)
            end
        end
        blameKillState.owned[patchKey] = false
        if patchKey == "scope" then
            blameKillState.scopeUntilMs = 0
        end
    end

    function KSBlameKillRestoreAllPatches()
        KSBlameKillRestorePatch("damageType")
        KSBlameKillRestorePatch("scope")
    end

    function KSBlameKillResolveTrigger()
        local triggerAddress = tonumber(featurePlaneInstall.sessionBlameKill.trigger)
        if triggerAddress == nil or triggerAddress <= 0 or triggerAddress >= 140737488355328 then
            return nil, "damage-event function was not resolved by startup configuration"
        end
        return triggerAddress
    end

    function KSBlameKillResolvePatch(patchKey)
        local blameKillState = featurePlaneInstall.sessionBlameKill
        if type(blameKillState.patches[patchKey]) == "table" then
            return blameKillState.patches[patchKey]
        end
        local editionSpec = blameKillState.patchSpecs[patchKey][KSBlameKillEdition()]
        local patchBaseAddress = tonumber(blameKillState.patchAddresses[patchKey])
        if patchBaseAddress == nil or patchBaseAddress <= 0 then
            return nil, patchKey .. " address was not resolved by startup configuration"
        end
        local resolvedEntries = {}
        for editIndex, editSpec in ipairs(editionSpec.edits) do
            local patchEntry = { address = patchBaseAddress + editSpec[1], original = editSpec[2], patched = editSpec[3] }
            if Memory.ReadByte(patchEntry.address) & 255 ~= patchEntry.original then
                return nil, patchKey .. " signature bytes changed during resolution"
            end
            resolvedEntries[editIndex] = patchEntry
        end
        blameKillState.patches[patchKey] = resolvedEntries
        return resolvedEntries
    end

    function KSBlameKillApplyPatch(patchKey)
        local blameKillState = featurePlaneInstall.sessionBlameKill
        local patchEntries, resolveError = KSBlameKillResolvePatch(patchKey)
        if patchEntries == nil then
            return false, resolveError
        end
        local expectedByteField = blameKillState.owned[patchKey] == true and "patched" or "original"
        for _, checkedEntry in ipairs(patchEntries) do
            if Memory.ReadByte(checkedEntry.address) & 255 ~= checkedEntry[expectedByteField] then
                KSBlameKillRestorePatch(patchKey)
                return false, patchKey .. " bytes changed before use"
            end
        end
        if expectedByteField == "patched" then
            return true
        end
        blameKillState.owned[patchKey] = true
        for _, patchEntry in ipairs(patchEntries) do
            Memory.WriteByte(patchEntry.address, patchEntry.patched)
        end
        return true
    end

    KS_SESSION_BLAME_KILL_CALL_GUARD = {
        __close = function(callGuard, closeError)
            KSBlameKillRestorePatch("damageType")
            if closeError ~= nil or callGuard.keepScope ~= true then
                KSBlameKillRestorePatch("scope")
            end
        end,
    }
    KS_SESSION_BLAME_KILL_RUNNER_GUARD = {
        __close = function()
            local blameKillState = featurePlaneInstall.sessionBlameKill
            KSBlameKillRestoreAllPatches()
            blameKillState.queue = {}
            blameKillState.running = false
        end,
    }

    function KSBlameKillTargetAllowed(victimId, blamerId)
        local victimPlayerId = tonumber(victimId)
        if victimPlayerId == nil or victimPlayerId < 0 or victimPlayerId >= 32 or victimPlayerId == GTA.GetLocalPlayerId() or victimPlayerId == tonumber(blamerId) or not isNetPlayerOk(victimPlayerId, false, false) then
            return false, "player is no longer a valid target"
        end
        if not isDev then
            local victimPlayer = Players.GetById(victimPlayerId)
            local victimGamerInfo = victimPlayer ~= nil and victimPlayer:GetGamerInfo() or nil
            local victimRockstarId = victimGamerInfo ~= nil and victimGamerInfo.RockstarId or nil
            if type(blacklistRIDList) == "table" then
                local isBlacklistedRid = blacklistRIDList[victimRockstarId]
                if isBlacklistedRid then
                    if isBlacklistedRid then
                        return false, "protected target"
                    end
                    goto allowTarget
                end
            end
            if type(KS_IsProtectedKScriptTarget) == "function" and KS_IsProtectedKScriptTarget(victimPlayerId, victimRockstarId, KSBlameKillPlayerName(victimPlayerId)) then
                return false, "protected target"
            end
            ::allowTarget::
        end
        return true
    end

    function KSBlameKillFire(victimId, blamerId)
        local isTargetAllowed, rejectReason = KSBlameKillTargetAllowed(victimId, blamerId)
        if not isTargetAllowed then
            return false, rejectReason
        end
        if blamerId == nil or blamerId < 0 or not isNetPlayerOk(blamerId, false, false) then
            return false, "blamed player is no longer in the session"
        end
        local victimPedHandle = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(victimId)
        local fireSucceeded, failureReason
        if victimPedHandle ~= nil and victimPedHandle ~= 0 then
            if type(ENTITY.IS_ENTITY_DEAD) ~= "function" then
                goto fireAtVictim
            end
            if not ENTITY.IS_ENTITY_DEAD(victimPedHandle, false) then
                goto fireAtVictim
            end
        end
        fireSucceeded = false
        failureReason = "target is already dead or unavailable"
        do
            return fireSucceeded, failureReason
        end
        ::fireAtVictim::
        local victimCPed = Players.GetCPed(victimId)
        local blamerCPed = Players.GetCPed(blamerId)
        if victimCPed == nil or blamerCPed == nil then
            return false, "player ped was unavailable"
        end
        local victimPedAddress = victimCPed:GetAddress()
        local blamerPedAddress = blamerCPed:GetAddress()
        if not (victimPedAddress and victimPedAddress ~= 0 and blamerPedAddress) or blamerPedAddress == 0 then
            return false, "player ped address was unavailable"
        end
        local triggerAddress, triggerError = KSBlameKillResolveTrigger()
        if triggerAddress == nil then
            return false, triggerError
        end
        local callGuard = setmetatable({ keepScope = false }, KS_SESSION_BLAME_KILL_CALL_GUARD)
        local scopePatchOk, scopePatchError = KSBlameKillApplyPatch("scope")
        if not scopePatchOk then
            return false, scopePatchError
        end
        local damageTypePatchOk, damageTypePatchError = KSBlameKillApplyPatch("damageType")
        if not damageTypePatchOk then
            return false, damageTypePatchError
        end
        local blameKillState = featurePlaneInstall.sessionBlameKill
        blameKillState.scopeUntilMs = getRuntimeNowMs() + 750
        local zeroVector = V3.New(0.0, 0.0, 0.0)
        for _ = 1, blameKillState.shots do
            Memory.LuaCallCFunction(triggerAddress, blamerPedAddress, victimPedAddress, victimPedAddress + 144, 0, 1, blameKillState.weapon, blameKillState.damage, 0, 0, blameKillState.flags, 0, 0, 0, 0, 0, 0, 0, zeroVector)
        end
        return true
    end

    function KSBlameKillNotifyFailure(failureReason)
        notify("Blame Kill failed: " .. tostring(failureReason or "unknown error"))
    end

    function KSBlameKillRunQueue()
        local runnerGuard = setmetatable({}, KS_SESSION_BLAME_KILL_RUNNER_GUARD)
        local blameKillState = featurePlaneInstall.sessionBlameKill
        while isFeaturePlaneInstallCurrent() and not isUnloadRequested() and (#blameKillState.queue > 0 or blameKillState.owned.scope == true) do
            if #blameKillState.queue > 0 then
                if not KS_IsNetworkPlayerSessionReady() then
                    KSBlameKillNotifyFailure("the network session is not ready")
                    return
                end
                local entriesDrainedThisTick = 0
                while #blameKillState.queue > 0 and entriesDrainedThisTick < blameKillState.drainPerTick do
                    local queuedKill = table.remove(blameKillState.queue, 1)
                    local didFire, fireError = KSBlameKillFire(queuedKill.victim, queuedKill.blamer)
                    if not didFire and fireError ~= "target is already dead or unavailable" and fireError ~= "player is no longer a valid target" and fireError ~= "protected target" then
                        KSBlameKillNotifyFailure(fireError)
                        return
                    end
                    entriesDrainedThisTick = entriesDrainedThisTick + 1
                end
                Script.Yield(0)
            elseif blameKillState.owned.scope == true then
                if getRuntimeNowMs() >= blameKillState.scopeUntilMs then
                    KSBlameKillRestorePatch("scope")
                else
                    Script.Yield(25)
                end
            end
        end
    end

    function KSBlameKillEnsureRunner()
        local blameKillState = featurePlaneInstall.sessionBlameKill
        if blameKillState.running then
            return true
        end
        if not isTableOrUserdata(Script) or type(Script.QueueJob) ~= "function" then
            KSBlameKillNotifyFailure("the job scheduler is unavailable")
            return false
        end
        blameKillState.running = true
        if Script.QueueJob(KSBlameKillRunQueue) == false then
            blameKillState.running = false
            KSBlameKillNotifyFailure("the job could not be queued")
            return false
        end
        return true
    end

    function KSBlameKillEnqueue(victimId, blamerId)
        local blameKillState = featurePlaneInstall.sessionBlameKill
        if #blameKillState.queue >= blameKillState.maxQueued then
            return false
        end
        blameKillState.queue[#blameKillState.queue + 1] = { victim = victimId, blamer = blamerId }
        return true
    end

    function KSBlameKillRefreshSelectors(forceRefresh)
        local blameKillState = featurePlaneInstall.sessionBlameKill
        local nowMs = getRuntimeNowMs()
        if not blameKillState.refreshing then
            if forceRefresh == true then
                goto performRefresh
            end
            if not (nowMs - blameKillState.lastRefreshMs < 500) then
                goto performRefresh
            end
        end
        do
            return
        end
        ::performRefresh::
        blameKillState.refreshing = true
        blameKillState.lastRefreshMs = nowMs
        local blamerLabels = { "(select player)" }
        local blamerPlayerIds = { -1 }
        local victimLabels = { "(select player)" }
        local victimPlayerIds = { -1 }
        local blamerListIndex = 0
        local victimListIndex = 0
        local localPlayerId = GTA.GetLocalPlayerId()
        for candidatePlayerId = 0, 31 do
            if candidatePlayerId ~= localPlayerId and isNetPlayerOk(candidatePlayerId, false, false) then
                local playerLabel = ("%s [%d]"):format(KSBlameKillPlayerName(candidatePlayerId), candidatePlayerId)
                blamerPlayerIds[#blamerPlayerIds + 1] = candidatePlayerId
                blamerLabels[#blamerLabels + 1] = playerLabel
                if candidatePlayerId == blameKillState.blamerPid then
                    blamerListIndex = #blamerPlayerIds - 1
                end
                if candidatePlayerId ~= blameKillState.blamerPid then
                    victimPlayerIds[#victimPlayerIds + 1] = candidatePlayerId
                    victimLabels[#victimLabels + 1] = playerLabel
                    if candidatePlayerId == blameKillState.victimPid then
                        victimListIndex = #victimPlayerIds - 1
                    end
                end
            end
        end
        if blamerListIndex == 0 then
            blameKillState.blamerPid = -1
        end
        if victimListIndex == 0 then
            blameKillState.victimPid = -1
        end
        blameKillState.victimIds = victimPlayerIds
        blameKillState.blamerIds = blamerPlayerIds
        local blamerFeature = FeatureMgr.GetFeature(H_SESSION_BLAME_KILL_BLAMER)
        local victimFeature = FeatureMgr.GetFeature(H_SESSION_BLAME_KILL_VICTIM)
        if blamerFeature ~= nil then
            blamerFeature:SetList(blamerLabels)
            blamerFeature:SetListIndex(blamerListIndex)
        end
        if victimFeature ~= nil then
            victimFeature:SetList(victimLabels)
            victimFeature:SetListIndex(victimListIndex)
        end
        blameKillState.refreshing = false
    end

    function KSBlameKillQueueSelected()
        KSBlameKillRefreshSelectors(true)
        local blameKillState = featurePlaneInstall.sessionBlameKill
        if blameKillState.blamerPid < 0 then
            notify("Blame Kill: select a player to blame first.")
            return
        end
        if blameKillState.victimPid < 0 then
            notify("Blame Kill: select a victim first.")
            return
        end
        local isTargetAllowed, disallowReason = KSBlameKillTargetAllowed(blameKillState.victimPid, blameKillState.blamerPid)
        if not isTargetAllowed then
            notify("Blame Kill: " .. disallowReason .. ".")
            return
        end
        if not KSBlameKillEnqueue(blameKillState.victimPid, blameKillState.blamerPid) then
            notify("Blame Kill: the pending queue is full.")
            return
        end
        KSBlameKillEnsureRunner()
    end

    function KSBlameKillQueueSession()
        KSBlameKillRefreshSelectors(true)
        local blameKillState = featurePlaneInstall.sessionBlameKill
        if blameKillState.blamerPid < 0 then
            notify("Blame Kill: select a player to blame first.")
            return
        end
        local queuedCount = 0
        for targetPlayerId = 0, 31 do
            if KSBlameKillTargetAllowed(targetPlayerId, blameKillState.blamerPid) then
                if not KSBlameKillEnqueue(targetPlayerId, blameKillState.blamerPid) then
                    break
                end
                queuedCount = queuedCount + 1
            end
        end
        if queuedCount == 0 then
            notify("Blame Kill: no eligible session targets.")
            return
        end
        KSBlameKillEnsureRunner()
    end

    function KSBlameKillRandomizeBlamer()
        KSBlameKillRefreshSelectors(true)
        local blameKillState = featurePlaneInstall.sessionBlameKill
        if #blameKillState.blamerIds <= 1 then
            notify("Blame Kill: no remote players available.")
            return
        end
        local candidateBlamerIds = {}
        for blamerIdIndex = 2, #blameKillState.blamerIds do
            if blameKillState.blamerIds[blamerIdIndex] ~= blameKillState.blamerPid then
                candidateBlamerIds[#candidateBlamerIds + 1] = blameKillState.blamerIds[blamerIdIndex]
            end
        end
        if #candidateBlamerIds == 0 then
            candidateBlamerIds[1] = blameKillState.blamerIds[2]
        end
        blameKillState.blamerPid = candidateBlamerIds[math.random(#candidateBlamerIds)]
        blameKillState.lastRefreshMs = 0
        KSBlameKillRefreshSelectors(true)
        notify("Blame Kill: now blaming " .. KSBlameKillPlayerName(blameKillState.blamerPid) .. ".")
    end

