    function onUnload()
        KScriptTosReleaseMouseCursor()
        KSResetSessionBlameKill("script_unload")
        if type(contextR25UnloadHook) == "function" then
            contextR25UnloadHook()
        end
        if type(KSModules) == "table" and type(KSModules.unloadAll) == "function" then
            KSModules.unloadAll("script unload")
        end
        local rpcState = type(rpc) == "table" and rpc or nil
        if rpcState and rpcState.active then
            rpcState.active = false
            if rpcState.pipe then
                clearRpcActivity()
                rpcState.pipe:close()
                rpcState.pipe = nil
            end
        end
        FeatureMgr.GetFeature(Utils.Joaat("acceptAlerts")):Reset()
        FeatureMgr.GetFeature(Utils.Joaat("skipReload")):Reset()
        KS_ReleaseDebugEventBuffer()
        FeatureMgr.GetFeature(Utils.Joaat("dbug")):Reset()
        if FeatureMgr.GetFeature(Utils.Joaat("natSpoofToggle")):IsToggled() then
            Memory.WriteInt(natTypeAddr, originalNatTypeIndex)
        end
        if FeatureMgr.GetFeature(Utils.Joaat("regionSpoofToggle")):IsToggled() then
            Memory.WriteInt(geoLocRegionAddr, originalMatchmakingRegionIndex)
        end
        if #party_buses ~= 0 and #static_buses ~= 0 then
            for partyBusIndex = 0, #party_buses do
                DeleteEnt(party_buses[partyBusIndex])
            end
            for staticBusIndex = 0, #static_buses do
                DeleteEnt(static_buses[staticBusIndex])
            end
        end
        collectgarbage("collect")
    end

