    function deletePlayerNote(rockstarId)
        local notesFilePath = FileMgr.GetMenuRootPath() .. "\\Lua\\K-Script\\PlayerNotes.json"
        if not FileMgr.DoesFileExist(notesFilePath) then
            notify("No PlayerNotes.json found!")
            return
        end
        local notesFileContent = FileMgr.ReadFileContent(notesFilePath)
        if not notesFileContent or notesFileContent == "" then
            notify("PlayerNotes.json is empty!")
            return
        end
        local playerNotes = json.decode(notesFileContent)
        if type(playerNotes) ~= "table" then
            notify("PlayerNotes.json is corrupted!")
            return
        end
        local noteKey = tostring(rockstarId)
        if playerNotes[noteKey] == nil then
            notify(("Note not found for key: %s"):format(noteKey))
            return
        end
        playerNotes[noteKey] = nil
        local encodedNotes = json.encode(playerNotes, { indent = true })
        if FileMgr.WriteFileContent(notesFilePath, encodedNotes) == false then
            notify("Failed to delete note.")
            return
        end
        notify(("Deleted note for Rockstar ID %s"):format(noteKey))
    end

    cursorPos = -1.0
    fadeContentAlpha = 1.0
    currentTab = 0
    lastTab = 0
    lastGUITab = 0
    fadeCurrentTab = 0
    fadeLastTab = 0
    fadeLastGUITab = 0
    activeTabPath = ""
    lastActiveTabPath = ""
    tabBarDepth = 0
    activeTabLabelsByDepth = {}
    pendingContentSlide = false
    slideAppliedThisFrame = false

    function lerp(startValue, endValue, blendFactor)
        return startValue + (endValue - startValue) * blendFactor
    end

    function TryApplySlideOffset()
        if pendingContentSlide and not slideAppliedThisFrame and FeatureMgr.IsFeatureToggled(Utils.Joaat("FeatureTransitions")) then
            ImGui.SetCursorPosX(cursorPos)
            slideAppliedThisFrame = true
            pendingContentSlide = false
        end
    end

    local function resetTabTransitionFrameState()
        activeTabPath = ""
        tabBarDepth = 0
        activeTabLabelsByDepth = {}
        slideAppliedThisFrame = false
    end

    local function updateTabSlideAndFadeTransitions()
        if not isTableOrUserdata(ImGui) or not isTableOrUserdata(GUI) or not isTableOrUserdata(ClickGUI) then
            return
        end
        local frameRate = tonumber(ImGui.GetFrameRate()) or 60
        local isGuiOpen = GUI.IsOpen() == true
        local activeMenuTab = ClickGUI.GetActiveMenuTab() or lastGUITab or 0
        local currentTabPath = activeTabPath
        if currentTabPath == nil or currentTabPath == "" then
            currentTabPath = tostring(currentTab)
        end
        if type(FeatureMgr) == "table" then
            if type(FeatureMgr.IsFeatureToggled) == "function" and FeatureMgr.IsFeatureToggled(Utils.Joaat("FeatureTransitions")) then
                local transitionSpeed = 1.0
                local slideStartPosX = -1.0
                local transitionSpeedFeature = FeatureMgr.GetFeature(Utils.Joaat("FeatureTransitionsTransitionSpeed"))
                local transitionPositionFeature = FeatureMgr.GetFeature(Utils.Joaat("FeatureTransitionsPosition"))
                if transitionSpeedFeature and type(transitionSpeedFeature.GetFloatValue) == "function" then
                    transitionSpeed = transitionSpeedFeature:GetFloatValue()
                end
                if transitionPositionFeature and type(transitionPositionFeature.GetIntValue) == "function" then
                    slideStartPosX = transitionPositionFeature:GetIntValue()
                end
                local slideStep = transitionSpeed * (82 / frameRate)
                if cursorPos < -1.0 then
                    cursorPos = lerp(cursorPos, 1.0, slideStep)
                    if cursorPos > -1.0 then
                        cursorPos = -1.0
                    end
                else
                    cursorPos = -1.0
                end
                local hasTabPathChanged = currentTabPath ~= lastActiveTabPath
                if not isGuiOpen then
                    cursorPos = -1.0
                    lastActiveTabPath = currentTabPath
                    lastTab = currentTab
                    lastGUITab = activeMenuTab
                    pendingContentSlide = false
                elseif hasTabPathChanged then
                    cursorPos = slideStartPosX
                    pendingContentSlide = true
                    lastActiveTabPath = currentTabPath
                    lastTab = currentTab
                    lastGUITab = activeMenuTab
                end
            end
        else
            pendingContentSlide = false
            cursorPos = -1.0
            lastActiveTabPath = currentTabPath
            lastTab = currentTab
            lastGUITab = activeMenuTab
        end
        if type(FeatureMgr) == "table" then
            if type(FeatureMgr.IsFeatureToggled) == "function" and FeatureMgr.IsFeatureToggled(Utils.Joaat("FadeContent")) then
                local fadeSpeed = 1.0
                local fadeInitialAlpha = 0.0
                local fadeSpeedFeature = FeatureMgr.GetFeature(Utils.Joaat("FadeContentFadeSpeed"))
                local fadeInitialValueFeature = FeatureMgr.GetFeature(Utils.Joaat("FadeContentFadeInitialValue"))
                if fadeSpeedFeature and type(fadeSpeedFeature.GetFloatValue) == "function" then
                    fadeSpeed = fadeSpeedFeature:GetFloatValue() / 50
                end
                if fadeInitialValueFeature and type(fadeInitialValueFeature.GetFloatValue) == "function" then
                    fadeInitialAlpha = fadeInitialValueFeature:GetFloatValue()
                end
                local fadeStep = fadeSpeed * (82 / frameRate)
                if fadeContentAlpha < 1.0 then
                    fadeContentAlpha = fadeContentAlpha + fadeStep
                    if fadeContentAlpha > 1.0 then
                        fadeContentAlpha = 1.0
                    end
                else
                    fadeContentAlpha = 1.0
                end
                local hasFadeTabChanged = currentTabPath ~= fadeLastTab
                if not isGuiOpen then
                    fadeContentAlpha = 1.0
                    fadeLastTab = currentTabPath
                    fadeLastGUITab = activeMenuTab
                elseif hasFadeTabChanged then
                    fadeLastTab = currentTabPath
                    fadeLastGUITab = activeMenuTab
                    fadeContentAlpha = fadeInitialAlpha
                end
            end
        else
            fadeContentAlpha = 1.0
            fadeLastTab = currentTabPath
            fadeLastGUITab = activeMenuTab
        end
    end

    local function wrapClickGuiTabRenderer(tabLabel, renderTabCallback)
        return passThroughLabeledCallback(tabLabel, function(...)
            resetTabTransitionFrameState()
            local firstRenderArg = ...
            local renderResults = { renderTabCallback(firstRenderArg) }
            updateTabSlideAndFadeTransitions()
            return table.unpack(renderResults)
        end)
    end

