                                KS_RenderRemovalRestrictionAlert(removalGateState)
                            elseif removalGateState.active == true then
                                ImGui.Text(formatRemovalGateStatus(removalGateState))
                            end
                            if isAdmin or isSupporter then
                                ImGui.BeginDisabled()
                                renderClickFeature("sigTest")
                                ImGui.EndDisabled()
                                local comparedGatePhase = removalGateState.phase
                                local blockingGatePhase = "running"
                                if comparedGatePhase ~= blockingGatePhase then
                                    comparedGatePhase = removalGateState.phase
                                    blockingGatePhase = "restricted"
                                end
                                local isYachtCrashLocked = comparedGatePhase == blockingGatePhase
                                if isYachtCrashLocked then
                                    ImGui.BeginDisabled()
                                end
                                renderClickFeature("YachtParachuteCrash")
                                if isYachtCrashLocked then
                                    ImGui.EndDisabled()
                                end
                            end
                            renderClickFeature("crashAllk")
                            ClickGUI.EndCustomChildWindow()
                        end
                        local notesGridColumns = 5
                        local notesGridRows = 5
                        ImGui.Columns()
                        if ClickGUI.BeginCustomChildWindow("Player Notes") then
                            local savedPlayerNotes = contextLoadPlayerNotes()
                            local sortedNoteRockstarIds = {}
                            for noteRockstarId in pairs(savedPlayerNotes) do
                                table.insert(sortedNoteRockstarIds, noteRockstarId)
                            end
                            table.sort(sortedNoteRockstarIds)
                            if #sortedNoteRockstarIds == 0 then
                                ImGui.Text("No saved player notes.")
                                ClickGUI.EndCustomChildWindow()
                            else
                                currentNotesPage = currentNotesPage or 1
                                local notesPerPage = notesGridColumns * notesGridRows
                                local totalNotePages = math.max(1, math.ceil(#sortedNoteRockstarIds / notesPerPage))
                                if totalNotePages < currentNotesPage then
                                    currentNotesPage = totalNotePages
                                end
                                local pageFirstNoteIndex = (currentNotesPage - 1) * notesPerPage + 1
                                local pageLastNoteIndex = math.min(pageFirstNoteIndex + notesPerPage - 1, #sortedNoteRockstarIds)
                                if ImGui.BeginTable("PlayerNotesTable", notesGridColumns, ImGuiTableFlags.BordersInner) then
                                    for tableColumnNumber = 1, notesGridColumns do
                                        ImGui.TableSetupColumn("##col" .. tableColumnNumber, ImGuiTableColumnFlags.None)
                                    end
                                    local gridColumnIndex = 0
                                    for sortedIdIndex = pageFirstNoteIndex, pageLastNoteIndex do
                                        local cellRockstarId = sortedNoteRockstarIds[sortedIdIndex]
                                        local playerNote = savedPlayerNotes[cellRockstarId]
                                        if gridColumnIndex == 0 then
                                            ImGui.TableNextRow()
                                        end
                                        ImGui.TableSetColumnIndex(gridColumnIndex)
                                        local notePlayerName = playerNote.player_name or "Unknown Player"
                                        ImGui.Text(notePlayerName)
                                        if ImGui.IsItemHovered() then
                                            if ImGui.IsKeyPressed(ImGuiKey.Backspace) then
                                                deletePlayerNote(cellRockstarId)
                                            end
                                            ImGui.BeginTooltip()
                                            ImGui.Text("Press BACKSPACE to delete this note ")
                                            ImGui.Text("Name: " .. notePlayerName)
                                            ImGui.Text("Rockstar ID: " .. tostring(playerNote.rockstar_id))
                                            ImGui.Text("Last Seen: " .. formatTime(playerNote.last_seen))
                                            ImGui.Text("Note:")
                                            ImGui.TextWrapped(playerNote.note or "")
                                            ImGui.EndTooltip()
                                        end
                                        if ImGui.IsItemClicked() then
                                            Script.QueueJob(function()
                                                if isGameVersionEnhanced then
                                                    local noteGameVersion = playerNote.GameVersion
                                                    if noteGameVersion == "Legacy" then
                                                        if noteGameVersion == "Enhanced" then
                                                            notify(("Cannot Join %s due to Game Version mismatch!\nYou must be on %s to join them."):format(sanitizedClientName, user.GameVersion))
                                                            return
                                                        end
                                                        goto joinNotedPlayer
                                                    end
                                                end
                                                if not isGameVersionEnhanced and playerNote.GameVersion == "Enhanced" then
                                                    notify(("Cannot Join %s due to Game Version mismatch!\nYou must be on %s to join them."):format(sanitizedClientName, user.GameVersion))
                                                    return
                                                end
                                                ::joinNotedPlayer::
                                                notify(("Trying to Join %s..."):format(notePlayerName))
                                                FeatureMgr.GetFeatureByName("Notify On Player Join"):SetValue(false)
                                                FeatureMgr.GetFeatureByName("Notify On Player Leave"):SetValue(false)
                                                local preJoinCoords = V3.New(ENTITY.GET_ENTITY_COORDS(getPlayerPed()))
                                                FeatureMgr.GetFeature(Utils.Joaat("SCAPIRID")):SetIntValue(playerNote.rockstar_id)
                                                for _ = 0, 70 do
                                                    FeatureMgr.GetFeatureByName("Join Rockstar Id"):TriggerCallback()
                                                    Script.Yield(650)
                                                end
                                                FeatureMgr.GetFeature(Utils.Joaat("SCAPIRID")):SetIntValue(12345)
                                                local joinDeadlineMs = Time.GetEpocheMs() + 15000
                                                while not maintransitionActive and joinDeadlineMs > Time.GetEpocheMs() and not ShouldUnload() do
                                                    Script.Yield(2000)
                                                end
                                                if not maintransitionActive and joinDeadlineMs > Time.GetEpocheMs() then
                                                    notify("Player join failed: mainTransition not launched.")
                                                    return
                                                end
                                                if joinDeadlineMs > Time.GetEpocheMs() then
                                                    notify("Joined player successfully!")
                                                else
                                                    notify("Player join timed out.")
                                                    return
                                                end
                                                FeatureMgr.GetFeatureByName("Notify On Player Join"):SetValue(true)
                                                FeatureMgr.GetFeatureByName("Notify On Player Leave"):SetValue(true)
                                                while getTransitionState() ~= 66 and not ShouldUnload() do
                                                    Script.Yield(100)
                                                end
                                                for _ = 0, 5 do
                                                    ENTITY.SET_ENTITY_COORDS_NO_OFFSET(getPlayerPed(), preJoinCoords.x, preJoinCoords.y, preJoinCoords.z, false, false, false)
                                                end
                                            end)
                                        end
                                        gridColumnIndex = gridColumnIndex + 1
                                        if notesGridColumns <= gridColumnIndex then
                                            gridColumnIndex = 0
                                        end
                                    end
                                    ImGui.EndTable()
                                end
                                ImGui.Separator()
                                ImGui.SetCursorPosX((ImGui.GetWindowWidth() - 200) * 0.5)
                                if ImGui.Button("<") then
                                    currentNotesPage = math.max(1, currentNotesPage - 1)
                                end
                                ImGui.SameLine()
                                ImGui.Text("Page " .. currentNotesPage .. " / " .. totalNotePages)
                                ImGui.SameLine()
                                if ImGui.Button(">") then
                                    currentNotesPage = math.min(totalNotePages, currentNotesPage + 1)
                                end
                                ClickGUI.EndCustomChildWindow()
                            end
                        end
                        ImGui.EndTabItem()
                    end
                    if ImGui.BeginTabItem("Session Purifier") then
                        renderClickFeature("PurificationMain")
                        ImGui.SameLine()
                        renderClickFeature("SessionPurifierAutoCrash")
                        ImGui.Separator()
                        ImGui.Text("Search Country:")
                        ImGui.SameLine()
                        if ImGui.Button("Clear") then
                            searchQuery = ""
                            filteredCountries = {}
                            lastSearchQuery = ""
                        end
                        renderClickFeature("purification_search")
                        local searchInputText = FeatureMgr.GetFeatureString(Utils.Joaat("purification_search"))
                        if searchInputText ~= searchQuery then
                            searchQuery = searchInputText.lower(searchInputText)
                            filteredCountries = {}
                            if #searchQuery > 0 then
                                for _, countryName in ipairs(countriesToKick) do
                                    local lowerCountryName = countryName.lower(countryName)
                                    if lowerCountryName.find(lowerCountryName, searchQuery, 1, true) then
                                        table.insert(filteredCountries, countryName)
                                    end
                                end
                            end
                            lastSearchQuery = searchQuery
                        end
                        if #searchQuery == 0 and #filteredCountries > 0 then
                            filteredCountries = {}
                        end
                        if ClickGUI.BeginCustomChildWindow("Countries", 1, 14) then
                            local visibleCountries = #searchQuery == 0 and countriesToKick or filteredCountries
