                                    end
                                end
                            end
                            ClickGUI.EndCustomChildWindow()
                        end
                        ImGui.EndTabItem()
                    end
                    ImGui.EndTabBar()
                end
                ImGui.EndTabItem()
            end
            if ImGui.BeginTabItem("Emotes") then
