    function renderPlayerTabClickUI()
        if not GUI.IsOpen() then
            return
        end
        local playerTabColumnCount = 2
        local playerTableFlags = ImGuiTableFlags.SizingStretchSame
        local selectedPlayerId = tonumber(Utils.GetSelectedPlayer())
        if selectedPlayerId == nil or selectedPlayerId < 0 or selectedPlayerId >= 32 then
            return
        end
        local isFadeAlphaPushed = false
        if FeatureMgr.IsFeatureToggled(Utils.Joaat("FadeContent")) then
            ImGui.PushStyleVar(ImGuiStyleVar.Alpha, fadeContentAlpha)
            isFadeAlphaPushed = true
        end
        if ImGui.BeginTable("Player Lua Tab", playerTabColumnCount, playerTableFlags) then
            ImGui.TableNextRow()
            for columnIndex = 0, playerTabColumnCount - 1 do
                ImGui.TableSetColumnIndex(columnIndex)
                if columnIndex == 0 then
                    if ClickGUI.BeginCustomChildWindow("Removals") then
                        local removalGateState = getRemovalGateState()
                        if removalGateState.phase == "restricted" then
                            KS_RenderRemovalRestrictionAlert(removalGateState)
                        elseif removalGateState.active == true then
                            ImGui.Text(formatRemovalGateStatus(removalGateState))
                        end

                        local function renderRemovalFeature(featureName, isHighRiskRemoval)
                            local featureHash = Utils.Joaat(featureName)
                            local hasPlayerFeature = FeatureMgr.GetFeature(featureHash, selectedPlayerId) ~= nil
                            local isGateActive = removalGateState.active
                            local shouldDisableFeature = isGateActive and (isHighRiskRemoval == true or isGateActive)
                            if shouldDisableFeature then
                                ImGui.BeginDisabled()
                            end
                            ClickGUI.RenderFeature(featureHash, selectedPlayerId)
                            if shouldDisableFeature then
                                ImGui.EndDisabled()
                            end
                        end

                        renderRemovalFeature("zeroCrash")
                        renderRemovalFeature("nCrash")
                        renderRemovalFeature("lexisSkid")
                        renderRemovalFeature("syncCrash")
                        renderRemovalFeature("TempVehicle1")
                        if isSupporter then
                            renderRemovalFeature("pBigBrainCrash", true)
                            renderRemovalFeature("pBigBrainCrashV2", true)
                            renderRemovalFeature("goofycrash")
                            if not isGameVersionEnhanced then
                                renderRemovalFeature("standCrash")
                            end
                            renderRemovalFeature("vehlightCwash")
                            if isAdmin then
                                renderRemovalFeature("TractorCrash")
                                renderRemovalFeature("9/11 cwash")
                                renderRemovalFeature("niggerCrash")
                            end
                            renderRemovalFeature("invalidPoolDelete1")
                            renderRemovalFeature("zykloneShower")
                            if isGameVersionEnhanced then
                                renderRemovalFeature("instanceCrash1")
                            end
                            renderRemovalFeature("InvalidMComp1")
                            renderRemovalFeature("rapeLexis")
                            renderRemovalFeature("masterpiece")
                            renderRemovalFeature("tugspam")
                            renderRemovalFeature("spongebobc")
                        else
                            ImGui.Text("\nFor more Crashes get Donator!")
                        end
                        ClickGUI.EndCustomChildWindow()
                    end
                    if ClickGUI.BeginCustomChildWindow("General") then
                        ClickGUI.RenderFeature(Utils.Joaat("AutoTPToPlayer"), selectedPlayerId)
                        ClickGUI.EndCustomChildWindow()
                    end
                    if ClickGUI.BeginCustomChildWindow("Utils") then
                        ClickGUI.RenderFeature(Utils.Joaat("KScriptHostKick"), selectedPlayerId)
                        ClickGUI.EndCustomChildWindow()
                    end
                    if ClickGUI.BeginCustomChildWindow("Player Notes") then
                        ClickGUI.RenderFeature(Utils.Joaat("PlayerNote"), selectedPlayerId)
                        ClickGUI.RenderFeature(Utils.Joaat("SavePlayerNote"), selectedPlayerId)
                        ClickGUI.EndCustomChildWindow()
                    end
                end
                if columnIndex == 1 then
                    if ClickGUI.BeginCustomChildWindow("Trolling") then
                        ClickGUI.RenderFeature(Utils.Joaat("lexisSkid2"), selectedPlayerId)
                        if isSupporter then
                            ClickGUI.RenderFeature(Utils.Joaat("invflag"), selectedPlayerId)
                            ClickGUI.RenderFeature(Utils.Joaat("SpawnWindmillAtRemotePlayerFeet"), selectedPlayerId)
                            ClickGUI.RenderFeature(Utils.Joaat("OPTrollingCarfrfr"), selectedPlayerId)
                            ClickGUI.RenderFeature(Utils.Joaat("largeObjDmp1"), selectedPlayerId)
                            ClickGUI.RenderFeature(Utils.Joaat("largeObjDmpCleanup1"))
                            ClickGUI.RenderFeature(Utils.Joaat("glitchP1"), selectedPlayerId)
                            ClickGUI.RenderFeature(Utils.Joaat("cargoglitch1"), selectedPlayerId)
                            ClickGUI.RenderFeature(Utils.Joaat("pyroTroll1"), selectedPlayerId)
                            ClickGUI.RenderFeature(Utils.Joaat("flipper1"), selectedPlayerId)
                            ClickGUI.RenderFeature(Utils.Joaat("tugLagger"), selectedPlayerId)
                        end
                        ClickGUI.RenderFeature(Utils.Joaat("Invalid claim notification"), selectedPlayerId)
                        ClickGUI.EndCustomChildWindow()
                    end
                    if isSupporter and ClickGUI.BeginCustomChildWindow("Abuse") then
                        ImGui.Text("Activity Bypass:")
                        for _, activityFeatureName in pairs(activities) do
                            ClickGUI.RenderFeature(Utils.Joaat(activityFeatureName), selectedPlayerId)
                        end
                        ClickGUI.RenderFeature(Utils.Joaat("interactionLoop"), selectedPlayerId)
                        ClickGUI.EndCustomChildWindow()
                    end
                    if ClickGUI.BeginCustomChildWindow("Host Share", 1) then
                        ClickGUI.RenderFeature(Utils.Joaat("remotehostkick"), selectedPlayerId)
                        ClickGUI.EndCustomChildWindow()
                    end
                end
            end
            ImGui.EndTable()
        end
        if isFadeAlphaPushed then
            ImGui.PopStyleVar()
        end
    end

    function renderListUI()
        local listRootTab = ListGUI.GetRootTab()
        if listRootTab then
            if listRootTab:GetSubTab("K-Script") then
                return
            end
            local kScriptTab = listRootTab:AddSubTab("K-Script", "")
            if kScriptTab then
                local sessionCrashesTab = kScriptTab:AddSubTab("Session Crashes")
