    function RenderModeWatcher()
        if ShouldUnload() then
            return
        end
        if not isTableOrUserdata(GUI) or type(GUI.GetMode) ~= "function" then
            Script.Yield(500)
            return
        end
        local currentGuiMode = GUI.GetMode()
        cachedMode = currentGuiMode
        if currentGuiMode == eGuiMode.ClickGUI then
            if isTableOrUserdata(ClickGUI) and type(ClickGUI.AddTab) == "function" and not isClickGuiMainTabAdded and ClickGUI.AddTab("K-Script", wrapClickGuiTabRenderer("clickgui-tab", renderUnifiedTab)) ~= false then
                isClickGuiMainTabAdded = true
                markMenuSurfaceRegistered()
            end
            if isTableOrUserdata(ClickGUI) and type(ClickGUI.AddPlayerTab) == "function" and not isClickGuiPlayerTabAdded and ClickGUI.AddPlayerTab("K-Script", wrapClickGuiTabRenderer("clickgui-player-tab", renderPlayerTabClickUI)) ~= false then
                isClickGuiPlayerTabAdded = true
            end
        elseif currentGuiMode == eGuiMode.ListGUI then
            if type(renderListUI) == "function" and not isListGuiMenuRegistered and renderListUI() ~= false then
                isListGuiMenuRegistered = true
                markMenuSurfaceRegistered()
            end
        end
        Script.Yield(500)
    end

