    function featurePlaneContext.__ksAngelAi.featureEnabled(angelEventKind)
        return FeatureMgr.IsFeatureEnabled(Utils.Joaat(angelEventKind == "respawn" and "AngelAIOnDeath" or "AngelAIOnWeaponChange")) == true
    end

    function featurePlaneContext.__ksAngelAi.weaponUiBlocked()
        if type(SCRIPT) ~= "table" or type(SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH) ~= "function" then
            return false
        end
        for _, blockingScriptName in ipairs({ "appinternet", "appcamera", "cellphone_flashhand" }) do
            if (tonumber(SCRIPT.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH(Utils.Joaat(blockingScriptName))) or 0) > 0 then
                return true
            end
        end
        return false
    end

    local function isRuntimeCurrentAndNotUnloading(callerLoadGeneration)
        local isRuntimeStillCurrent = isFeaturePlaneInstallCurrent()
        if isRuntimeStillCurrent then
            isRuntimeStillCurrent = isRuntimeGenerationCurrent()
            if isRuntimeStillCurrent then
                local isUnloadPending = isUnloadRequested()
                isRuntimeStillCurrent = isUnloadPending ~= true and isUnloadPending
            end
        end
        return isRuntimeStillCurrent
    end

    function featurePlaneContext.__ksAngelAi.queueEvent(eventKind, eventPayload)
        if eventKind ~= "respawn" or not "respawn" then
            eventKind = "weapon"
        end
        local angelAiState = featurePlaneContext.__ksAngelAi
        local eventCountByKind = angelAiState.eventCount
        local previousEventCount = tonumber(angelAiState.eventCount[eventKind]) or 0
        eventCountByKind[eventKind] = previousEventCount + 1
        angelAiState.sequence = angelAiState.sequence + 1
        local copiedEventValue = nil
        if type(eventPayload) == "number" or type(eventPayload) == "string" then
            copiedEventValue = eventPayload
        end
        local latestEventByKind = angelAiState.latest
        local receivedEventRecord = {
            sequence = angelAiState.sequence,
            copied_value = copiedEventValue,
            received_at_ms = getRuntimeNowMs(),
        }
        latestEventByKind[eventKind] = receivedEventRecord
        angelAiState.lastReason = eventKind .. ":event-received"
        if angelAiState.unloading then
            return false
        end
        if angelAiState.queued[eventKind] then
            angelAiState.lastReason = eventKind .. ":superseded"
            return true
        end
        if not isTableOrUserdata(Script) or type(Script.QueueJob) ~= "function" or type(Script.Yield) ~= "function" then
            angelAiState.lastReason = eventKind .. ":queue-api-unavailable"
            return false
        end
        angelAiState.queued[eventKind] = true
        local queuedLoadGeneration = runtimeLoadGeneration
        if Script.QueueJob(function()
            local pendingEventRecord = angelAiState.latest[eventKind]
            local pedSettleDeadlineMs = getRuntimeNowMs() + (eventKind == "respawn" and 5000 or 1500)
            yieldScriptMs(eventKind == "respawn" and 250 or 175)
            while isRuntimeCurrentAndNotUnloading(queuedLoadGeneration) and pendingEventRecord ~= nil do
                if angelAiState.latest[eventKind] ~= pendingEventRecord then
                    pendingEventRecord = angelAiState.latest[eventKind]
                    pedSettleDeadlineMs = getRuntimeNowMs() + (eventKind == "respawn" and 5000 or 1500)
                    angelAiState.lastReason = eventKind .. ":superseded"
                    yieldScriptMs(eventKind == "respawn" and 250 or 175)
                elseif not angelAiState.featureEnabled(eventKind) then
                    angelAiState.lastReason = eventKind .. ":disabled-before-play"
                    break
                elseif eventKind == "weapon" then
                    if angelAiState.weaponUiBlocked() then
                        angelAiState.lastReason = eventKind .. ":ui-blocked"
                        break
                    end
                else
                    local localPlayerPed = PLAYER.PLAYER_PED_ID()
                    local hasLocalPed = localPlayerPed ~= nil and localPlayerPed ~= 0
                    if hasLocalPed and eventKind == "weapon" and isTableOrUserdata(WEAPON) and type(WEAPON.GET_SELECTED_PED_WEAPON) == "function" then
                        local selectedWeaponHash = tonumber(WEAPON.GET_SELECTED_PED_WEAPON(localPlayerPed))
                        local unarmedWeaponHash = tonumber(Utils.Joaat("WEAPON_UNARMED"))
                        if selectedWeaponHash == nil or selectedWeaponHash == 0 or selectedWeaponHash == unarmedWeaponHash then
                            angelAiState.lastReason = eventKind .. ":weapon-unavailable"
                            break
                        end
                    end
                    if hasLocalPed then
                        if angelAiState.latest[eventKind] ~= pendingEventRecord then
                            angelAiState.lastReason = eventKind .. ":superseded"
                        else
                            local isMaleFreemodePed = ENTITY.GET_ENTITY_MODEL(localPlayerPed) == Utils.Joaat("MP_M_Freemode_01")
                            local angelSpeechName
                            if eventKind == "respawn" then
                                if isMaleFreemodePed then
                                    angelSpeechName = "XM25_GYM_MALE"
                                    if angelSpeechName then
                                        goto playSelectedSpeech
                                    end
                                end
                                angelSpeechName = "XM25_GYM_FEMALE"
                                if angelSpeechName then
                                    goto playSelectedSpeech
                                end
                            end
                            if isMaleFreemodePed then
                                angelSpeechName = "XM25_WEAPONS_PURCHASED_MALE"
                                if angelSpeechName then
                                    goto playSelectedSpeech
                                end
                            end
                            angelSpeechName = "XM25_WEAPONS_PURCHASED_FEMALE"
                            ::playSelectedSpeech::
                            KS_PlayAngelAiSpeech(angelSpeechName, eventKind, eventKind == "respawn" and 3000 or 1500)
                            if angelAiState.latest[eventKind] == pendingEventRecord then
                                break
                            end
                        end
                    elseif pedSettleDeadlineMs <= getRuntimeNowMs() then
                        angelAiState.lastReason = eventKind .. ":ped-settle-timeout"
                        break
                    end
                    Script.Yield(100)
                end
            end
            if not isRuntimeCurrentAndNotUnloading(queuedLoadGeneration) then
                angelAiState.lastReason = eventKind .. ":cancelled"
            end
            angelAiState.queued[eventKind] = false
        end) == false then
            angelAiState.queued[eventKind] = false
            angelAiState.lastReason = eventKind .. ":queue-rejected"
            return false
        end
        angelAiState.lastReason = eventKind .. ":queued"
        return true
    end

    function featurePlaneContext.__ksAngelAi.registerHandler(angelEventKind, luaEventId, eventCallback)
        featurePlaneContext.__ksAngelAi.callbacks[angelEventKind] = eventCallback
        local registrationHandle = EventMgr.RegisterHandler(luaEventId, eventCallback)
        if registrationHandle == false or registrationHandle == nil then
            featurePlaneContext.__ksAngelAi.lastReason = angelEventKind .. ":handler-registration-failed"
            return false
        end
        featurePlaneContext.__ksAngelAi.handlers[angelEventKind] = registrationHandle or eventCallback
        return true
    end

