    local deferredRenderHandlerQueue = {}

    local function registerRenderHandlerNow(renderEventId, handlerName, renderCallback, maxFailures)
        if type(renderCallback) ~= "function" then
            return nil, false, "missing_callback"
        end
        if not isTableOrUserdata(EventMgr) or type(EventMgr.RegisterHandler) ~= "function" or renderEventId == nil then
            return nil, false, "render_api_unavailable"
        end
        if uiReadinessState.renderHandlerGenerations[handlerName] == runtimeLoadGeneration then
            return uiReadinessState.renderHandlers[handlerName], true, nil
        end

        uiReadinessState.renderCallbacks[handlerName] = function(...)
            if handlerName ~= "renderImGui" then
                renderCallback(...)
                return
            end
            if uiReadinessState.firstRenderCompleted then
                return renderCallback(...)
            end
            local renderReturnValue = renderCallback(...)
            if not uiReadinessState.firstRenderCompleted then
                recordFirstRenderResult(handlerName, renderReturnValue ~= false)
            end
            return renderReturnValue
        end

        local renderHandlerHandle = EventMgr.RegisterHandler(renderEventId, uiReadinessState.renderCallbacks[handlerName])
        if renderHandlerHandle == false or renderHandlerHandle == nil then
            uiReadinessState.renderCallbacks[handlerName] = nil
            return nil, false, "registration_rejected"
        end
        uiReadinessState.renderHandlers[handlerName] = renderHandlerHandle
        uiReadinessState.renderHandlerGenerations[handlerName] = runtimeLoadGeneration
        markRenderHandlerRegistered(handlerName)
        return renderHandlerHandle, true, nil
    end

    function uiReadinessState.renderRegistrationPrerequisitesMet()
        return isFeaturePlaneInstallCurrent() and uiReadinessState.runtimeStartupComplete and uiReadinessState.settingsReady and uiReadinessState.mainUIRenderable
    end

    local function registerOrDeferRenderHandler(renderEventId, handlerName, renderCallback, maxFailures)
        if not isRuntimeLoopDrainComplete or not uiReadinessState.renderRegistrationPrerequisitesMet() then
            deferredRenderHandlerQueue[#deferredRenderHandlerQueue + 1] = {
                event = renderEventId,
                name = handlerName,
                fn = renderCallback,
                maxFailures = maxFailures,
                attempts = 0,
            }
            if isRuntimeActivated and type(startRuntimeLoopDrainer) == "function" then
                startRuntimeLoopDrainer("late-render-handler")
            end
            return nil
        end
        return registerRenderHandlerNow(renderEventId, handlerName, renderCallback, maxFailures)
    end

    local deferredRuntimeLoopQueue = {}
    local isRuntimeDrainerLoopRegistered = false
    local hasRuntimeDrainerStartDelayElapsed = false
    local runtimeDrainerStartedAtMs = 0

    function KS_RuntimeNowMs()
        if isTableOrUserdata(Time) and type(Time.GetEpocheMs) == "function" then
            local epochNowMs = Time.GetEpocheMs()
            if tonumber(epochNowMs) ~= nil then
                return tonumber(epochNowMs)
            end
        end
        if type(os) == "table" and type(os.clock) == "function" then
            return math.floor(os.clock() * 1000)
        end
        return 0
    end

    local function wrapLoopForCurrentRuntime(loopName, loopCallback)
        return function(...)
            if not isFeaturePlaneInstallCurrent() then
                if isTableOrUserdata(Script) and type(Script.Yield) == "function" then
                    Script.Yield(5000)
                end
                return
            end
            local firstLoopArgument = ...
            return loopCallback(firstLoopArgument)
        end
    end

    local function enqueueRuntimeLoop(loopName, loopCallback)
        if type(loopCallback) ~= "function" then
            return nil
        end
        deferredRuntimeLoopQueue[#deferredRuntimeLoopQueue + 1] = { name = tostring(loopName or "loop"), fn = wrapLoopForCurrentRuntime(loopName, loopCallback) }
        if isRuntimeActivated and type(startRuntimeLoopDrainer) == "function" then
            startRuntimeLoopDrainer("late-loop")
        end
        return nil
    end

    function KS_PopFirst(pendingQueue)
        if #pendingQueue <= 0 then
            return nil
        end
        return table.remove(pendingQueue, 1)
    end

    local function removeQueuedEntryByName(pendingQueue, entryName)
        for entryIndex, queuedEntry in ipairs(pendingQueue) do
            if queuedEntry.name == entryName then
                return table.remove(pendingQueue, entryIndex)
            end
        end
        return nil
    end

    function startRuntimeLoopDrainer(drainerStartReason)
        if isRuntimeDrainerLoopRegistered then
            return true
        end
        if not isTableOrUserdata(Script) or type(Script.RegisterLooped) ~= "function" then
            return false
        end
        isRuntimeDrainerLoopRegistered = true
        runtimeDrainerStartedAtMs = KS_RuntimeNowMs()
        if Script.RegisterLooped(function()
            if not isFeaturePlaneInstallCurrent() then
                Script.Yield(5000)
                return
            end
            if ShouldUnload() then
                Script.Yield(5000)
                return
            end
            if not isRuntimeActivated then
                Script.Yield(0)
                return
            end
            if not hasRuntimeDrainerStartDelayElapsed then
                if KS_RuntimeNowMs() - (runtimeDrainerStartedAtMs or 0) < 0 then
                    Script.Yield(0)
                    return
                end
                hasRuntimeDrainerStartDelayElapsed = true
            end
            local defaultConfigLoopEntry = removeQueuedEntryByName(deferredRuntimeLoopQueue, "loadDefaultConfigOnce")
            if defaultConfigLoopEntry ~= nil then
                if Script.RegisterLooped(defaultConfigLoopEntry.fn) == false then
                    table.insert(deferredRuntimeLoopQueue, 1, defaultConfigLoopEntry)
                    yieldScriptMs(100)
                    return
                end
                Script.Yield(0)
                return
            end
            if uiReadinessState.renderRegistrationPrerequisitesMet() and not uiReadinessState.renderRegistered then
                local mainRenderEntry = removeQueuedEntryByName(deferredRenderHandlerQueue, "renderImGui")
                if mainRenderEntry ~= nil then
                    local mainRenderHandle, isMainRenderRegistered = registerRenderHandlerNow(mainRenderEntry.event, mainRenderEntry.name, mainRenderEntry.fn, mainRenderEntry.maxFailures)
                    if not isMainRenderRegistered then
                        mainRenderEntry.attempts = (tonumber(mainRenderEntry.attempts) or 0) + 1
                        if mainRenderEntry.attempts < 8 then
                            table.insert(deferredRenderHandlerQueue, 1, mainRenderEntry)
                        else
                            markUiStartupFailed("render_registration_failed")
                        end
                        yieldScriptMs(math.min(2000, 100 * 2 ^ math.max(0, mainRenderEntry.attempts - 1)))
                        return
                    end
                    networkQuietUntilMs = math.max(tonumber(networkQuietUntilMs or 0) or 0, KS_RuntimeNowMs() + 12000)
                    if type(_G) == "table" then
                        _G.KS_STARTUP_NETWORK_QUIET_UNTIL_MS = math.max(tonumber(_G.KS_STARTUP_NETWORK_QUIET_UNTIL_MS or 0) or 0, networkQuietUntilMs)
                    end
                    Script.Yield(0)
                    return
                end
            end
            local nextLoopEntry = KS_PopFirst(deferredRuntimeLoopQueue)
            if nextLoopEntry ~= nil then
                if Script.RegisterLooped(nextLoopEntry.fn) == false then
                    table.insert(deferredRuntimeLoopQueue, 1, nextLoopEntry)
                    yieldScriptMs(100)
                    return
                end
                Script.Yield(0)
                return
            end
            local shouldStartIntroSplash = isIntroSplashRequested == true
            if not isRuntimeLoopDrainComplete then
                isRuntimeLoopDrainComplete = true
                setRuntimeRenderReady(true, "runtime-drainer-complete")
                if shouldStartIntroSplash and type(startIntroSplashIfRequested) == "function" then
                    startIntroSplashIfRequested("runtime-drainer-complete")
                end
            end
            if not uiReadinessState.renderRegistrationPrerequisitesMet() then
                Script.Yield(0)
                return
            end
            local nextRenderEntry = KS_PopFirst(deferredRenderHandlerQueue)
            if nextRenderEntry ~= nil then
                local nextRenderHandle, isNextRenderRegistered = registerRenderHandlerNow(nextRenderEntry.event, nextRenderEntry.name, nextRenderEntry.fn, nextRenderEntry.maxFailures)
                if not isNextRenderRegistered then
                    nextRenderEntry.attempts = (tonumber(nextRenderEntry.attempts) or 0) + 1
                    if nextRenderEntry.attempts < 8 then
                        deferredRenderHandlerQueue[#deferredRenderHandlerQueue + 1] = nextRenderEntry
                    else
                        markUiStartupFailed("render_registration_failed")
                    end
                    yieldScriptMs(math.min(2000, 100 * 2 ^ math.max(0, nextRenderEntry.attempts - 1)))
                    return
                end
                networkQuietUntilMs = math.max(tonumber(networkQuietUntilMs or 0) or 0, KS_RuntimeNowMs() + 12000)
                if type(_G) == "table" then
                    _G.KS_STARTUP_NETWORK_QUIET_UNTIL_MS = math.max(tonumber(_G.KS_STARTUP_NETWORK_QUIET_UNTIL_MS or 0) or 0, networkQuietUntilMs)
                end
                Script.Yield(0)
                return
            end
            Script.Yield(60000)
        end) == false then
            isRuntimeDrainerLoopRegistered = false
            return false
        end
        return true
    end

    registerOrDeferRenderHandler(eLuaEvent.ON_PRESENT, "renderImGui", renderImGui)
    registerOrDeferRenderHandler(eLuaEvent.ON_PRESENT, "emotetext", emotetext)

    local function resolveRenderToastsFunction()
        if type(featurePlaneContext) == "table" and type(featurePlaneContext.renderToasts) == "function" then
            return featurePlaneContext.renderToasts, "ctx.renderToasts"
        end
        if type(renderToasts) == "function" then
            return renderToasts, "global.renderToasts"
        end
        if type(_ENV) == "table" and type(renderToasts) == "function" then
            return renderToasts, "_ENV.renderToasts"
        end
        return nil, "missing"
    end

    local function tryRegisterToastRenderHandler(attemptLabel)
        if isToastRendererPreRegistered then
            return true
        end
        if isToastRendererRegistered then
            return true
        end
        local renderToastsHandler, renderToastsSource = resolveRenderToastsFunction()
        if type(renderToastsHandler) ~= "function" then
            return false
        end
        registerOrDeferRenderHandler(eLuaEvent.ON_PRESENT, "renderToasts", renderToastsHandler, 3)
        isToastRendererRegistered = true
        return true
    end

    if not tryRegisterToastRenderHandler("initial") and not isToastRetryLoopDisabled and isTableOrUserdata(Script) and type(Script.RegisterLooped) == "function" then
        local toastRenderRegistrationRetryCount = 0
        Script.RegisterLooped(function()
            if isToastRendererRegistered or isUnloadRequested() then
                Script.Yield(60000)
                return
            end
            toastRenderRegistrationRetryCount = toastRenderRegistrationRetryCount + 1
            if tryRegisterToastRenderHandler("retry-" .. tostring(toastRenderRegistrationRetryCount)) then
                Script.Yield(60000)
                return
            end
            if toastRenderRegistrationRetryCount >= 30 then
                Script.Yield(60000)
                return
            end
            Script.Yield(500)
        end)
    end

    function featurePlaneInstall.paidRemovalProvider.current(removalProvider)
        local isProviderCurrent = isFeaturePlaneInstallCurrent()
        if isProviderCurrent then
            isProviderCurrent = isRuntimeGenerationCurrent()
            if isProviderCurrent then
                isProviderCurrent = KS_IsNetworkPlayerSessionReady()
                if isProviderCurrent then
                    local shouldUnloadNow = ShouldUnload()
                    isProviderCurrent = shouldUnloadNow == true and shouldUnloadNow
                end
            end
        end
        return isProviderCurrent
    end

    function featurePlaneInstall.paidRemovalProvider.queueCleanup(removalProvider, cleanupRecords)
        for _, cleanupRecord in ipairs(cleanupRecords or {}) do
            cleanupRecord.cleanupEpoch = removalProvider.cleanupEpoch or 0
            removalProvider.cleanupQueue[#removalProvider.cleanupQueue + 1] = cleanupRecord
        end
        if removalProvider.cleanupQueued or #removalProvider.cleanupQueue == 0 then
            return true
        end
        removalProvider.cleanupQueued = true
        if Script.QueueJob(function()
            while #removalProvider.cleanupQueue > 0 do
                local queuedRecord = table.remove(removalProvider.cleanupQueue, 1)
                local entityHandle = tonumber(queuedRecord.handle) or 0
                if queuedRecord.cleanupEpoch == (removalProvider.cleanupEpoch or 0) and entityHandle ~= 0 and ENTITY.DOES_ENTITY_EXIST(entityHandle) and (queuedRecord.controlOnly ~= true or NETWORK.NETWORK_HAS_CONTROL_OF_ENTITY(entityHandle)) then
                    DeleteEnt(entityHandle)
                end
                Script.Yield(0)
            end
            removalProvider.cleanupQueued = false
        end) == false then
            removalProvider.cleanupQueued = false
            return false
        end
        return true
    end

    function featurePlaneInstall.paidRemovalProvider.resolveNetworkObject(removalProvider, entityHandle, deadlineMs, isOperationActive)
        local effectiveDeadlineMs = tonumber(deadlineMs) or getRuntimeNowMs()
        for _ = 1, 50 do
            if not removalProvider:current() or type(isOperationActive) == "function" and not isOperationActive() or not ENTITY.DOES_ENTITY_EXIST(entityHandle) then
                return nil, "cancelled"
            end
            local entityPointer = GTA.HandleToPointer(entityHandle)
            local netObject = entityPointer and entityPointer.NetObject or nil
            local networkObjectId = netObject and tonumber(netObject.ObjectID) or nil
            if networkObjectId ~= nil and networkObjectId >= 0 and networkObjectId <= 65535 then
                return networkObjectId, tonumber(netObject.PlayerId), tonumber(netObject.PendingPlayerId)
            end
            if effectiveDeadlineMs <= getRuntimeNowMs() then
                return nil, "network_object_timeout"
            end
            Script.Yield(0)
        end
        return nil, "network_object_timeout"
    end

    function featurePlaneInstall.paidRemovalProvider.releaseEntityOperation(removalProvider, operationToken, shouldDeleteEntities, releaseReason)
        local entityOperation = removalProvider.entityOperations[operationToken]
        if entityOperation == nil then
            return false, "operation_inactive"
        end
        removalProvider.entityOperations[operationToken] = nil
        entityOperation.active = false
        entityOperation.reason = releaseReason
        local releasedRecords = entityOperation.records
        entityOperation.records = {}
        if shouldDeleteEntities == true then
            removalProvider:queueCleanup(releasedRecords)
        end
        return true
    end

    function featurePlaneInstall.paidRemovalProvider.beginEntityOperation(removalProvider, featureId, targetPlayerId)
        targetPlayerId = math.tointeger(tonumber(targetPlayerId) or -1)
        if featureId ~= "zykloneshower" or targetPlayerId < 0 or targetPlayerId >= 32 or not removalProvider:current() then
            return nil, "operation_context_invalid"
        end
        local existingOperationCount = 0
        local oldestOperationToken = nil
        local oldestSequence = nil
        for existingToken, existingOperation in pairs(removalProvider.entityOperations) do
            if existingOperation.featureId == featureId and existingOperation.target == targetPlayerId then
                if existingOperation.active == true and existingOperation.completed ~= true then
                    return nil, "operation_busy"
                end
                existingOperationCount = existingOperationCount + 1
                if oldestSequence == nil or oldestSequence > existingOperation.sequence then
                    oldestSequence = existingOperation.sequence
                    oldestOperationToken = existingToken
                end
            end
        end
        if existingOperationCount >= 4 and oldestOperationToken ~= nil then
            removalProvider:releaseEntityOperation(oldestOperationToken, true, "bounded_history")
        end
        removalProvider.sequence = removalProvider.sequence + 1
        local operationToken = ("%d:%s:%d:%d"):format(removalProvider.generation, featureId, targetPlayerId, removalProvider.sequence)
        local entityOperation = {
            active = true,
            completed = false,
            featureId = featureId,
            target = targetPlayerId,
            generation = removalProvider.generation,
            sequence = removalProvider.sequence,
            records = {},
            token = operationToken,
        }
        removalProvider.entityOperations[operationToken] = entityOperation

        local function isOperationCurrent()
            return removalProvider:current() and entityOperation.active == true
        end

        local operationHandle = { current = isOperationCurrent }

        function operationHandle.track(trackedEntity, networkObjectId, entityKind)
            if not isOperationCurrent() or type(trackedEntity) ~= "number" or trackedEntity == 0 or not ENTITY.DOES_ENTITY_EXIST(trackedEntity) then
                return false
            end
            entityOperation.records[#entityOperation.records + 1] = {
                handle = trackedEntity,
                objectId = networkObjectId,
                kind = tostring(entityKind or "entity"),
                controlOnly = false,
            }
            return true
        end

        function operationHandle.resolveNetworkObject(entityHandle, deadlineMs)
            return removalProvider:resolveNetworkObject(entityHandle, deadlineMs, isOperationCurrent)
        end

        function operationHandle.complete()
            if not isOperationCurrent() or #entityOperation.records == 0 then
                return false
            end
            entityOperation.completed = true
            for _, operationRecord in ipairs(entityOperation.records) do
                operationRecord.controlOnly = true
            end
            return true
        end

        function operationHandle.cancel(cancelReason)
            return removalProvider:releaseEntityOperation(operationToken, true, cancelReason or "cancelled")
        end

        return operationHandle
    end

    function featurePlaneInstall.paidRemovalProvider.releaseMasterpiece(removalProvider, targetPlayerId, shouldDeleteEntities, releaseReason)
        local masterpieceActivation = removalProvider.masterpieceByTarget[targetPlayerId]
        if masterpieceActivation == nil then
            return false, "activation_inactive"
        end
        removalProvider.masterpieceByTarget[targetPlayerId] = nil
        masterpieceActivation.active = false
        masterpieceActivation.reason = releaseReason
        for trackedObjectId in pairs(masterpieceActivation.identities) do
            if removalProvider.masterpieceByObjectId[trackedObjectId] == masterpieceActivation then
                removalProvider.masterpieceByObjectId[trackedObjectId] = nil
            end
        end
        masterpieceActivation.identities = {}
        local releasedRecords = masterpieceActivation.records
        masterpieceActivation.records = {}
        if shouldDeleteEntities == true then
            removalProvider:queueCleanup(releasedRecords)
        end
        return true
    end

    function featurePlaneInstall.paidRemovalProvider.activateMasterpiece(removalProvider, targetPlayerId)
        targetPlayerId = math.tointeger(tonumber(targetPlayerId) or -1)
        if targetPlayerId < 0 or targetPlayerId >= 32 or not removalProvider:current() then
            return nil, "activation_context_invalid"
        end
        if removalProvider.masterpieceByTarget[targetPlayerId] ~= nil then
            removalProvider:releaseMasterpiece(targetPlayerId, true, "activation_replaced")
        end
        removalProvider.sequence = removalProvider.sequence + 1
        local masterpieceActivation = {
            active = true,
            complete = false,
            owner = "m3_masterpiece",
            target = targetPlayerId,
            generation = removalProvider.generation,
            priority = 200,
            sequence = removalProvider.sequence,
            identities = {},
            records = {},
        }
        removalProvider.masterpieceByTarget[targetPlayerId] = masterpieceActivation

        local function isActivationCurrent()
            return removalProvider:current() and masterpieceActivation.active == true
        end

        local activationHandle = { current = isActivationCurrent }

        function activationHandle.resolveNetworkObject(entityHandle, deadlineMs)
            return removalProvider:resolveNetworkObject(entityHandle, deadlineMs, isActivationCurrent)
        end

        function activationHandle.trackPickup(pickupHandle, pickupObjectId)
            pickupObjectId = math.tointeger(tonumber(pickupObjectId) or -1)
            if not isActivationCurrent() or type(pickupHandle) ~= "number" or pickupHandle == 0 or pickupObjectId < 0 or pickupObjectId > 65535 or masterpieceActivation.identities[pickupObjectId] or removalProvider.masterpieceByObjectId[pickupObjectId] ~= nil or not ENTITY.DOES_ENTITY_EXIST(pickupHandle) then
                return false
            end
            masterpieceActivation.identities[pickupObjectId] = true
            masterpieceActivation.records[#masterpieceActivation.records + 1] = { handle = pickupHandle, objectId = pickupObjectId, kind = "pickup", controlOnly = false }
            removalProvider.masterpieceByObjectId[pickupObjectId] = masterpieceActivation
            return true
        end

        function activationHandle.finish()
            if not isActivationCurrent() or #masterpieceActivation.records ~= 5 then
                return false
            end
            masterpieceActivation.complete = true
            return true
        end

        function activationHandle.cancel(cancelReason)
            return removalProvider:releaseMasterpiece(targetPlayerId, true, cancelReason or "cancelled")
        end

        return activationHandle
    end

    function featurePlaneInstall.paidRemovalProvider.releaseTarget(removalProvider, targetPlayerId, shouldDeleteEntities, releaseReason)
        removalProvider:releaseMasterpiece(targetPlayerId, shouldDeleteEntities, releaseReason)
        local targetOperationTokens = {}
        for operationToken, entityOperation in pairs(removalProvider.entityOperations) do
            if entityOperation.target == targetPlayerId then
                targetOperationTokens[#targetOperationTokens + 1] = operationToken
            end
        end
        table.sort(targetOperationTokens)
        for _, tokenToRelease in ipairs(targetOperationTokens) do
            removalProvider:releaseEntityOperation(tokenToRelease, shouldDeleteEntities, releaseReason)
        end
        return true
    end

    function featurePlaneInstall.paidRemovalProvider.reset(removalProvider, shouldQueueCleanup, resetReason)
        local releasedRecords = {}
        for _, masterpieceOperation in pairs(removalProvider.masterpieceByTarget) do
            masterpieceOperation.active = false
            for _, masterpieceRecord in ipairs(masterpieceOperation.records) do
                releasedRecords[#releasedRecords + 1] = masterpieceRecord
            end
        end
        for _, entityOperation in pairs(removalProvider.entityOperations) do
            entityOperation.active = false
            for _, entityRecord in ipairs(entityOperation.records) do
                releasedRecords[#releasedRecords + 1] = entityRecord
            end
        end
        removalProvider.masterpieceByTarget = {}
        removalProvider.masterpieceByObjectId = {}
        removalProvider.entityOperations = {}
        if shouldQueueCleanup == true then
            removalProvider:queueCleanup(releasedRecords)
        else
            removalProvider.cleanupEpoch = (removalProvider.cleanupEpoch or 0) + 1
            removalProvider.cleanupQueue = {}
            removalProvider.cleanupQueued = false
        end
        removalProvider.lastResetReason = resetReason
        return true
    end

    function featurePlaneInstall.paidRemovalProvider.matchMasterpiece(removalProvider, targetPlayerId, syncEntity)
        if not removalProvider:current() or syncEntity == nil or syncEntity.NetObject == nil then
            return nil
        end
        local netObjectId = tonumber(syncEntity.NetObject.ObjectID)
        local matchedMasterpiece = netObjectId ~= nil and removalProvider.masterpieceByObjectId[netObjectId] or nil
        if matchedMasterpiece ~= nil and matchedMasterpiece.active == true and matchedMasterpiece.complete == true and matchedMasterpiece.generation == removalProvider.generation and matchedMasterpiece.target == targetPlayerId and matchedMasterpiece.priority == 200 then
            return matchedMasterpiece
        end
        return nil
    end

    function featurePlaneInstall.paidRemovalProvider.collectorObjectId(removalProvider, targetPlayerId)
        if not removalProvider:current() then
            return nil
        end
        local targetPedHandle = PLAYER.GET_PLAYER_PED_SCRIPT_INDEX(targetPlayerId)
        if type(targetPedHandle) ~= "number" or targetPedHandle == 0 or not ENTITY.DOES_ENTITY_EXIST(targetPedHandle) then
            return nil
        end
        local targetPedPointer = GTA.HandleToPointer(targetPedHandle)
        local targetNetObject = targetPedPointer and targetPedPointer.NetObject or nil
        local targetObjectId = targetNetObject and tonumber(targetNetObject.ObjectID) or nil
        if targetObjectId == nil or targetObjectId < 0 or targetObjectId > 65535 then
            return nil
        end
        return targetObjectId
    end

    featurePlaneInstall.paidRemovalProvider.entityFacade = {
        begin = function(operationFeatureId, targetPlayerId)
            return featurePlaneInstall.paidRemovalProvider:beginEntityOperation(operationFeatureId, targetPlayerId)
        end,
    }
    local paidRemovalProviderRef = featurePlaneInstall.paidRemovalProvider
    local masterpieceActivationFacade = {
        activate = function(targetPlayerId)
            return featurePlaneInstall.paidRemovalProvider:activateMasterpiece(targetPlayerId)
        end,
    }

    function masterpieceActivationFacade.disable(targetPlayerId)
        return featurePlaneInstall.paidRemovalProvider:releaseMasterpiece(targetPlayerId, true, "disabled")
    end

    paidRemovalProviderRef.masterpieceFacade = masterpieceActivationFacade
    featurePlaneInstall.capabilities["feature_plane.runtime_context"].entityOperations = featurePlaneInstall.paidRemovalProvider.entityFacade

