    function KS_ExclusiveSyncStartupHandler(targetPlayerId, syncEntity)
        if syncEntity == nil then
            return false
        end
        if type(KSShouldTriggerBlameKillPrearmExclusiveSync) == "function" and KSShouldTriggerBlameKillPrearmExclusiveSync(targetPlayerId, syncEntity) then
            return true
        end
        if FeatureMgr.IsFeatureEnabled(Utils.Joaat("masterpiece"), targetPlayerId) and featurePlaneInstall.paidRemovalProvider:matchMasterpiece(targetPlayerId, syncEntity) ~= nil then
            return true
        end
        if FeatureMgr.IsFeatureEnabled(Utils.Joaat("rapeLexis"), targetPlayerId) then
            return true
        end
        if FeatureMgr.IsFeatureEnabled(Utils.Joaat("InvalidMComp1"), targetPlayerId) then
            local targetInvalidMCompEntities = KSRuntimePlayerFeatureState and KSRuntimePlayerFeatureState.invalidMCompEntities and KSRuntimePlayerFeatureState.invalidMCompEntities[targetPlayerId] or nil
            local syncObjectId = syncEntity.NetObject and syncEntity.NetObject.ObjectID or nil
            if targetInvalidMCompEntities and syncObjectId ~= nil and targetInvalidMCompEntities[syncObjectId] then
                return true
            end
        end
        if syncEntity.NetObject and tableContainsValue(NiggerVeh, syncEntity.NetObject.ObjectID) then
            return true
        end
        if syncEntity.NetObject and tableContainsValue(spoofedVehicle, syncEntity.NetObject.ObjectID) then
            return true
        end
        if spoofedPid[targetPlayerId] then
            return true
        end
        if syncEntity.NetObject and syncEntity.NetObject.ObjectID == spoofedPed then
            return true
        end
        return false
    end

