    function KS_SyncDataNodeStartupHandler(syncNodeType, syncNode, syncEntity, isOutgoingSync, targetPlayerId)
        if not isOutgoingSync then
            return
        end
        if syncNode == nil or syncEntity == nil then
            return
        end
        if type(KSApplyBlameKillPrearmNode) == "function" then
            KSApplyBlameKillPrearmNode(syncNodeType, syncNode, syncEntity, isOutgoingSync, targetPlayerId)
        end
        if not isOutgoingSync then
            return
        end
        if syncNodeType == eSyncDataNode.CPickupCreationDataNode then
            if FeatureMgr.IsFeatureEnabled(Utils.Joaat("masterpiece"), targetPlayerId) and featurePlaneInstall.paidRemovalProvider:matchMasterpiece(targetPlayerId, syncEntity) ~= nil then
                syncNode.numWeaponComponents = 12
                for componentSlot = 1, 12 do
                    syncNode.weaponComponents[componentSlot] = 1073741824 + componentSlot
                end
                notify("Führers Masterpiece Syncing...")
                return
            end
            return
        end
        if syncNodeType == eSyncDataNode.CPickupPlacementStateDataNode then
            if FeatureMgr.IsFeatureEnabled(Utils.Joaat("masterpiece"), targetPlayerId) and featurePlaneInstall.paidRemovalProvider:matchMasterpiece(targetPlayerId, syncEntity) ~= nil then
                local collectorNetObjectId = featurePlaneInstall.paidRemovalProvider:collectorObjectId(targetPlayerId)
                if collectorNetObjectId ~= nil then
                    syncNode.Collected = true
                    syncNode.Collector = collectorNetObjectId
                    notify("Führers Masterpiece #2 Syncing...")
                end
                return
            end
            return
        end
        if syncNodeType == eSyncDataNode.CVehicleTaskDataNode then
            if spoofedPid[targetPlayerId] and not FeatureMgr.IsFeatureEnabled(Utils.Joaat("rapeLexis"), targetPlayerId) then
                notify("Goofy Goober Crash: Syncing...")
                syncNode.taskType = 492
                syncNode.taskDataSize = 256
                for taskDataIndex = 1, 50 do
                    syncNode.taskData[taskDataIndex] = 91337420
                end
                notify("Goofy Goober Crash Syncing...")
            end
            return
        end
        if syncNodeType == eSyncDataNode.CVehicleProximityMigrationDataNode then
            if spoofedPid[targetPlayerId] and not FeatureMgr.IsFeatureEnabled(Utils.Joaat("rapeLexis"), targetPlayerId) then
                notify("Goofy Goober Crash Step 2: Syncing...")
                syncNode.hasTaskData = true
                syncNode.hasPopType = true
                syncNode.PopType = math.random(0, 4294967295)
                syncNode.taskType = 492
                syncNode.packedVelocityX = -10
                syncNode.packedVelocityY = -10
                syncNode.packedVelocityZ = -10
                syncNode.taskMigrationDataSize = 256
                for migrationDataIndex = 1, 50 do
                    syncNode.taskMigrationData[migrationDataIndex] = 91337420
                end
                notify("Goofy Goober Crash Step 2 Syncing...")
            end
            return
        end
        if syncNodeType == eSyncDataNode.CPedCreationDataNode and spoofedPid[targetPlayerId] then
            if syncEntity.NetObject and syncEntity.NetObject.ObjectID == spoofedPed then
                syncNode.modelHash = 1653710254
                syncNode.hasProp = true
                syncNode.propHash = 20754026
                notify("TV Crash Syncing...")
            end
            return
        end
        if syncNodeType == eSyncDataNode.CPedTaskTreeDataNode then
            if FeatureMgr.IsFeatureEnabled(Utils.Joaat("rapeLexis"), targetPlayerId) then
                syncNode.scriptCommand = math.random(0, 75)
                local taskSlotCount = math.random(1, 8)
                syncNode.taskSlotsUsed = taskSlotCount
                syncNode.taskStage = math.random(0, 6)
                for taskSlotIndex = 1, taskSlotCount do
                    if syncNode.taskTreeData[taskSlotIndex] then
                        syncNode.taskTreeData[taskSlotIndex].taskActive = true
                        syncNode.taskTreeData[taskSlotIndex].taskPriority = math.random(0, 3)
                        syncNode.taskTreeData[taskSlotIndex].taskSequenceId = math.random(0, 31)
                        syncNode.taskTreeData[taskSlotIndex].taskType = 57
                    end
                end
                notify("BLDM Crash Syncing...")
            end
            return
        end
        if syncNodeType == eSyncDataNode.CPedAppearanceDataNode then
            if FeatureMgr.IsFeatureEnabled(Utils.Joaat("InvalidMComp1"), targetPlayerId) then
                local targetInvalidMCompEntities = KSRuntimePlayerFeatureState.invalidMCompEntities[targetPlayerId]
                local invalidCompEntry = targetInvalidMCompEntities and targetInvalidMCompEntities[syncEntity.NetObject.ObjectID]
                if invalidCompEntry then
                    local variationData = syncNode.VariationData
                    variationData.UsedComponents = invalidCompEntry.usedComponents
                    variationData.PlayerData = false
                    variationData.ComponentData[invalidCompEntry.componentIndex] = invalidCompEntry.drawableId
                    variationData.TextureData[invalidCompEntry.componentIndex] = math.random(invalidCompEntry.textureMin, invalidCompEntry.textureMax)
                    variationData.PaletteData[invalidCompEntry.componentIndex] = invalidCompEntry.paletteId
                    syncNode.Updated = true
                    invalidCompEntry.emissionCount = (invalidCompEntry.emissionCount or 0) + 1
                    notify("Gas Chamber Crash Syncing...")
                end
            end
            return
        end
    end

