            unregisterTosPromptRenderHandler()
            if isTableOrUserdata(EventMgr) and type(EventMgr.RemoveHandler) == "function" then
                for _, eventHandlerId in pairs(featurePlaneInstall.handlers) do
                    EventMgr.RemoveHandler(eventHandlerId)
                end
                featurePlaneInstall.handlers = {}
                featurePlaneContext.__ksAngelAi.unloading = true
                featurePlaneContext.__ksAngelAi.sequence = featurePlaneContext.__ksAngelAi.sequence + 1
                featurePlaneContext.__ksAngelAi.latest.weapon = nil
                featurePlaneContext.__ksAngelAi.latest.respawn = nil
                for _, angelAiHandlerId in pairs(featurePlaneContext.__ksAngelAi.handlers) do
                    if angelAiHandlerId ~= nil then
                        EventMgr.RemoveHandler(angelAiHandlerId)
                    end
                end
                featurePlaneContext.__ksAngelAi.handlers = {}
                featurePlaneContext.__ksAngelAi.callbacks = {}
                for renderHandlerKey, renderHandlerId in pairs(uiReadinessState.renderHandlers) do
                    if uiReadinessState.renderHandlerGenerations[renderHandlerKey] == runtimeLoadGeneration and renderHandlerId ~= nil then
                        EventMgr.RemoveHandler(renderHandlerId)
                    end
                end
            end
            uiReadinessState.renderCallbacks = {}
            uiReadinessState.renderHandlers = {}
            uiReadinessState.renderHandlerGenerations = {}
            if KS_BLAME_KILL_PREARM.aimEntityPtr ~= nil then
                Memory.Free(KS_BLAME_KILL_PREARM.aimEntityPtr)
                KS_BLAME_KILL_PREARM.aimEntityPtr = nil
            end
            if KS_BLAME_KILL_PREARM.explosiveRayBuffer ~= nil then
                Memory.Free(KS_BLAME_KILL_PREARM.explosiveRayBuffer)
                KS_BLAME_KILL_PREARM.explosiveRayBuffer = nil
            end
            if KS_BLAME_KILL_PREARM.projectilePositionBuffer ~= nil then
                Memory.Free(KS_BLAME_KILL_PREARM.projectilePositionBuffer)
                KS_BLAME_KILL_PREARM.projectilePositionBuffer = nil
            end
            if KS_BLAME_KILL_PREARM.projectileEntityPtr ~= nil then
                Memory.Free(KS_BLAME_KILL_PREARM.projectileEntityPtr)
                KS_BLAME_KILL_PREARM.projectileEntityPtr = nil
            end
            if KS_BLAME_KILL_PREARM.vehicleWeaponPtr ~= nil then
                Memory.Free(KS_BLAME_KILL_PREARM.vehicleWeaponPtr)
                KS_BLAME_KILL_PREARM.vehicleWeaponPtr = nil
            end
            if KS_BLAME_KILL_PREARM.incomingVehicleWeaponPtr ~= nil then
                Memory.Free(KS_BLAME_KILL_PREARM.incomingVehicleWeaponPtr)
                KS_BLAME_KILL_PREARM.incomingVehicleWeaponPtr = nil
            end
            featurePlaneInstall.ready = false
            featurePlaneContext[FEATURE_PLANE_INSTALL_KEY] = nil
        end
        return true
    end

    logStartupStage("feature_ready")
    featurePlaneInstall.ready = true
    featurePlaneInstall.exports = featureRuntimeModuleExports
    return featureRuntimeModuleExports
end

return installFeaturePlaneRuntime
